const e=[{id:0,oaid:"W2116658855",doi:"10.1523/jneurosci.5587-06.2007",title:"Dissociable Intrinsic Connectivity Networks for Salience Processing and Executive Control",authors:[{name:"William W. Seeley",institutions:["University of California, San Francisco"]},{name:"Vinod Menon",institutions:[]},{name:"Alan F. Schatzberg",institutions:[]},{name:"Jennifer Keller",institutions:[]},{name:"Gary H. Glover",institutions:[]},{name:"Heather A. Kenna",institutions:[]},{name:"Allan L. Reiss",institutions:[]},{name:"Michael D. Greicius",institutions:["Stanford University"]}],authorString:"William W. Seeley; Vinod Menon; Alan F. Schatzberg; Jennifer Keller; Gary H. Glover; Heather A. Kenna; Allan L. Reiss; Michael D. Greicius",institutions:["Stanford University","University of California, San Francisco"],countries:["US"],year:2007,journal:"Journal of Neuroscience",citations:7569,abstract:'Variations in neural circuitry, inherited or acquired, may underlie important individual differences in thought, feeling, and action patterns. Here, we used task-free connectivity analyses to isolate and characterize two distinct networks typically coactivated during functional MRI tasks. We identified a "salience network," anchored by dorsal anterior cingulate (dACC) and orbital frontoinsular cortices with robust connectivity to subcortical and limbic structures, and an "executive-control network" that links dorsolateral frontal and parietal neocortices. These intrinsic connectivity networks showed dissociable correlations with functions measured outside the scanner. Prescan anxiety ratings correlated with intrinsic functional connectivity of the dACC node of the salience network, but with no region in the executive-control network, whereas executive task performance correlated with lateral parietal nodes of the executive-control network, but with no region in the salience network. Our findings suggest that task-free analysis of intrinsic connectivity networks may help elucidate the neural architectures that support fundamental aspects of human behavior.',keywords:["Task-positive network","Salience","Neuroscience","Anterior cingulate cortex","Functional connectivity","Default mode network","Cognitive psychology"],concepts:["Psychology","Task-positive network","Salience (neuroscience)","Neuroscience","Anterior cingulate cortex","Functional connectivity","Default mode network","Cognitive psychology"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Neural and Behavioral Psychology Studies"],pdf_url:"https://www.jneurosci.org/content/jneuro/27/9/2349.full.pdf",is_oa:!0,n_refs:68,n_refs_in_core:5,degree:37,community:2,deg_w:471,betweenness:.0026,pagerank:.00427,eigenvector:.0222,pdf_file:"Seeley_2007.pdf",pdf_downloaded:!0},{id:1,oaid:"W2060464767",doi:"10.1103/physrevlett.87.198701",title:"Efficient Behavior of Small-World Networks",authors:[{name:"Vito Latora",institutions:["Université Paris-Sud","University of Catania","Laboratoire de Physique Théorique et Modèles Statistiques"]},{name:"Massimo Marchiori",institutions:["Massachusetts Institute of Technology"]}],authorString:"Vito Latora; Massimo Marchiori",institutions:["Laboratoire de Physique Théorique et Modèles Statistiques","Massachusetts Institute of Technology","University of Catania","Université Paris-Sud"],countries:["FR","IT","US"],year:2001,journal:"Physical Review Letters",citations:5174,abstract:'We introduce the concept of efficiency of a network as a measure of how efficiently it exchanges information. By using this simple measure, small-world networks are seen as systems that are both globally and locally efficient. This gives a clear physical meaning to the concept of "small world," and also a precise quantitative analysis of both weighted and unweighted networks. We study neural networks and man-made communication and transportation systems and we show that the underlying general principle of their construction is in fact a small-world principle of high efficiency.',keywords:["Small-world network","Measure","Simple","Meaning","Artificial neural network","Complex network"],concepts:["Small-world network","Measure (data warehouse)","Computer science","Simple (philosophy)","Meaning (existential)","Artificial neural network","Artificial intelligence","Complex network"],topics:["Neural Networks and Applications","Neural dynamics and brain function","Neural Networks Stability and Synchronization"],pdf_url:"http://link.aps.org/pdf/10.1103/PhysRevLett.87.198701",is_oa:!0,n_refs:19,n_refs_in_core:0,degree:83,community:1,deg_w:883.5,betweenness:.0125,pagerank:.00632,eigenvector:.1006,pdf_file:"Latora_2001.pdf",pdf_downloaded:!0},{id:2,oaid:"W1983183519",doi:"10.1089/brain.2012.0073",title:"<i>Conn</i> : A Functional Connectivity Toolbox for Correlated and Anticorrelated Brain Networks",authors:[{name:"Susan Whitfield‐Gabrieli",institutions:["McGovern Institute for Brain Research","Massachusetts Institute of Technology"]},{name:"Alfonso Nieto-Castañón",institutions:["McGovern Institute for Brain Research","Massachusetts Institute of Technology"]}],authorString:"Susan Whitfield‐Gabrieli; Alfonso Nieto-Castañón",institutions:["Massachusetts Institute of Technology","McGovern Institute for Brain Research"],countries:["US"],year:2012,journal:"Brain Connectivity",citations:5088,abstract:"Resting state functional connectivity reveals intrinsic, spontaneous networks that elucidate the functional architecture of the human brain. However, valid statistical analysis used to identify such networks must address sources of noise in order to avoid possible confounds such as spurious correlations based on non-neuronal sources. We have developed a functional connectivity toolbox Conn ( www.nitrc.org/projects/conn ) that implements the component-based noise correction method (CompCor) strategy for physiological and other noise source reduction, additional removal of movement, and temporal covariates, temporal filtering and windowing of the residual blood oxygen level-dependent (BOLD) contrast signal, first-level estimation of multiple standard functional connectivity magnetic resonance imaging (fcMRI) measures, and second-level random-effect analysis for resting state as well as task-related data. Compared to methods that rely on global signal regression, the CompCor noise reduction method allows for interpretation of anticorrelations as there is no regression of the global signal. The toolbox implements fcMRI measures, such as estimation of seed-to-voxel and region of interest (ROI)-to-ROI functional correlations, as well as semipartial correlation and bivariate/multivariate regression analysis for multiple ROI sources, graph theoretical analysis, and novel voxel-to-voxel analysis of functional connectivity. We describe the methods implemented in the Conn toolbox for the analysis of fcMRI data, together with examples of use and interscan reliability estimates of all the implemented fcMRI measures. The results indicate that the CompCor method increases the sensitivity and selectivity of fcMRI analysis, and show a high degree of interscan reliability for many fcMRI measures.",keywords:["Functional magnetic resonance imaging","Voxel","Pattern recognition","Human Connectome Project","Communication noise","Resting state fMRI"],concepts:["Computer science","Artificial intelligence","Functional magnetic resonance imaging","Voxel","Pattern recognition (psychology)","Human Connectome Project","Communication noise","Resting state fMRI"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:null,is_oa:!1,n_refs:74,n_refs_in_core:10,degree:29,community:2,deg_w:474.5,betweenness:.0017,pagerank:.00402,eigenvector:.0332,pdf_file:null,pdf_downloaded:!1},{id:3,oaid:"W2002923643",doi:"10.1073/pnas.0601417103",title:"Consistent resting-state networks across healthy subjects",authors:[{name:"Jessica S. Damoiseaux",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Serge A.R.B. Rombouts",institutions:["Leiden University Medical Center"]},{name:"Frederik Barkhof",institutions:["University Radiology"]},{name:"Philip Scheltens",institutions:["Vrije Universiteit Amsterdam"]},{name:"Cornelis J. Stam",institutions:["Vrije Universiteit Amsterdam","Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Stephen M. Smith",institutions:["John Radcliffe Hospital","University of Oxford"]},{name:"Christian F. Beckmann",institutions:["John Radcliffe Hospital","University of Oxford"]}],authorString:"Jessica S. Damoiseaux; Serge A.R.B. Rombouts; Frederik Barkhof; Philip Scheltens; Cornelis J. Stam; Stephen M. Smith; Christian F. Beckmann",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam","John Radcliffe Hospital","Leiden University Medical Center","University Radiology","University of Oxford","Vrije Universiteit Amsterdam"],countries:["GB","NL","US"],year:2006,journal:"Proceedings of the National Academy of Sciences",citations:4411,abstract:"Functional MRI (fMRI) can be applied to study the functional connectivity of the human brain. It has been suggested that fluctuations in the blood oxygenation level-dependent (BOLD) signal during rest reflect the neuronal baseline activity of the brain, representing the state of the human brain in the absence of goal-directed neuronal action and external input, and that these slow fluctuations correspond to functionally relevant resting-state networks. Several studies on resting fMRI have been conducted, reporting an apparent similarity between the identified patterns. The spatial consistency of these resting patterns, however, has not yet been evaluated and quantified. In this study, we apply a data analysis approach called tensor probabilistic independent component analysis to resting-state fMRI data to find coherencies that are consistent across subjects and sessions. We characterize and quantify the consistency of these effects by using a bootstrapping approach, and we estimate the BOLD amplitude modulation as well as the voxel-wise cross-subject variation. The analysis found 10 patterns with potential functional relevance, consisting of regions known to be involved in motor function, visual processing, executive functioning, auditory processing, memory, and the so-called default-mode network, each with BOLD signal changes up to 3%. In general, areas with a high mean percentage BOLD signal are consistent and show the least variation around the mean. These findings show that the baseline activity of the brain is consistent across subjects exhibiting significant temporal dynamics, with percentage BOLD signal change comparable with the signal changes found in task-related experiments.",keywords:["Resting state fMRI","Functional magnetic resonance imaging","Default mode network","Brain activity and meditation","Brain mapping","Neuroscience","Voxel"],concepts:["Resting state fMRI","Functional magnetic resonance imaging","Default mode network","Brain activity and meditation","Brain mapping","Neuroscience","Voxel","Psychology"],topics:["Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.ncbi.nlm.nih.gov/pmc/articles/1564249",is_oa:!0,n_refs:42,n_refs_in_core:5,degree:69,community:2,deg_w:987,betweenness:.0143,pagerank:.00773,eigenvector:.0693,pdf_file:"Damoiseaux_2006.pdf",pdf_downloaded:!0},{id:4,oaid:"W2159929956",doi:"10.1371/journal.pbio.0060159",title:"Mapping the Structural Core of Human Cerebral Cortex",authors:[{name:"Patric Hagmann",institutions:["École Polytechnique Fédérale de Lausanne","University of Lausanne"]},{name:"Leila Cammoun",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Xavier Gigandet",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Reto Meuli",institutions:["University of Lausanne"]},{name:"Christopher J. Honey",institutions:["Indiana University Bloomington"]},{name:"Van J. Wedeen",institutions:["Athinoula A. Martinos Center for Biomedical Imaging","Harvard University","Massachusetts General Hospital"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]}],authorString:"Patric Hagmann; Leila Cammoun; Xavier Gigandet; Reto Meuli; Christopher J. Honey; Van J. Wedeen; Olaf Sporns",institutions:["Athinoula A. Martinos Center for Biomedical Imaging","Harvard University","Indiana University Bloomington","Massachusetts General Hospital","University of Lausanne","École Polytechnique Fédérale de Lausanne"],countries:["CH","US"],year:2008,journal:"PLoS Biology",citations:4378,abstract:"Structurally segregated and functionally specialized regions of the human cerebral cortex are interconnected by a dense network of cortico-cortical axonal pathways. By using diffusion spectrum imaging, we noninvasively mapped these pathways within and across cortical hemispheres in individual human participants. An analysis of the resulting large-scale structural brain networks reveals a structural core within posterior medial and parietal cerebral cortex, as well as several distinct temporal and frontal modules. Brain regions within the structural core share high degree, strength, and betweenness centrality, and they constitute connector hubs that link all major structural modules. The structural core contains brain regions that form the posterior components of the human default network. Looking both within and outside of core regions, we observed a substantial correspondence between structural connectivity and resting-state functional connectivity measured in the same participants. The spatial and topological centrality of the core within cortex suggests an important role in functional integration.",keywords:["Neuroscience","Betweenness centrality","Human brain","Cortex","Cerebral cortex","Functional specialization","Core"],concepts:["Neuroscience","Betweenness centrality","Biology","Human brain","Cortex (anatomy)","Cerebral cortex","Functional specialization","Core (optical fiber)"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Neural dynamics and brain function"],pdf_url:"https://journals.plos.org/plosbiology/article/file?id=10.1371/journal.pbio.0060159&type=printable",is_oa:!0,n_refs:57,n_refs_in_core:10,degree:130,community:1,deg_w:2251,betweenness:.0561,pagerank:.01552,eigenvector:.2109,pdf_file:"Hagmann_2008.pdf",pdf_downloaded:!0},{id:5,oaid:"W2005821483",doi:"10.1371/journal.pone.0068910",title:"BrainNet Viewer: A Network Visualization Tool for Human Brain Connectomics",authors:[{name:"Mingrui Xia",institutions:["Beijing Normal University"]},{name:"Jinhui Wang",institutions:["Beijing Normal University"]},{name:"Yong He",institutions:["Beijing Normal University"]}],authorString:"Mingrui Xia; Jinhui Wang; Yong He",institutions:["Beijing Normal University"],countries:["CN"],year:2013,journal:"PLoS ONE",citations:4324,abstract:"The human brain is a complex system whose topological organization can be represented using connectomics. Recent studies have shown that human connectomes can be constructed using various neuroimaging technologies and further characterized using sophisticated analytic strategies, such as graph theory. These methods reveal the intriguing topological architectures of human brain networks in healthy populations and explore the changes throughout normal development and aging and under various pathological conditions. However, given the huge complexity of this methodology, toolboxes for graph-based network visualization are still lacking. Here, using MATLAB with a graphical user interface (GUI), we developed a graph-theoretical network visualization toolbox, called BrainNet Viewer, to illustrate human connectomes as ball-and-stick models. Within this toolbox, several combinations of defined files with connectome information can be loaded to display different combinations of brain surface, nodes and edges. In addition, display properties, such as the color and size of network elements or the layout of the figure, can be adjusted within a comprehensive but easy-to-use settings panel. Moreover, BrainNet Viewer draws the brain surface, nodes and edges in sequence and displays brain networks in multiple views, as required by the user. The figure can be manipulated with certain interaction functions to display more detailed information. Furthermore, the figures can be exported as commonly used image file formats or demonstration video for further use. BrainNet Viewer helps researchers to visualize brain networks in an easy, flexible and quick manner, and this software is freely available on the NITRC website (www.nitrc.org/projects/bnv/).",keywords:["Connectomics","Connectome","Visualization","Toolbox","Graphical user interface","Graph drawing","Human–computer interaction"],concepts:["Connectomics","Computer science","Connectome","Visualization","Toolbox","Graphical user interface","Graph drawing","Human–computer interaction"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0068910&type=printable",is_oa:!0,n_refs:92,n_refs_in_core:34,degree:64,community:1,deg_w:1179,betweenness:.0072,pagerank:.0083,eigenvector:.1118,pdf_file:"Xia_2013.pdf",pdf_downloaded:!0},{id:6,oaid:"W2951617899",doi:"10.1093/cercor/bhx179",title:"Local-Global Parcellation of the Human Cerebral Cortex from Intrinsic Functional Connectivity MRI",authors:[{name:"Alexander Schaefer",institutions:["A*STAR-NUS Clinical Imaging Research Centre","National University of Singapore"]},{name:"Ru Kong",institutions:["National University of Singapore","A*STAR-NUS Clinical Imaging Research Centre"]},{name:"Evan M. Gordon",institutions:["VA Heart of Texas Health Care Network","Center for Occupational Research and Development"]},{name:"Timothy O. Laumann",institutions:["Washington University in St. Louis"]},{name:"Xi‐Nian Zuo",institutions:["Institute of Psychology, Chinese Academy of Sciences","University of Chinese Academy of Sciences"]},{name:"Avram J. Holmes",institutions:["Yale University"]},{name:"Simon B. Eickhoff",institutions:["Forschungszentrum Jülich","Heinrich Heine University Düsseldorf"]},{name:"B.T. Thomas Yeo",institutions:["National University of Singapore","A*STAR-NUS Clinical Imaging Research Centre","Massachusetts General Hospital","Duke-NUS Medical School","Athinoula A. Martinos Center for Biomedical Imaging"]}],authorString:"Alexander Schaefer; Ru Kong; Evan M. Gordon; Timothy O. Laumann; Xi‐Nian Zuo; Avram J. Holmes; Simon B. Eickhoff; B.T. Thomas Yeo",institutions:["A*STAR-NUS Clinical Imaging Research Centre","Athinoula A. Martinos Center for Biomedical Imaging","Center for Occupational Research and Development","Duke-NUS Medical School","Forschungszentrum Jülich","Heinrich Heine University Düsseldorf","Institute of Psychology, Chinese Academy of Sciences","Massachusetts General Hospital","National University of Singapore","University of Chinese Academy of Sciences","VA Heart of Texas Health Care Network","Washington University in St. Louis","Yale University"],countries:["CN","DE","SG","US"],year:2017,journal:"Cerebral Cortex",citations:3817,abstract:'A central goal in systems neuroscience is the parcellation of the cerebral cortex into discrete neurobiological "atoms". Resting-state functional magnetic resonance imaging (rs-fMRI) offers the possibility of in vivo human cortical parcellation. Almost all previous parcellations relied on 1 of 2 approaches. The local gradient approach detects abrupt transitions in functional connectivity patterns. These transitions potentially reflect cortical areal boundaries defined by histology or visuotopic fMRI. By contrast, the global similarity approach clusters similar functional connectivity patterns regardless of spatial proximity, resulting in parcels with homogeneous (similar) rs-fMRI signals. Here, we propose a gradient-weighted Markov Random Field (gwMRF) model integrating local gradient and global similarity approaches. Using task-fMRI and rs-fMRI across diverse acquisition protocols, we found gwMRF parcellations to be more homogeneous than 4 previously published parcellations. Furthermore, gwMRF parcellations agreed with the boundaries of certain cortical areas defined using histology and visuotopic fMRI. Some parcels captured subareal (somatotopic and visuotopic) features that likely reflect distinct computational units within known cortical areas. These results suggest that gwMRF parcellations reveal neurobiologically meaningful features of brain organization and are potentially useful for future applications requiring dimensionality reduction of voxel-wise fMRI data. Multiresolution parcellations generated from 1489 participants are publicly available (https://github.com/ThomasYeoLab/CBIG/tree/master/stable_projects/brain_parcellation/Schaefer2018_LocalGlobal).',keywords:["Neuroscience","Functional connectivity","Cerebral cortex","Human brain","Brain mapping"],concepts:["Neuroscience","Functional connectivity","Cerebral cortex","Psychology","Human brain","Brain mapping"],topics:["Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://academic.oup.com/cercor/article-pdf/28/9/3095/25696343/bhx179.pdf",is_oa:!0,n_refs:193,n_refs_in_core:13,degree:32,community:2,deg_w:445,betweenness:.0036,pagerank:.00397,eigenvector:.0224,pdf_file:"Schaefer_2017.pdf",pdf_downloaded:!0},{id:7,oaid:"W2137526583",doi:"10.1098/rstb.2005.1634",title:"Investigations into resting-state connectivity using independent component analysis",authors:[{name:"Christian F. Beckmann",institutions:["John Radcliffe Hospital","University of Oxford","Wellcome Centre for Integrative Neuroimaging"]},{name:"Marilena DeLuca",institutions:["John Radcliffe Hospital","University of Oxford","Wellcome Centre for Integrative Neuroimaging"]},{name:"Joseph T. Devlin",institutions:["John Radcliffe Hospital","University of Oxford","Wellcome Centre for Integrative Neuroimaging"]},{name:"Stephen M. Smith",institutions:["John Radcliffe Hospital","University of Oxford","Wellcome Centre for Integrative Neuroimaging"]}],authorString:"Christian F. Beckmann; Marilena DeLuca; Joseph T. Devlin; Stephen M. Smith",institutions:["John Radcliffe Hospital","University of Oxford","Wellcome Centre for Integrative Neuroimaging"],countries:["GB"],year:2005,journal:"Philosophical Transactions of the Royal Society B Biological Sciences",citations:3496,abstract:"Inferring resting-state connectivity patterns from functional magnetic resonance imaging (fMRI) data is a challenging task for any analytical technique. In this paper, we review a probabilistic independent component analysis (PICA) approach, optimized for the analysis of fMRI data, and discuss the role which this exploratory technique can take in scientific investigations into the structure of these effects. We apply PICA to fMRI data acquired at rest, in order to characterize the spatio-temporal structure of such data, and demonstrate that this is an effective and robust tool for the identification of low-frequency resting-state patterns from data acquired at various different spatial and temporal resolutions. We show that these networks exhibit high spatial consistency across subjects and closely resemble discrete cortical functional networks such as visual cortical areas or sensory-motor cortex.",keywords:["Resting state fMRI","Functional magnetic resonance imaging","Independent component analysis","Pattern recognition","Probabilistic logic","Functional connectivity"],concepts:["Resting state fMRI","Functional magnetic resonance imaging","Independent component analysis","Computer science","Pattern recognition (psychology)","Artificial intelligence","Probabilistic logic","Functional connectivity"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://www.ncbi.nlm.nih.gov/pmc/articles/1854918",is_oa:!0,n_refs:55,n_refs_in_core:0,degree:45,community:2,deg_w:514.5,betweenness:.0054,pagerank:.00448,eigenvector:.034,pdf_file:"Beckmann_2005.pdf",pdf_downloaded:!0},{id:8,oaid:"W2146693559",doi:"10.1371/journal.pcbi.0010042",title:"The Human Connectome: A Structural Description of the Human Brain",authors:[{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]},{name:"Giulio Tononi",institutions:["University of Wisconsin–Madison","Indiana University Bloomington","Heinrich Heine University Düsseldorf"]},{name:"Rolf Kötter",institutions:["University of Wisconsin–Madison","Indiana University Bloomington","Heinrich Heine University Düsseldorf"]}],authorString:"Olaf Sporns; Giulio Tononi; Rolf Kötter",institutions:["Heinrich Heine University Düsseldorf","Indiana University Bloomington","University of Wisconsin–Madison"],countries:["DE","US"],year:2005,journal:"PLoS Computational Biology",citations:3383,abstract:'The connection matrix of the human brain (the human "connectome") represents an indispensable foundation for basic and applied neurobiological research. However, the network of anatomical connections linking the neuronal elements of the human brain is still largely unknown. While some databases or collations of large-scale anatomical connection patterns exist for other mammalian species, there is currently no connection matrix of the human brain, nor is there a coordinated research effort to collect, archive, and disseminate this important information. We propose a research strategy to achieve this goal, and discuss its potential impact.',keywords:["Connectome","Human brain","Connection","Human Connectome Project","Neuroscience","Cognitive science","Foundation"],concepts:["Connectome","Human brain","Connection (principal bundle)","Human Connectome Project","Computer science","Neuroscience","Cognitive science","Foundation (evidence)"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.0010042&type=printable",is_oa:!0,n_refs:86,n_refs_in_core:1,degree:82,community:1,deg_w:1042.5,betweenness:.0142,pagerank:.00742,eigenvector:.1146,pdf_file:"Sporns_2005.pdf",pdf_downloaded:!0},{id:9,oaid:"W2170702893",doi:"10.1093/cercor/bhs352",title:"Tracking Whole-Brain Connectivity Dynamics in the Resting State",authors:[{name:"Elena A. Allen",institutions:["Mind Research Network","University of Bergen"]},{name:"Eswar Damaraju",institutions:["Mind Research Network"]},{name:"Sergey Plis",institutions:["Mind Research Network"]},{name:"Erik B. Erhardt",institutions:["Mind Research Network"]},{name:"Tom Eichele",institutions:["Mind Research Network","Haukeland University Hospital","University of Bergen"]},{name:"Vince D. Calhoun",institutions:["Mind Research Network","University of New Mexico"]}],authorString:"Elena A. Allen; Eswar Damaraju; Sergey Plis; Erik B. Erhardt; Tom Eichele; Vince D. Calhoun",institutions:["Haukeland University Hospital","Mind Research Network","University of Bergen","University of New Mexico"],countries:["NO","US"],year:2012,journal:"Cerebral Cortex",citations:3227,abstract:"Spontaneous fluctuations are a hallmark of recordings of neural signals, emergent over time scales spanning milliseconds and tens of minutes. However, investigations of intrinsic brain organization based on resting-state functional magnetic resonance imaging have largely not taken into account the presence and potential of temporal variability, as most current approaches to examine functional connectivity (FC) implicitly assume that relationships are constant throughout the length of the recording. In this work, we describe an approach to assess whole-brain FC dynamics based on spatial independent component analysis, sliding time window correlation, and k-means clustering of windowed correlation matrices. The method is applied to resting-state data from a large sample (n = 405) of young adults. Our analysis of FC variability highlights particularly flexible connections between regions in lateral parietal and cingulate cortex, and argues against a labeling scheme where such regions are treated as separate and antagonistic entities. Additionally, clustering analysis reveals unanticipated FC states that in part diverge strongly from stationary connectivity patterns and challenge current descriptions of interactions between large-scale networks. Temporal trends in the occurrence of different FC states motivate theories regarding their functional roles and relationships with vigilance/arousal. Overall, we suggest that the study of time-varying aspects of FC can unveil flexibility in the functional coordination between different neural systems, and that the exploitation of these dynamics in further investigations may improve our understanding of behavioral shifts and adaptive processes.",keywords:["Dynamic functional connectivity","Functional magnetic resonance imaging","Resting state fMRI","Functional connectivity","Neuroscience","Cluster analysis","Flexibility"],concepts:["Dynamic functional connectivity","Functional magnetic resonance imaging","Resting state fMRI","Functional connectivity","Neuroscience","Computer science","Cluster analysis","Flexibility (engineering)"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://academic.oup.com/cercor/article-pdf/24/3/663/14099596/bhs352.pdf",is_oa:!0,n_refs:103,n_refs_in_core:9,degree:36,community:2,deg_w:485,betweenness:.0039,pagerank:.0043,eigenvector:.0253,pdf_file:"Allen_2012.pdf",pdf_downloaded:!0},{id:10,oaid:"W2008607322",doi:"10.1073/pnas.0911855107",title:"Toward discovery science of human brain function",authors:[{name:"Bharat B. Biswal",institutions:["Rutgers, The State University of New Jersey","Rutgers New Jersey Medical School"]},{name:"Maarten Mennes",institutions:["NYU Langone Health"]},{name:"Xi‐Nian Zuo",institutions:["NYU Langone Health"]},{name:"Suril Gohel",institutions:["Rutgers, The State University of New Jersey","Rutgers New Jersey Medical School"]},{name:"Clare Kelly",institutions:["NYU Langone Health"]},{name:"Steve M. Smith",institutions:["University of Oxford","Wellcome Centre for Integrative Neuroimaging"]},{name:"Christian F. Beckmann",institutions:["University of Oxford","Wellcome Centre for Integrative Neuroimaging"]},{name:"Jonathan S. Adelstein",institutions:["NYU Langone Health"]},{name:"Randy L. Buckner",institutions:["Howard Hughes Medical Institute","Harvard University"]},{name:"Stan Colcombe",institutions:["Bangor University"]},{name:"Anne-Marie Dogonowski",institutions:["Hvidovre Hospital","Copenhagen University Hospital"]},{name:"Monique Ernst",institutions:["National Institutes of Health","National Institute of Mental Health"]},{name:"Damien A. Fair",institutions:["Oregon Health & Science University"]},{name:"Michelle Hampson",institutions:["Yale University"]},{name:"Matthew J. Hoptman",institutions:["Nathan Kline Institute for Psychiatric Research"]},{name:"James S. Hyde",institutions:["Medical College of Wisconsin"]},{name:"Vesa Kiviniemi",institutions:["Oulu University Hospital"]},{name:"Rolf Kötter",institutions:["Radboud University Nijmegen"]},{name:"Shi‐Jiang Li",institutions:["Medical College of Wisconsin"]},{name:"Ching‐Po Lin",institutions:["National Yang Ming Chiao Tung University","National Yang Ming University Hospital"]},{name:"Mark J. Lowe",institutions:["Cleveland Clinic"]},{name:"Clare E. Mackay",institutions:["University of Oxford","Wellcome Centre for Integrative Neuroimaging"]},{name:"David J. Madden",institutions:["Duke Medical Center","Duke University Hospital"]},{name:"Kristoffer H. Madsen",institutions:["Hvidovre Hospital","Copenhagen University Hospital"]},{name:"Daniel S. Margulies",institutions:["Max Planck Institute for Human Cognitive and Brain Sciences"]},{name:"Helen S. Mayberg",institutions:["Emory University"]},{name:"Katie L. McMahon",institutions:["The University of Queensland","National Imaging Facility"]},{name:"Christopher S. Monk",institutions:["University of Michigan"]},{name:"Stewart H. Mostofsky",institutions:["Kennedy Krieger Institute"]},{name:"Bonnie J. Nagel",institutions:["Oregon Health & Science University"]},{name:"James J. Pekar",institutions:["Kennedy Krieger Institute"]},{name:"Scott Peltier",institutions:["University of Michigan"]},{name:"Steven E. Petersen",institutions:["Hope Center for Neurological Disorders"]},{name:"Valentin Riedl",institutions:["TUM Klinikum","Technical University of Munich"]},{name:"Serge A.R.B. Rombouts",institutions:["Leiden University Medical Center"]},{name:"Bart Rypma",institutions:["The University of Texas at Dallas"]},{name:"Bradley L. Schlaggar",institutions:["Washington University in St. Louis"]},{name:"Sein Schmidt",institutions:["Charité - Universitätsmedizin Berlin"]},{name:"Rachael D. Seidler",institutions:["University of Michigan"]},{name:"Greg J. Siegle",institutions:["University of Pittsburgh"]},{name:"Christian Sorg",institutions:["TUM Klinikum","Technical University of Munich"]},{name:"Gao‐Jun Teng",institutions:["Zhongda Hospital Southeast University"]},{name:"Juha Veijola",institutions:["University of Oulu"]},{name:"Arno Villringer",institutions:["Charité - Universitätsmedizin Berlin"]},{name:"Martin Walter",institutions:["Otto-von-Guericke-Universität Magdeburg"]},{name:"Lihong Wang",institutions:["Duke Medical Center","Duke University Hospital"]},{name:"Xu-Chu Weng",institutions:["Chinese Academy of Sciences","Institute of Psychology, Chinese Academy of Sciences"]},{name:"Susan Whitfield‐Gabrieli",institutions:["Harvard–MIT Division of Health Sciences and Technology","Massachusetts Institute of Technology"]},{name:"Peter Williamson",institutions:["Western University"]},{name:"Christian Windischberger",institutions:["Medical University of Vienna"]},{name:"Yu‐Feng Zang",institutions:["Beijing Normal University"]},{name:"Hong-Ying Zhang",institutions:["Zhongda Hospital Southeast University"]},{name:"F. Xavier Castellanos",institutions:["Nathan Kline Institute for Psychiatric Research","NYU Langone Health"]},{name:"Michael P. Milham",institutions:["NYU Langone Health"]}],authorString:"Bharat B. Biswal; Maarten Mennes; Xi‐Nian Zuo; Suril Gohel; Clare Kelly; Steve M. Smith; Christian F. Beckmann; Jonathan S. Adelstein; Randy L. Buckner; Stan Colcombe; Anne-Marie Dogonowski; Monique Ernst et al.",institutions:["Bangor University","Beijing Normal University","Charité - Universitätsmedizin Berlin","Chinese Academy of Sciences","Cleveland Clinic","Copenhagen University Hospital","Duke Medical Center","Duke University Hospital","Emory University","Harvard University","Harvard–MIT Division of Health Sciences and Technology","Hope Center for Neurological Disorders","Howard Hughes Medical Institute","Hvidovre Hospital","Institute of Psychology, Chinese Academy of Sciences","Kennedy Krieger Institute","Leiden University Medical Center","Massachusetts Institute of Technology","Max Planck Institute for Human Cognitive and Brain Sciences","Medical College of Wisconsin","Medical University of Vienna","NYU Langone Health","Nathan Kline Institute for Psychiatric Research","National Imaging Facility","National Institute of Mental Health","National Institutes of Health","National Yang Ming Chiao Tung University","National Yang Ming University Hospital","Oregon Health & Science University","Otto-von-Guericke-Universität Magdeburg","Oulu University Hospital","Radboud University Nijmegen","Rutgers New Jersey Medical School","Rutgers, The State University of New Jersey","TUM Klinikum","Technical University of Munich","The University of Queensland","The University of Texas at Dallas","University of Michigan","University of Oulu","University of Oxford","University of Pittsburgh","Washington University in St. Louis","Wellcome Centre for Integrative Neuroimaging","Western University","Yale University","Zhongda Hospital Southeast University"],countries:["AT","AU","CA","CN","DE","DK","FI","GB","NL","TW","US"],year:2010,journal:"Proceedings of the National Academy of Sciences",citations:3098,abstract:`Although it is being successfully implemented for exploration of the genome, discovery science has eluded the functional neuroimaging community. The core challenge remains the development of common paradigms for interrogating the myriad functional systems in the brain without the constraints of a priori hypotheses. Resting-state functional MRI (R-fMRI) constitutes a candidate approach capable of addressing this challenge. Imaging the brain during rest reveals large-amplitude spontaneous low-frequency (<0.1 Hz) fluctuations in the fMRI signal that are temporally correlated across functionally related areas. Referred to as functional connectivity, these correlations yield detailed maps of complex neural systems, collectively constituting an individual's "functional connectome." Reproducibility across datasets and individuals suggests the functional connectome has a common architecture, yet each individual's functional connectome exhibits unique features, with stable, meaningful interindividual differences in connectivity patterns and strengths. Comprehensive mapping of the functional connectome, and its subsequent exploitation to discern genetic influences and brain-behavior relationships, will require multicenter collaborative datasets. Here we initiate this endeavor by gathering R-fMRI data from 1,414 volunteers collected independently at 35 international centers. We demonstrate a universal architecture of positive and negative functional connections, as well as consistent loci of inter-individual variability. Age and sex emerged as significant determinants. These results demonstrate that independent R-fMRI datasets can be aggregated and shared. High-throughput R-fMRI can provide quantitative phenotypes for molecular genetic studies and biomarkers of developmental and pathological processes in the brain. To initiate discovery science of brain function, the 1000 Functional Connectomes Project dataset is freely accessible at www.nitrc.org/projects/fcon_1000/.`,keywords:["Human Connectome Project","Connectome","Neuroimaging","Functional connectivity","Resting state fMRI","Neuroscience","Connectomics","Drug discovery"],concepts:["Human Connectome Project","Connectome","Neuroimaging","Functional connectivity","Resting state fMRI","Neuroscience","Connectomics","Drug discovery"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"https://www.ncbi.nlm.nih.gov/pmc/articles/2842060",is_oa:!0,n_refs:52,n_refs_in_core:10,degree:52,community:2,deg_w:764.5,betweenness:.0065,pagerank:.00596,eigenvector:.0605,pdf_file:"Biswal_2010.pdf",pdf_downloaded:!0},{id:11,oaid:"W2126650951",doi:"10.1523/jneurosci.5062-08.2009",title:"Cortical Hubs Revealed by Intrinsic Functional Connectivity: Mapping, Assessment of Stability, and Relation to Alzheimer's Disease",authors:[{name:"Randy L. Buckner",institutions:["Harvard University"]},{name:"Jorge Sepulcre",institutions:["Harvard University","Athinoula A. Martinos Center for Biomedical Imaging","University Radiology"]},{name:"Tanveer Talukdar",institutions:["Athinoula A. Martinos Center for Biomedical Imaging","University Radiology"]},{name:"Fenna M. Krienen",institutions:["Harvard University","Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Hesheng Liu",institutions:["Athinoula A. Martinos Center for Biomedical Imaging","University Radiology"]},{name:"Trey Hedden",institutions:["Harvard University","Athinoula A. Martinos Center for Biomedical Imaging","University Radiology"]},{name:"Jessica R. Andrews‐Hanna",institutions:["Harvard University","Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Reisa A. Sperling",institutions:["Brigham and Women's Hospital","Harvard University","Athinoula A. Martinos Center for Biomedical Imaging","University Radiology"]},{name:"Keith A. Johnson",institutions:["Brigham and Women's Hospital","Harvard University","Massachusetts General Hospital","University Radiology"]}],authorString:"Randy L. Buckner; Jorge Sepulcre; Tanveer Talukdar; Fenna M. Krienen; Hesheng Liu; Trey Hedden; Jessica R. Andrews‐Hanna; Reisa A. Sperling; Keith A. Johnson",institutions:["Athinoula A. Martinos Center for Biomedical Imaging","Brigham and Women's Hospital","Harvard University","Massachusetts General Hospital","University Radiology"],countries:["US"],year:2009,journal:"Journal of Neuroscience",citations:2955,abstract:"Recent evidence suggests that some brain areas act as hubs interconnecting distinct, functionally specialized systems. These nexuses are intriguing because of their potential role in integration and also because they may augment metabolic cascades relevant to brain disease. To identify regions of high connectivity in the human cerebral cortex, we applied a computationally efficient approach to map the degree of intrinsic functional connectivity across the brain. Analysis of two separate functional magnetic resonance imaging datasets (each n = 24) demonstrated hubs throughout heteromodal areas of association cortex. Prominent hubs were located within posterior cingulate, lateral temporal, lateral parietal, and medial/lateral prefrontal cortices. Network analysis revealed that many, but not all, hubs were located within regions previously implicated as components of the default network. A third dataset (n = 12) demonstrated that the locations of hubs were present across passive and active task states, suggesting that they reflect a stable property of cortical network architecture. To obtain an accurate reference map, data were combined across 127 participants to yield a consensus estimate of cortical hubs. Using this consensus estimate, we explored whether the topography of hubs could explain the pattern of vulnerability in Alzheimer's disease (AD) because some models suggest that regions of high activity and metabolism accelerate pathology. Positron emission tomography amyloid imaging in AD (n = 10) compared with older controls (n = 29) showed high amyloid-beta deposition in the locations of cortical hubs consistent with the possibility that hubs, while acting as critical way stations for information processing, may also augment the underlying pathological cascade in AD.",keywords:["Neuroscience","Default mode network","Functional magnetic resonance imaging","Posterior parietal cortex","Posterior cingulate","Neuroimaging","Prefrontal cortex"],concepts:["Neuroscience","Default mode network","Functional magnetic resonance imaging","Posterior parietal cortex","Posterior cingulate","Neuroimaging","Psychology","Prefrontal cortex"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Neural dynamics and brain function"],pdf_url:"https://www.jneurosci.org/content/jneuro/29/6/1860.full.pdf",is_oa:!0,n_refs:94,n_refs_in_core:8,degree:81,community:2,deg_w:1347,betweenness:.0176,pagerank:.00959,eigenvector:.1301,pdf_file:"Buckner_2009.pdf",pdf_downloaded:!0},{id:12,oaid:"W2016954751",doi:"10.1073/pnas.0704320104",title:"Distinct brain networks for adaptive and stable task control in humans",authors:[{name:"Nico U.F. Dosenbach",institutions:[]},{name:"Damien A. Fair",institutions:["Neurology, Inc"]},{name:"Francis M. Miezin",institutions:["Neurology, Inc"]},{name:"Alexander L. Cohen",institutions:[]},{name:"Kristin K. Wenger",institutions:["Neurology, Inc"]},{name:"Ronny A. T. Dosenbach",institutions:["Neurology, Inc"]},{name:"Michael Fox",institutions:[]},{name:"Abraham Z. Snyder",institutions:["Neurology, Inc"]},{name:"Justin L. Vincent",institutions:[]},{name:"Marcus E. Raichle",institutions:["Neurology, Inc"]},{name:"Bradley L. Schlaggar",institutions:["Pediatrics and Genetics","Neurology, Inc"]},{name:"Steven E. Petersen",institutions:["Washington University in St. Louis","Pediatrics and Genetics","Neurology, Inc"]}],authorString:"Nico U.F. Dosenbach; Damien A. Fair; Francis M. Miezin; Alexander L. Cohen; Kristin K. Wenger; Ronny A. T. Dosenbach; Michael Fox; Abraham Z. Snyder; Justin L. Vincent; Marcus E. Raichle; Bradley L. Schlaggar; Steven E. Petersen",institutions:["Neurology, Inc","Pediatrics and Genetics","Washington University in St. Louis"],countries:["US"],year:2007,journal:"Proceedings of the National Academy of Sciences",citations:2757,abstract:"Control regions in the brain are thought to provide signals that configure the brain's moment-to-moment information processing. Previously, we identified regions that carried signals related to task-control initiation, maintenance, and adjustment. Here we characterize the interactions of these regions by applying graph theory to resting state functional connectivity MRI data. In contrast to previous, more unitary models of control, this approach suggests the presence of two distinct task-control networks. A frontoparietal network included the dorsolateral prefrontal cortex and intraparietal sulcus. This network emphasized start-cue and error-related activity and may initiate and adapt control on a trial-by-trial basis. The second network included dorsal anterior cingulate/medial superior frontal cortex, anterior insula/frontal operculum, and anterior prefrontal cortex. Among other signals, these regions showed activity sustained across the entire task epoch, suggesting that this network may control goal-directed behavior through the stable maintenance of task sets. These two independent networks appear to operate on different time scales and affect downstream processing via dissociable mechanisms.",keywords:["Intraparietal sulcus","Neuroscience","Anterior cingulate cortex","Dorsolateral prefrontal cortex","Task","Sulcus","Prefrontal cortex"],concepts:["Intraparietal sulcus","Neuroscience","Anterior cingulate cortex","Dorsolateral prefrontal cortex","Task (project management)","Sulcus","Prefrontal cortex","Psychology"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Neural and Behavioral Psychology Studies"],pdf_url:"https://www.ncbi.nlm.nih.gov/pmc/articles/1904171",is_oa:!0,n_refs:58,n_refs_in_core:3,degree:35,community:2,deg_w:412.5,betweenness:.0026,pagerank:.00357,eigenvector:.0344,pdf_file:"Dosenbach_2007.pdf",pdf_downloaded:!0},{id:13,oaid:"W1979426401",doi:"10.1177/1073858406293182",title:"Small-World Brain Networks",authors:[{name:"Danielle S. Bassett",institutions:["National Institutes of Health","University of Cambridge","Addenbrooke's Hospital","National Institute of Mental Health"]},{name:"Edward T. Bullmore",institutions:["University of Cambridge","Addenbrooke's Hospital"]}],authorString:"Danielle S. Bassett; Edward T. Bullmore",institutions:["Addenbrooke's Hospital","National Institute of Mental Health","National Institutes of Health","University of Cambridge"],countries:["GB","US"],year:2006,journal:"The Neuroscientist",citations:2687,abstract:"Many complex networks have a small-world topology characterized by dense local clustering or cliquishness of connections between neighboring nodes yet a short path length between any (distant) pair of nodes due to the existence of relatively few long-range connections. This is an attractive model for the organization of brain anatomical and functional networks because a small-world topology can support both segregated/specialized and distributed/integrated information processing. Moreover, small-world networks are economical, tending to minimize wiring costs while supporting high dynamical complexity. The authors introduce some of the key mathematical concepts in graph theory required for small-world analysis and review how these methods have been applied to quantification of cortical connectivity matrices derived from anatomical tract-tracing studies in the macaque monkey and the cat. The evolution of small-world networks is discussed in terms of a selection pressure to deliver cost-effective information-processing systems. The authors illustrate how these techniques and concepts are increasingly being applied to the analysis of human brain functional networks derived from electroencephalography/magnetoencephalography and fMRI experiments. Finally, the authors consider the relevance of small-world models for understanding the emergence of complex behaviors and the resilience of brain systems to pathological attack by disease or aberrant development. They conclude that small-world models provide a powerful and versatile approach to understanding the structure and function of human brain systems.",keywords:["Small-world network","Complex network","Magnetoencephalography","Network topology","Neuroscience","Distributed computing"],concepts:["Small-world network","Computer science","Complex network","Magnetoencephalography","Network topology","Neuroscience","Artificial intelligence","Distributed computing"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Complex Network Analysis Techniques"],pdf_url:null,is_oa:!1,n_refs:68,n_refs_in_core:3,degree:68,community:1,deg_w:1051,betweenness:.009,pagerank:.00737,eigenvector:.1195,pdf_file:null,pdf_downloaded:!1},{id:14,oaid:"W1974764791",doi:"10.1371/journal.pcbi.0030017",title:"Efficiency and Cost of Economical Brain Functional Networks",authors:[{name:"Sophie Achard",institutions:["University of Cambridge","Addenbrooke's Hospital"]},{name:"Edward T. Bullmore",institutions:["University of Cambridge","Addenbrooke's Hospital"]}],authorString:"Sophie Achard; Edward T. Bullmore",institutions:["Addenbrooke's Hospital","University of Cambridge"],countries:["GB"],year:2007,journal:"PLoS Computational Biology",citations:2615,abstract:'Brain anatomical networks are sparse, complex, and have economical small-world properties. We investigated the efficiency and cost of human brain functional networks measured using functional magnetic resonance imaging (fMRI) in a factorial design: two groups of healthy old (N = 11; mean age = 66.5 years) and healthy young (N = 15; mean age = 24.7 years) volunteers were each scanned twice in a no-task or "resting" state following placebo or a single dose of a dopamine receptor antagonist (sulpiride 400 mg). Functional connectivity between 90 cortical and subcortical regions was estimated by wavelet correlation analysis, in the frequency interval 0.06-0.11 Hz, and thresholded to construct undirected graphs. These brain functional networks were small-world and economical in the sense of providing high global and local efficiency of parallel information processing for low connection cost. Efficiency was reduced disproportionately to cost in older people, and the detrimental effects of age on efficiency were localised to frontal and temporal cortical and subcortical regions. Dopamine antagonism also impaired global and local efficiency of the network, but this effect was differentially localised and did not interact with the effect of age. Brain functional networks have economical small-world properties-supporting efficient parallel information transfer at relatively low cost-which are differently impaired by normal aging and pharmacological blockade of dopamine transmission.',keywords:["Functional magnetic resonance imaging","Human brain","Dopamine","Neuroscience","Resting state fMRI"],concepts:["Functional magnetic resonance imaging","Human brain","Dopamine","Neuroscience","Resting state fMRI","Computer science","Psychology"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.0030017&type=printable",is_oa:!0,n_refs:55,n_refs_in_core:6,degree:94,community:1,deg_w:1525.5,betweenness:.0186,pagerank:.01052,eigenvector:.1607,pdf_file:"Achard_2007.pdf",pdf_downloaded:!0},{id:15,oaid:"W2012559638",doi:"10.1523/jneurosci.3539-11.2011",title:"Rich-Club Organization of the Human Connectome",authors:[{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]}],authorString:"Martijn P. van den Heuvel; Olaf Sporns",institutions:["Indiana University Bloomington","University Medical Center Utrecht"],countries:["NL","US"],year:2011,journal:"Journal of Neuroscience",citations:2489,abstract:'The human brain is a complex network of interlinked regions. Recent studies have demonstrated the existence of a number of highly connected and highly central neocortical hub regions, regions that play a key role in global information integration between different parts of the network. The potential functional importance of these "brain hubs" is underscored by recent studies showing that disturbances of their structural and functional connectivity profile are linked to neuropathology. This study aims to map out both the subcortical and neocortical hubs of the brain and examine their mutual relationship, particularly their structural linkages. Here, we demonstrate that brain hubs form a so-called "rich club," characterized by a tendency for high-degree nodes to be more densely connected among themselves than nodes of a lower degree, providing important information on the higher-level topology of the brain network. Whole-brain structural networks of 21 subjects were reconstructed using diffusion tensor imaging data. Examining the connectivity profile of these networks revealed a group of 12 strongly interconnected bihemispheric hub regions, comprising the precuneus, superior frontal and superior parietal cortex, as well as the subcortical hippocampus, putamen, and thalamus. Importantly, these hub regions were found to be more densely interconnected than would be expected based solely on their degree, together forming a rich club. We discuss the potential functional implications of the rich-club organization of the human connectome, particularly in light of its role in information integration and in conferring robustness to its structural core.',keywords:["Connectome","Neuroscience","Human brain","Precuneus","Thalamus","Functional connectivity"],concepts:["Connectome","Neuroscience","Human brain","Precuneus","Thalamus","Computer science","Psychology"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/31/44/15775.full.pdf",is_oa:!0,n_refs:63,n_refs_in_core:16,degree:107,community:0,deg_w:1827,betweenness:.0329,pagerank:.01308,eigenvector:.1414,pdf_file:null,pdf_downloaded:!1},{id:16,oaid:"W1987924998",doi:"10.1523/jneurosci.3874-05.2006",title:"A Resilient, Low-Frequency, Small-World Human Brain Functional Network with Highly Connected Association Cortical Hubs",authors:[{name:"Sophie Achard",institutions:["Addenbrooke's Hospital"]},{name:"Raymond Salvador",institutions:["University of Cambridge","Parc Sanitari Sant Joan de Déu","Addenbrooke's Hospital"]},{name:"Brandon Whitcher",institutions:["GlaxoSmithKline (United Kingdom)"]},{name:"John Suckling",institutions:["University of Cambridge","Addenbrooke's Hospital"]},{name:"Edward T. Bullmore",institutions:["GlaxoSmithKline (United Kingdom)","University of Cambridge","Addenbrooke's Hospital"]}],authorString:"Sophie Achard; Raymond Salvador; Brandon Whitcher; John Suckling; Edward T. Bullmore",institutions:["Addenbrooke's Hospital","GlaxoSmithKline (United Kingdom)","Parc Sanitari Sant Joan de Déu","University of Cambridge"],countries:["ES","GB"],year:2006,journal:"Journal of Neuroscience",citations:2478,abstract:"Small-world properties have been demonstrated for many complex networks. Here, we applied the discrete wavelet transform to functional magnetic resonance imaging (fMRI) time series, acquired from healthy volunteers in the resting state, to estimate frequency-dependent correlation matrices characterizing functional connectivity between 90 cortical and subcortical regions. After thresholding the wavelet correlation matrices to create undirected graphs of brain functional networks, we found a small-world topology of sparse connections most salient in the low-frequency interval 0.03-0.06 Hz. Global mean path length (2.49) was approximately equivalent to a comparable random network, whereas clustering (0.53) was two times greater; similar parameters have been reported for the network of anatomical connections in the macaque cortex. The human functional network was dominated by a neocortical core of highly connected hubs and had an exponentially truncated power law degree distribution. Hubs included recently evolved regions of the heteromodal association cortex, with long-distance connections to other regions, and more cliquishly connected regions of the unimodal association and primary cortices; paralimbic and limbic regions were topologically more peripheral. The network was more resilient to targeted attack on its hubs than a comparable scale-free network, but about equally resilient to random error. We conclude that correlated, low-frequency oscillations in human fMRI data have a small-world architecture that probably reflects underlying anatomical connectivity of the cortex. Because the major hubs of this network are critical for cognition, its slow dynamics could provide a physiological substrate for segregated and distributed information processing.",keywords:["Neuroscience","Small-world network","Human brain","Functional magnetic resonance imaging","Cortex","Average path length","Thresholding"],concepts:["Neuroscience","Small-world network","Human brain","Functional magnetic resonance imaging","Cortex (anatomy)","Computer science","Average path length","Thresholding"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"https://www.jneurosci.org/content/jneuro/26/1/63.full.pdf",is_oa:!0,n_refs:44,n_refs_in_core:2,degree:117,community:1,deg_w:1825,betweenness:.0355,pagerank:.01256,eigenvector:.1867,pdf_file:"Achard_2006.pdf",pdf_downloaded:!0},{id:17,oaid:"W2063404606",doi:"10.1126/science.1194144",title:"Prediction of Individual Brain Maturity Using fMRI",authors:[{name:"Nico U.F. Dosenbach",institutions:["Washington University in St. Louis"]},{name:"Binyam Nardos",institutions:["Washington University in St. Louis"]},{name:"Alexander L. Cohen",institutions:["Washington University in St. Louis"]},{name:"Damien A. Fair",institutions:["Oregon Health & Science University"]},{name:"Jonathan D. Power",institutions:["Washington University in St. Louis"]},{name:"Jessica A. Church",institutions:["Washington University in St. Louis"]},{name:"Steven M. Nelson",institutions:["Washington University in St. Louis"]},{name:"Gagan S. Wig",institutions:["Harvard University","Washington University in St. Louis","Massachusetts General Hospital","Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Alecia C. Vogel",institutions:["Washington University in St. Louis"]},{name:"Christina N. Lessov‐Schlaggar",institutions:["Washington University in St. Louis"]},{name:"Kelly A. Barnes",institutions:["Washington University in St. Louis"]},{name:"Joseph W. Dubis",institutions:["Washington University in St. Louis"]},{name:"Eric Feczko",institutions:["Washington University in St. Louis"]},{name:"Rebecca S. Coalson",institutions:["Washington University in St. Louis"]},{name:"John R. Pruett",institutions:["Washington University in St. Louis"]},{name:"Deanna M. Barch",institutions:["Washington University in St. Louis"]},{name:"Steven E. Petersen",institutions:["Washington University in St. Louis"]},{name:"Bradley L. Schlaggar",institutions:["Washington University in St. Louis"]}],authorString:"Nico U.F. Dosenbach; Binyam Nardos; Alexander L. Cohen; Damien A. Fair; Jonathan D. Power; Jessica A. Church; Steven M. Nelson; Gagan S. Wig; Alecia C. Vogel; Christina N. Lessov‐Schlaggar; Kelly A. Barnes; Joseph W. Dubis et al.",institutions:["Athinoula A. Martinos Center for Biomedical Imaging","Harvard University","Massachusetts General Hospital","Oregon Health & Science University","Washington University in St. Louis"],countries:["US"],year:2010,journal:"Science",citations:2304,abstract:"Group functional connectivity magnetic resonance imaging (fcMRI) studies have documented reliable changes in human functional brain maturity over development. Here we show that support vector machine-based multivariate pattern analysis extracts sufficient information from fcMRI data to make accurate predictions about individuals' brain maturity across development. The use of only 5 minutes of resting-state fcMRI data from 238 scans of typically developing volunteers (ages 7 to 30 years) allowed prediction of individual brain maturity as a functional connectivity maturation index. The resultant functional maturation curve accounted for 55% of the sample variance and followed a nonlinear asymptotic growth curve shape. The greatest relative contribution to predicting individual brain maturity was made by the weakening of short-range functional connections between the adult brain's major functional networks.",keywords:["White matter","Neuroscience","Resting state fMRI","Functional magnetic resonance imaging","Human brain","Brain mapping","Functional connectivity"],concepts:["White matter","Neuroscience","Psychology","Resting state fMRI","Functional magnetic resonance imaging","Human brain","Brain mapping","Functional connectivity"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.ncbi.nlm.nih.gov/pmc/articles/3135376",is_oa:!0,n_refs:36,n_refs_in_core:6,degree:40,community:2,deg_w:378,betweenness:.004,pagerank:.00331,eigenvector:.0283,pdf_file:null,pdf_downloaded:!1},{id:18,oaid:"W2106396500",doi:"10.1093/cercor/bhn059",title:"Resting-State Functional Connectivity Reflects Structural Connectivity in the Default Mode Network",authors:[{name:"Michael D. Greicius",institutions:["Stanford University"]},{name:"Kaustubh Supekar",institutions:["Stanford University"]},{name:"Vinod Menon",institutions:["Stanford University"]},{name:"Robert F. Dougherty",institutions:["Stanford University"]}],authorString:"Michael D. Greicius; Kaustubh Supekar; Vinod Menon; Robert F. Dougherty",institutions:["Stanford University"],countries:["US"],year:2008,journal:"Cerebral Cortex",citations:2229,abstract:"Resting-state functional connectivity magnetic resonance imaging (fcMRI) studies constitute a growing proportion of functional brain imaging publications. This approach detects temporal correlations in spontaneous blood oxygen level-dependent (BOLD) signal oscillations while subjects rest quietly in the scanner. Although distinct resting-state networks related to vision, language, executive processing, and other sensory and cognitive domains have been identified, considerable skepticism remains as to whether resting-state functional connectivity maps reflect neural connectivity or simply track BOLD signal correlations driven by nonneural artifact. Here we combine diffusion tensor imaging (DTI) tractography with resting-state fcMRI to test the hypothesis that resting-state functional connectivity reflects structural connectivity. These 2 modalities were used to investigate connectivity within the default mode network, a set of brain regions--including medial prefrontal cortex (MPFC), medial temporal lobes (MTLs), and posterior cingulate cortex (PCC)/retropslenial cortex (RSC)--implicated in episodic memory processing. Using seed regions from the functional connectivity maps, the DTI analysis revealed robust structural connections between the MTLs and the retrosplenial cortex whereas tracts from the MPFC contacted the PCC (just rostral to the RSC). The results demonstrate that resting-state functional connectivity reflects structural connectivity and that combining modalities can enrich our understanding of these canonical brain networks.",keywords:["Default mode network","Resting state fMRI","Neuroscience","Posterior cingulate","Functional magnetic resonance imaging","Prefrontal cortex","Retrosplenial cortex","Diffusion MRI"],concepts:["Default mode network","Resting state fMRI","Neuroscience","Posterior cingulate","Functional magnetic resonance imaging","Prefrontal cortex","Retrosplenial cortex","Diffusion MRI"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"http://doi.org/10.1093/cercor/bhn059",is_oa:!0,n_refs:60,n_refs_in_core:4,degree:51,community:2,deg_w:576,betweenness:.008,pagerank:.00481,eigenvector:.0427,pdf_file:null,pdf_downloaded:!1},{id:19,oaid:"W1994341528",doi:"10.1126/science.1238411",title:"Structural and Functional Brain Networks: From Connections to Cognition",authors:[{name:"Hae‐Jeong Park",institutions:["Yonsei University","Severance Hospital"]},{name:"Karl Friston",institutions:["Wellcome Centre for Human Neuroimaging","National Hospital for Neurology and Neurosurgery","University College London"]}],authorString:"Hae‐Jeong Park; Karl Friston",institutions:["National Hospital for Neurology and Neurosurgery","Severance Hospital","University College London","Wellcome Centre for Human Neuroimaging","Yonsei University"],countries:["GB","KR"],year:2013,journal:"Science",citations:2185,abstract:"How rich functionality emerges from the invariant structural architecture of the brain remains a major mystery in neuroscience. Recent applications of network theory and theoretical neuroscience to large-scale brain networks have started to dissolve this mystery. Network analyses suggest that hierarchical modular brain networks are particularly suited to facilitate local (segregated) neuronal operations and the global integration of segregated functions. Although functional networks are constrained by structural connections, context-sensitive integration during cognition tasks necessarily entails a divergence between structural and functional networks. This degenerate (many-to-one) function-structure mapping is crucial for understanding the nature of brain networks. The emergence of dynamic functional networks from static structural connections calls for a formal (computational) approach to neuronal information processing that may resolve this dialectic between structure and function.",keywords:["Neuroscience","Cognitive science","Modular design","Cognition","Context","Computational neuroscience"],concepts:["Neuroscience","Cognitive science","Computer science","Modular design","Cognition","Context (archaeology)","Computational neuroscience"],topics:["Neural dynamics and brain function","Functional Brain Connectivity Studies","Plant and Biological Electrophysiology Studies"],pdf_url:"https://ir.ymlib.yonsei.ac.kr/handle/22282913/88987",is_oa:!0,n_refs:50,n_refs_in_core:9,degree:33,community:0,deg_w:273,betweenness:.0031,pagerank:.00273,eigenvector:.0134,pdf_file:null,pdf_downloaded:!1},{id:20,oaid:"W2158592797",doi:"10.1523/jneurosci.2177-05.2005",title:"Molecular, Structural, and Functional Characterization of Alzheimer's Disease: Evidence for a Relationship between Default Activity, Amyloid, and Memory",authors:[{name:"Randy L. Buckner",institutions:["Howard Hughes Medical Institute","Institute of Neurobiology","Mallinckrodt (Ireland)"]},{name:"Abraham Z. Snyder",institutions:["Mallinckrodt (Ireland)"]},{name:"Benjamin J. Shannon",institutions:[]},{name:"Gina LaRossa",institutions:["Mallinckrodt (Ireland)"]},{name:"Rimmon Sachs",institutions:["Mallinckrodt (Ireland)"]},{name:"Anthony F. Fotenos",institutions:[]},{name:"Yvette I. Sheline",institutions:["Mallinckrodt (Ireland)"]},{name:"William E. Klunk",institutions:["University of Pittsburgh"]},{name:"Chester A. Mathis",institutions:["University of Pittsburgh"]},{name:"John C. Morris",institutions:["Washington University in St. Louis"]},{name:"Mark A. Mintun",institutions:["Mallinckrodt (Ireland)"]}],authorString:"Randy L. Buckner; Abraham Z. Snyder; Benjamin J. Shannon; Gina LaRossa; Rimmon Sachs; Anthony F. Fotenos; Yvette I. Sheline; William E. Klunk; Chester A. Mathis; John C. Morris; Mark A. Mintun",institutions:["Howard Hughes Medical Institute","Institute of Neurobiology","Mallinckrodt (Ireland)","University of Pittsburgh","Washington University in St. Louis"],countries:["BG","IE","US"],year:2005,journal:"Journal of Neuroscience",citations:2157,abstract:"Alzheimer's disease (AD) and antecedent factors associated with AD were explored using amyloid imaging and unbiased measures of longitudinal atrophy in combination with reanalysis of previous metabolic and functional studies. In total, data from 764 participants were compared across five in vivo imaging methods. Convergence of effects was seen in posterior cortical regions, including posterior cingulate, retrosplenial, and lateral parietal cortex. These regions were active in default states in young adults and also showed amyloid deposition in older adults with AD. At early stages of AD progression, prominent atrophy and metabolic abnormalities emerged in these posterior cortical regions; atrophy in medial temporal regions was also observed. Event-related functional magnetic resonance imaging studies further revealed that these cortical regions are active during successful memory retrieval in young adults. One possibility is that lifetime cerebral metabolism associated with regionally specific default activity predisposes cortical regions to AD-related changes, including amyloid deposition, metabolic disruption, and atrophy. These cortical regions may be part of a network with the medial temporal lobe whose disruption contributes to memory impairment.",keywords:["Posterior cingulate","Atrophy","Default mode network","Neuroscience","Retrosplenial cortex","Posterior cortical atrophy","Temporal lobe","Functional magnetic resonance imaging"],concepts:["Posterior cingulate","Atrophy","Default mode network","Neuroscience","Retrosplenial cortex","Posterior cortical atrophy","Temporal lobe","Functional magnetic resonance imaging"],topics:["Dementia and Cognitive Impairment Research","Alzheimer's disease research and treatments","Functional Brain Connectivity Studies"],pdf_url:"https://www.jneurosci.org/content/jneuro/25/34/7709.full.pdf",is_oa:!0,n_refs:96,n_refs_in_core:0,degree:24,community:2,deg_w:244,betweenness:.0011,pagerank:.00248,eigenvector:.0164,pdf_file:"Buckner_2005.pdf",pdf_downloaded:!0},{id:21,oaid:"W2036785860",doi:"10.1002/nbm.781",title:"Fiber tracking: principles and strategies – a technical review",authors:[{name:"Susumu Mori",institutions:["Kennedy Krieger Institute","Johns Hopkins University","Johns Hopkins Medicine"]},{name:"Peter C.M. van Zijl",institutions:["Kennedy Krieger Institute","Johns Hopkins University"]}],authorString:"Susumu Mori; Peter C.M. van Zijl",institutions:["Johns Hopkins Medicine","Johns Hopkins University","Kennedy Krieger Institute"],countries:["US"],year:2002,journal:"NMR in Biomedicine",citations:2034,abstract:"The state of the art of reconstruction of the axonal tracts in the central nervous system (CNS) using diffusion tensor imaging (DTI) is reviewed. This relatively new technique has generated much enthusiasm and high expectations because it presently is the only approach available to non-invasively study the three-dimensional architecture of white matter tracts. While there is no doubt that DTI fiber tracking is providing exciting new opportunities to study CNS anatomy, it is very important to understand its limitations. In this review we therefore assess the basic principles and the assumptions that need to be made for each step of the study, including both data acquisition and the elaborate fiber reconstruction algorithms. Special attention is paid to situations where complications may arise, and possible solutions are reviewed. Validation issues and potential future directions and improvements are also discussed.",keywords:["Diffusion MRI","Neuroscience","Fiber","Tracking","White matter","Data science","Fiber tract"],concepts:["Diffusion MRI","Computer science","Neuroscience","Fiber","Tracking (education)","White matter","Data science","Fiber tract"],topics:["Advanced Neuroimaging Techniques and Applications","Cerebral Palsy and Movement Disorders","Botulinum Toxin and Related Neurological Disorders"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/nbm.781",is_oa:!0,n_refs:59,n_refs_in_core:0,degree:24,community:0,deg_w:169,betweenness:.001,pagerank:.00191,eigenvector:.0148,pdf_file:null,pdf_downloaded:!1},{id:22,oaid:"W2101219946",doi:"10.1093/cercor/bhr099",title:"Decoding Subject-Driven Cognitive States with Whole-Brain Connectivity Patterns",authors:[{name:"William R. Shirer",institutions:["Stanford Medicine","Stanford University"]},{name:"Srikanth Ryali",institutions:[]},{name:"Elena Rykhlevskaia",institutions:[]},{name:"Vinod Menon",institutions:["Stanford Medicine"]},{name:"Michael D. Greicius",institutions:["Stanford Medicine"]}],authorString:"William R. Shirer; Srikanth Ryali; Elena Rykhlevskaia; Vinod Menon; Michael D. Greicius",institutions:["Stanford Medicine","Stanford University"],countries:["US"],year:2011,journal:"Cerebral Cortex",citations:1942,abstract:"Decoding specific cognitive states from brain activity constitutes a major goal of neuroscience. Previous studies of brain-state classification have focused largely on decoding brief, discrete events and have required the timing of these events to be known. To date, methods for decoding more continuous and purely subject-driven cognitive states have not been available. Here, we demonstrate that free-streaming subject-driven cognitive states can be decoded using a novel whole-brain functional connectivity analysis. Ninety functional regions of interest (ROIs) were defined across 14 large-scale resting-state brain networks to generate a 3960 cell matrix reflecting whole-brain connectivity. We trained a classifier to identify specific patterns of whole-brain connectivity as subjects rested quietly, remembered the events of their day, subtracted numbers, or (silently) sang lyrics. In a leave-one-out cross-validation, the classifier identified these 4 cognitive states with 84% accuracy. More critically, the classifier achieved 85% accuracy when identifying these states in a second, independent cohort of subjects. Classification accuracy remained high with imaging runs as short as 30-60 s. At all temporal intervals assessed, the 90 functionally defined ROIs outperformed a set of 112 commonly used structural ROIs in classifying cognitive states. This approach should enable decoding a myriad of subject-driven cognitive states from brief imaging data samples.",keywords:["Decoding methods","Cognition","Classifier","Neuroimaging","Resting state fMRI","Brain activity and meditation"],concepts:["Decoding methods","Cognition","Computer science","Classifier (UML)","Neuroimaging","Resting state fMRI","Artificial intelligence","Brain activity and meditation"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://academic.oup.com/cercor/article-pdf/22/1/158/14096754/bhr099.pdf",is_oa:!0,n_refs:62,n_refs_in_core:7,degree:27,community:2,deg_w:296,betweenness:.0014,pagerank:.00296,eigenvector:.0127,pdf_file:null,pdf_downloaded:!1},{id:23,oaid:"W2122457251",doi:"10.1002/hbm.21333",title:"A whole brain fMRI atlas generated via spatially constrained spectral clustering",authors:[{name:"R. Cameron Craddock",institutions:["Baylor College of Medicine"]},{name:"G. Andrew James",institutions:["University of Arkansas for Medical Sciences"]},{name:"Paul E. Holtzheimer",institutions:["Emory University"]},{name:"Xiaoping Hu",institutions:["Georgia Institute of Technology","The Wallace H. Coulter Department of Biomedical Engineering"]},{name:"Helen S. Mayberg",institutions:["Emory University"]}],authorString:"R. Cameron Craddock; G. Andrew James; Paul E. Holtzheimer; Xiaoping Hu; Helen S. Mayberg",institutions:["Baylor College of Medicine","Emory University","Georgia Institute of Technology","The Wallace H. Coulter Department of Biomedical Engineering","University of Arkansas for Medical Sciences"],countries:["US"],year:2011,journal:"Human Brain Mapping",citations:1712,abstract:"Connectivity analyses and computational modeling of human brain function from fMRI data frequently require the specification of regions of interests (ROIs). Several analyses have relied on atlases derived from anatomical or cyto-architectonic boundaries to specify these ROIs, yet the suitability of atlases for resting state functional connectivity (FC) studies has yet to be established. This article introduces a data-driven method for generating an ROI atlas by parcellating whole brain resting-state fMRI data into spatially coherent regions of homogeneous FC. Several clustering statistics are used to compare methodological trade-offs as well as determine an adequate number of clusters. Additionally, we evaluate the suitability of the parcellation atlas against four ROI atlases (Talairach and Tournoux, Harvard-Oxford, Eickoff-Zilles, and Automatic Anatomical Labeling) and a random parcellation approach. The evaluated anatomical atlases exhibit poor ROI homogeneity and do not accurately reproduce FC patterns present at the voxel scale. In general, the proposed functional and random parcellations perform equivalently for most of the metrics evaluated. ROI size and hence the number of ROIs in a parcellation had the greatest impact on their suitability for FC analysis. With 200 or fewer ROIs, the resulting parcellations consist of ROIs with anatomic homology, and thus offer increased interpretability. Parcellation results containing higher numbers of ROIs (600 or 1,000) most accurately represent FC patterns present at the voxel scale and are preferable when interpretability can be sacrificed for accuracy. The resulting atlases and clustering software have been made publicly available at: http://www.nitrc.org/projects/cluster_roi/.",keywords:["Interpretability","Voxel","Cluster analysis","Atlas","Pattern recognition","Region of interest"],concepts:["Interpretability","Voxel","Artificial intelligence","Cluster analysis","Atlas (anatomy)","Pattern recognition (psychology)","Computer science","Region of interest"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:null,is_oa:!1,n_refs:55,n_refs_in_core:5,degree:30,community:2,deg_w:280,betweenness:.0026,pagerank:.00276,eigenvector:.0162,pdf_file:null,pdf_downloaded:!1},{id:24,oaid:"W2159549823",doi:"10.1371/journal.pcbi.1000381",title:"Functional Brain Networks Develop from a “Local to Distributed” Organization",authors:[{name:"Damien A. Fair",institutions:["Oregon Health & Science University"]},{name:"Alexander L. Cohen",institutions:["Washington University in St. Louis"]},{name:"Jonathan D. Power",institutions:["Washington University in St. Louis"]},{name:"Nico U.F. Dosenbach",institutions:["Washington University in St. Louis"]},{name:"Jessica A. Church",institutions:["Washington University in St. Louis"]},{name:"Francis M. Miezin",institutions:["Washington University in St. Louis"]},{name:"Bradley L. Schlaggar",institutions:["Washington University in St. Louis"]},{name:"Steven E. Petersen",institutions:["Hope Center for Neurological Disorders"]}],authorString:"Damien A. Fair; Alexander L. Cohen; Jonathan D. Power; Nico U.F. Dosenbach; Jessica A. Church; Francis M. Miezin; Bradley L. Schlaggar; Steven E. Petersen",institutions:["Hope Center for Neurological Disorders","Oregon Health & Science University","Washington University in St. Louis"],countries:["US"],year:2009,journal:"PLoS Computational Biology",citations:1577,abstract:`The mature human brain is organized into a collection of specialized functional networks that flexibly interact to support various cognitive functions. Studies of development often attempt to identify the organizing principles that guide the maturation of these functional networks. In this report, we combine resting state functional connectivity MRI (rs-fcMRI), graph analysis, community detection, and spring-embedding visualization techniques to analyze four separate networks defined in earlier studies. As we have previously reported, we find, across development, a trend toward 'segregation' (a general decrease in correlation strength) between regions close in anatomical space and 'integration' (an increased correlation strength) between selected regions distant in space. The generalization of these earlier trends across multiple networks suggests that this is a general developmental principle for changes in functional connectivity that would extend to large-scale graph theoretic analyses of large-scale brain networks. Communities in children are predominantly arranged by anatomical proximity, while communities in adults predominantly reflect functional relationships, as defined from adult fMRI studies. In sum, over development, the organization of multiple functional networks shifts from a local anatomical emphasis in children to a more "distributed" architecture in young adults. We argue that this "local to distributed" developmental characterization has important implications for understanding the development of neural systems underlying cognition. Further, graph metrics (e.g., clustering coefficients and average path lengths) are similar in child and adult graphs, with both showing "small-world"-like properties, while community detection by modularity optimization reveals stable communities within the graphs that are clearly different between young children and young adults. These observations suggest that early school age children and adults both have relatively efficient systems that may solve similar information processing problems in divergent ways.`,keywords:["Modularity","Clustering coefficient","Cognition","Connectome","Graph theory","Connectomics","Betweenness centrality"],concepts:["Modularity (biology)","Clustering coefficient","Cognition","Connectome","Computer science","Graph theory","Connectomics","Betweenness centrality"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1000381&type=printable",is_oa:!0,n_refs:106,n_refs_in_core:6,degree:59,community:2,deg_w:974,betweenness:.0073,pagerank:.00718,eigenvector:.0882,pdf_file:"Fair_2009.pdf",pdf_downloaded:!0},{id:25,oaid:"W2143502460",doi:"10.1146/annurev-psych-122414-033634",title:"Modular Brain Networks",authors:[{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]},{name:"Richard F. Betzel",institutions:["Indiana University Bloomington"]}],authorString:"Olaf Sporns; Richard F. Betzel",institutions:["Indiana University Bloomington"],countries:["US"],year:2015,journal:"Annual Review of Psychology",citations:1492,abstract:"The development of new technologies for mapping structural and functional brain connectivity has led to the creation of comprehensive network maps of neuronal circuits and systems. The architecture of these brain networks can be examined and analyzed with a large variety of graph theory tools. Methods for detecting modules, or network communities, are of particular interest because they uncover major building blocks or subnetworks that are particularly densely connected, often corresponding to specialized functional components. A large number of methods for community detection have become available and are now widely applied in network neuroscience. This article first surveys a number of these methods, with an emphasis on their advantages and shortcomings; then it summarizes major findings on the existence of modules in both structural and functional brain networks and briefly considers their potential functional roles in brain evolution, wiring minimization, and the emergence of functional specialization and complex dynamics.",keywords:["Modular design","Cognitive science","Variety","Network analysis","Neuroscience","Modularity","Functional connectivity"],concepts:["Modular design","Computer science","Cognitive science","Variety (cybernetics)","Network analysis","Neuroscience","Modularity (biology)","Functional connectivity"],topics:["Neural dynamics and brain function","Functional Brain Connectivity Studies","Photoreceptor and optogenetics research"],pdf_url:"https://www.annualreviews.org/doi/pdf/10.1146/annurev-psych-122414-033634",is_oa:!0,n_refs:150,n_refs_in_core:17,degree:43,community:0,deg_w:879,betweenness:.0038,pagerank:.00693,eigenvector:.0451,pdf_file:null,pdf_downloaded:!1},{id:26,oaid:"W1586771686",doi:"10.3389/fnhum.2015.00386",title:"GRETNA: a graph theoretical network analysis toolbox for imaging connectomics",authors:[{name:"Jinhui Wang",institutions:["Hangzhou Normal University","Chinese Institute for Brain Research","Beijing Normal University"]},{name:"Xindi Wang",institutions:["Chinese Institute for Brain Research","Beijing Normal University"]},{name:"Mingrui Xia",institutions:["Chinese Institute for Brain Research","Beijing Normal University"]},{name:"Xuhong Liao",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Alan C. Evans",institutions:["McGill University","Montreal Neurological Institute and Hospital"]},{name:"Yong He",institutions:["Montreal Neurological Institute and Hospital","McGill University","Chinese Institute for Brain Research","Beijing Normal University"]}],authorString:"Jinhui Wang; Xindi Wang; Mingrui Xia; Xuhong Liao; Alan C. Evans; Yong He",institutions:["Beijing Normal University","Chinese Institute for Brain Research","Hangzhou Normal University","McGill University","Montreal Neurological Institute and Hospital"],countries:["CA","CN"],year:2015,journal:"Frontiers in Human Neuroscience",citations:1478,abstract:"Recent studies have suggested that the brain's structural and functional networks (i.e., connectomics) can be constructed by various imaging technologies (e.g., EEG/MEG; structural, diffusion and functional MRI) and further characterized by graph theory. Given the huge complexity of network construction, analysis and statistics, toolboxes incorporating these functions are largely lacking. Here, we developed the GRaph thEoreTical Network Analysis (GRETNA) toolbox for imaging connectomics. The GRETNA contains several key features as follows: (i) an open-source, Matlab-based, cross-platform (Windows and UNIX OS) package with a graphical user interface (GUI); (ii) allowing topological analyses of global and local network properties with parallel computing ability, independent of imaging modality and species; (iii) providing flexible manipulations in several key steps during network construction and analysis, which include network node definition, network connectivity processing, network type selection and choice of thresholding procedure; (iv) allowing statistical comparisons of global, nodal and connectional network metrics and assessments of relationship between these network metrics and clinical or behavioral variables of interest; and (v) including functionality in image preprocessing and network construction based on resting-state functional MRI (R-fMRI) data. After applying the GRETNA to a publicly released R-fMRI dataset of 54 healthy young adults, we demonstrated that human brain functional networks exhibit efficient small-world, assortative, hierarchical and modular organizations and possess highly connected hubs and that these findings are robust against different analytical strategies. With these efforts, we anticipate that GRETNA will accelerate imaging connectomics in an easy, quick and flexible manner. GRETNA is freely available on the NITRC website.",keywords:["Connectomics","Toolbox","Power graph analysis","Graph","Connectome","Neuroscience"],concepts:["Connectomics","Toolbox","Power graph analysis","Computer science","Graph","Connectome"],topics:["Functional Brain Connectivity Studies","Bioinformatics and Genomic Networks","Complex Network Analysis Techniques"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnhum.2015.00386/pdf",is_oa:!0,n_refs:129,n_refs_in_core:34,degree:52,community:1,deg_w:1069.5,betweenness:.0036,pagerank:.00751,eigenvector:.1166,pdf_file:"Wang_2015.pdf",pdf_downloaded:!0},{id:27,oaid:"W2124953625",doi:"10.1111/j.1749-6632.2010.05888.x",title:"The human connectome: a complex network",authors:[{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]}],authorString:"Olaf Sporns",institutions:["Indiana University Bloomington"],countries:["US"],year:2011,journal:"Annals of the New York Academy of Sciences",citations:1431,abstract:"The human brain is a complex network. An important first step toward understanding the function of such a network is to map its elements and connections, to create a comprehensive structural description of the network architecture. This paper reviews current empirical efforts toward generating a network map of the human brain, the human connectome, and explores how the connectome can provide new insights into the organization of the brain's structural connections and their role in shaping functional dynamics. Network studies of structural connectivity obtained from noninvasive neuroimaging have revealed a number of highly nonrandom network attributes, including high clustering and modularity combined with high efficiency and short path length. The combination of these attributes simultaneously promotes high specialization and high integration within a modular small-world architecture. Structural and functional networks share some of the same characteristics, although their relationship is complex and nonlinear. Future studies of the human connectome will greatly expand our knowledge of network topology and dynamics in the healthy, developing, aging, and diseased brain.",keywords:["Modularity","Connectome","Complex network","Connectomics","Modular design","Network topology","Human Connectome Project"],concepts:["Modularity (biology)","Connectome","Computer science","Complex network","Connectomics","Modular design","Network topology","Human Connectome Project"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:null,is_oa:!1,n_refs:144,n_refs_in_core:29,degree:63,community:1,deg_w:1365.5,betweenness:.0081,pagerank:.0095,eigenvector:.1461,pdf_file:null,pdf_downloaded:!1},{id:28,oaid:"W2041951497",doi:"10.1523/jneurosci.0333-10.2010",title:"Functional Connectivity and Brain Networks in Schizophrenia",authors:[{name:"Mary-Ellen Lynall",institutions:["University of Cambridge"]},{name:"Danielle S. Bassett",institutions:["National Institutes of Health","University of Cambridge"]},{name:"R Kerwin",institutions:["King's College London"]},{name:"Peter J. McKenna",institutions:["Centro de Investigación Biomédica en Red de Salud Mental"]},{name:"Manfred G. Kitzbichler",institutions:["University of Cambridge","Neuroscience Institute"]},{name:"U. Müller",institutions:["University of Cambridge","Neuroscience Institute"]},{name:"Edward T. Bullmore",institutions:["University of Cambridge","GlaxoSmithKline (Netherlands)"]}],authorString:"Mary-Ellen Lynall; Danielle S. Bassett; R Kerwin; Peter J. McKenna; Manfred G. Kitzbichler; U. Müller; Edward T. Bullmore",institutions:["Centro de Investigación Biomédica en Red de Salud Mental","GlaxoSmithKline (Netherlands)","King's College London","National Institutes of Health","Neuroscience Institute","University of Cambridge"],countries:["ES","GB","IT","NL","US"],year:2010,journal:"Journal of Neuroscience",citations:1415,abstract:"Schizophrenia has often been conceived as a disorder of connectivity between components of large-scale brain networks. We tested this hypothesis by measuring aspects of both functional connectivity and functional network topology derived from resting-state fMRI time series acquired at 72 cerebral regions over 17 min from 15 healthy volunteers (14 male, 1 female) and 12 people diagnosed with schizophrenia (10 male, 2 female). We investigated between-group differences in strength and diversity of functional connectivity in the 0.06-0.125 Hz frequency interval, and some topological properties of undirected graphs constructed from thresholded interregional correlation matrices. In people with schizophrenia, strength of functional connectivity was significantly decreased, whereas diversity of functional connections was increased. Topologically, functional brain networks had reduced clustering and small-worldness, reduced probability of high-degree hubs, and increased robustness in the schizophrenic group. Reduced degree and clustering were locally significant in medial parietal, premotor and cingulate, and right orbitofrontal cortical nodes of functional networks in schizophrenia. Functional connectivity and topological metrics were correlated with each other and with behavioral performance on a verbal fluency task. We conclude that people with schizophrenia tend to have a less strongly integrated, more diverse profile of brain functional connectivity, associated with a less hub-dominated configuration of complex brain functional networks. Alongside these behaviorally disadvantageous differences, however, brain networks in the schizophrenic group also showed a greater robustness to random attack, pointing to a possible benefit of the schizophrenia connectome, if less extremely expressed.",keywords:["Resting state fMRI","Schizophrenia","Connectome","Functional connectivity","Neuroscience","Functional magnetic resonance imaging","Psychiatry"],concepts:["Resting state fMRI","Schizophrenia (object-oriented programming)","Connectome","Functional connectivity","Psychology","Neuroscience","Functional magnetic resonance imaging"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"https://www.jneurosci.org/content/jneuro/30/28/9477.full.pdf",is_oa:!0,n_refs:81,n_refs_in_core:10,degree:53,community:3,deg_w:778,betweenness:.0052,pagerank:.00582,eigenvector:.0713,pdf_file:null,pdf_downloaded:!1},{id:29,oaid:"W2129109788",doi:"10.1093/cercor/bhi016",title:"Neurophysiological Architecture of Functional Magnetic Resonance Images of Human Brain",authors:[{name:"Raymond Salvador",institutions:["Addenbrooke's Hospital"]},{name:"John Suckling",institutions:[]},{name:"Martin R. Coleman",institutions:[]},{name:"John D. Pickard",institutions:[]},{name:"David Menon",institutions:[]},{name:"Edward T. Bullmore",institutions:[]}],authorString:"Raymond Salvador; John Suckling; Martin R. Coleman; John D. Pickard; David Menon; Edward T. Bullmore",institutions:["Addenbrooke's Hospital"],countries:["GB"],year:2005,journal:"Cerebral Cortex",citations:1379,abstract:"We investigated large-scale systems organization of the whole human brain using functional magnetic resonance imaging (fMRI) data acquired from healthy volunteers in a no-task or 'resting' state. Images were parcellated using a prior anatomical template, yielding regional mean time series for each of 90 regions (major cortical gyri and subcortical nuclei) in each subject. Significant pairwise functional connections, defined by the group mean inter-regional partial correlation matrix, were mostly either local and intrahemispheric or symmetrically interhemispheric. Low-frequency components in the time series subtended stronger inter-regional correlations than high-frequency components. Intrahemispheric connectivity was generally related to anatomical distance by an inverse square law; many symmetrical interhemispheric connections were stronger than predicted by the anatomical distance between bilaterally homologous regions. Strong interhemispheric connectivity was notably absent in data acquired from a single patient, minimally conscious following a brainstem lesion. Multivariate analysis by hierarchical clustering and multidimensional scaling consistently defined six major systems in healthy volunteers-- corresponding approximately to four neocortical lobes, medial temporal lobe and subcortical nuclei- - that could be further decomposed into anatomically and functionally plausible subsystems, e.g. dorsal and ventral divisions of occipital cortex. An undirected graph derived by thresholding the healthy group mean partial correlation matrix demonstrated local clustering or cliquishness of connectivity and short mean path length compatible with prior data on small world characteristics of non-human cortical anatomy. Functional MRI demonstrates a neurophysiological architecture of the normal human brain that is anatomically sensible, strongly symmetrical, disrupted by acute brain injury, subtended predominantly by low frequencies and consistent with a small world network topology.",keywords:["Human brain","Functional magnetic resonance imaging","Neuroscience","Anatomy","Connectomics","Brainstem","Resting state fMRI","Magnetic resonance imaging"],concepts:["Human brain","Functional magnetic resonance imaging","Neuroscience","Anatomy","Connectomics","Brainstem","Resting state fMRI","Magnetic resonance imaging"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:null,is_oa:!1,n_refs:56,n_refs_in_core:2,degree:82,community:1,deg_w:1013,betweenness:.0188,pagerank:.0074,eigenvector:.1067,pdf_file:null,pdf_downloaded:!1},{id:30,oaid:"W2133015986",doi:"10.1093/cercor/bhl149",title:"Small-World Anatomical Networks in the Human Brain Revealed by Cortical Thickness from MRI",authors:[{name:"Yong He",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Zhang J. Chen",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Alan C. Evans",institutions:["Montreal Neurological Institute and Hospital","McGill University"]}],authorString:"Yong He; Zhang J. Chen; Alan C. Evans",institutions:["McGill University","Montreal Neurological Institute and Hospital"],countries:["CA"],year:2007,journal:"Cerebral Cortex",citations:1365,abstract:"An important issue in neuroscience is the characterization for the underlying architectures of complex brain networks. However, little is known about the network of anatomical connections in the human brain. Here, we investigated large-scale anatomical connection patterns of the human cerebral cortex using cortical thickness measurements from magnetic resonance images. Two areas were considered anatomically connected if they showed statistically significant correlations in cortical thickness and we constructed the network of such connections using 124 brains from the International Consortium for Brain Mapping database. Significant short- and long-range connections were found in both intra- and interhemispheric regions, many of which were consistent with known neuroanatomical pathways measured by human diffusion imaging. More importantly, we showed that the human brain anatomical network had robust small-world properties with cohesive neighborhoods and short mean distances between regions that were insensitive to the selection of correlation thresholds. Additionally, we also found that this network and the probability of finding a connection between 2 regions for a given anatomical distance had both exponentially truncated power-law distributions. Our results demonstrated the basic organizational principles for the anatomical network in the human brain compatible with previous functional networks studies, which provides important implications of how functional brain states originate from their structural underpinnings. To our knowledge, this study provides the first report of small-world properties and degree distribution of anatomical networks in the human brain using cortical thickness measurements.",keywords:["Human brain","Neuroscience","Cerebral cortex","Cortex","Brain mapping","Diffusion MRI","Functional connectivity","Small-world network"],concepts:["Human brain","Neuroscience","Cerebral cortex","Cortex (anatomy)","Brain mapping","Diffusion MRI","Functional connectivity","Small-world network"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Neural dynamics and brain function"],pdf_url:"https://academic.oup.com/cercor/article-pdf/17/10/2407/17296816/bhl149.pdf",is_oa:!0,n_refs:84,n_refs_in_core:4,degree:71,community:1,deg_w:1277,betweenness:.0072,pagerank:.00871,eigenvector:.1496,pdf_file:null,pdf_downloaded:!1},{id:31,oaid:"W2118323338",doi:"10.1093/cercor/bhj127",title:"Small-World Networks and Functional Connectivity in Alzheimer's Disease",authors:[{name:"Cornelis J. Stam",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"B.F. Jones",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Guido Nolte",institutions:["National Institutes of Health"]},{name:"Michael Breakspear",institutions:["The University of Sydney","Westmead Hospital"]},{name:"Philip Scheltens",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]}],authorString:"Cornelis J. Stam; B.F. Jones; Guido Nolte; Michael Breakspear; Philip Scheltens",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam","National Institutes of Health","The University of Sydney","Westmead Hospital"],countries:["AU","NL","US"],year:2006,journal:"Cerebral Cortex",citations:1289,abstract:`We investigated whether functional brain networks are abnormally organized in Alzheimer's disease (AD). To this end, graph theoretical analysis was applied to matrices of functional connectivity of beta band-filtered electroencephalography (EEG) channels, in 15 Alzheimer patients and 13 control subjects. Correlations between all pairwise combinations of EEG channels were determined with the synchronization likelihood. The resulting synchronization matrices were converted to graphs by applying a threshold, and cluster coefficients and path lengths were computed as a function of threshold or as a function of degree K. For a wide range of thresholds, the characteristic path length L was significantly longer in the Alzheimer patients, whereas the cluster coefficient C showed no significant changes. This pattern was still present when L and C were computed as a function of K. A longer path length with a relatively preserved cluster coefficient suggests a loss of complexity and a less optimal organization. The present study provides further support for the presence of "small-world" features in functional brain networks and demonstrates that AD is characterized by a loss of small-world network characteristics. Graph theoretical analysis may be a useful approach to study the complexity of patterns of interrelations between EEG channels.`,keywords:["Small-world network","Electroencephalography","Functional connectivity","Path length","Power graph analysis","Pairwise comparison","Clustering coefficient","Complex network"],concepts:["Small-world network","Electroencephalography","Functional connectivity","Path length","Power graph analysis","Pairwise comparison","Clustering coefficient","Complex network"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://academic.oup.com/cercor/article-pdf/17/1/92/795883/bhj127.pdf",is_oa:!0,n_refs:45,n_refs_in_core:2,degree:56,community:1,deg_w:758.5,betweenness:.0066,pagerank:.00558,eigenvector:.0858,pdf_file:null,pdf_downloaded:!1},{id:32,oaid:"W2009650955",doi:"10.1523/jneurosci.1929-08.2008",title:"Hierarchical Organization of Human Cortical Networks in Health and Schizophrenia",authors:[{name:"Danielle S. Bassett",institutions:["National Institute of Mental Health"]},{name:"Edward T. Bullmore",institutions:["University of Cambridge","Cambridge University Hospitals NHS Foundation Trust","Addenbrooke's Hospital"]},{name:"Beth A. Verchinski",institutions:["National Institutes of Health","National Institute of Mental Health"]},{name:"Venkata S. Mattay",institutions:["National Institutes of Health","National Institute of Mental Health"]},{name:"Daniel R. Weinberger",institutions:["National Institutes of Health","Gènes, synapses et cognition"]},{name:"Andreas Meyer‐Lindenberg",institutions:["National Institutes of Health","Central Institute of Mental Health","Gènes, synapses et cognition"]}],authorString:"Danielle S. Bassett; Edward T. Bullmore; Beth A. Verchinski; Venkata S. Mattay; Daniel R. Weinberger; Andreas Meyer‐Lindenberg",institutions:["Addenbrooke's Hospital","Cambridge University Hospitals NHS Foundation Trust","Central Institute of Mental Health","Gènes, synapses et cognition","National Institute of Mental Health","National Institutes of Health","University of Cambridge"],countries:["DE","FR","GB","US"],year:2008,journal:"Journal of Neuroscience",citations:1275,abstract:"The complex organization of connectivity in the human brain is incompletely understood. Recently, topological measures based on graph theory have provided a new approach to quantify large-scale cortical networks. These methods have been applied to anatomical connectivity data on nonhuman species, and cortical networks have been shown to have small-world topology, associated with high local and global efficiency of information transfer. Anatomical networks derived from cortical thickness measurements have shown the same organizational properties of the healthy human brain, consistent with similar results reported in functional networks derived from resting state functional magnetic resonance imaging (MRI) and magnetoencephalographic data. Here we show, using anatomical networks derived from analysis of inter-regional covariation of gray matter volume in MRI data on 259 healthy volunteers, that classical divisions of cortex (multimodal, unimodal, and transmodal) have some distinct topological attributes. Although all cortical divisions shared nonrandom properties of small-worldness and efficient wiring (short mean Euclidean distance between connected regions), the multimodal network had a hierarchical organization, dominated by frontal hubs with low clustering, whereas the transmodal network was assortative. Moreover, in a sample of 203 people with schizophrenia, multimodal network organization was abnormal, as indicated by reduced hierarchy, the loss of frontal and the emergence of nonfrontal hubs, and increased connection distance. We propose that the topological differences between divisions of normal cortex may represent the outcome of different growth processes for multimodal and transmodal networks and that neurodevelopmental abnormalities in schizophrenia specifically impact multimodal cortical organization.",keywords:["Schizophrenia","Neuroscience","Hierarchical organization","Functional connectivity","Clustering coefficient","Hierarchy","Small-world network"],concepts:["Schizophrenia (object-oriented programming)","Neuroscience","Hierarchical organization","Functional connectivity","Clustering coefficient","Psychology","Hierarchy","Small-world network"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/28/37/9239.full.pdf",is_oa:!0,n_refs:56,n_refs_in_core:8,degree:74,community:1,deg_w:1168,betweenness:.0083,pagerank:.00807,eigenvector:.1312,pdf_file:null,pdf_downloaded:!1},{id:33,oaid:"W2021947606",doi:"10.3389/fnins.2010.00200",title:"Modular and Hierarchically Modular Organization of Brain Networks",authors:[{name:"David Meunier",institutions:["University of Cambridge"]},{name:"Renaud Lambiotte",institutions:["Imperial College London"]},{name:"Edward T. Bullmore",institutions:["University of Cambridge"]}],authorString:"David Meunier; Renaud Lambiotte; Edward T. Bullmore",institutions:["Imperial College London","University of Cambridge"],countries:["GB"],year:2010,journal:"Frontiers in Neuroscience",citations:1234,abstract:"Brain networks are increasingly understood as one of a large class of information processing systems that share important organizational principles in common, including the property of a modular community structure. A module is topologically defined as a subset of highly inter-connected nodes which are relatively sparsely connected to nodes in other modules. In brain networks, topological modules are often made up of anatomically neighboring and/or functionally related cortical regions, and inter-modular connections tend to be relatively long distance. Moreover, brain networks and many other complex systems demonstrate the property of hierarchical modularity, or modularity on several topological scales: within each module there will be a set of sub-modules, and within each sub-module a set of sub-sub-modules, etc. There are several general advantages to modular and hierarchically modular network organization, including greater robustness, adaptivity, and evolvability of network function. In this context, we review some of the mathematical concepts available for quantitative analysis of (hierarchical) modularity in brain networks and we summarize some of the recent work investigating modularity of structural and functional brain networks derived from analysis of human neuroimaging data.",keywords:["Modular design","Modularity","Evolvability","Robustness","Set","Property","Distributed computing"],concepts:["Modular design","Modularity (biology)","Computer science","Evolvability","Robustness (evolution)","Set (abstract data type)","Property (philosophy)","Distributed computing"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Bioinformatics and Genomic Networks"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnins.2010.00200/pdf",is_oa:!0,n_refs:98,n_refs_in_core:19,degree:55,community:0,deg_w:1080,betweenness:.0054,pagerank:.0077,eigenvector:.1048,pdf_file:"Meunier_2010.pdf",pdf_downloaded:!0},{id:34,oaid:"W2161493176",doi:"10.1093/brain/awu132",title:"The hubs of the human connectome are generally implicated in the anatomy of brain disorders",authors:[{name:"Nicolás Crossley",institutions:["King's College London"]},{name:"Andrea Mechelli",institutions:["King's College London"]},{name:"Jessica Scott",institutions:["King's College London"]},{name:"Francesco Carletti",institutions:["King's College London"]},{name:"Peter T. Fox",institutions:["The University of Texas at San Antonio Health Science Center","The University of Texas at San Antonio"]},{name:"Philip McGuire",institutions:["King's College London"]},{name:"Edward T. Bullmore",institutions:["GlaxoSmithKline (United Kingdom)","University of Cambridge","Cambridgeshire and Peterborough NHS Foundation Trust"]}],authorString:"Nicolás Crossley; Andrea Mechelli; Jessica Scott; Francesco Carletti; Peter T. Fox; Philip McGuire; Edward T. Bullmore",institutions:["Cambridgeshire and Peterborough NHS Foundation Trust","GlaxoSmithKline (United Kingdom)","King's College London","The University of Texas at San Antonio","The University of Texas at San Antonio Health Science Center","University of Cambridge"],countries:["GB","US"],year:2014,journal:"Brain",citations:1215,abstract:"Brain networks or 'connectomes' include a minority of highly connected hub nodes that are functionally valuable, because their topological centrality supports integrative processing and adaptive behaviours. Recent studies also suggest that hubs have higher metabolic demands and longer-distance connections than other brain regions, and therefore could be considered biologically costly. Assuming that hubs thus normally combine both high topological value and high biological cost, we predicted that pathological brain lesions would be concentrated in hub regions. To test this general hypothesis, we first identified the hubs of brain anatomical networks estimated from diffusion tensor imaging data on healthy volunteers (n = 56), and showed that computational attacks targeted on hubs disproportionally degraded the efficiency of brain networks compared to random attacks. We then prepared grey matter lesion maps, based on meta-analyses of published magnetic resonance imaging data on more than 20 000 subjects and 26 different brain disorders. Magnetic resonance imaging lesions that were common across all brain disorders were more likely to be located in hubs of the normal brain connectome (P < 10(-4), permutation test). Specifically, nine brain disorders had lesions that were significantly more likely to be located in hubs (P < 0.05, permutation test), including schizophrenia and Alzheimer's disease. Both these disorders had significantly hub-concentrated lesion distributions, although (almost completely) distinct subsets of cortical hubs were lesioned in each disorder: temporal lobe hubs specifically were associated with higher lesion probability in Alzheimer's disease, whereas in schizophrenia lesions were concentrated in both frontal and temporal cortical hubs. These results linking pathological lesions to the topological centrality of nodes in the normal diffusion tensor imaging connectome were generally replicated when hubs were defined instead by the meta-analysis of more than 1500 task-related functional neuroimaging studies of healthy volunteers to create a normative functional co-activation network. We conclude that the high cost/high value hubs of human brain networks are more likely to be anatomically abnormal than non-hubs in many (if not all) brain disorders.",keywords:["Connectome","Schizophrenia","Neuroscience","Temporal lobe","Lesion","Diffusion MRI","Magnetic resonance imaging"],concepts:["Connectome","Schizophrenia (object-oriented programming)","Neuroscience","Temporal lobe","Lesion","Diffusion MRI","Magnetic resonance imaging","Psychology"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"https://academic.oup.com/brain/article-pdf/137/8/2382/13797791/awu132.pdf",is_oa:!0,n_refs:86,n_refs_in_core:22,degree:64,community:0,deg_w:1076.5,betweenness:.0096,pagerank:.00818,eigenvector:.0709,pdf_file:"Crossley_2014.pdf",pdf_downloaded:!0},{id:35,oaid:"W2143661428",doi:"10.3389/fnsys.2010.00019",title:"Clinical applications of resting state functional connectivity",authors:[{name:"Michael Fox",institutions:["Brigham and Women's Hospital"]}],authorString:"Michael Fox",institutions:["Brigham and Women's Hospital"],countries:["US"],year:2010,journal:"Frontiers in Systems Neuroscience",citations:1214,abstract:"During resting conditions the brain remains functionally and metabolically active. One manifestation of this activity that has become an important research tool is spontaneous fluctuations in the blood oxygen level-dependent (BOLD) signal of functional magnetic resonance imaging (fMRI). The identification of correlation patterns in these spontaneous fluctuations has been termed resting state functional connectivity (fcMRI) and has the potential to greatly increase the translation of fMRI into clinical care. In this article we review the advantages of the resting state signal for clinical applications including detailed discussion of signal to noise considerations. We include guidelines for performing resting state research on clinical populations, outline the different areas for clinical application, and identify important barriers to be addressed to facilitate the translation of resting state fcMRI into the clinical realm.",keywords:["Resting state fMRI","Functional connectivity","Functional magnetic resonance imaging","Neuroscience","Blood-oxygen-level dependent","Translation","Communication noise"],concepts:["Resting state fMRI","Functional connectivity","Functional magnetic resonance imaging","Neuroscience","Blood-oxygen-level dependent","Translation (biology)","Communication noise","Computer science"],topics:["Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications","Atomic and Subatomic Physics Research"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnsys.2010.00019/pdf",is_oa:!0,n_refs:141,n_refs_in_core:11,degree:28,community:2,deg_w:510,betweenness:.0014,pagerank:.00439,eigenvector:.0289,pdf_file:"Fox_2010.pdf",pdf_downloaded:!0},{id:36,oaid:"W2166148649",doi:"10.1371/journal.pone.0013701",title:"Comparing Brain Networks of Different Size and Connectivity Density Using Graph Theory",authors:[{name:"Bernadette C.M. van Wijk",institutions:["Vrije Universiteit Amsterdam"]},{name:"Cornelis J. Stam",institutions:["Amsterdam UMC Location VUmc"]},{name:"Andreas Daffertshofer",institutions:["Vrije Universiteit Amsterdam"]}],authorString:"Bernadette C.M. van Wijk; Cornelis J. Stam; Andreas Daffertshofer",institutions:["Amsterdam UMC Location VUmc","Vrije Universiteit Amsterdam"],countries:["NL"],year:2010,journal:"PLoS ONE",citations:1207,abstract:"Graph theory is a valuable framework to study the organization of functional and anatomical connections in the brain. Its use for comparing network topologies, however, is not without difficulties. Graph measures may be influenced by the number of nodes (N) and the average degree (k) of the network. The explicit form of that influence depends on the type of network topology, which is usually unknown for experimental data. Direct comparisons of graph measures between empirical networks with different N and/or k can therefore yield spurious results. We list benefits and pitfalls of various approaches that intend to overcome these difficulties. We discuss the initial graph definition of unweighted graphs via fixed thresholds, average degrees or edge densities, and the use of weighted graphs. For instance, choosing a threshold to fix N and k does eliminate size and density effects but may lead to modifications of the network by enforcing (ignoring) non-significant (significant) connections. Opposed to fixing N and k, graph measures are often normalized via random surrogates but, in fact, this may even increase the sensitivity to differences in N and k for the commonly used clustering coefficient and small-world index. To avoid such a bias we tried to estimate the N,k-dependence for empirical networks, which can serve to correct for size effects, if successful. We also add a number of methods used in social sciences that build on statistics of local network structures including exponential random graph models and motif counting. We show that none of the here-investigated methods allows for a reliable and fully unbiased comparison, but some perform better than others.",keywords:["Spurious relationship","Clustering coefficient","Random graph","Network topology","Exponential random graph models","Graph theory","Graph"],concepts:["Spurious relationship","Clustering coefficient","Random graph","Network topology","Exponential random graph models","Computer science","Graph theory","Graph"],topics:["Functional Brain Connectivity Studies","Complex Network Analysis Techniques","Mental Health Research Topics"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0013701&type=printable",is_oa:!0,n_refs:86,n_refs_in_core:21,degree:51,community:1,deg_w:929,betweenness:.0043,pagerank:.00665,eigenvector:.101,pdf_file:"Wijk_2010.pdf",pdf_downloaded:!0},{id:37,oaid:"W2033078279",doi:"10.1371/journal.pone.0001049",title:"Identification and Classification of Hubs in Brain Networks",authors:[{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]},{name:"Christopher J. Honey",institutions:["Indiana University Bloomington"]},{name:"Rolf Kötter",institutions:["Radboud University Medical Center","Radboud University Nijmegen","Heinrich Heine University Düsseldorf"]}],authorString:"Olaf Sporns; Christopher J. Honey; Rolf Kötter",institutions:["Heinrich Heine University Düsseldorf","Indiana University Bloomington","Radboud University Medical Center","Radboud University Nijmegen"],countries:["DE","NL","US"],year:2007,journal:"PLoS ONE",citations:1206,abstract:"Brain regions in the mammalian cerebral cortex are linked by a complex network of fiber bundles. These inter-regional networks have previously been analyzed in terms of their node degree, structural motif, path length and clustering coefficient distributions. In this paper we focus on the identification and classification of hub regions, which are thought to play pivotal roles in the coordination of information flow. We identify hubs and characterize their network contributions by examining motif fingerprints and centrality indices for all regions within the cerebral cortices of both the cat and the macaque. Motif fingerprints capture the statistics of local connection patterns, while measures of centrality identify regions that lie on many of the shortest paths between parts of the network. Within both cat and macaque networks, we find that a combination of degree, motif participation, betweenness centrality and closeness centrality allows for reliable identification of hub regions, many of which have previously been functionally classified as polysensory or multimodal. We then classify hubs as either provincial (intra-cluster) hubs or connector (inter-cluster) hubs, and proceed to show that lesioning hubs of each type from the network produces opposite effects on the small-world index. Our study presents an approach to the identification and classification of putative hub regions in brain networks on the basis of multiple network attributes and charts potential links between the structural embedding of such regions and their functional roles.",keywords:["Betweenness centrality","Centrality","Motif","Macaque","Network motif","Clustering coefficient","Network analysis"],concepts:["Betweenness centrality","Centrality","Motif (music)","Macaque","Network motif","Clustering coefficient","Network analysis","Computer science"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0001049&type=printable",is_oa:!0,n_refs:76,n_refs_in_core:7,degree:79,community:1,deg_w:1352,betweenness:.0154,pagerank:.00943,eigenvector:.1438,pdf_file:"Sporns_2007.pdf",pdf_downloaded:!0},{id:38,oaid:"W2136199096",doi:"10.1093/cercor/bhr269",title:"Network Centrality in the Human Functional Connectome",authors:[{name:"Xi‐Nian Zuo",institutions:["NYU Langone Health","Institute of Psychology, Chinese Academy of Sciences"]},{name:"Ross C. Ehmke",institutions:["Indiana University Bloomington"]},{name:"Maarten Mennes",institutions:["NYU Langone Health"]},{name:"Davide Imperati",institutions:["NYU Langone Health"]},{name:"F. Xavier Castellanos",institutions:["Nathan Kline Institute for Psychiatric Research","NYU Langone Health"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]},{name:"Michael P. Milham",institutions:["Child Mind Institute"]}],authorString:"Xi‐Nian Zuo; Ross C. Ehmke; Maarten Mennes; Davide Imperati; F. Xavier Castellanos; Olaf Sporns; Michael P. Milham",institutions:["Child Mind Institute","Indiana University Bloomington","Institute of Psychology, Chinese Academy of Sciences","NYU Langone Health","Nathan Kline Institute for Psychiatric Research"],countries:["CN","US"],year:2011,journal:"Cerebral Cortex",citations:1206,abstract:'The network architecture of functional connectivity within the human brain connectome is poorly understood at the voxel level. Here, using resting state functional magnetic resonance imaging data from 1003 healthy adults, we investigate a broad array of network centrality measures to provide novel insights into connectivity within the whole-brain functional network (i.e., the functional connectome). We first assemble and visualize the voxel-wise (4 mm) functional connectome as a functional network. We then demonstrate that each centrality measure captures different aspects of connectivity, highlighting the importance of considering both global and local connectivity properties of the functional connectome. Beyond "detecting functional hubs," we treat centrality as measures of functional connectivity within the brain connectome and demonstrate their reliability and phenotypic correlates (i.e., age and sex). Specifically, our analyses reveal age-related decreases in degree centrality, but not eigenvector centrality, within precuneus and posterior cingulate regions. This implies that while local or (direct) connectivity decreases with age, connections with hub-like regions within the brain remain stable with age at a global level. In sum, these findings demonstrate the nonredundancy of various centrality measures and raise questions regarding their underlying physiological mechanisms that may be relevant to the study of neurodegenerative and psychiatric disorders.',keywords:["Centrality","Connectome","Functional magnetic resonance imaging","Human Connectome Project","Precuneus","Neuroscience","Functional connectivity","Voxel"],concepts:["Centrality","Connectome","Functional magnetic resonance imaging","Human Connectome Project","Precuneus","Neuroscience","Functional connectivity","Voxel"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:null,is_oa:!1,n_refs:93,n_refs_in_core:18,degree:57,community:2,deg_w:893.5,betweenness:.0082,pagerank:.00685,eigenvector:.0676,pdf_file:null,pdf_downloaded:!1},{id:39,oaid:"W2161515775",doi:"10.1146/annurev-clinpsy-040510-143934",title:"Brain Graphs: Graphical Models of the Human Brain Connectome",authors:[{name:"Edward T. Bullmore",institutions:["University of Cambridge"]},{name:"Danielle S. Bassett",institutions:["University of California, Santa Barbara"]}],authorString:"Edward T. Bullmore; Danielle S. Bassett",institutions:["University of California, Santa Barbara","University of Cambridge"],countries:["GB","US"],year:2011,journal:"Annual Review of Clinical Psychology",citations:1197,abstract:"Brain graphs provide a relatively simple and increasingly popular way of modeling the human brain connectome, using graph theory to abstractly define a nervous system as a set of nodes (denoting anatomical regions or recording electrodes) and interconnecting edges (denoting structural or functional connections). Topological and geometrical properties of these graphs can be measured and compared to random graphs and to graphs derived from other neuroscience data or other (nonneural) complex systems. Both structural and functional human brain graphs have consistently demonstrated key topological properties such as small-worldness, modularity, and heterogeneous degree distributions. Brain graphs are also physically embedded so as to nearly minimize wiring cost, a key geometric property. Here we offer a conceptual review and methodological guide to graphical analysis of human neuroimaging data, with an emphasis on some of the key assumptions, issues, and trade-offs facing the investigator.",keywords:["Connectome","Modularity","Graph theory","Human Connectome Project","Set","Human brain","Connectomics"],concepts:["Connectome","Modularity (biology)","Computer science","Graph theory","Human Connectome Project","Set (abstract data type)","Human brain","Connectomics"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Bioinformatics and Genomic Networks"],pdf_url:null,is_oa:!1,n_refs:150,n_refs_in_core:31,degree:71,community:1,deg_w:1963,betweenness:.0067,pagerank:.01314,eigenvector:.2107,pdf_file:null,pdf_downloaded:!1},{id:40,oaid:"W2138991775",doi:"10.1371/journal.pcbi.1000100",title:"Network Analysis of Intrinsic Functional Brain Connectivity in Alzheimer's Disease",authors:[{name:"Kaustubh Supekar",institutions:["Stanford University"]},{name:"Vinod Menon",institutions:["Stanford University"]},{name:"Daniel J. Rubin",institutions:["Stanford University"]},{name:"Mark A. Musen",institutions:["Stanford University"]},{name:"Michael D. Greicius",institutions:["Stanford University"]}],authorString:"Kaustubh Supekar; Vinod Menon; Daniel J. Rubin; Mark A. Musen; Michael D. Greicius",institutions:["Stanford University"],countries:["US"],year:2008,journal:"PLoS Computational Biology",citations:1172,abstract:`Functional brain networks detected in task-free ("resting-state") functional magnetic resonance imaging (fMRI) have a small-world architecture that reflects a robust functional organization of the brain. Here, we examined whether this functional organization is disrupted in Alzheimer's disease (AD). Task-free fMRI data from 21 AD subjects and 18 age-matched controls were obtained. Wavelet analysis was applied to the fMRI data to compute frequency-dependent correlation matrices. Correlation matrices were thresholded to create 90-node undirected-graphs of functional brain networks. Small-world metrics (characteristic path length and clustering coefficient) were computed using graph analytical methods. In the low frequency interval 0.01 to 0.05 Hz, functional brain networks in controls showed small-world organization of brain activity, characterized by a high clustering coefficient and a low characteristic path length. In contrast, functional brain networks in AD showed loss of small-world properties, characterized by a significantly lower clustering coefficient (p<0.01), indicative of disrupted local connectivity. Clustering coefficients for the left and right hippocampus were significantly lower (p<0.01) in the AD group compared to the control group. Furthermore, the clustering coefficient distinguished AD participants from the controls with a sensitivity of 72% and specificity of 78%. Our study provides new evidence that there is disrupted organization of functional brain networks in AD. Small-world metrics can characterize the functional organization of the brain in AD, and our findings further suggest that these network measures may be useful as an imaging-based biomarker to distinguish AD from healthy aging.`,keywords:["Clustering coefficient","Functional magnetic resonance imaging","Resting state fMRI","Neuroscience","Default mode network","Cluster analysis","Small-world network","Alzheimer's disease"],concepts:["Clustering coefficient","Functional magnetic resonance imaging","Resting state fMRI","Neuroscience","Default mode network","Cluster analysis","Small-world network","Alzheimer's disease"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1000100&type=printable",is_oa:!0,n_refs:59,n_refs_in_core:8,degree:52,community:1,deg_w:796,betweenness:.006,pagerank:.00597,eigenvector:.0809,pdf_file:"Supekar_2008.pdf",pdf_downloaded:!0},{id:41,oaid:"W2162686834",doi:"10.1093/cercor/bhn102",title:"Mapping Anatomical Connectivity Patterns of Human Cerebral Cortex Using In Vivo Diffusion Tensor Imaging Tractography",authors:[{name:"Gaolang Gong",institutions:["University of Alberta"]},{name:"Yong He",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Luis Concha",institutions:["University of Alberta"]},{name:"Catherine Lebel",institutions:["University of Alberta"]},{name:"Donald Gross",institutions:["University of Alberta"]},{name:"Alan C. Evans",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Christian Beaulieu",institutions:["University of Alberta"]}],authorString:"Gaolang Gong; Yong He; Luis Concha; Catherine Lebel; Donald Gross; Alan C. Evans; Christian Beaulieu",institutions:["McGill University","Montreal Neurological Institute and Hospital","University of Alberta"],countries:["CA"],year:2008,journal:"Cerebral Cortex",citations:1145,abstract:'The characterization of the topological architecture of complex networks underlying the structural and functional organization of the brain is a basic challenge in neuroscience. However, direct evidence for anatomical connectivity networks in the human brain remains scarce. Here, we utilized diffusion tensor imaging deterministic tractography to construct a macroscale anatomical network capturing the underlying common connectivity pattern of human cerebral cortex in a large sample of subjects (80 young adults) and further quantitatively analyzed its topological properties with graph theoretical approaches. The cerebral cortex was divided into 78 cortical regions, each representing a network node, and 2 cortical regions were considered connected if the probability of fiber connections exceeded a statistical criterion. The topological parameters of the established cortical network (binarized) resemble that of a "small-world" architecture characterized by an exponentially truncated power-law distribution. These characteristics imply high resilience to localized damage. Furthermore, this cortical network was characterized by major hub regions in association cortices that were connected by bridge connections following long-range white matter pathways. Our results are compatible with previous structural and functional brain networks studies and provide insight into the organizational principles of human brain anatomical networks that underlie functional states.',keywords:["Diffusion MRI","Tractography","Neuroscience","Cerebral cortex","Functional connectivity","Cortex","Connectome","Connectomics"],concepts:["Diffusion MRI","Tractography","Neuroscience","Cerebral cortex","Functional connectivity","Cortex (anatomy)","Connectome","Connectomics"],topics:["Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications","Functional Brain Connectivity Studies"],pdf_url:"https://academic.oup.com/cercor/article-pdf/19/3/524/17300772/bhn102.pdf",is_oa:!0,n_refs:83,n_refs_in_core:11,degree:79,community:1,deg_w:1622.5,betweenness:.0114,pagerank:.01094,eigenvector:.1863,pdf_file:null,pdf_downloaded:!1},{id:42,oaid:"W2157106546",doi:"10.3174/ajnr.a3263",title:"Resting-State fMRI: A Review of Methods and Clinical Applications",authors:[{name:"M.H. Lee",institutions:["Research Institute of Radiology","Mallinckrodt (Ireland)"]},{name:"Christopher D. Smyser",institutions:["Washington University in St. Louis","Mallinckrodt (Ireland)"]},{name:"Joshua S. Shimony",institutions:["Washington University in St. Louis","Research Institute of Radiology","Mallinckrodt (Ireland)"]}],authorString:"M.H. Lee; Christopher D. Smyser; Joshua S. Shimony",institutions:["Mallinckrodt (Ireland)","Research Institute of Radiology","Washington University in St. Louis"],countries:["BY","IE","US"],year:2012,journal:"American Journal of Neuroradiology",citations:1139,abstract:"SUMMARY: Resting-state fMRI measures spontaneous low-frequency fluctuations in the BOLD signal to investigate the functional architecture of the brain. Application of this technique has allowed the identification of various RSNs, or spatially distinct areas of the brain that demonstrate synchronous BOLD fluctuations at rest. Various methods exist for analyzing resting-state data, including seed-based approaches, independent component analysis, graph methods, clustering algorithms, neural networks, and pattern classifiers. Clinical applications of resting-state fMRI are at an early stage of development. However, its use in presurgical planning for patients with brain tumor and epilepsy demonstrates early promise, and the technique may have a future role in providing diagnostic and prognostic information for neurologic and psychiatric diseases.",keywords:["Resting state fMRI","Medicine","Functional connectivity","Neuroscience","Epilepsy","Independent component analysis","Cluster analysis","Brain activity and meditation"],concepts:["Resting state fMRI","Medicine","Functional connectivity","Neuroscience","Epilepsy","Independent component analysis","Cluster analysis","Brain activity and meditation"],topics:["Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications","Neural dynamics and brain function"],pdf_url:"http://www.ajnr.org/content/ajnr/34/10/1866.full.pdf",is_oa:!0,n_refs:95,n_refs_in_core:13,degree:27,community:2,deg_w:391,betweenness:.001,pagerank:.00351,eigenvector:.0206,pdf_file:null,pdf_downloaded:!1},{id:43,oaid:"W2165985389",doi:"10.1523/jneurosci.1443-09.2009",title:"Efficiency of Functional Brain Networks and Intellectual Performance",authors:[{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]},{name:"Cornelis J. Stam",institutions:["Amsterdam UMC Location VUmc"]},{name:"René S. Kahn",institutions:["University Medical Center Utrecht"]},{name:"Hilleke E. Hulshoff Pol",institutions:["University Medical Center Utrecht"]}],authorString:"Martijn P. van den Heuvel; Cornelis J. Stam; René S. Kahn; Hilleke E. Hulshoff Pol",institutions:["Amsterdam UMC Location VUmc","University Medical Center Utrecht"],countries:["NL"],year:2009,journal:"Journal of Neuroscience",citations:1131,abstract:"Our brain is a complex network in which information is continuously processed and transported between spatially distributed but functionally linked regions. Recent studies have shown that the functional connections of the brain network are organized in a highly efficient small-world manner, indicating a high level of local neighborhood clustering, together with the existence of more long-distance connections that ensure a high level of global communication efficiency within the overall network. Such an efficient network architecture of our functional brain raises the question of a possible association between how efficiently the regions of our brain are functionally connected and our level of intelligence. Examining the overall organization of the brain network using graph analysis, we show a strong negative association between the normalized characteristic path length lambda of the resting-state brain network and intelligence quotient (IQ). This suggests that human intellectual performance is likely to be related to how efficiently our brain integrates information between multiple brain regions. Most pronounced effects between normalized path length and IQ were found in frontal and parietal regions. Our findings indicate a strong positive association between the global efficiency of functional brain networks and intellectual performance.",keywords:["Human brain","Association","Small-world network","Neuroscience","Resting state fMRI","Clustering coefficient","Intelligence quotient"],concepts:["Human brain","Association (psychology)","Small-world network","Neuroscience","Resting state fMRI","Computer science","Clustering coefficient","Intelligence quotient"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://www.jneurosci.org/content/jneuro/29/23/7619.full.pdf",is_oa:!0,n_refs:42,n_refs_in_core:9,degree:58,community:3,deg_w:914,betweenness:.0051,pagerank:.00654,eigenvector:.1022,pdf_file:"Heuvel_2009.pdf",pdf_downloaded:!0},{id:44,oaid:"W2116818517",doi:"10.1093/brain/awl359",title:"Association fibre pathways of the brain: parallel observations from diffusion spectrum imaging and autoradiography",authors:[{name:"Jeremy D. Schmahmann",institutions:["Boston University","Harvard University","Massachusetts General Hospital"]},{name:"Deepak Ν. Pandya",institutions:["Boston University","Harvard University","Massachusetts General Hospital","Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Ruofan Wang",institutions:["Boston University","Harvard University","Massachusetts General Hospital","Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Guangping Dai",institutions:["Boston University","Harvard University","Massachusetts General Hospital","Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Helen D’Arceuil",institutions:["Boston University","Harvard University","Massachusetts General Hospital","Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Alex J. de Crespigny",institutions:["Boston University","Harvard University","Massachusetts General Hospital","Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Van J. Wedeen",institutions:["Boston University","Harvard University","Massachusetts General Hospital","Athinoula A. Martinos Center for Biomedical Imaging"]}],authorString:"Jeremy D. Schmahmann; Deepak Ν. Pandya; Ruofan Wang; Guangping Dai; Helen D’Arceuil; Alex J. de Crespigny; Van J. Wedeen",institutions:["Athinoula A. Martinos Center for Biomedical Imaging","Boston University","Harvard University","Massachusetts General Hospital"],countries:["US"],year:2007,journal:"Brain",citations:1090,abstract:"Understanding the long association pathways that convey cortical connections is a critical step in exploring the anatomic substrates of cognition in health and disease. Diffusion tensor imaging (DTI) is able to demonstrate fibre tracts non-invasively, but present approaches have been hampered by the inability to visualize fibres that have intersecting trajectories (crossing fibres), and by the lack of a detailed map of the origins, course and terminations of the white matter pathways. We therefore used diffusion spectrum imaging (DSI) that has the ability to resolve crossing fibres at the scale of single MRI voxels, and identified the long association tracts in the monkey brain. We then compared the results with available expositions of white matter pathways in the monkey using autoradiographic histological tract tracing. We identified 10 long association fibre bundles with DSI that match the observations in the isotope material: emanating from the parietal lobe, the superior longitudinal fasciculus subcomponents I, II and III; from the occipital-parietal region, the fronto-occipital fasciculus; from the temporal lobe, the middle longitudinal fasciculus and from rostral to caudal, the uncinate fasciculus, extreme capsule and arcuate fasciculus; from the occipital-temporal region, the inferior longitudinal fasciculus; and from the cingulate gyrus, the cingulum bundle. We suggest new interpretations of the putative functions of these fibre bundles based on the cortical areas that they link. These findings using DSI and validated with reference to autoradiographic tract tracing in the monkey represent a considerable advance in the understanding of the fibre pathways in the cerebral white matter. By replicating the major features of these tracts identified by histological techniques in monkey, we show that DSI has the potential to cast new light on the organization of the human brain in the normal state and in clinical disorders.",keywords:["Uncinate fasciculus","Arcuate fasciculus","White matter","Fasciculus","Superior longitudinal fasciculus","Anatomy","Diffusion MRI","Neuroscience"],concepts:["Uncinate fasciculus","Arcuate fasciculus","White matter","Fasciculus","Superior longitudinal fasciculus","Anatomy","Diffusion MRI","Neuroscience"],topics:["Advanced Neuroimaging Techniques and Applications","Fetal and Pediatric Neurological Disorders","Functional Brain Connectivity Studies"],pdf_url:"https://academic.oup.com/brain/article-pdf/130/3/630/780588/awl359.pdf",is_oa:!0,n_refs:114,n_refs_in_core:1,degree:14,community:0,deg_w:97.5,betweenness:2e-4,pagerank:.00141,eigenvector:.0095,pdf_file:null,pdf_downloaded:!1},{id:45,oaid:"W2159242554",doi:"10.1093/brain/awn018",title:"Disrupted small-world networks in schizophrenia",authors:[{name:"Yong Liu",institutions:["Montreal Neurological Institute and Hospital","Central South University","Capital Medical University","Chinese Academy of Sciences","Institute of Automation","Second Xiangya Hospital of Central South University","McGill University"]},{name:"Meng Liang",institutions:["Montreal Neurological Institute and Hospital","Central South University","Capital Medical University","Institute of Automation","Second Xiangya Hospital of Central South University","McGill University"]},{name:"Yuan Zhou",institutions:["Montreal Neurological Institute and Hospital","Central South University","Capital Medical University","Institute of Automation","Second Xiangya Hospital of Central South University","McGill University"]},{name:"Yong He",institutions:["Montreal Neurological Institute and Hospital","Central South University","Capital Medical University","Institute of Automation","Second Xiangya Hospital of Central South University","McGill University"]},{name:"Yihui Hao",institutions:["Montreal Neurological Institute and Hospital","Central South University","Capital Medical University","Institute of Automation","Second Xiangya Hospital of Central South University","McGill University"]},{name:"Ming Song",institutions:["Montreal Neurological Institute and Hospital","Central South University","Capital Medical University","Institute of Automation","Second Xiangya Hospital of Central South University","McGill University"]},{name:"Chunshui Yu",institutions:["Montreal Neurological Institute and Hospital","Central South University","Capital Medical University","Institute of Automation","Second Xiangya Hospital of Central South University","McGill University"]},{name:"Haihong Liu",institutions:["Montreal Neurological Institute and Hospital","Central South University","Capital Medical University","Institute of Automation","Second Xiangya Hospital of Central South University","McGill University"]},{name:"Zhening Liu",institutions:["Montreal Neurological Institute and Hospital","Central South University","Capital Medical University","Institute of Automation","Second Xiangya Hospital of Central South University","McGill University"]},{name:"Tianzi Jiang",institutions:["Montreal Neurological Institute and Hospital","Central South University","Capital Medical University","Institute of Automation","Second Xiangya Hospital of Central South University","McGill University"]}],authorString:"Yong Liu; Meng Liang; Yuan Zhou; Yong He; Yihui Hao; Ming Song; Chunshui Yu; Haihong Liu; Zhening Liu; Tianzi Jiang",institutions:["Capital Medical University","Central South University","Chinese Academy of Sciences","Institute of Automation","McGill University","Montreal Neurological Institute and Hospital","Second Xiangya Hospital of Central South University"],countries:["CA","CN"],year:2008,journal:"Brain",citations:1055,abstract:"The human brain has been described as a large, sparse, complex network characterized by efficient small-world properties, which assure that the brain generates and integrates information with high efficiency. Many previous neuroimaging studies have provided consistent evidence of 'dysfunctional connectivity' among the brain regions in schizophrenia; however, little is known about whether or not this dysfunctional connectivity causes disruption of the topological properties of brain functional networks. To this end, we investigated the topological properties of human brain functional networks derived from resting-state functional magnetic resonance imaging (fMRI). Data was obtained from 31 schizophrenia patients and 31 healthy subjects; then functional connectivity between 90 cortical and sub-cortical regions was estimated by partial correlation analysis and thresholded to construct a set of undirected graphs. Our findings demonstrated that the brain functional networks had efficient small-world properties in the healthy subjects; whereas these properties were disrupted in the patients with schizophrenia. Brain functional networks have efficient small-world properties which support efficient parallel information transfer at a relatively low cost. More importantly, in patients with schizophrenia the small-world topological properties are significantly altered in many brain regions in the prefrontal, parietal and temporal lobes. These findings are consistent with a hypothesis of dysfunctional integration of the brain in this illness. Specifically, we found that these altered topological measurements correlate with illness duration in schizophrenia. Detection and estimation of these alterations could prove helpful for understanding the pathophysiological mechanism as well as for evaluation of the severity of schizophrenia.",keywords:["Schizophrenia","Dysfunctional family","Neuroscience","Functional magnetic resonance imaging","Neuroimaging","Human brain","Resting state fMRI"],concepts:["Schizophrenia (object-oriented programming)","Dysfunctional family","Neuroscience","Functional magnetic resonance imaging","Neuroimaging","Human brain","Psychology","Resting state fMRI"],topics:["Functional Brain Connectivity Studies","Mental Health Research Topics","Neural dynamics and brain function"],pdf_url:"https://academic.oup.com/brain/article-pdf/131/4/945/16694858/awn018.pdf",is_oa:!0,n_refs:77,n_refs_in_core:10,degree:64,community:1,deg_w:1200.5,betweenness:.0074,pagerank:.00836,eigenvector:.1331,pdf_file:null,pdf_downloaded:!1},{id:46,oaid:"W2026384313",doi:"10.1186/1753-4631-1-3",title:"Graph theoretical analysis of complex networks in the brain",authors:[{name:"Cornelis J. Stam",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Jaap C. Reijneveld",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]}],authorString:"Cornelis J. Stam; Jaap C. Reijneveld",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"],countries:["NL"],year:2007,journal:"Nonlinear Biomedical Physics",citations:1053,abstract:"Since the discovery of small-world and scale-free networks the study of complex systems from a network perspective has taken an enormous flight. In recent years many important properties of complex networks have been delineated. In particular, significant progress has been made in understanding the relationship between the structural properties of networks and the nature of dynamics taking place on these networks. For instance, the 'synchronizability' of complex networks of coupled oscillators can be determined by graph spectral analysis. These developments in the theory of complex networks have inspired new applications in the field of neuroscience. Graph analysis has been used in the study of models of neural networks, anatomical connectivity, and functional connectivity based upon fMRI, EEG and MEG. These studies suggest that the human brain can be modelled as a complex network, and may have a small-world structure both at the level of anatomical as well as functional connectivity. This small-world structure is hypothesized to reflect an optimal situation associated with rapid synchronization and information transfer, minimal wiring costs, as well as a balance between local processing and global integration. The topological structure of functional networks is probably restrained by genetic and anatomical factors, but can be modified during tasks. There is also increasing evidence that various types of brain disease such as Alzheimer's disease, schizophrenia, brain tumours and epilepsy may be associated with deviations of the functional network topology from the optimal small-world pattern.",keywords:["Complex network","Small-world network","Graph theory","Network science","Neuroscience","Network analysis","Synchronization"],concepts:["Complex network","Computer science","Small-world network","Graph theory","Network science","Neuroscience","Network analysis","Synchronization (alternating current)"],topics:["Neural dynamics and brain function","Functional Brain Connectivity Studies","Gene Regulatory Network Analysis"],pdf_url:"https://nonlinearbiomedphys.biomedcentral.com/counter/pdf/10.1186/1753-4631-1-3",is_oa:!0,n_refs:135,n_refs_in_core:8,degree:43,community:1,deg_w:806,betweenness:.0028,pagerank:.00584,eigenvector:.0903,pdf_file:"Stam_2007.pdf",pdf_downloaded:!0},{id:47,oaid:"W2101334128",doi:"10.1093/brain/awq075",title:"Divergent network connectivity changes in behavioural variant frontotemporal dementia and Alzheimer’s disease",authors:[{name:"Juan Zhou",institutions:["University of California, San Francisco","University Memory and Aging Center"]},{name:"Michael D. Greicius",institutions:["Stanford University"]},{name:"Efstathios D. Gennatas",institutions:["University of California, San Francisco","University Memory and Aging Center"]},{name:"Matthew E. Growdon",institutions:["University of California, San Francisco","University Memory and Aging Center"]},{name:"Jung Yun Jang",institutions:["University of California, San Francisco","University Memory and Aging Center"]},{name:"Gil D. Rabinovici",institutions:["University of California, San Francisco","University Memory and Aging Center"]},{name:"Joel H. Kramer",institutions:["University of California, San Francisco","University Memory and Aging Center"]},{name:"Michael W. Weiner",institutions:["San Francisco VA Medical Center","United States Department of Veterans Affairs"]},{name:"Bruce L. Miller",institutions:["University of California, San Francisco","University Memory and Aging Center"]},{name:"William W. Seeley",institutions:["University of California, San Francisco","University Memory and Aging Center"]}],authorString:"Juan Zhou; Michael D. Greicius; Efstathios D. Gennatas; Matthew E. Growdon; Jung Yun Jang; Gil D. Rabinovici; Joel H. Kramer; Michael W. Weiner; Bruce L. Miller; William W. Seeley",institutions:["San Francisco VA Medical Center","Stanford University","United States Department of Veterans Affairs","University Memory and Aging Center","University of California, San Francisco"],countries:["US"],year:2010,journal:"Brain",citations:1032,abstract:"Resting-state or intrinsic connectivity network functional magnetic resonance imaging provides a new tool for mapping large-scale neural network function and dysfunction. Recently, we showed that behavioural variant frontotemporal dementia and Alzheimer's disease cause atrophy within two major networks, an anterior 'Salience Network' (atrophied in behavioural variant frontotemporal dementia) and a posterior 'Default Mode Network' (atrophied in Alzheimer's disease). These networks exhibit an anti-correlated relationship with each other in the healthy brain. The two diseases also feature divergent symptom-deficit profiles, with behavioural variant frontotemporal dementia undermining social-emotional function and preserving or enhancing visuospatial skills, and Alzheimer's disease showing the inverse pattern. We hypothesized that these disorders would exert opposing connectivity effects within the Salience Network (disrupted in behavioural variant frontotemporal dementia but enhanced in Alzheimer's disease) and the Default Mode Network (disrupted in Alzheimer's disease but enhanced in behavioural variant frontotemporal dementia). With task-free functional magnetic resonance imaging, we tested these ideas in behavioural variant frontotemporal dementia, Alzheimer's disease and healthy age-matched controls (n = 12 per group), using independent component analyses to generate group-level network contrasts. As predicted, behavioural variant frontotemporal dementia attenuated Salience Network connectivity, most notably in frontoinsular, cingulate, striatal, thalamic and brainstem nodes, but enhanced connectivity within the Default Mode Network. Alzheimer's disease, in contrast, reduced Default Mode Network connectivity to posterior hippocampus, medial cingulo-parieto-occipital regions and the dorsal raphe nucleus, but intensified Salience Network connectivity. Specific regions of connectivity disruption within each targeted network predicted intrinsic connectivity enhancement within the reciprocal network. In behavioural variant frontotemporal dementia, clinical severity correlated with loss of right frontoinsular Salience Network connectivity and with biparietal Default Mode Network connectivity enhancement. Based on these results, we explored whether a combined index of Salience Network and Default Mode Network connectivity might discriminate between the three groups. Linear discriminant analysis achieved 92% clinical classification accuracy, including 100% separation of behavioural variant frontotemporal dementia and Alzheimer's disease. Patients whose clinical diagnoses were supported by molecular imaging, genetics, or pathology showed 100% separation using this method, including four diagnostically equivocal 'test' patients not used to train the algorithm. Overall, the findings suggest that behavioural variant frontotemporal dementia and Alzheimer's disease lead to divergent network connectivity patterns, consistent with known reciprocal network interactions and the strength and deficit profiles of the two disorders. Further developed, intrinsic connectivity network signatures may provide simple, inexpensive, and non-invasive biomarkers for dementia differential diagnosis and disease monitoring.",keywords:["Frontotemporal dementia","Dementia","Alzheimer's disease","Neuroscience","Disease","Medicine","Pathology"],concepts:["Frontotemporal dementia","Dementia","Alzheimer's disease","Neuroscience","Disease","Psychology","Medicine"],topics:["Functional Brain Connectivity Studies","Dementia and Cognitive Impairment Research","Alzheimer's disease research and treatments"],pdf_url:"https://academic.oup.com/brain/article-pdf/133/5/1352/16697214/awq075.pdf",is_oa:!0,n_refs:106,n_refs_in_core:9,degree:30,community:2,deg_w:378,betweenness:.0017,pagerank:.00357,eigenvector:.0151,pdf_file:null,pdf_downloaded:!1},{id:48,oaid:"W2007572953",doi:"10.1073/pnas.0708803104",title:"Selective changes of resting-state networks in individuals at risk for Alzheimer's disease",authors:[{name:"Christian Sorg",institutions:[]},{name:"Valentin Riedl",institutions:["Neurology, Inc","Technical University of Munich","Ludwig-Maximilians-Universität München"]},{name:"Mark Mühlau",institutions:["Neurology, Inc","Technical University of Munich"]},{name:"Vince D. Calhoun",institutions:["University of New Mexico"]},{name:"Tom Eichele",institutions:["University of Bergen"]},{name:"Leonhard Läer",institutions:["Heliophysics","Technical University of Munich"]},{name:"Alexander Drzezga",institutions:["TUM Klinikum","Technical University of Munich"]},{name:"Hans Förstl",institutions:["Technical University of Munich"]},{name:"Alexander Kurz",institutions:["Technical University of Munich"]},{name:"Claus Zimmer",institutions:["Heliophysics","Technical University of Munich"]},{name:"Afra M. Wohlschläger",institutions:["TUM Klinikum","Heliophysics","Neurology, Inc","Technical University of Munich"]}],authorString:"Christian Sorg; Valentin Riedl; Mark Mühlau; Vince D. Calhoun; Tom Eichele; Leonhard Läer; Alexander Drzezga; Hans Förstl; Alexander Kurz; Claus Zimmer; Afra M. Wohlschläger",institutions:["Heliophysics","Ludwig-Maximilians-Universität München","Neurology, Inc","TUM Klinikum","Technical University of Munich","University of Bergen","University of New Mexico"],countries:["DE","NO","US"],year:2007,journal:"Proceedings of the National Academy of Sciences",citations:1026,abstract:"Alzheimer's disease (AD) is a neurodegenerative disorder that prominently affects cerebral connectivity. Assessing the functional connectivity at rest, recent functional MRI (fMRI) studies reported on the existence of resting-state networks (RSNs). RSNs are characterized by spatially coherent, spontaneous fluctuations in the blood oxygen level-dependent signal and are made up of regional patterns commonly involved in functions such as sensory, attention, or default mode processing. In AD, the default mode network (DMN) is affected by reduced functional connectivity and atrophy. In this work, we analyzed functional and structural MRI data from healthy elderly (n = 16) and patients with amnestic mild cognitive impairment (aMCI) (n = 24), a syndrome of high risk for developing AD. Two questions were addressed: (i) Are any RSNs altered in aMCI? (ii) Do changes in functional connectivity relate to possible structural changes? Independent component analysis of resting-state fMRI data identified eight spatially consistent RSNs. Only selected areas of the DMN and the executive attention network demonstrated reduced network-related activity in the patient group. Voxel-based morphometry revealed atrophy in both medial temporal lobes (MTL) of the patients. The functional connectivity between both hippocampi in the MTLs and the posterior cingulate of the DMN was present in healthy controls but absent in patients. We conclude that in individuals at risk for AD, a specific subset of RSNs is altered, likely representing effects of ongoing early neurodegeneration. We interpret our finding as a proof of principle, demonstrating that functional brain disorders can be characterized by functional-disconnectivity profiles of RSNs.",keywords:["Default mode network","Resting state fMRI","Posterior cingulate","Neuroscience","Atrophy","Functional magnetic resonance imaging","Functional connectivity"],concepts:["Default mode network","Resting state fMRI","Posterior cingulate","Neuroscience","Atrophy","Psychology","Functional magnetic resonance imaging","Functional connectivity"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://www.ncbi.nlm.nih.gov/pmc/articles/2141850",is_oa:!0,n_refs:58,n_refs_in_core:4,degree:29,community:2,deg_w:352,betweenness:.0013,pagerank:.00338,eigenvector:.0148,pdf_file:null,pdf_downloaded:!1},{id:49,oaid:"W1983537704",doi:"10.1523/jneurosci.0141-08.2008",title:"Structural Insights into Aberrant Topological Patterns of Large-Scale Cortical Networks in Alzheimer's Disease",authors:[{name:"Yong He",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Zhang Chen",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Alan C. Evans",institutions:["Montreal Neurological Institute and Hospital","McGill University"]}],authorString:"Yong He; Zhang Chen; Alan C. Evans",institutions:["McGill University","Montreal Neurological Institute and Hospital"],countries:["CA"],year:2008,journal:"Journal of Neuroscience",citations:997,abstract:"Recent research on Alzheimer's disease (AD) has shown that cognitive and memory decline in this disease is accompanied by disrupted changes in the coordination of large-scale brain functional networks. However, alterations in coordinated patterns of structural brain networks in AD are still poorly understood. Here, we used cortical thickness measurement from magnetic resonance imaging to investigate large-scale structural brain networks in 92 AD patients and 97 normal controls. Brain networks were constructed by thresholding cortical thickness correlation matrices of 54 regions and analyzed using graph theoretical approaches. Compared with controls, AD patients showed decreased cortical thickness intercorrelations between the bilateral parietal regions and increased intercorrelations in several selective regions involving the lateral temporal and parietal cortex as well as the cingulate and medial frontal cortex regions. Specially, AD patients showed abnormal small-world architecture in the structural cortical networks (increased clustering and shortest paths linking individual regions), implying a less optimal topological organization in AD. Moreover, AD patients were associated with reduced nodal centrality predominantly in the temporal and parietal heteromodal association cortex regions and increased nodal centrality in the occipital cortex regions. Finally, the brain networks of AD were about equally as robust to random failures as those of controls, but more vulnerable against targeted attacks, presumably because of the effects of pathological topological organization. Our findings suggest that the coordinated patterns of cortical morphology are widely altered in AD patients, thus providing structural evidence for disrupted integrity in large-scale brain networks that underlie cognition. This work has implications for our understanding of how functional deficits in patients are associated with their underlying structural (morphological) basis.",keywords:["Neuroscience","Cortex","Posterior parietal cortex","Centrality","Cerebral cortex","Cognition","Alzheimer's disease"],concepts:["Neuroscience","Cortex (anatomy)","Posterior parietal cortex","Centrality","Cerebral cortex","Psychology","Cognition","Alzheimer's disease"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/28/18/4756.full.pdf",is_oa:!0,n_refs:96,n_refs_in_core:9,degree:57,community:1,deg_w:1195,betweenness:.0037,pagerank:.00824,eigenvector:.1361,pdf_file:null,pdf_downloaded:!1},{id:50,oaid:"W2100145912",doi:"10.1038/ncomms9414",title:"Controllability of structural brain networks",authors:[{name:"Shi Gu",institutions:["University of the Sciences","University of Pennsylvania"]},{name:"Fabio Pasqualetti",institutions:["University of California, Riverside"]},{name:"Matthew Cieslak",institutions:["University of California, Santa Barbara"]},{name:"Qawi K. Telesford",institutions:["DEVCOM Army Research Laboratory","University of Pennsylvania"]},{name:"Alfred B. Yu",institutions:["DEVCOM Army Research Laboratory"]},{name:"Ari E. Kahn",institutions:["University of Pennsylvania"]},{name:"John D. Medaglia",institutions:["University of Pennsylvania"]},{name:"Jean M. Vettel",institutions:["University of California, Santa Barbara","DEVCOM Army Research Laboratory"]},{name:"Michael B. Miller",institutions:["University of California, Santa Barbara"]},{name:"Scott T. Grafton",institutions:["University of California, Santa Barbara"]},{name:"Danielle S. Bassett",institutions:["University of Pennsylvania"]}],authorString:"Shi Gu; Fabio Pasqualetti; Matthew Cieslak; Qawi K. Telesford; Alfred B. Yu; Ari E. Kahn; John D. Medaglia; Jean M. Vettel; Michael B. Miller; Scott T. Grafton; Danielle S. Bassett",institutions:["DEVCOM Army Research Laboratory","University of California, Riverside","University of California, Santa Barbara","University of Pennsylvania","University of the Sciences"],countries:["US"],year:2015,journal:"Nature Communications",citations:980,abstract:"Cognitive function is driven by dynamic interactions between large-scale neural circuits or networks, enabling behaviour. However, fundamental principles constraining these dynamic network processes have remained elusive. Here we use tools from control and network theories to offer a mechanistic explanation for how the brain moves between cognitive states drawn from the network organization of white matter microstructure. Our results suggest that densely connected areas, particularly in the default mode system, facilitate the movement of the brain to many easily reachable states. Weakly connected areas, particularly in cognitive control systems, facilitate the movement of the brain to difficult-to-reach states. Areas located on the boundary between network communities, particularly in attentional control systems, facilitate the integration or segregation of diverse cognitive systems. Our results suggest that structural network differences between cognitive circuits dictate their distinct roles in controlling trajectories of brain network function.",keywords:["Cognition","Controllability","Default mode network","Neuroscience","Network controllability","Biological neural network","Cognitive network"],concepts:["Cognition","Controllability","Computer science","Default mode network","Neuroscience","Network controllability","Biological neural network","Cognitive network"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.nature.com/articles/ncomms9414.pdf",is_oa:!0,n_refs:148,n_refs_in_core:12,degree:33,community:0,deg_w:493,betweenness:.0016,pagerank:.00417,eigenvector:.028,pdf_file:"Gu_2015.pdf",pdf_downloaded:!0},{id:51,oaid:"W2112151839",doi:"10.1093/cercor/bhs270",title:"A Weighted and Directed Interareal Connectivity Matrix for Macaque Cerebral Cortex",authors:[{name:"Nikola T. Markov",institutions:["Université Claude Bernard Lyon 1","Inserm","Yale University","Institut Cellule Souche et Cerveau"]},{name:"Mária Ercsey-Ravasz",institutions:["University of Notre Dame","Babeș-Bolyai University"]},{name:"Ana Rita Ribeiro Gomes",institutions:["Université Claude Bernard Lyon 1","Inserm","Institut Cellule Souche et Cerveau"]},{name:"Camille Lamy",institutions:["Université Claude Bernard Lyon 1","Inserm","Institut Cellule Souche et Cerveau"]},{name:"Loïc Magrou",institutions:["Université Claude Bernard Lyon 1","Inserm","Institut Cellule Souche et Cerveau"]},{name:"Julien Vezoli",institutions:["Université Claude Bernard Lyon 1","Inserm","Ernst Strüngmann Institute for Neuroscience","Institut Cellule Souche et Cerveau"]},{name:"Pierre Misery",institutions:["Université Claude Bernard Lyon 1","Inserm","Institut Cellule Souche et Cerveau"]},{name:"Arnaud Falchier",institutions:["Université Claude Bernard Lyon 1","Nathan Kline Institute for Psychiatric Research","Inserm","Institut Cellule Souche et Cerveau"]},{name:"René Quilodran",institutions:["Université Claude Bernard Lyon 1","Inserm","Institut Cellule Souche et Cerveau","University of Valparaíso"]},{name:"Marie-Alice Gariel",institutions:["Université Claude Bernard Lyon 1","Netherlands Institute for Neuroscience","Inserm","Institut Cellule Souche et Cerveau"]},{name:"Jérôme Sallet",institutions:["Université Claude Bernard Lyon 1","Inserm","University of Oxford","Institut Cellule Souche et Cerveau"]},{name:"R. Gamanut",institutions:["Université Claude Bernard Lyon 1","Inserm","Institut Cellule Souche et Cerveau"]},{name:"Cyril Huissoud",institutions:["Université Claude Bernard Lyon 1","Inserm","Hospices Civils de Lyon","Institut Cellule Souche et Cerveau"]},{name:"Simon Clavagnier",institutions:["Université Claude Bernard Lyon 1","Inserm","Institut Cellule Souche et Cerveau","McGill University"]},{name:"Pascale Giroud",institutions:["Université Claude Bernard Lyon 1","Inserm","Institut Cellule Souche et Cerveau"]},{name:"Dominique Sappey‐Marinier",institutions:["Centre d'Exploration et de Recherche Médicale par Emission de Positons"]},{name:"Pascal Barone",institutions:["Université Claude Bernard Lyon 1","Inserm","Institut Cellule Souche et Cerveau","Centre de recherche cerveau et cognition"]},{name:"Colette Dehay",institutions:["Université Claude Bernard Lyon 1","Inserm","Institut Cellule Souche et Cerveau"]},{name:"Zoltán Toroczkai",institutions:["University of Notre Dame"]},{name:"Kenneth Knoblauch",institutions:["Université Claude Bernard Lyon 1","Inserm","Institut Cellule Souche et Cerveau"]},{name:"David C. Van Essen",institutions:["Washington University in St. Louis"]},{name:"Henry Kennedy",institutions:["Université Claude Bernard Lyon 1","Inserm","Institut Cellule Souche et Cerveau"]}],authorString:"Nikola T. Markov; Mária Ercsey-Ravasz; Ana Rita Ribeiro Gomes; Camille Lamy; Loïc Magrou; Julien Vezoli; Pierre Misery; Arnaud Falchier; René Quilodran; Marie-Alice Gariel; Jérôme Sallet; R. Gamanut et al.",institutions:["Babeș-Bolyai University","Centre d'Exploration et de Recherche Médicale par Emission de Positons","Centre de recherche cerveau et cognition","Ernst Strüngmann Institute for Neuroscience","Hospices Civils de Lyon","Inserm","Institut Cellule Souche et Cerveau","McGill University","Nathan Kline Institute for Psychiatric Research","Netherlands Institute for Neuroscience","University of Notre Dame","University of Oxford","University of Valparaíso","Université Claude Bernard Lyon 1","Washington University in St. Louis","Yale University"],countries:["CA","CL","DE","FR","GB","NL","RO","US"],year:2012,journal:"Cerebral Cortex",citations:971,abstract:"Retrograde tracer injections in 29 of the 91 areas of the macaque cerebral cortex revealed 1,615 interareal pathways, a third of which have not previously been reported. A weight index (extrinsic fraction of labeled neurons [FLNe]) was determined for each area-to-area pathway. Newly found projections were weaker on average compared with the known projections; nevertheless, the 2 sets of pathways had extensively overlapping weight distributions. Repeat injections across individuals revealed modest FLNe variability given the range of FLNe values (standard deviation <1 log unit, range 5 log units). The connectivity profile for each area conformed to a lognormal distribution, where a majority of projections are moderate or weak in strength. In the G29 × 29 interareal subgraph, two-thirds of the connections that can exist do exist. Analysis of the smallest set of areas that collects links from all 91 nodes of the G29 × 91 subgraph (dominating set analysis) confirms the dense (66%) structure of the cortical matrix. The G29 × 29 subgraph suggests an unexpectedly high incidence of unidirectional links. The directed and weighted G29 × 91 connectivity matrix for the macaque will be valuable for comparison with connectivity analyses in other species, including humans. It will also inform future modeling studies that explore the regularities of cortical networks.",keywords:["Macaque","Cerebral cortex","Neuroscience"],concepts:["Macaque","Cerebral cortex","Neuroscience","Mathematics"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://academic.oup.com/cercor/article-pdf/24/1/17/14097351/bhs270.pdf",is_oa:!0,n_refs:121,n_refs_in_core:6,degree:29,community:0,deg_w:356,betweenness:.0016,pagerank:.00314,eigenvector:.0306,pdf_file:null,pdf_downloaded:!1},{id:52,oaid:"W2002562224",doi:"10.3389/fnsys.2010.00008",title:"Advances and pitfalls in the analysis and interpretation of resting-state FMRI data",authors:[{name:"David M. Cole",institutions:["Imperial College London"]}],authorString:"David M. Cole",institutions:["Imperial College London"],countries:["GB"],year:2010,journal:"Frontiers in Systems Neuroscience",citations:969,abstract:"The last 15 years have witnessed a steady increase in the number of resting-state functional neuroimaging studies. The connectivity patterns of multiple functional, distributed, large-scale networks of brain dynamics have been recognised for their potential as useful tools in the domain of systems and other neurosciences. The application of functional connectivity methods to areas such as cognitive psychology, clinical diagnosis and treatment progression has yielded promising preliminary results, but is yet to be fully realised. This is due, in part, to an array of methodological and interpretative issues that remain to be resolved. We here present a review of the methods most commonly applied in this rapidly advancing field, such as seed-based correlation analysis and independent component analysis, along with examples of their use at the individual subject and group analysis levels and a discussion of practical and theoretical issues arising from this data 'explosion'. We describe the similarities and differences across these varied statistical approaches to processing resting-state functional magnetic resonance imaging signals, and conclude that further technical optimisation and experimental refinement is required in order to fully delineate and characterise the gross complexity of the human neural functional architecture.",keywords:["Resting state fMRI","Neuroimaging","Functional connectivity","Cognitive science","Neuroscience","Cognition"],concepts:["Resting state fMRI","Computer science","Neuroimaging","Functional connectivity","Cognitive science","Artificial intelligence","Neuroscience","Cognition"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnsys.2010.00008/pdf",is_oa:!0,n_refs:140,n_refs_in_core:11,degree:33,community:2,deg_w:674,betweenness:.0022,pagerank:.00544,eigenvector:.0487,pdf_file:"Cole_2010.pdf",pdf_downloaded:!0},{id:53,oaid:"W2124141514",doi:"10.1093/cercor/bhn256",title:"The Resting Brain: Unconstrained yet Reliable",authors:[{name:"Zarrar Shehzad",institutions:[]},{name:"Clare Kelly",institutions:[]},{name:"Philip T. Reiss",institutions:["Nathan Kline Institute for Psychiatric Research"]},{name:"Dylan G. Gee",institutions:[]},{name:"Kristin Gotimer",institutions:[]},{name:"Lucina Q. Uddin",institutions:["Stanford University"]},{name:"Sang H. Lee",institutions:["Nathan Kline Institute for Psychiatric Research"]},{name:"Daniel S. Margulies",institutions:["Humboldt-Universität zu Berlin"]},{name:"Amy Krain Roy",institutions:[]},{name:"Bharat B. Biswal",institutions:["Nathan Kline Institute for Psychiatric Research","University Hospital, Newark"]},{name:"Eva Petkova",institutions:["Nathan Kline Institute for Psychiatric Research"]},{name:"F. Xavier Castellanos",institutions:["Nathan Kline Institute for Psychiatric Research"]},{name:"Michael P. Milham",institutions:[]}],authorString:"Zarrar Shehzad; Clare Kelly; Philip T. Reiss; Dylan G. Gee; Kristin Gotimer; Lucina Q. Uddin; Sang H. Lee; Daniel S. Margulies; Amy Krain Roy; Bharat B. Biswal; Eva Petkova; F. Xavier Castellanos et al.",institutions:["Humboldt-Universität zu Berlin","Nathan Kline Institute for Psychiatric Research","Stanford University","University Hospital, Newark"],countries:["DE","US"],year:2009,journal:"Cerebral Cortex",citations:947,abstract:'Recent years have witnessed an upsurge in the usage of resting-state functional magnetic resonance imaging (fMRI) to examine functional connectivity (fcMRI), both in normal and pathological populations. Despite this increasing popularity, concerns about the psychologically unconstrained nature of the "resting-state" remain. Across studies, the patterns of functional connectivity detected are remarkably consistent. However, the test-retest reliability for measures of resting state fcMRI measures has not been determined. Here, we quantify the test-retest reliability, using resting scans from 26 participants at 3 different time points. Specifically, we assessed intersession (>5 months apart), intrasession (<1 h apart), and multiscan (across all 3 scans) reliability and consistency for both region-of-interest and voxel-wise analyses. For both approaches, we observed modest to high reliability across connections, dependent upon 3 predictive factors: 1) correlation significance (significantly nonzero > nonsignificant), 2) correlation valence (positive > negative), and 3) network membership (default mode > task positive network). Short- and long-term measures of the consistency of global connectivity patterns were highly robust. Finally, hierarchical clustering solutions were highly reproducible, both across participants and sessions. Our findings provide a solid foundation for continued examination of resting state fcMRI in typical and atypical populations.',keywords:["Resting state fMRI","Functional connectivity","Default mode network","Reliability","Voxel","Functional magnetic resonance imaging","Correlation"],concepts:["Resting state fMRI","Functional connectivity","Default mode network","Reliability (semiconductor)","Voxel","Functional magnetic resonance imaging","Correlation","Psychology"],topics:["Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications","Neural dynamics and brain function"],pdf_url:"https://academic.oup.com/cercor/article-pdf/19/10/2209/17300841/bhn256.pdf",is_oa:!0,n_refs:88,n_refs_in_core:13,degree:45,community:2,deg_w:814.5,betweenness:.0032,pagerank:.00625,eigenvector:.0702,pdf_file:null,pdf_downloaded:!1},{id:54,oaid:"W2111709777",doi:null,title:"Mapping functionally related regions of brain with functional connectivity MR imaging.",authors:[{name:"Dietmar Cordes",institutions:["University of Wisconsin–Madison"]},{name:"Victor M. Haughton",institutions:[]},{name:"Konstantinos Arfanakis",institutions:[]},{name:"Gary Wendt",institutions:[]},{name:"P A Turski",institutions:[]},{name:"Chad H. Moritz",institutions:[]},{name:"Michelle Quigley",institutions:[]},{name:"M. Elizabeth Meyerand",institutions:[]}],authorString:"Dietmar Cordes; Victor M. Haughton; Konstantinos Arfanakis; Gary Wendt; P A Turski; Chad H. Moritz; Michelle Quigley; M. Elizabeth Meyerand",institutions:["University of Wisconsin–Madison"],countries:["US"],year:2e3,journal:"PubMed",citations:942,abstract:"BACKGROUND AND PURPOSE: In subjects who are performing no prescribed cognitive task, functional connectivity mapped with MR imaging (fcMRI) shows regions with synchronous fluctuations of cerebral blood flow. When specific tasks are performed, functional MR imaging (fMRI) can map locations in which regional cerebral blood flow increases synchronously with the performance of the task. We tested the hypothesis that fcMRI maps, based on the synchrony of low-frequency blood flow fluctuations, identify brain regions that show activation on fMRI maps of sensorimotor, visual, language, and auditory tasks. METHODS: In four volunteers, task-activation fMRI and functional connectivity (resting-state) fcMRI data were acquired. A small region of interest (in an area that showed maximal task activation) was chosen, and the correlation coefficient of the corresponding resting-state signal with the signal of all other voxels in the resting data set was calculated. The correlation coefficient was decomposed into frequency components and its distribution determined for each fcMRI map. The fcMRI maps were compared with the fMRI maps. RESULTS: For each task, fcMRI maps based on one to four seed voxel(s) produced clusters of voxels in regions of eloquent cortex. For each fMRI map a closely corresponding fcMRI map was obtained. The frequencies that predominated in the cross-correlation coefficients for the functionally related regions were below 0.1 Hz. CONCLUSION: Functionally related brain regions can be identified by means of their synchronous slow fluctuations in signal intensity. Such blood flow synchrony can be detected in sensorimotor areas, expressive and receptive language regions, and the visual cortex by fcMRI. Regions identified by the slow synchronous fluctuations are similar to those activated by motor, language, or visual tasks.",keywords:["Voxel","Resting state fMRI","Brain mapping","Cerebral blood flow","Neuroscience","Visual cortex","Functional magnetic resonance imaging","Correlation"],concepts:["Voxel","Resting state fMRI","Brain mapping","Cerebral blood flow","Neuroscience","Visual cortex","Functional magnetic resonance imaging","Correlation"],topics:["Functional Brain Connectivity Studies","Face Recognition and Perception","Neural and Behavioral Psychology Studies"],pdf_url:"https://www.ncbi.nlm.nih.gov/pmc/articles/8174861",is_oa:!0,n_refs:32,n_refs_in_core:0,degree:16,community:2,deg_w:126,betweenness:4e-4,pagerank:.00164,eigenvector:.0096,pdf_file:null,pdf_downloaded:!1},{id:55,oaid:"W2040092971",doi:"10.1371/journal.pcbi.1001066",title:"Structural Properties of the Caenorhabditis elegans Neuronal Network",authors:[{name:"Lav R. Varshney",institutions:["Massachusetts Institute of Technology"]},{name:"Beth L. Chen",institutions:["Cold Spring Harbor Laboratory"]},{name:"Eric Paniagua",institutions:["California Institute of Technology"]},{name:"David H. Hall",institutions:["Albert Einstein College of Medicine"]},{name:"Dmitri B. Chklovskii",institutions:["Janelia Research Campus","Howard Hughes Medical Institute"]}],authorString:"Lav R. Varshney; Beth L. Chen; Eric Paniagua; David H. Hall; Dmitri B. Chklovskii",institutions:["Albert Einstein College of Medicine","California Institute of Technology","Cold Spring Harbor Laboratory","Howard Hughes Medical Institute","Janelia Research Campus","Massachusetts Institute of Technology"],countries:["US"],year:2011,journal:"PLoS Computational Biology",citations:935,abstract:"Despite recent interest in reconstructing neuronal networks, complete wiring diagrams on the level of individual synapses remain scarce and the insights into function they can provide remain unclear. Even for Caenorhabditis elegans, whose neuronal network is relatively small and stereotypical from animal to animal, published wiring diagrams are neither accurate nor complete and self-consistent. Using materials from White et al. and new electron micrographs we assemble whole, self-consistent gap junction and chemical synapse networks of hermaphrodite C. elegans. We propose a method to visualize the wiring diagram, which reflects network signal flow. We calculate statistical and topological properties of the network, such as degree distributions, synaptic multiplicities, and small-world properties, that help in understanding network signal propagation. We identify neurons that may play central roles in information processing, and network motifs that could serve as functional modules of the network. We explore propagation of neuronal activity in response to sensory or artificial stimulation using linear systems theory and find several activity patterns that could serve as substrates of previously described behaviors. Finally, we analyze the interaction between the gap junction and the chemical synapse networks. Since several statistical properties of the C. elegans network, such as multiplicity and motif distributions are similar to those found in mammalian neocortex, they likely point to general principles of neuronal networks. The wiring diagram reported here can help in understanding the mechanistic basis of behavior by generating predictions about future experiments involving genetic perturbations, laser ablations, or monitoring propagation of neuronal activity in response to stimulation.",keywords:["Caenorhabditis elegans","Neuroscience","Biological neural network","Wiring diagram","Gap junction","Neocortex"],concepts:["Caenorhabditis elegans","Neuroscience","Biological neural network","Computer science","Wiring diagram","Gap junction","Biology","Neocortex"],topics:["Genetics, Aging, and Longevity in Model Organisms","Circadian rhythm and melatonin","Photoreceptor and optogenetics research"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1001066&type=printable",is_oa:!0,n_refs:106,n_refs_in_core:5,degree:20,community:0,deg_w:209.5,betweenness:6e-4,pagerank:.00216,eigenvector:.0152,pdf_file:"Varshney_2011.pdf",pdf_downloaded:!0},{id:56,oaid:"W2116083905",doi:"10.1093/brain/awn262",title:"Graph theoretical analysis of magnetoencephalographic functional connectivity in Alzheimer's disease",authors:[{name:"Cornelis J. Stam",institutions:[]},{name:"Willem de Haan",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Andreas Daffertshofer",institutions:["Vrije Universiteit Amsterdam"]},{name:"B.F. Jones",institutions:["UK Dementia Research Institute","University College London"]},{name:"Ilonka Manshanden",institutions:[]},{name:"A. M. van Cappellen van Walsum",institutions:["Radboud University Nijmegen","Radboud University Medical Center","University of Twente"]},{name:"T. Montez",institutions:["University of Lisbon"]},{name:"J.P.A. Verbunt",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Jan C. de Munck",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Bob W. van Dijk",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Henk W. Berendse",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Philip Scheltens",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]}],authorString:"Cornelis J. Stam; Willem de Haan; Andreas Daffertshofer; B.F. Jones; Ilonka Manshanden; A. M. van Cappellen van Walsum; T. Montez; J.P.A. Verbunt; Jan C. de Munck; Bob W. van Dijk; Henk W. Berendse; Philip Scheltens",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam","Radboud University Medical Center","Radboud University Nijmegen","UK Dementia Research Institute","University College London","University of Lisbon","University of Twente","Vrije Universiteit Amsterdam"],countries:["GB","NL","PT"],year:2008,journal:"Brain",citations:932,abstract:"In this study we examined changes in the large-scale structure of resting-state brain networks in patients with Alzheimer's disease compared with non-demented controls, using concepts from graph theory. Magneto-encephalograms (MEG) were recorded in 18 Alzheimer's disease patients and 18 non-demented control subjects in a no-task, eyes-closed condition. For the main frequency bands, synchronization between all pairs of MEG channels was assessed using a phase lag index (PLI, a synchronization measure insensitive to volume conduction). PLI-weighted connectivity networks were calculated, and characterized by a mean clustering coefficient and path length. Alzheimer's disease patients showed a decrease of mean PLI in the lower alpha and beta band. In the lower alpha band, the clustering coefficient and path length were both decreased in Alzheimer's disease patients. Network changes in the lower alpha band were better explained by a 'Targeted Attack' model than by a 'Random Failure' model. Thus, Alzheimer's disease patients display a loss of resting-state functional connectivity in lower alpha and beta bands even when a measure insensitive to volume conduction effects is used. Moreover, the large-scale structure of lower alpha band functional networks in Alzheimer's disease is more random. The modelling results suggest that highly connected neural network 'hubs' may be especially at risk in Alzheimer's disease.",keywords:["Magnetoencephalography","Clustering coefficient","Alzheimer's disease","Neuroscience","Resting state fMRI","BETA","Electroencephalography","Disease"],concepts:["Magnetoencephalography","Clustering coefficient","Alzheimer's disease","Neuroscience","Resting state fMRI","BETA (programming language)","Electroencephalography","Disease"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:null,is_oa:!1,n_refs:87,n_refs_in_core:10,degree:43,community:1,deg_w:601,betweenness:.0029,pagerank:.00464,eigenvector:.0575,pdf_file:null,pdf_downloaded:!1},{id:57,oaid:"W1967931162",doi:"10.1097/wco.0b013e32832d93dd",title:"Human brain networks in health and disease",authors:[{name:"Danielle S. Bassett",institutions:["University of Cambridge","Addenbrooke's Hospital","National Institute of Mental Health"]},{name:"Edward T. Bullmore",institutions:["Addenbrooke's Hospital","GTx (United States)","GlaxoSmithKline (United Kingdom)"]}],authorString:"Danielle S. Bassett; Edward T. Bullmore",institutions:["Addenbrooke's Hospital","GTx (United States)","GlaxoSmithKline (United Kingdom)","National Institute of Mental Health","University of Cambridge"],countries:["GB","US"],year:2009,journal:"Current Opinion in Neurology",citations:930,abstract:"PURPOSE OF REVIEW: Recent developments in the statistical physics of complex networks have been translated to neuroimaging data in an effort to enhance our understanding of human brain structural and functional networks. This review focuses on studies using graph theoretical measures applied to structural MRI, diffusion MRI, functional MRI, electroencephalography, and magnetoencephalography data. RECENT FINDINGS: Complex network properties have been identified with some consistency in all modalities of neuroimaging data and over a range of spatial and time scales. Conserved properties include small worldness, high efficiency of information transfer for low wiring cost, modularity, and the existence of network hubs. Structural and functional network metrics have been found to be heritable and to change with normal aging. Clinical studies, principally in Alzheimer's disease and schizophrenia, have identified abnormalities of network configuration in patients. Future work will likely involve efforts to synthesize structural and functional networks in integrated models and to explore the interdependence of network configuration and cognitive performance. SUMMARY: Graph theoretical analysis of neuroimaging data is growing rapidly and could potentially provide a relatively simple but powerful quantitative framework to describe and compare whole human brain structural and functional networks under diverse experimental and clinical conditions.",keywords:["Neuroimaging","Modularity","Magnetoencephalography","Neuroscience","Modalities","Human brain","Diffusion MRI"],concepts:["Neuroimaging","Modularity (biology)","Magnetoencephalography","Computer science","Neuroscience","Modalities","Human brain","Diffusion MRI"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Mental Health Research Topics"],pdf_url:"https://www.ncbi.nlm.nih.gov/pmc/articles/2902726",is_oa:!0,n_refs:49,n_refs_in_core:16,degree:58,community:1,deg_w:929,betweenness:.0058,pagerank:.00662,eigenvector:.1053,pdf_file:null,pdf_downloaded:!1},{id:58,oaid:"W2107632000",doi:"10.1093/brain/awp313",title:"Default network connectivity reflects the level of consciousness in non-communicative brain-damaged patients",authors:[{name:"Audrey Vanhaudenhuyse",institutions:["University of Liège"]},{name:"Quentin Noirhomme",institutions:["University of Liège"]},{name:"Luaba Tshibanda",institutions:["University of Liège","Centre Hospitalier Universitaire de Liège"]},{name:"Marie‐Aurélie Bruno",institutions:["University of Liège"]},{name:"Pierre Boveroux",institutions:["University of Liège","Centre Hospitalier Universitaire de Liège"]},{name:"Caroline Schnakers",institutions:["University of Liège"]},{name:"Andrea Soddu",institutions:["University of Liège"]},{name:"Vincent Perlbarg",institutions:["Inserm","Sorbonne Université","Pitié-Salpêtrière Hospital"]},{name:"Didier Ledoux",institutions:["University of Liège","Centre Hospitalier Universitaire de Liège"]},{name:"Jean-François Brichant",institutions:["University of Liège","Centre Hospitalier Universitaire de Liège"]},{name:"Gustave Moonen",institutions:["University of Liège","Centre Hospitalier Universitaire de Liège"]},{name:"Pierre Maquet",institutions:["University of Liège"]},{name:"Michael D. Greicius",institutions:["Neurological Surgery","Stanford University"]},{name:"Steven Laureys",institutions:["University of Liège","Centre Hospitalier Universitaire de Liège"]},{name:"Mélanie Boly",institutions:["University of Liège","Centre Hospitalier Universitaire de Liège"]}],authorString:"Audrey Vanhaudenhuyse; Quentin Noirhomme; Luaba Tshibanda; Marie‐Aurélie Bruno; Pierre Boveroux; Caroline Schnakers; Andrea Soddu; Vincent Perlbarg; Didier Ledoux; Jean-François Brichant; Gustave Moonen; Pierre Maquet et al.",institutions:["Centre Hospitalier Universitaire de Liège","Inserm","Neurological Surgery","Pitié-Salpêtrière Hospital","Sorbonne Université","Stanford University","University of Liège"],countries:["BE","FR","US"],year:2009,journal:"Brain",citations:920,abstract:"The 'default network' is defined as a set of areas, encompassing posterior-cingulate/precuneus, anterior cingulate/mesiofrontal cortex and temporo-parietal junctions, that show more activity at rest than during attention-demanding tasks. Recent studies have shown that it is possible to reliably identify this network in the absence of any task, by resting state functional magnetic resonance imaging connectivity analyses in healthy volunteers. However, the functional significance of these spontaneous brain activity fluctuations remains unclear. The aim of this study was to test if the integrity of this resting-state connectivity pattern in the default network would differ in different pathological alterations of consciousness. Fourteen non-communicative brain-damaged patients and 14 healthy controls participated in the study. Connectivity was investigated using probabilistic independent component analysis, and an automated template-matching component selection approach. Connectivity in all default network areas was found to be negatively correlated with the degree of clinical consciousness impairment, ranging from healthy controls and locked-in syndrome to minimally conscious, vegetative then coma patients. Furthermore, precuneus connectivity was found to be significantly stronger in minimally conscious patients as compared with unconscious patients. Locked-in syndrome patient's default network connectivity was not significantly different from controls. Our results show that default network connectivity is decreased in severely brain-damaged patients, in proportion to their degree of consciousness impairment. Future prospective studies in a larger patient population are needed in order to evaluate the prognostic value of the presented methodology.",keywords:["Default mode network","Precuneus","Posterior cingulate","Minimally conscious state","Resting state fMRI","Functional magnetic resonance imaging","Locked-in syndrome"],concepts:["Default mode network","Precuneus","Posterior cingulate","Psychology","Minimally conscious state","Resting state fMRI","Functional magnetic resonance imaging","Locked-in syndrome"],topics:["Functional Brain Connectivity Studies","Traumatic Brain Injury Research","Atomic and Subatomic Physics Research"],pdf_url:"https://academic.oup.com/brain/article-pdf/133/1/161/16696417/awp313.pdf",is_oa:!0,n_refs:58,n_refs_in_core:6,degree:24,community:2,deg_w:237,betweenness:.0013,pagerank:.00253,eigenvector:.0102,pdf_file:null,pdf_downloaded:!1},{id:59,oaid:"W2511999769",doi:"10.1177/1073858416667720",title:"Small-World Brain Networks Revisited",authors:[{name:"Danielle S. Bassett",institutions:["University of Pennsylvania"]},{name:"Edward T. Bullmore",institutions:["GlaxoSmithKline (United Kingdom)","University of Cambridge"]}],authorString:"Danielle S. Bassett; Edward T. Bullmore",institutions:["GlaxoSmithKline (United Kingdom)","University of Cambridge","University of Pennsylvania"],countries:["GB","US"],year:2016,journal:"The Neuroscientist",citations:902,abstract:"It is nearly 20 years since the concept of a small-world network was first quantitatively defined, by a combination of high clustering and short path length; and about 10 years since this metric of complex network topology began to be widely applied to analysis of neuroimaging and other neuroscience data as part of the rapid growth of the new field of connectomics. Here, we review briefly the foundational concepts of graph theoretical estimation and generation of small-world networks. We take stock of some of the key developments in the field in the past decade and we consider in some detail the implications of recent studies using high-resolution tract-tracing methods to map the anatomical networks of the macaque and the mouse. In doing so, we draw attention to the important methodological distinction between topological analysis of binary or unweighted graphs, which have provided a popular but simple approach to brain network analysis in the past, and the topology of weighted graphs, which retain more biologically relevant information and are more appropriate to the increasingly sophisticated data on brain connectivity emerging from contemporary tract-tracing and other imaging studies. We conclude by highlighting some possible future trends in the further development of weighted small-worldness as part of a deeper and broader understanding of the topology and the functional value of the strong and weak links between areas of mammalian cortex.",keywords:["Connectomics","Macaque","Small-world network","Network topology","Power graph analysis","Complex network","Data science"],concepts:["Connectomics","Computer science","Macaque","Small-world network","Network topology","Power graph analysis","Complex network","Data science"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://journals.sagepub.com/doi/pdf/10.1177/1073858416667720",is_oa:!0,n_refs:136,n_refs_in_core:22,degree:40,community:0,deg_w:666,betweenness:.0028,pagerank:.00528,eigenvector:.046,pdf_file:null,pdf_downloaded:!1},{id:60,oaid:"W4295605475",doi:"10.31887/dcns.2013.15.3/osporns",title:"Structure and function of complex brain networks",authors:[{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]}],authorString:"Olaf Sporns",institutions:["Indiana University Bloomington"],countries:["US"],year:2013,journal:"Dialogues in Clinical Neuroscience",citations:881,abstract:"An increasing number of theoretical and empirical studies approach the function of the human brain from a network perspective. The analysis of brain networks is made feasible by the development of new imaging acquisition methods as well as new tools from graph theory and dynamical systems. This review surveys some of these methodological advances and summarizes recent findings on the architecture of structural and functional brain networks. Studies of the structural connectome reveal several modules or network communities that are interlinked by hub regions mediating communication processes between modules. Recent network analyses have shown that network hubs form a densely linked collective called a “rich club,” centrally positioned for attracting and dispersing signal traffic. In parallel, recordings of resting and task-evoked neural activity have revealed distinct resting-state networks that contribute to functions in distinct cognitive domains. Network methods are increasingly applied in a clinical context, and their promise for elucidating neural substrates of brain and mental disorders is discussed.",keywords:["Connectome","Neuroscience","Resting state fMRI","Context","Cognitive science","Brain function","Network science"],concepts:["Connectome","Neuroscience","Computer science","Resting state fMRI","Context (archaeology)","Cognitive science","Brain function","Network science"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Photoreceptor and optogenetics research"],pdf_url:"https://doi.org/10.31887/dcns.2013.15.3/osporns",is_oa:!0,n_refs:150,n_refs_in_core:27,degree:46,community:0,deg_w:1041.5,betweenness:.0034,pagerank:.00747,eigenvector:.1014,pdf_file:null,pdf_downloaded:!1},{id:61,oaid:"W1996196481",doi:"10.1073/pnas.1400181111",title:"Time-resolved resting-state brain networks",authors:[{name:"Andrew Zalesky",institutions:["The University of Melbourne","Melbourne Health"]},{name:"Alex Fornito",institutions:["The University of Melbourne","Melbourne Health","Monash University"]},{name:"Luca Cocchi",institutions:["The University of Queensland"]},{name:"Leonardo L. Gollo",institutions:["QIMR Berghofer Medical Research Institute"]},{name:"Michael Breakspear",institutions:["QIMR Berghofer Medical Research Institute","Royal Brisbane and Women's Hospital","Royal Ottawa Mental Health Centre","Metro South Health"]}],authorString:"Andrew Zalesky; Alex Fornito; Luca Cocchi; Leonardo L. Gollo; Michael Breakspear",institutions:["Melbourne Health","Metro South Health","Monash University","QIMR Berghofer Medical Research Institute","Royal Brisbane and Women's Hospital","Royal Ottawa Mental Health Centre","The University of Melbourne","The University of Queensland"],countries:["AU","CA"],year:2014,journal:"Proceedings of the National Academy of Sciences",citations:841,abstract:"Neuronal dynamics display a complex spatiotemporal structure involving the precise, context-dependent coordination of activation patterns across a large number of spatially distributed regions. Functional magnetic resonance imaging (fMRI) has played a central role in demonstrating the nontrivial spatial and topological structure of these interactions, but thus far has been limited in its capacity to study their temporal evolution. Here, using high-resolution resting-state fMRI data obtained from the Human Connectome Project, we mapped time-resolved functional connectivity across the entire brain at a subsecond resolution with the aim of understanding how nonstationary fluctuations in pairwise interactions between regions relate to large-scale topological properties of the human brain. We report evidence for a consistent set of functional connections that show pronounced fluctuations in their strength over time. The most dynamic connections are intermodular, linking elements from topologically separable subsystems, and localize to known hubs of default mode and fronto-parietal systems. We found that spatially distributed regions spontaneously increased, for brief intervals, the efficiency with which they can transfer information, producing temporary, globally efficient network states. Our findings suggest that brain dynamics give rise to variations in complex network properties over time, possibly achieving a balance between efficient information-processing and metabolic expenditure.",keywords:["Functional magnetic resonance imaging","Resting state fMRI","Neuroscience","Brain activity and meditation","State","Scale","Human brain"],concepts:["Functional magnetic resonance imaging","Resting state fMRI","Neuroscience","Brain activity and meditation","State (computer science)","Computer science","Scale (ratio)","Human brain"],topics:["Neural dynamics and brain function","Functional Brain Connectivity Studies","Photoreceptor and optogenetics research"],pdf_url:"https://www.ncbi.nlm.nih.gov/pmc/articles/4104861",is_oa:!0,n_refs:80,n_refs_in_core:17,degree:38,community:0,deg_w:612,betweenness:.0032,pagerank:.00496,eigenvector:.0428,pdf_file:null,pdf_downloaded:!1},{id:62,oaid:"W1990574575",doi:"10.1073/pnas.1203593109",title:"High-cost, high-capacity backbone for global brain communication",authors:[{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]},{name:"René S. Kahn",institutions:["University Medical Center Utrecht"]},{name:"Joaquín Goñi",institutions:["Indiana University Bloomington"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]}],authorString:"Martijn P. van den Heuvel; René S. Kahn; Joaquín Goñi; Olaf Sporns",institutions:["Indiana University Bloomington","University Medical Center Utrecht"],countries:["NL","US"],year:2012,journal:"Proceedings of the National Academy of Sciences",citations:840,abstract:'Network studies of human brain structural connectivity have identified a specific set of brain regions that are both highly connected and highly central. Recent analyses have shown that these putative hub regions are mutually and densely interconnected, forming a "rich club" within the human brain. Here we show that the set of pathways linking rich club regions forms a central high-cost, high-capacity backbone for global brain communication. Diffusion tensor imaging (DTI) data of two sets of 40 healthy subjects were used to map structural brain networks. The contributions to network cost and communication capacity of global cortico-cortical connections were assessed through measures of their topology and spatial embedding. Rich club connections were found to be more costly than predicted by their density alone and accounted for 40% of the total communication cost. Furthermore, 69% of all minimally short paths between node pairs were found to travel through the rich club and a large proportion of these communication paths consisted of ordered sequences of edges ("path motifs") that first fed into, then traversed, and finally exited the rich club, while passing through nodes of increasing and then decreasing degree. The prevalence of short paths that follow such ordered degree sequences suggests that neural communication might take advantage of strategies for dynamic routing of information between brain regions, with an important role for a highly central rich club. Taken together, our results show that rich club connections make an important contribution to interregional signal traffic, forming a central high-cost, high-capacity backbone for global brain communication.',keywords:["Set","Node","Embedding","Topology","Distributed computing","Computer network"],concepts:["Set (abstract data type)","Computer science","Node (physics)","Embedding","Topology (electrical circuits)","Distributed computing","Computer network"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Neural dynamics and brain function"],pdf_url:"https://pure.amsterdamumc.nl/en/publications/0c9ef14f-9040-41b7-b830-b8507815f35b",is_oa:!0,n_refs:43,n_refs_in_core:14,degree:70,community:0,deg_w:1068,betweenness:.0098,pagerank:.00796,eigenvector:.0818,pdf_file:null,pdf_downloaded:!1},{id:63,oaid:"W2101400241",doi:"10.1371/journal.pbio.1000157",title:"Development of Large-Scale Functional Brain Networks in Children",authors:[{name:"Kaustubh Supekar",institutions:["Stanford University","Stanford Medicine"]},{name:"Mark A. Musen",institutions:["Stanford University"]},{name:"Vinod Menon",institutions:["Stanford University"]}],authorString:"Kaustubh Supekar; Mark A. Musen; Vinod Menon",institutions:["Stanford Medicine","Stanford University"],countries:["US"],year:2009,journal:"PLoS Biology",citations:822,abstract:`The ontogeny of large-scale functional organization of the human brain is not well understood. Here we use network analysis of intrinsic functional connectivity to characterize the organization of brain networks in 23 children (ages 7-9 y) and 22 young-adults (ages 19-22 y). Comparison of network properties, including path-length, clustering-coefficient, hierarchy, and regional connectivity, revealed that although children and young-adults' brains have similar "small-world" organization at the global level, they differ significantly in hierarchical organization and interregional connectivity. We found that subcortical areas were more strongly connected with primary sensory, association, and paralimbic areas in children, whereas young-adults showed stronger cortico-cortical connectivity between paralimbic, limbic, and association areas. Further, combined analysis of functional connectivity with wiring distance measures derived from white-matter fiber tracking revealed that the development of large-scale brain networks is characterized by weakening of short-range functional connectivity and strengthening of long-range functional connectivity. Importantly, our findings show that the dynamic process of over-connectivity followed by pruning, which rewires connectivity at the neuronal level, also operates at the systems level, helping to reconfigure and rebalance subcortical and paralimbic connectivity in the developing brain. Our study demonstrates the usefulness of network analysis of brain connectivity to elucidate key principles underlying functional brain maturation, paving the way for novel studies of disrupted brain connectivity in neurodevelopmental disorders such as autism.`,keywords:["Neuroscience","Functional organization","Human brain","White matter","Functional connectivity","Functional integration","Autism"],concepts:["Neuroscience","Biology","Functional organization","Human brain","White matter","Functional connectivity","Functional integration","Autism"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Neural dynamics and brain function"],pdf_url:"https://journals.plos.org/plosbiology/article/file?id=10.1371/journal.pbio.1000157&type=printable",is_oa:!0,n_refs:108,n_refs_in_core:11,degree:50,community:2,deg_w:897,betweenness:.0035,pagerank:.00653,eigenvector:.0941,pdf_file:"Supekar_2009.pdf",pdf_downloaded:!0},{id:64,oaid:"W2071158443",doi:"10.1371/journal.pbio.0020369",title:"Motifs in Brain Networks",authors:[{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]},{name:"Rolf Kötter",institutions:["Heinrich Heine University Düsseldorf"]}],authorString:"Olaf Sporns; Rolf Kötter",institutions:["Heinrich Heine University Düsseldorf","Indiana University Bloomington"],countries:["DE","US"],year:2004,journal:"PLoS Biology",citations:809,abstract:"Complex brains have evolved a highly efficient network architecture whose structural connectivity is capable of generating a large repertoire of functional states. We detect characteristic network building blocks (structural and functional motifs) in neuroanatomical data sets and identify a small set of structural motifs that occur in significantly increased numbers. Our analysis suggests the hypothesis that brain networks maximize both the number and the diversity of functional motifs, while the repertoire of structural motifs remains small. Using functional motif number as a cost function in an optimization algorithm, we obtain network topologies that resemble real brain networks across a broad spectrum of structural measures, including small-world attributes. These results are consistent with the hypothesis that highly evolved neural architectures are organized to maximize functional repertoires and to support highly efficient integration of information.",keywords:["Structural motif","Repertoire","Computational biology","Functional diversity","Network motif","Set","Brain function"],concepts:["Biology","Structural motif","Repertoire","Computational biology","Functional diversity","Network motif","Set (abstract data type)","Brain function"],topics:["Neural dynamics and brain function","Functional Brain Connectivity Studies","Gene Regulatory Network Analysis"],pdf_url:"https://journals.plos.org/plosbiology/article/file?id=10.1371/journal.pbio.0020369&type=printable",is_oa:!0,n_refs:52,n_refs_in_core:0,degree:29,community:1,deg_w:351.5,betweenness:.0013,pagerank:.00303,eigenvector:.0338,pdf_file:"Sporns_2004.pdf",pdf_downloaded:!0},{id:65,oaid:"W1972412818",doi:"10.1371/journal.pone.0000597",title:"Mapping Human Whole-Brain Structural Networks with Diffusion MRI",authors:[{name:"Patric Hagmann",institutions:["University Hospital of Lausanne","École Polytechnique Fédérale de Lausanne","University of Lausanne"]},{name:"Maciej Kurant",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Xavier Gigandet",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Patrick Thiran",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Van J. Wedeen",institutions:["Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Reto Meuli",institutions:["University Hospital of Lausanne","University of Lausanne"]},{name:"Jean‐Philippe Thiran",institutions:["École Polytechnique Fédérale de Lausanne"]}],authorString:"Patric Hagmann; Maciej Kurant; Xavier Gigandet; Patrick Thiran; Van J. Wedeen; Reto Meuli; Jean‐Philippe Thiran",institutions:["Athinoula A. Martinos Center for Biomedical Imaging","University Hospital of Lausanne","University of Lausanne","École Polytechnique Fédérale de Lausanne"],countries:["CH","US"],year:2007,journal:"PLoS ONE",citations:805,abstract:"Understanding the large-scale structural network formed by neurons is a major challenge in system neuroscience. A detailed connectivity map covering the entire brain would therefore be of great value. Based on diffusion MRI, we propose an efficient methodology to generate large, comprehensive and individual white matter connectional datasets of the living or dead, human or animal brain. This non-invasive tool enables us to study the basic and potentially complex network properties of the entire brain. For two human subjects we find that their individual brain networks have an exponential node degree distribution and that their global organization is in the form of a small world.",keywords:["Human brain","Diffusion MRI","White matter","Neuroscience","Brain mapping","Node","Complex network"],concepts:["Human brain","Diffusion MRI","White matter","Computer science","Neuroscience","Brain mapping","Node (physics)","Complex network"],topics:["Advanced Neuroimaging Techniques and Applications","Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0000597&type=printable",is_oa:!0,n_refs:59,n_refs_in_core:3,degree:54,community:1,deg_w:702.5,betweenness:.0053,pagerank:.00523,eigenvector:.0803,pdf_file:"Hagmann_2007.pdf",pdf_downloaded:!0},{id:66,oaid:"W1552598564",doi:"10.1002/hbm.22058",title:"Resting-state networks show dynamic functional connectivity in awake humans and anesthetized macaques",authors:[{name:"R. Matthew Hutchison",institutions:["Western University"]},{name:"Thilo Womelsdorf",institutions:["Western University","York University"]},{name:"Joseph S. Gati",institutions:["Robarts Clinical Trials"]},{name:"Stefan Everling",institutions:["Western University"]},{name:"Ravi S. Menon",institutions:["Western University","Robarts Clinical Trials"]}],authorString:"R. Matthew Hutchison; Thilo Womelsdorf; Joseph S. Gati; Stefan Everling; Ravi S. Menon",institutions:["Robarts Clinical Trials","Western University","York University"],countries:["CA"],year:2012,journal:"Human Brain Mapping",citations:781,abstract:'Characterization of large-scale brain networks using blood-oxygenation-level-dependent functional magnetic resonance imaging is typically based on the assumption of network stationarity across the duration of scan. Recent studies in humans have questioned this assumption by showing that within-network functional connectivity fluctuates on the order of seconds to minutes. Time-varying profiles of resting-state networks (RSNs) may relate to spontaneously shifting, electrophysiological network states and are thus mechanistically of particular importance. However, because these studies acquired data from awake subjects, the fluctuating connectivity could reflect various forms of conscious brain processing such as passive mind wandering, active monitoring, memory formation, or changes in attention and arousal during image acquisition. Here, we characterize RSN dynamics of anesthetized macaques that control for these accounts, and compare them to awake human subjects. We find that functional connectivity among nodes comprising the "oculomotor (OCM) network" strongly fluctuated over time during awake as well as anaesthetized states. For time dependent analysis with short windows (<60 s), periods of positive functional correlations alternated with prominent anticorrelations that were missed when assessed with longer time windows. Similarly, the analysis identified network nodes that transiently link to the OCM network and did not emerge in average RSN analysis. Furthermore, time-dependent analysis reliably revealed transient states of large-scale synchronization that spanned all seeds. The results illustrate that resting-state functional connectivity is not static and that RSNs can exhibit nonstationary, spontaneous relationships irrespective of conscious, cognitive processing. The findings imply that mechanistically important network information can be missed when using average functional connectivity as the single network measure.',keywords:["Dynamic functional connectivity","Neuroscience","Functional magnetic resonance imaging","Resting state fMRI","Functional connectivity","Synchronization","Wakefulness"],concepts:["Dynamic functional connectivity","Neuroscience","Functional magnetic resonance imaging","Resting state fMRI","Functional connectivity","Synchronization (alternating current)","Wakefulness","Psychology"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/hbm.22058?download=true",is_oa:!0,n_refs:151,n_refs_in_core:7,degree:28,community:2,deg_w:401.5,betweenness:.0022,pagerank:.0037,eigenvector:.0203,pdf_file:null,pdf_downloaded:!1},{id:67,oaid:"W2171630967",doi:"10.1002/hbm.20324",title:"Altered functional connectivity in early Alzheimer's disease: A resting‐state fMRI study",authors:[{name:"Kun Wang",institutions:["Chinese Academy of Sciences","Institute of Automation"]},{name:"Meng Liang",institutions:["Chinese Academy of Sciences","Institute of Automation"]},{name:"Liang Wang",institutions:["Capital Medical University"]},{name:"Lixia Tian",institutions:["Chinese Academy of Sciences","Institute of Automation"]},{name:"Xinqing Zhang",institutions:["Capital Medical University"]},{name:"Kuncheng Li",institutions:["Capital Medical University","Chinese Academy of Sciences","Institute of Automation"]},{name:"Tianzi Jiang",institutions:["Capital Medical University","Chinese Academy of Sciences","Institute of Automation"]}],authorString:"Kun Wang; Meng Liang; Liang Wang; Lixia Tian; Xinqing Zhang; Kuncheng Li; Tianzi Jiang",institutions:["Capital Medical University","Chinese Academy of Sciences","Institute of Automation"],countries:["CN"],year:2006,journal:"Human Brain Mapping",citations:748,abstract:"Previous studies have led to the proposal that patients with Alzheimer's disease (AD) may have disturbed functional connectivity between different brain regions. Furthermore, recent resting-state functional magnetic resonance imaging (fMRI) studies have also shown that low-frequency (<0.08 Hz) fluctuations (LFF) of the blood oxygenation level-dependent signals were abnormal in several brain areas of AD patients. However, few studies have investigated disturbed LFF connectivity in AD patients. By using resting-state fMRI, this study sought to investigate the abnormal functional connectivities throughout the entire brain of early AD patients, and analyze the global distribution of these abnormalities. For this purpose, the authors divided the whole brain into 116 regions and identified abnormal connectivities by comparing the correlation coefficients of each pair. Compared with healthy controls, AD patients had decreased positive correlations between the prefrontal and parietal lobes, but increased positive correlations within the prefrontal lobe, parietal lobe, and occipital lobe. The AD patients also had decreased negative correlations (closer to zero) between two intrinsically anti-correlated networks that had previously been found in the resting brain. By using resting-state fMRI, our results supported previous studies that have reported an anterior-posterior disconnection phenomenon and increased within-lobe functional connectivity in AD patients. In addition, the results also suggest that AD may disturb the correlation/anti-correlation effect in the two intrinsically anti-correlated networks.",keywords:["Resting state fMRI","Neuroscience","Parietal lobe","Functional magnetic resonance imaging","Occipital lobe","Temporal lobe","Correlation"],concepts:["Resting state fMRI","Neuroscience","Parietal lobe","Functional magnetic resonance imaging","Psychology","Occipital lobe","Temporal lobe","Correlation"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced MRI Techniques and Applications"],pdf_url:"https://www.ncbi.nlm.nih.gov/pmc/articles/6871392",is_oa:!0,n_refs:56,n_refs_in_core:3,degree:30,community:2,deg_w:367.5,betweenness:.0013,pagerank:.00337,eigenvector:.0228,pdf_file:null,pdf_downloaded:!1},{id:68,oaid:"W2101328227",doi:"10.1073/pnas.1009073107",title:"White matter maturation reshapes structural connectivity in the late developing human brain",authors:[{name:"Patric Hagmann",institutions:["École Polytechnique Fédérale de Lausanne","University of Lausanne"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]},{name:"Neel Madan",institutions:["Tufts Medical Center"]},{name:"Leila Cammoun",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Rudolph Pienaar",institutions:["Boston Children's Hospital"]},{name:"Van J. Wedeen",institutions:["Massachusetts General Hospital","Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Reto Meuli",institutions:["University of Lausanne"]},{name:"Jean‐Philippe Thiran",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"P. Ellen Grant",institutions:["Boston Children's Hospital","Massachusetts General Hospital","Athinoula A. Martinos Center for Biomedical Imaging"]}],authorString:"Patric Hagmann; Olaf Sporns; Neel Madan; Leila Cammoun; Rudolph Pienaar; Van J. Wedeen; Reto Meuli; Jean‐Philippe Thiran; P. Ellen Grant",institutions:["Athinoula A. Martinos Center for Biomedical Imaging","Boston Children's Hospital","Indiana University Bloomington","Massachusetts General Hospital","Tufts Medical Center","University of Lausanne","École Polytechnique Fédérale de Lausanne"],countries:["CH","US"],year:2010,journal:"Proceedings of the National Academy of Sciences",citations:735,abstract:"From toddler to late teenager, the macroscopic pattern of axonal projections in the human brain remains largely unchanged while undergoing dramatic functional modifications that lead to network refinement. These functional modifications are mediated by increasing myelination and changes in axonal diameter and synaptic density, as well as changes in neurochemical mediators. Here we explore the contribution of white matter maturation to the development of connectivity between ages 2 and 18 y using high b-value diffusion MRI tractography and connectivity analysis. We measured changes in connection efficacy as the inverse of the average diffusivity along a fiber tract. We observed significant refinement in specific metrics of network topology, including a significant increase in node strength and efficiency along with a decrease in clustering. Major structural modules and hubs were in place by 2 y of age, and they continued to strengthen their profile during subsequent development. Recording resting-state functional MRI from a subset of subjects, we confirmed a positive correlation between structural and functional connectivity, and in addition observed that this relationship strengthened with age. Continuously increasing integration and decreasing segregation of structural connectivity with age suggests that network refinement mediated by white matter maturation promotes increased global efficiency. In addition, the strengthening of the correlation between structural and functional connectivity with age suggests that white matter connectivity in combination with other factors, such as differential modulation of axonal diameter and myelin thickness, that are partially captured by inverse average diffusivity, play an increasingly important role in creating brain-wide coherence and synchrony.",keywords:["White matter","Diffusion MRI","Tractography","Neuroscience","Neurochemical","Connectome","Human brain","Functional connectivity"],concepts:["White matter","Diffusion MRI","Tractography","Neuroscience","Neurochemical","Connectome","Human brain","Functional connectivity"],topics:["Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications","Functional Brain Connectivity Studies"],pdf_url:"http://infoscience.epfl.ch/record/153351",is_oa:!0,n_refs:62,n_refs_in_core:6,degree:39,community:0,deg_w:436.5,betweenness:.0041,pagerank:.00376,eigenvector:.0317,pdf_file:null,pdf_downloaded:!1},{id:69,oaid:"W2092655084",doi:"10.1097/wco.0b013e32833aa567",title:"Graph theoretical modeling of brain connectivity",authors:[{name:"Yong He",institutions:["Beijing Normal University"]},{name:"Alan C. Evans",institutions:["McGill University","Montreal Neurological Institute and Hospital"]}],authorString:"Yong He; Alan C. Evans",institutions:["Beijing Normal University","McGill University","Montreal Neurological Institute and Hospital"],countries:["CA","CN"],year:2010,journal:"Current Opinion in Neurology",citations:717,abstract:"PURPOSE OF REVIEW: In recent years, there has been an explosion of studies on network modeling of brain connectivity. This review will focus mainly on recent findings concerning graph theoretical analysis of human brain networks with a variety of imaging modalities, including structural MRI, diffusion MRI, functional MRI, and EEG/MEG. RECENT FINDINGS: Recent studies have utilized graph theoretical approaches to investigate the organizational principles of brain networks. These studies have consistently shown many important statistical properties underlying the topological organization of the human brain, including modularity, small-worldness, and the existence of highly connected network hubs. Importantly, these quantifiable network properties were found to change during normal development, aging, and various neurological and neuropsychiatric diseases such as Alzheimer's disease and schizophrenia. Moreover, several studies have also suggested that these network properties correlate with behavioral and genetic factors. SUMMARY: The exciting research regarding graph theoretical analysis of brain connectivity yields truly integrative and comprehensive descriptions of the structural and functional organization of the human brain, which provides important implications for health and disease. Future research will most likely involve integrative models of brain structural and functional connectivity with multimodal neuroimaging data, exploring whether graph-based brain network analysis could yield reliable biomarkers for disease diagnosis and treatment.",keywords:["Neuroimaging","Neuroscience","Modularity","Human brain","Diffusion MRI","Power graph analysis","Modalities"],concepts:["Neuroimaging","Neuroscience","Modularity (biology)","Human brain","Diffusion MRI","Power graph analysis","Computer science","Modalities"],topics:["Functional Brain Connectivity Studies","Mental Health Research Topics","Bioinformatics and Genomic Networks"],pdf_url:null,is_oa:!1,n_refs:62,n_refs_in_core:27,degree:62,community:1,deg_w:1225.5,betweenness:.0047,pagerank:.00838,eigenvector:.1408,pdf_file:null,pdf_downloaded:!1},{id:70,oaid:"W2094426896",doi:"10.3389/neuro.11.037.2009",title:"Hierarchical modularity in human brain functional networks",authors:[{name:"David Meunier",institutions:["University of Cambridge"]}],authorString:"David Meunier",institutions:["University of Cambridge"],countries:["GB"],year:2009,journal:"Frontiers in Neuroinformatics",citations:699,abstract:`The idea that complex systems have a hierarchical modular organization originated in the early 1960s and has recently attracted fresh support from quantitative studies of large scale, real-life networks. Here we investigate the hierarchical modular (or "modules-within-modules") decomposition of human brain functional networks, measured using functional magnetic resonance imaging in 18 healthy volunteers under no-task or resting conditions. We used a customized template to extract networks with more than 1800 regional nodes, and we applied a fast algorithm to identify nested modular structure at several hierarchical levels. We used mutual information, 0 < I < 1, to estimate the similarity of community structure of networks in different subjects, and to identify the individual network that is most representative of the group. Results show that human brain functional networks have a hierarchical modular organization with a fair degree of similarity between subjects, I = 0.63. The largest five modules at the highest level of the hierarchy were medial occipital, lateral occipital, central, parieto-frontal and fronto-temporal systems; occipital modules demonstrated less sub-modular organization than modules comprising regions of multimodal association cortex. Connector nodes and hubs, with a key role in inter-modular connectivity, were also concentrated in association cortical areas. We conclude that methods are available for hierarchical modular decomposition of large numbers of high resolution brain functional networks using computationally expedient algorithms. This could enable future investigations of Simon's original hypothesis that hierarchy or near-decomposability of physical symbol systems is a critical design feature for their fast adaptivity to changing environmental conditions.`,keywords:["Modularity","Modular design","Hierarchy","Hierarchical organization","Functional magnetic resonance imaging","Similarity","Complex network"],concepts:["Modularity (biology)","Modular design","Computer science","Hierarchy","Hierarchical organization","Functional magnetic resonance imaging","Similarity (geometry)","Complex network"],topics:["Functional Brain Connectivity Studies","Mental Health Research Topics","Neural dynamics and brain function"],pdf_url:"https://www.frontiersin.org/articles/10.3389/neuro.11.037.2009/pdf",is_oa:!0,n_refs:55,n_refs_in_core:5,degree:40,community:0,deg_w:466,betweenness:.0038,pagerank:.00381,eigenvector:.046,pdf_file:"Meunier_2009.pdf",pdf_downloaded:!0},{id:71,oaid:"W2059564226",doi:"10.1002/hbm.10022",title:"Detection of functional connectivity using temporal correlations in MR images",authors:[{name:"Michelle Hampson",institutions:["Yale University"]},{name:"Bradley S. Peterson",institutions:["Yale University"]},{name:"Pawel Skudlarski",institutions:["Yale University"]},{name:"J.C. Gatenby",institutions:["Yale University"]},{name:"John C. Gore",institutions:["Yale University"]}],authorString:"Michelle Hampson; Bradley S. Peterson; Pawel Skudlarski; J.C. Gatenby; John C. Gore",institutions:["Yale University"],countries:["US"],year:2002,journal:"Human Brain Mapping",citations:695,abstract:"Functional connectivity among brain regions has been investigated via an analysis of correlations between regional signal fluctuations recorded in magnetic resonance (MR) images obtained in a steady state. In comparison with studies of functional connectivity that utilize task manipulations, the analysis of correlations in steady state data is less susceptible to confounds arising when functionally unrelated brain regions respond in similar ways to changes in task. A new approach to identifying interregional correlations in steady state data makes use of two independent data sets. Regions of interest (ROIs) are defined and hypotheses regarding their connectivity are generated in one data set. The connectivity hypotheses are then evaluated in the remaining (independent) data set by analyzing low frequency temporal correlations between regions. The roles of the two data sets are then reversed and the process repeated, perhaps multiple times. This method was illustrated by application to the language system. The existence of a functional connection between Broca's area and Wernicke's area was confirmed in healthy subjects at rest. An increase in this functional connection when the language system was actively engaged (when subjects were continuously listening to narrative text) was also confirmed. In a second iteration of analyses, a correlation between Broca's area and a region in left premotor cortex was found to be significant at rest and to increase during continuous listening. These findings suggest that the proposed methodology can reveal the presence and strength of functional connections in high-level cognitive systems.",keywords:["Functional magnetic resonance imaging","Active listening","Dynamic functional connectivity","Functional connectivity","Premotor cortex","Set","Resting state fMRI","Supplementary motor area"],concepts:["Functional magnetic resonance imaging","Active listening","Dynamic functional connectivity","Functional connectivity","Premotor cortex","Set (abstract data type)","Resting state fMRI","Supplementary motor area"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Neural and Behavioral Psychology Studies"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/hbm.10022?download=true",is_oa:!0,n_refs:52,n_refs_in_core:1,degree:20,community:2,deg_w:164,betweenness:9e-4,pagerank:.00193,eigenvector:.0124,pdf_file:null,pdf_downloaded:!1},{id:72,oaid:"W2058711140",doi:"10.1523/jneurosci.2874-10.2010",title:"Aberrant Frontal and Temporal Complex Network Structure in Schizophrenia: A Graph Theoretical Analysis",authors:[{name:"Martijn P. van den Heuvel",institutions:["Utrecht University"]},{name:"René C.W. Mandl",institutions:["Utrecht University","University Medical Center Utrecht"]},{name:"Cornelis J. Stam",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"René S. Kahn",institutions:["Vrije Universiteit Amsterdam","Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Hilleke E. Hulshoff Pol",institutions:["Utrecht University","University Medical Center Utrecht"]}],authorString:"Martijn P. van den Heuvel; René C.W. Mandl; Cornelis J. Stam; René S. Kahn; Hilleke E. Hulshoff Pol",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam","University Medical Center Utrecht","Utrecht University","Vrije Universiteit Amsterdam"],countries:["NL"],year:2010,journal:"Journal of Neuroscience",citations:694,abstract:"Brain regions are not independent. They are interconnected by white matter tracts, together forming one integrative complex network. The topology of this network is crucial for efficient information integration between brain regions. Here, we demonstrate that schizophrenia involves an aberrant topology of the structural infrastructure of the brain network. Using graph theoretical analysis, complex structural brain networks of 40 schizophrenia patients and 40 human healthy controls were examined. Diffusion tensor imaging was used to reconstruct the white matter connections of the brain network, with the strength of the connections defined as the level of myelination of the tracts as measured through means of magnetization transfer ratio magnetic resonance imaging. Patients displayed a preserved overall small-world network organization, but focusing on specific brain regions and their capacity to communicate with other regions of the brain revealed significantly longer node-specific path lengths (higher L) of frontal and temporal regions, especially of bilateral inferior/superior frontal cortex and temporal pole regions. These findings suggest that schizophrenia impacts global network connectivity of frontal and temporal brain regions. Furthermore, frontal hubs of patients showed a significant reduction of betweenness centrality, suggesting a less central hub role of these regions in the overall network structure. Together, our findings suggest that schizophrenia patients have a less strongly globally integrated structural brain network with a reduced central role for key frontal hubs, resulting in a limited structural capacity to integrate information across brain regions.",keywords:["Schizophrenia","Graph","Power graph analysis","Complex network","Cognitive science","Neuroscience","Cognitive psychology"],concepts:["Schizophrenia (object-oriented programming)","Psychology","Graph","Power graph analysis","Complex network","Cognitive science","Neuroscience","Cognitive psychology"],topics:["Functional Brain Connectivity Studies","Mental Health Research Topics","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/30/47/15915.full.pdf",is_oa:!0,n_refs:77,n_refs_in_core:15,degree:58,community:3,deg_w:920,betweenness:.0064,pagerank:.00678,eigenvector:.0813,pdf_file:null,pdf_downloaded:!1},{id:73,oaid:"W2009726930",doi:"10.1073/pnas.1214900110",title:"Coupling of functional connectivity and regional cerebral blood flow reveals a physiological basis for network hubs of the human brain",authors:[{name:"Xia Liang",institutions:["National Institutes of Health","National Institute on Drug Abuse","Beijing Normal University"]},{name:"Qihong Zou",institutions:["Peking University"]},{name:"Yong He",institutions:["Beijing Normal University"]},{name:"Yihong Yang",institutions:["National Institutes of Health","National Institute on Drug Abuse"]}],authorString:"Xia Liang; Qihong Zou; Yong He; Yihong Yang",institutions:["Beijing Normal University","National Institute on Drug Abuse","National Institutes of Health","Peking University"],countries:["CN","US"],year:2013,journal:"Proceedings of the National Academy of Sciences",citations:691,abstract:"Human brain functional networks contain a few densely connected hubs that play a vital role in transferring information across regions during resting and task states. However, the relationship of these functional hubs to measures of brain physiology, such as regional cerebral blood flow (rCBF), remains incompletely understood. Here, we used functional MRI data of blood-oxygenation-level-dependent and arterial-spin-labeling perfusion contrasts to investigate the relationship between functional connectivity strength (FCS) and rCBF during resting and an N-back working-memory task. During resting state, functional brain hubs with higher FCS were identified, primarily in the default-mode, insula, and visual regions. The FCS showed a striking spatial correlation with rCBF, and the correlation was stronger in the default-mode network (DMN; including medial frontal-parietal cortices) and executive control network (ECN; including lateral frontal-parietal cortices) compared with visual and sensorimotor networks. Moreover, the relationship was connection-distance dependent; i.e., rCBF correlated stronger with long-range hubs than short-range ones. It is notable that several DMN and ECN regions exhibited higher rCBF per unit connectivity strength (rCBF/FCS ratio); whereas, this index was lower in posterior visual areas. During the working-memory experiment, both FCS-rCBF coupling and rCBF/FCS ratio were modulated by task load in the ECN and/or DMN regions. Finally, task-induced changes of FCS and rCBF in the lateral-parietal lobe positively correlated with behavioral performance. Together, our results indicate a tight coupling between blood supply and brain functional topology during rest and its modulation in response to task demands, which may shed light on the physiological basis of human brain functional connectome.",keywords:["Cerebral blood flow","Default mode network","Neuroscience","Resting state fMRI","Functional connectivity","Working memory","Posterior parietal cortex","Task-positive network"],concepts:["Cerebral blood flow","Default mode network","Neuroscience","Resting state fMRI","Functional connectivity","Working memory","Posterior parietal cortex","Task-positive network"],topics:["Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.pnas.org/content/pnas/110/5/1929.full.pdf",is_oa:!0,n_refs:37,n_refs_in_core:9,degree:36,community:0,deg_w:366,betweenness:.0026,pagerank:.00319,eigenvector:.0311,pdf_file:null,pdf_downloaded:!1},{id:74,oaid:"W1996630013",doi:"10.1002/hbm.20623",title:"Parcellation‐dependent small‐world brain functional networks: A resting‐state fMRI study",authors:[{name:"Jinhui Wang",institutions:["Beijing Normal University"]},{name:"Liang Wang",institutions:["Beijing Institute of Technology","Beijing Normal University"]},{name:"Yu‐Feng Zang",institutions:["Beijing Normal University"]},{name:"Hong Yang",institutions:["Sichuan University","Beijing Normal University","West China Hospital of Sichuan University"]},{name:"Hehan Tang",institutions:["Sichuan University","West China Hospital of Sichuan University"]},{name:"Qiyong Gong",institutions:["Sichuan University","West China Hospital of Sichuan University"]},{name:"Zhang Chen",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Chaozhe Zhu",institutions:["Beijing Normal University"]},{name:"Yong He",institutions:["Montreal Neurological Institute and Hospital","Beijing Normal University","McGill University"]}],authorString:"Jinhui Wang; Liang Wang; Yu‐Feng Zang; Hong Yang; Hehan Tang; Qiyong Gong; Zhang Chen; Chaozhe Zhu; Yong He",institutions:["Beijing Institute of Technology","Beijing Normal University","McGill University","Montreal Neurological Institute and Hospital","Sichuan University","West China Hospital of Sichuan University"],countries:["CA","CN"],year:2008,journal:"Human Brain Mapping",citations:673,abstract:"Recent studies have demonstrated small-world properties in both functional and structural brain networks that are constructed based on different parcellation approaches. However, one fundamental but vital issue of the impact of different brain parcellation schemes on the network topological architecture remains unclear. Here, we used resting-state functional MRI (fMRI) to investigate the influences of different brain parcellation atlases on the topological organization of brain functional networks. Whole-brain fMRI data were divided into ninety and seventy regions of interest according to two predefined anatomical atlases, respectively. Brain functional networks were constructed by thresholding the correlation matrices among the parcellated regions and further analyzed using graph theoretical approaches. Both atlas-based brain functional networks were found to show robust small-world properties and truncated power-law connectivity degree distributions, which are consistent with previous brain functional and structural networks studies. However, more importantly, we found that there were significant differences in multiple topological parameters (e.g., small-worldness and degree distribution) between the two groups of brain functional networks derived from the two atlases. This study provides quantitative evidence on how the topological organization of brain networks is affected by the different parcellation strategies applied.",keywords:["Resting state fMRI","Neuroscience","Functional connectivity","Thresholding","Human brain","Neuroimaging","Degree distribution","Complex network"],concepts:["Resting state fMRI","Neuroscience","Functional connectivity","Thresholding","Human brain","Neuroimaging","Degree distribution","Complex network"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Complex Network Analysis Techniques"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/hbm.20623?download=true",is_oa:!0,n_refs:54,n_refs_in_core:14,degree:59,community:1,deg_w:1205,betweenness:.004,pagerank:.00825,eigenvector:.1425,pdf_file:null,pdf_downloaded:!1},{id:75,oaid:"W2162551380",doi:"10.1001/jamapsychiatry.2013.1328",title:"Abnormal Rich Club Organization and Functional Brain Dynamics in Schizophrenia",authors:[{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]},{name:"Guusje Collin",institutions:["University Medical Center Utrecht"]},{name:"Thomas W. Scheewe",institutions:["University Medical Center Utrecht"]},{name:"René C.W. Mandl",institutions:["University Medical Center Utrecht"]},{name:"Wiepke Cahn",institutions:["University Medical Center Utrecht"]},{name:"Joaquín Goñi",institutions:["Indiana University Bloomington"]},{name:"Hilleke E. Hulshoff Pol",institutions:["University Medical Center Utrecht"]},{name:"René S. Kahn",institutions:["University Medical Center Utrecht"]}],authorString:"Martijn P. van den Heuvel; Olaf Sporns; Guusje Collin; Thomas W. Scheewe; René C.W. Mandl; Wiepke Cahn; Joaquín Goñi; Hilleke E. Hulshoff Pol; René S. Kahn",institutions:["Indiana University Bloomington","University Medical Center Utrecht"],countries:["NL","US"],year:2013,journal:"JAMA Psychiatry",citations:670,abstract:"IMPORTANCE: The human brain forms a large-scale structural network of regions and interregional pathways. Recent studies have reported the existence of a selective set of highly central and interconnected hub regions that may play a crucial role in the brain's integrative processes, together forming a central backbone for global brain communication. Abnormal brain connectivity may have a key role in the pathophysiology of schizophrenia. OBJECTIVE: To examine the structure of the rich club in schizophrenia and its role in global functional brain dynamics. DESIGN: Structural diffusion tensor imaging and resting-state functional magnetic resonance imaging were performed in patients with schizophrenia and matched healthy controls. SETTING: Department of Psychiatry, Rudolf Magnus Institute of Neuroscience, University Medical Center Utrecht, Utrecht, the Netherlands. PARTICIPANTS: Forty-eight patients and 45 healthy controls participated in the study. An independent replication data set of 41 patients and 51 healthy controls was included to replicate and validate significant findings. MAIN OUTCOME(S) AND MEASURES: Measures of rich club organization, connectivity density of rich club connections and connections linking peripheral regions to brain hubs, measures of global brain network efficiency, and measures of coupling between brain structure and functional dynamics. RESULTS: Rich club organization between high-degree hub nodes was significantly affected in patients, together with a reduced density of rich club connections predominantly comprising the white matter pathways that link the midline frontal, parietal, and insular hub regions. This reduction in rich club density was found to be associated with lower levels of global communication capacity, a relationship that was absent for other white matter pathways. In addition, patients had an increase in the strength of structural connectivity-functional connectivity coupling. CONCLUSIONS: Our findings provide novel biological evidence that schizophrenia is characterized by a selective disruption of brain connectivity among central hub regions of the brain, potentially leading to reduced communication capacity and altered functional brain dynamics.",keywords:["White matter","Schizophrenia","Neuroscience","Diffusion MRI","Functional magnetic resonance imaging","Resting state fMRI","Medicine"],concepts:["White matter","Schizophrenia (object-oriented programming)","Neuroscience","Psychology","Diffusion MRI","Functional magnetic resonance imaging","Resting state fMRI"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Schizophrenia research and treatment"],pdf_url:"https://pure.amsterdamumc.nl/en/publications/634be217-1577-4b5d-9069-1de1ea130395",is_oa:!0,n_refs:65,n_refs_in_core:16,degree:53,community:0,deg_w:835.5,betweenness:.0055,pagerank:.00643,eigenvector:.0613,pdf_file:null,pdf_downloaded:!1},{id:76,oaid:"W1985168009",doi:"10.1523/jneurosci.2308-09.2009",title:"Age- and Gender-Related Differences in the Cortical Anatomical Network",authors:[{name:"Gaolang Gong",institutions:["Montreal Neurological Institute and Hospital"]},{name:"Pedro Rosa‐Neto",institutions:["Montreal Neurological Institute and Hospital"]},{name:"Félix Carbonell",institutions:["Montreal Neurological Institute and Hospital"]},{name:"Zhang J. Chen",institutions:["Montreal Neurological Institute and Hospital","Beijing Normal University"]},{name:"Yong He",institutions:["Montreal Neurological Institute and Hospital","University of California, Los Angeles"]},{name:"Alan C. Evans",institutions:["Montreal Neurological Institute and Hospital"]}],authorString:"Gaolang Gong; Pedro Rosa‐Neto; Félix Carbonell; Zhang J. Chen; Yong He; Alan C. Evans",institutions:["Beijing Normal University","Montreal Neurological Institute and Hospital","University of California, Los Angeles"],countries:["CA","CN","US"],year:2009,journal:"Journal of Neuroscience",citations:660,abstract:'Neuroanatomical differences attributable to aging and gender have been well documented, and these differences may be associated with differences in behaviors and cognitive performance. However, little is known about the dynamic organization of anatomical connectivity within the cerebral cortex, which may underlie population differences in brain function. In this study, we investigated age and sex effects on the anatomical connectivity patterns of 95 normal subjects ranging in age from 19 to 85 years. Using the connectivity probability derived from diffusion magnetic resonance imaging tractography, we characterized the cerebral cortex as a weighted network of connected regions. This approach captures the underlying organization of anatomical connectivity for each subject at a regional level. Advanced graph theoretical analysis revealed that the resulting cortical networks exhibited "small-world" character (i.e., efficient information transfer both at local and global scale). In particular, the precuneus and posterior cingulate gyrus were consistently observed as centrally connected regions, independent of age and sex. Additional analysis revealed a reduction in overall cortical connectivity with age. There were also changes in the underlying network organization that resulted in decreased local efficiency, and also a shift of regional efficiency from the parietal and occipital to frontal and temporal neocortex in older brains. In addition, women showed greater overall cortical connectivity and the underlying organization of their cortical networks was more efficient, both locally and globally. There were also distributed regional differences in efficiency between sexes. Our results provide new insights into the substrates that underlie behavioral and cognitive differences in aging and sex.',keywords:["Precuneus","Neocortex","Neuroscience","Cerebral cortex","Cortex","Tractography","Posterior cingulate"],concepts:["Precuneus","Neocortex","Neuroscience","Cerebral cortex","Cortex (anatomy)","Psychology","Tractography","Posterior cingulate"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/29/50/15684.full.pdf",is_oa:!0,n_refs:52,n_refs_in_core:13,degree:48,community:1,deg_w:796.5,betweenness:.0024,pagerank:.00573,eigenvector:.093,pdf_file:null,pdf_downloaded:!1},{id:77,oaid:"W2028645759",doi:"10.1371/journal.pone.0005226",title:"Uncovering Intrinsic Modular Organization of Spontaneous Brain Activity in Humans",authors:[{name:"Yong He",institutions:["Beijing Normal University"]},{name:"Jinhui Wang",institutions:["Beijing Normal University"]},{name:"Liang Wang",institutions:["Beijing Normal University"]},{name:"Zhang J. Chen",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Chao‐Gan Yan",institutions:["Beijing Normal University"]},{name:"Hong Yang",institutions:["Sichuan University","West China Hospital of Sichuan University","First Affiliated Hospital Zhejiang University","Zhejiang University"]},{name:"Hehan Tang",institutions:["Sichuan University","West China Hospital of Sichuan University"]},{name:"Chaozhe Zhu",institutions:["Beijing Normal University"]},{name:"Qiyong Gong",institutions:["Sichuan University","West China Hospital of Sichuan University"]},{name:"Yu‐Feng Zang",institutions:["Beijing Normal University"]},{name:"Alan C. Evans",institutions:["Montreal Neurological Institute and Hospital","McGill University"]}],authorString:"Yong He; Jinhui Wang; Liang Wang; Zhang J. Chen; Chao‐Gan Yan; Hong Yang; Hehan Tang; Chaozhe Zhu; Qiyong Gong; Yu‐Feng Zang; Alan C. Evans",institutions:["Beijing Normal University","First Affiliated Hospital Zhejiang University","McGill University","Montreal Neurological Institute and Hospital","Sichuan University","West China Hospital of Sichuan University","Zhejiang University"],countries:["CA","CN"],year:2009,journal:"PLoS ONE",citations:640,abstract:'The characterization of topological architecture of complex brain networks is one of the most challenging issues in neuroscience. Slow (<0.1 Hz), spontaneous fluctuations of the blood oxygen level dependent (BOLD) signal in functional magnetic resonance imaging are thought to be potentially important for the reflection of spontaneous neuronal activity. Many studies have shown that these fluctuations are highly coherent within anatomically or functionally linked areas of the brain. However, the underlying topological mechanisms responsible for these coherent intrinsic or spontaneous fluctuations are still poorly understood. Here, we apply modern network analysis techniques to investigate how spontaneous neuronal activities in the human brain derived from the resting-state BOLD signals are topologically organized at both the temporal and spatial scales. We first show that the spontaneous brain functional networks have an intrinsically cohesive modular structure in which the connections between regions are much denser within modules than between them. These identified modules are found to be closely associated with several well known functionally interconnected subsystems such as the somatosensory/motor, auditory, attention, visual, subcortical, and the "default" system. Specifically, we demonstrate that the module-specific topological features can not be captured by means of computing the corresponding global network parameters, suggesting a unique organization within each module. Finally, we identify several pivotal network connectors and paths (predominantly associated with the association and limbic/paralimbic cortex regions) that are vital for the global coordination of information flow over the whole network, and we find that their lesions (deletions) critically affect the stability and robustness of the brain functional system. Together, our results demonstrate the highly organized modular architecture and associated topological properties in the temporal and spatial brain functional networks of the human brain that underlie spontaneous neuronal dynamics, which provides important implications for our understanding of how intrinsically coherent spontaneous brain activity has evolved into an optimal neuronal architecture to support global computation and information integration in the absence of specific stimuli or behaviors.',keywords:["Modular design","Neuroscience"],concepts:["Modular design","Neuroscience","Biology","Computer science"],topics:["Functional Brain Connectivity Studies","Mental Health Research Topics","Neural dynamics and brain function"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0005226&type=printable",is_oa:!0,n_refs:92,n_refs_in_core:18,degree:57,community:1,deg_w:1265.5,betweenness:.0049,pagerank:.00871,eigenvector:.1473,pdf_file:"He_2009.pdf",pdf_downloaded:!0},{id:78,oaid:"W1589873300",doi:null,title:"Structure and function of complex brain networks.",authors:[{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]}],authorString:"Olaf Sporns",institutions:["Indiana University Bloomington"],countries:["US"],year:2013,journal:"PubMed",citations:637,abstract:'An increasing number of theoretical and empirical studies approach the function of the human brain from a network perspective. The analysis of brain networks is made feasible by the development of new imaging acquisition methods as well as new tools from graph theory and dynamical systems. This review surveys some of these methodological advances and summarizes recent findings on the architecture of structural and functional brain networks. Studies of the structural connectome reveal several modules or network communities that are interlinked by hub regions mediating communication processes between modules. Recent network analyses have shown that network hubs form a densely linked collective called a "rich club," centrally positioned for attracting and dispersing signal traffic. In parallel, recordings of resting and task-evoked neural activity have revealed distinct resting-state networks that contribute to functions in distinct cognitive domains. Network methods are increasingly applied in a clinical context, and their promise for elucidating neural substrates of brain and mental disorders is discussed.',keywords:["Context","Neuroscience","Resting state fMRI","Connectome","Brain function","Cognitive science","Cognition","Graph theory"],concepts:["Context (archaeology)","Neuroscience","Resting state fMRI","Connectome","Brain function","Cognitive science","Cognition","Graph theory"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:null,is_oa:!1,n_refs:161,n_refs_in_core:33,degree:51,community:0,deg_w:1171,betweenness:.0048,pagerank:.00837,eigenvector:.1069,pdf_file:null,pdf_downloaded:!1},{id:79,oaid:"W2057504626",doi:"10.3389/fnsys.2010.00016",title:"Graph-based network analysis of resting-state functional MRI",authors:[{name:"Jinhui Wang",institutions:["Beijing Normal University"]}],authorString:"Jinhui Wang",institutions:["Beijing Normal University"],countries:["CN"],year:2010,journal:"Frontiers in Systems Neuroscience",citations:631,abstract:"In the past decade, resting-state functional MRI (R-fMRI) measures of brain activity have attracted considerable attention. Based on changes in the blood oxygen level-dependent signal, R-fMRI offers a novel way to assess the brain's spontaneous or intrinsic (i.e., task-free) activity with both high spatial and temporal resolutions. The properties of both the intra- and inter-regional connectivity of resting-state brain activity have been well documented, promoting our understanding of the brain as a complex network. Specifically, the topological organization of brain networks has been recently studied with graph theory. In this review, we will summarize the recent advances in graph-based brain network analyses of R-fMRI signals, both in typical and atypical populations. Application of these approaches to R-fMRI data has demonstrated non-trivial topological properties of functional networks in the human brain. Among these is the knowledge that the brain's intrinsic activity is organized as a small-world, highly efficient network, with significant modularity and highly connected hub regions. These network properties have also been found to change throughout normal development, aging, and in various pathological conditions. The literature reviewed here suggests that graph-based network analyses are capable of uncovering system-level changes associated with different processes in the resting brain, which could provide novel insights into the understanding of the underlying physiological mechanisms of brain function. We also highlight several potential research topics in the future.",keywords:["Resting state fMRI","Modularity","Brain activity and meditation","Neuroscience","Human brain","Functional magnetic resonance imaging","Power graph analysis"],concepts:["Resting state fMRI","Modularity (biology)","Brain activity and meditation","Neuroscience","Human brain","Computer science","Functional magnetic resonance imaging","Power graph analysis"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced MRI Techniques and Applications"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnsys.2010.00016/pdf",is_oa:!0,n_refs:142,n_refs_in_core:35,degree:62,community:1,deg_w:1638.5,betweenness:.005,pagerank:.01096,eigenvector:.1875,pdf_file:"Wang_2010.pdf",pdf_downloaded:!0},{id:80,oaid:"W2011541551",doi:"10.1371/journal.pone.0013788",title:"Loss of ‘Small-World’ Networks in Alzheimer's Disease: Graph Analysis of fMRI Resting-State Functional Connectivity",authors:[{name:"Ernesto Sanz‐Arigita",institutions:["Fundacion CITA Alzheimer","Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Menno M. Schoonheim",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Jessica S. Damoiseaux",institutions:["Stanford University"]},{name:"Serge A.R.B. Rombouts",institutions:["Leiden University","Leiden University Medical Center"]},{name:"Eric Maris",institutions:["Radboud University Nijmegen"]},{name:"Frederik Barkhof",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Philip Scheltens",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Cornelis J. Stam",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]}],authorString:"Ernesto Sanz‐Arigita; Menno M. Schoonheim; Jessica S. Damoiseaux; Serge A.R.B. Rombouts; Eric Maris; Frederik Barkhof; Philip Scheltens; Cornelis J. Stam",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam","Fundacion CITA Alzheimer","Leiden University","Leiden University Medical Center","Radboud University Nijmegen","Stanford University"],countries:["ES","NL","US"],year:2010,journal:"PLoS ONE",citations:622,abstract:"BACKGROUND: Local network connectivity disruptions in Alzheimer's disease patients have been found using graph analysis in BOLD fMRI. Other studies using MEG and cortical thickness measures, however, show more global long distance connectivity changes, both in functional and structural imaging data. The form and role of functional connectivity changes thus remains ambiguous. The current study shows more conclusive data on connectivity changes in early AD using graph analysis on resting-state condition fMRI data. METHODOLOGY/PRINCIPAL FINDINGS: 18 mild AD patients and 21 healthy age-matched control subjects without memory complaints were investigated in resting-state condition with MRI at 1.5 Tesla. Functional coupling between brain regions was calculated on the basis of pair-wise synchronizations between regional time-series. Local (cluster coefficient) and global (path length) network measures were quantitatively defined. Compared to controls, the characteristic path length of AD functional networks is closer to the theoretical values of random networks, while no significant differences were found in cluster coefficient. The whole-brain average synchronization does not differ between Alzheimer and healthy control groups. Post-hoc analysis of the regional synchronization reveals increased AD synchronization involving the frontal cortices and generalized decreases located at the parietal and occipital regions. This effectively translates in a global reduction of functional long-distance links between frontal and caudal brain regions. CONCLUSIONS/SIGNIFICANCE: We present evidence of AD-induced changes in global brain functional connectivity specifically affecting long-distance connectivity. This finding is highly relevant for it supports the anterior-posterior disconnection theory and its role in AD. Our results can be interpreted as reflecting the randomization of the brain functional networks in AD, further suggesting a loss of global information integration in disease.",keywords:["Resting state fMRI","Functional connectivity","Neuroscience","Functional magnetic resonance imaging","Power graph analysis","Small-world network","Default mode network","Disconnection"],concepts:["Resting state fMRI","Functional connectivity","Neuroscience","Functional magnetic resonance imaging","Power graph analysis","Small-world network","Default mode network","Disconnection"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced MRI Techniques and Applications"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0013788&type=printable",is_oa:!0,n_refs:75,n_refs_in_core:13,degree:36,community:1,deg_w:550,betweenness:.0025,pagerank:.00444,eigenvector:.045,pdf_file:"SanzArigita_2010.pdf",pdf_downloaded:!0},{id:81,oaid:"W2073017605",doi:"10.1371/journal.pcbi.1000395",title:"Brain Anatomical Network and Intelligence",authors:[{name:"Yonghui Li",institutions:["Chinese Academy of Sciences","Institute of Automation"]},{name:"Yong Liu",institutions:["Institute of Automation","Chinese Academy of Sciences"]},{name:"Jun Li",institutions:["Institute of Automation","Chinese Academy of Sciences","Beijing Normal University"]},{name:"Wen Qin",institutions:["Capital Medical University"]},{name:"Kuncheng Li",institutions:["Capital Medical University"]},{name:"Chunshui Yu",institutions:["Capital Medical University"]},{name:"Tianzi Jiang",institutions:["Institute of Automation","Chinese Academy of Sciences"]}],authorString:"Yonghui Li; Yong Liu; Jun Li; Wen Qin; Kuncheng Li; Chunshui Yu; Tianzi Jiang",institutions:["Beijing Normal University","Capital Medical University","Chinese Academy of Sciences","Institute of Automation"],countries:["CN"],year:2009,journal:"PLoS Computational Biology",citations:610,abstract:"Intuitively, higher intelligence might be assumed to correspond to more efficient information transfer in the brain, but no direct evidence has been reported from the perspective of brain networks. In this study, we performed extensive analyses to test the hypothesis that individual differences in intelligence are associated with brain structural organization, and in particular that higher scores on intelligence tests are related to greater global efficiency of the brain anatomical network. We constructed binary and weighted brain anatomical networks in each of 79 healthy young adults utilizing diffusion tensor tractography and calculated topological properties of the networks using a graph theoretical method. Based on their IQ test scores, all subjects were divided into general and high intelligence groups and significantly higher global efficiencies were found in the networks of the latter group. Moreover, we showed significant correlations between IQ scores and network properties across all subjects while controlling for age and gender. Specifically, higher intelligence scores corresponded to a shorter characteristic path length and a higher global efficiency of the networks, indicating a more efficient parallel information transfer in the brain. The results were consistently observed not only in the binary but also in the weighted networks, which together provide convergent evidence for our hypothesis. Our findings suggest that the efficiency of brain structural organization may be an important biological basis for intelligence.",keywords:["Tractography","Diffusion MRI","Intelligence quotient","Fluid intelligence","Cognition","Connectomics"],concepts:["Tractography","Diffusion MRI","Intelligence quotient","Fluid intelligence","Psychology","Cognition","Connectomics","Artificial intelligence"],topics:["Advanced Neuroimaging Techniques and Applications","Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1000395&type=printable",is_oa:!0,n_refs:82,n_refs_in_core:13,degree:57,community:1,deg_w:962,betweenness:.005,pagerank:.00679,eigenvector:.1118,pdf_file:"Li_2009.pdf",pdf_downloaded:!0},{id:82,oaid:"W1979631864",doi:"10.1523/jneurosci.5698-11.2012",title:"Loss of Intranetwork and Internetwork Resting State Functional Connections with Alzheimer's Disease Progression",authors:[{name:"Matthew R. Brier",institutions:["Washington University in St. Louis"]},{name:"John B. Thomas",institutions:[]},{name:"Abraham Z. Snyder",institutions:[]},{name:"Tammie L.S. Benzinger",institutions:[]},{name:"Dong Zhang",institutions:[]},{name:"Marc Raichle",institutions:["Washington University in St. Louis"]},{name:"David M. Holtzman",institutions:["Alzheimer’s Disease Neuroimaging Initiative","Hope Center for Neurological Disorders"]},{name:"John C. Morris",institutions:["Alzheimer’s Disease Neuroimaging Initiative","Hope Center for Neurological Disorders"]},{name:"Beau M. Ances",institutions:["Washington University in St. Louis"]}],authorString:"Matthew R. Brier; John B. Thomas; Abraham Z. Snyder; Tammie L.S. Benzinger; Dong Zhang; Marc Raichle; David M. Holtzman; John C. Morris; Beau M. Ances",institutions:["Alzheimer’s Disease Neuroimaging Initiative","Hope Center for Neurological Disorders","Washington University in St. Louis"],countries:["US"],year:2012,journal:"Journal of Neuroscience",citations:603,abstract:"Alzheimer's disease (AD) is the most common cause of dementia. Much is known concerning AD pathophysiology but our understanding of the disease at the systems level remains incomplete. Previous AD research has used resting-state functional connectivity magnetic resonance imaging (rs-fcMRI) to assess the integrity of functional networks within the brain. Most studies have focused on the default-mode network (DMN), a primary locus of AD pathology. However, other brain regions are inevitably affected with disease progression. We studied rs-fcMRI in five functionally defined brain networks within a large cohort of human participants of either gender (n = 510) that ranged in AD severity from unaffected [clinical dementia rating (CDR) 0] to very mild (CDR 0.5) to mild (CDR 1). We observed loss of correlations within not only the DMN but other networks at CDR 0.5. Within the salience network (SAL), increases were seen between CDR 0 and CDR 0.5. However, at CDR 1, all networks, including SAL, exhibited reduced correlations. Specific networks were preferentially affected at certain CDR stages. In addition, cross-network relations were consistently lost with increasing AD severity. Our results demonstrate that AD is associated with widespread loss of both intranetwork and internetwork correlations. These results provide insight into AD pathophysiology and reinforce an integrative view of the brain's functional organization.",keywords:["Clinical Dementia Rating","Dementia","Resting state fMRI","Neuroscience","Disease","Default mode network","Pathophysiology"],concepts:["Clinical Dementia Rating","Dementia","Resting state fMRI","Neuroscience","Disease","Default mode network","Pathophysiology","Psychology"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/32/26/8890.full.pdf",is_oa:!0,n_refs:79,n_refs_in_core:14,degree:32,community:2,deg_w:513.5,betweenness:.0012,pagerank:.00452,eigenvector:.0239,pdf_file:null,pdf_downloaded:!1},{id:83,oaid:"W2131055855",doi:"10.1093/brain/awr223",title:"Altered functional–structural coupling of large-scale brain networks in idiopathic generalized epilepsy",authors:[{name:"Zhiqiang Zhang",institutions:["Nanjing General Hospital of Nanjing Military Command","Nanjing University"]},{name:"Wei Liao",institutions:["University of Electronic Science and Technology of China"]},{name:"Huafu Chen",institutions:["University of Electronic Science and Technology of China"]},{name:"Dante Mantini",institutions:["KU Leuven"]},{name:"Ju-Rong Ding",institutions:["University of Electronic Science and Technology of China"]},{name:"Qiang Xu",institutions:["University of Electronic Science and Technology of China"]},{name:"Zhengge Wang",institutions:["Nanjing General Hospital of Nanjing Military Command","Nanjing University"]},{name:"Cuiping Yuan",institutions:["Nanjing General Hospital of Nanjing Military Command","Nanjing University"]},{name:"Guang‐Hui Chen",institutions:["Nanjing General Hospital of Nanjing Military Command","Nanjing University"]},{name:"Qing Jiao",institutions:["Nanjing General Hospital of Nanjing Military Command","Nanjing University"]},{name:"Guangming Lu",institutions:["Nanjing General Hospital of Nanjing Military Command","Nanjing University"]}],authorString:"Zhiqiang Zhang; Wei Liao; Huafu Chen; Dante Mantini; Ju-Rong Ding; Qiang Xu; Zhengge Wang; Cuiping Yuan; Guang‐Hui Chen; Qing Jiao; Guangming Lu",institutions:["KU Leuven","Nanjing General Hospital of Nanjing Military Command","Nanjing University","University of Electronic Science and Technology of China"],countries:["BE","CN"],year:2011,journal:"Brain",citations:588,abstract:"The human brain is a large-scale integrated network in the functional and structural domain. Graph theoretical analysis provides a novel framework for analysing such complex networks. While previous neuroimaging studies have uncovered abnormalities in several specific brain networks in patients with idiopathic generalized epilepsy characterized by tonic-clonic seizures, little is known about changes in whole-brain functional and structural connectivity networks. Regarding functional and structural connectivity, networks are intimately related and share common small-world topological features. We predict that patients with idiopathic generalized epilepsy would exhibit a decoupling between functional and structural networks. In this study, 26 patients with idiopathic generalized epilepsy characterized by tonic-clonic seizures and 26 age- and sex-matched healthy controls were recruited. Resting-state functional magnetic resonance imaging signal correlations and diffusion tensor image tractography were used to generate functional and structural connectivity networks. Graph theoretical analysis revealed that the patients lost optimal topological organization in both functional and structural connectivity networks. Moreover, the patients showed significant increases in nodal topological characteristics in several cortical and subcortical regions, including mesial frontal cortex, putamen, thalamus and amygdala relative to controls, supporting the hypothesis that regions playing important roles in the pathogenesis of epilepsy may display abnormal hub properties in network analysis. Relative to controls, patients showed further decreases in nodal topological characteristics in areas of the default mode network, such as the posterior cingulate gyrus and inferior temporal gyrus. Most importantly, the degree of coupling between functional and structural connectivity networks was decreased, and exhibited a negative correlation with epilepsy duration in patients. Our findings suggest that the decoupling of functional and structural connectivity may reflect the progress of long-term impairment in idiopathic generalized epilepsy, and may be used as a potential biomarker to detect subtle brain abnormalities in epilepsy. Overall, our results demonstrate for the first time that idiopathic generalized epilepsy is reflected in a disrupted topological organization in large-scale brain functional and structural networks, thus providing valuable information for better understanding the pathophysiological mechanisms of generalized tonic-clonic seizures.",keywords:["Neuroscience","Functional magnetic resonance imaging","Diffusion MRI","Default mode network","Epilepsy","Thalamus","Resting state fMRI"],concepts:["Neuroscience","Functional magnetic resonance imaging","Diffusion MRI","Default mode network","Epilepsy","Thalamus","Resting state fMRI","Psychology"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"https://academic.oup.com/brain/article-pdf/134/10/2912/17865377/awr223.pdf",is_oa:!0,n_refs:121,n_refs_in_core:30,degree:50,community:1,deg_w:983.5,betweenness:.0035,pagerank:.00694,eigenvector:.112,pdf_file:null,pdf_downloaded:!1},{id:84,oaid:"W2042981671",doi:"10.3389/fnhum.2013.00458",title:"Reconceptualizing functional brain connectivity in autism from a developmental perspective",authors:[{name:"Lucina Q. Uddin",institutions:["Stanford Medicine","Stanford University"]},{name:"Kaustubh Supekar",institutions:["Stanford University"]},{name:"Vinod Menon",institutions:["Stanford University"]}],authorString:"Lucina Q. Uddin; Kaustubh Supekar; Vinod Menon",institutions:["Stanford Medicine","Stanford University"],countries:["US"],year:2013,journal:"Frontiers in Human Neuroscience",citations:586,abstract:"While there is almost universal agreement amongst researchers that autism is associated with alterations in brain connectivity, the precise nature of these alterations continues to be debated. Theoretical and empirical work is beginning to reveal that autism is associated with a complex functional phenotype characterized by both hypo- and hyper-connectivity of large-scale brain systems. It is not yet understood why such conflicting patterns of brain connectivity are observed across different studies, and the factors contributing to these heterogeneous findings have not been identified. Developmental changes in functional connectivity have received inadequate attention to date. We propose that discrepancies between findings of autism related hypo-connectivity and hyper-connectivity might be reconciled by taking developmental changes into account. We review neuroimaging studies of autism, with an emphasis on functional magnetic resonance imaging studies of intrinsic functional connectivity in children, adolescents and adults. The consistent pattern emerging across several studies is that while intrinsic functional connectivity in adolescents and adults with autism is generally reduced compared with age-matched controls, functional connectivity in younger children with the disorder appears to be increased. We suggest that by placing recent empirical findings within a developmental framework, and explicitly characterizing age and pubertal stage in future work, it may be possible to resolve conflicting findings of hypo- and hyper-connectivity in the extant literature and arrive at a more comprehensive understanding of the neurobiology of autism.",keywords:["Autism","Functional connectivity","Extant taxon","Functional magnetic resonance imaging","Neuroimaging","Neuroscience","Autism spectrum disorder"],concepts:["Autism","Functional connectivity","Extant taxon","Functional magnetic resonance imaging","Neuroimaging","Psychology","Neuroscience","Autism spectrum disorder"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Autism Spectrum Disorder Research"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnhum.2013.00458/pdf",is_oa:!0,n_refs:116,n_refs_in_core:10,degree:23,community:2,deg_w:220,betweenness:.0016,pagerank:.00233,eigenvector:.0115,pdf_file:"Uddin_2013.pdf",pdf_downloaded:!0},{id:85,oaid:"W2088905367",doi:"10.1371/journal.pcbi.1000408",title:"Modeling the Impact of Lesions in the Human Brain",authors:[{name:"Jeffrey Alstott",institutions:["Indiana University Bloomington"]},{name:"Michael Breakspear",institutions:["Black Dog Institute","QIMR Berghofer Medical Research Institute","Royal Brisbane and Women's Hospital","UNSW Sydney"]},{name:"Patric Hagmann",institutions:["École Polytechnique","Emergency University","Federal Supreme Court of Switzerland","Polytechnique Montréal","École Polytechnique Fédérale de Lausanne","University of Lausanne"]},{name:"Leila Cammoun",institutions:["École Polytechnique","Emergency University","Federal Supreme Court of Switzerland","Polytechnique Montréal","École Polytechnique Fédérale de Lausanne","University of Lausanne"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington","Indiana University"]}],authorString:"Jeffrey Alstott; Michael Breakspear; Patric Hagmann; Leila Cammoun; Olaf Sporns",institutions:["Black Dog Institute","Emergency University","Federal Supreme Court of Switzerland","Indiana University","Indiana University Bloomington","Polytechnique Montréal","QIMR Berghofer Medical Research Institute","Royal Brisbane and Women's Hospital","UNSW Sydney","University of Lausanne","École Polytechnique","École Polytechnique Fédérale de Lausanne"],countries:["AU","CA","CH","FR","US"],year:2009,journal:"PLoS Computational Biology",citations:586,abstract:'Lesions of anatomical brain networks result in functional disturbances of brain systems and behavior which depend sensitively, often unpredictably, on the lesion site. The availability of whole-brain maps of structural connections within the human cerebrum and our increased understanding of the physiology and large-scale dynamics of cortical networks allow us to investigate the functional consequences of focal brain lesions in a computational model. We simulate the dynamic effects of lesions placed in different regions of the cerebral cortex by recording changes in the pattern of endogenous ("resting-state") neural activity. We find that lesions produce specific patterns of altered functional connectivity among distant regions of cortex, often affecting both cortical hemispheres. The magnitude of these dynamic effects depends on the lesion location and is partly predicted by structural network properties of the lesion site. In the model, lesions along the cortical midline and in the vicinity of the temporo-parietal junction result in large and widely distributed changes in functional connectivity, while lesions of primary sensory or motor regions remain more localized. The model suggests that dynamic lesion effects can be predicted on the basis of specific network measures of structural brain networks and that these effects may be related to known behavioral and cognitive consequences of brain lesions.',keywords:["Computational biology"],concepts:["Computer science","Computational biology","Biology"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Health, Environment, Cognitive Aging"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1000408&type=printable",is_oa:!0,n_refs:55,n_refs_in_core:9,degree:35,community:1,deg_w:438,betweenness:.0024,pagerank:.00364,eigenvector:.0447,pdf_file:"Alstott_2009.pdf",pdf_downloaded:!0},{id:86,oaid:"W2158031492",doi:"10.1093/cercor/bhq071",title:"The Functional Architecture of the Infant Brain as Revealed by Resting-State fMRI",authors:[{name:"Peter Fransson",institutions:["Karolinska Institutet"]},{name:"Ulrika Ådén",institutions:["Karolinska Institutet"]},{name:"Mats Blennow",institutions:["Karolinska Institutet"]},{name:"Hugo Lagercrantz",institutions:["Karolinska Institutet"]}],authorString:"Peter Fransson; Ulrika Ådén; Mats Blennow; Hugo Lagercrantz",institutions:["Karolinska Institutet"],countries:["SE"],year:2010,journal:"Cerebral Cortex",citations:560,abstract:"The functional network topology of the adult human brain has recently begun to be noninvasively mapped using resting-state functional connectivity magnetic resonance imaging and described using mathematical tools originating from graph theory. Previous studies have revealed the existence of disproportionally connected brain regions, so called cortical hubs, which act as information convergence zones and supposedly capture key aspects of how the brain's architecture supports human behavior and how it is affected by disease. In this study, we present results showing that cortical hubs and their associated cortical networks are largely confined to primary sensory and motor brain regions in the infant brain. Our findings in infants stand in stark contrast to the situation found in adults where the majority of cortical hubs and hub-related networks are located in heteromodal association cortex. Our findings suggest that the functional network architecture in infants is linked to support tasks that are of a perception-action nature.",keywords:["Neuroscience","Functional magnetic resonance imaging","Human brain","Resting state fMRI","Perception","Functional connectivity","Sensory system"],concepts:["Neuroscience","Functional magnetic resonance imaging","Human brain","Resting state fMRI","Perception","Functional connectivity","Sensory system","Psychology"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Photoreceptor and optogenetics research"],pdf_url:"https://academic.oup.com/cercor/article-pdf/21/1/145/17304017/bhq071.pdf",is_oa:!0,n_refs:67,n_refs_in_core:14,degree:43,community:2,deg_w:714.5,betweenness:.003,pagerank:.00539,eigenvector:.0694,pdf_file:null,pdf_downloaded:!1},{id:87,oaid:"W2075496760",doi:"10.1523/jneurosci.4136-10.2010",title:"Diffusion Tensor Tractography Reveals Abnormal Topological Organization in Structural Cortical Networks in Alzheimer's Disease",authors:[{name:"Chun‐Yi Zac Lo",institutions:["National Yang Ming Chiao Tung University","National Yang Ming University Hospital"]},{name:"Pei-Ning Wang",institutions:["National Yang Ming Chiao Tung University","Taipei Veterans General Hospital"]},{name:"Kun-Hsien Chou",institutions:["National Yang Ming Chiao Tung University","National Yang Ming University Hospital"]},{name:"Jinhui Wang",institutions:["Beijing Normal University"]},{name:"Yong He",institutions:["Beijing Normal University"]},{name:"Ching‐Po Lin",institutions:["National Yang Ming Chiao Tung University","National Yang Ming University Hospital"]}],authorString:"Chun‐Yi Zac Lo; Pei-Ning Wang; Kun-Hsien Chou; Jinhui Wang; Yong He; Ching‐Po Lin",institutions:["Beijing Normal University","National Yang Ming Chiao Tung University","National Yang Ming University Hospital","Taipei Veterans General Hospital"],countries:["CN","TW"],year:2010,journal:"Journal of Neuroscience",citations:559,abstract:"Recent research on Alzheimer's disease (AD) has shown that the decline of cognitive and memory functions is accompanied by a disrupted neuronal connectivity characterized by white matter (WM) degeneration. However, changes in the topological organization of WM structural network in AD remain largely unknown. Here, we used diffusion tensor image tractography to construct the human brain WM networks of 25 AD patients and 30 age- and sex-matched healthy controls, followed by a graph theoretical analysis. We found that both AD patients and controls had a small-world topology in WM network, suggesting an optimal balance between structurally segregated and integrative organization. More important, the AD patients exhibited increased shortest path length and decreased global efficiency in WM network compared with controls, implying abnormal topological organization. Furthermore, we showed that the WM network contained highly connected hub regions that were predominately located in the precuneus, cingulate cortex, and dorsolateral prefrontal cortex, which was consistent with the previous diffusion-MRI studies. Specifically, AD patients were found to have reduced nodal efficiency predominantly located in the frontal regions. Finally, we showed that the alterations of various network properties were significantly correlated with the behavior performances. Together, the present study demonstrated for the first time that the Alzheimer's brain was associated with disrupted topological organization in the large-scale WM structural networks, thus providing the structural evidence for abnormalities of systematic integrity in this disease. This work could also have implications for understanding how the abnormalities of structural connectivity in AD underlie behavioral deficits in the patients.",keywords:["Precuneus","Diffusion MRI","Neuroscience","Tractography","White matter","Posterior cingulate","Disease"],concepts:["Precuneus","Diffusion MRI","Neuroscience","Tractography","White matter","Posterior cingulate","Psychology","Disease"],topics:["Advanced Neuroimaging Techniques and Applications","Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/30/50/16876.full.pdf",is_oa:!0,n_refs:75,n_refs_in_core:16,degree:42,community:1,deg_w:695.5,betweenness:.0026,pagerank:.00525,eigenvector:.0649,pdf_file:null,pdf_downloaded:!1},{id:88,oaid:"W2115990221",doi:"10.1371/journal.pcbi.1000314",title:"Broadband Criticality of Human Brain Network Synchronization",authors:[{name:"Manfred G. Kitzbichler",institutions:["University of Cambridge"]},{name:"Marie L. Smith",institutions:["MRC Cognition and Brain Sciences Unit"]},{name:"Søren Rahn Christensen",institutions:["GlaxoSmithKline (United Kingdom)","Addenbrooke's Hospital"]},{name:"Edward T. Bullmore",institutions:["GlaxoSmithKline (United Kingdom)","Addenbrooke's Hospital","University of Cambridge"]}],authorString:"Manfred G. Kitzbichler; Marie L. Smith; Søren Rahn Christensen; Edward T. Bullmore",institutions:["Addenbrooke's Hospital","GlaxoSmithKline (United Kingdom)","MRC Cognition and Brain Sciences Unit","University of Cambridge"],countries:["GB"],year:2009,journal:"PLoS Computational Biology",citations:550,abstract:`Self-organized criticality is an attractive model for human brain dynamics, but there has been little direct evidence for its existence in large-scale systems measured by neuroimaging. In general, critical systems are associated with fractal or power law scaling, long-range correlations in space and time, and rapid reconfiguration in response to external inputs. Here, we consider two measures of phase synchronization: the phase-lock interval, or duration of coupling between a pair of (neurophysiological) processes, and the lability of global synchronization of a (brain functional) network. Using computational simulations of two mechanistically distinct systems displaying complex dynamics, the Ising model and the Kuramoto model, we show that both synchronization metrics have power law probability distributions specifically when these systems are in a critical state. We then demonstrate power law scaling of both pairwise and global synchronization metrics in functional MRI and magnetoencephalographic data recorded from normal volunteers under resting conditions. These results strongly suggest that human brain functional systems exist in an endogenous state of dynamical criticality, characterized by a greater than random probability of both prolonged periods of phase-locking and occurrence of large rapid changes in the state of global synchronization, analogous to the neuronal "avalanches" previously described in cellular systems. Moreover, evidence for critical dynamics was identified consistently in neurophysiological systems operating at frequency intervals ranging from 0.05-0.11 to 62.5-125 Hz, confirming that criticality is a property of human brain functional network organization at all frequency intervals in the brain's physiological bandwidth.`,keywords:["Criticality","Synchronization","Magnetoencephalography","Phase synchronization","Kuramoto model","Synchronization networks","Neurophysiology"],concepts:["Criticality","Synchronization (alternating current)","Computer science","Magnetoencephalography","Phase synchronization","Kuramoto model","Synchronization networks","Neurophysiology"],topics:["Neural dynamics and brain function","Functional Brain Connectivity Studies","Nonlinear Dynamics and Pattern Formation"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1000314&type=printable",is_oa:!0,n_refs:53,n_refs_in_core:3,degree:17,community:0,deg_w:147.5,betweenness:5e-4,pagerank:.00173,eigenvector:.0148,pdf_file:"Kitzbichler_2009.pdf",pdf_downloaded:!0},{id:89,oaid:"W2025832022",doi:"10.1523/jneurosci.4465-11.2011",title:"Dynamic Reconfiguration of Structural and Functional Connectivity Across Core Neurocognitive Brain Networks with Development",authors:[{name:"Lucina Q. Uddin",institutions:["Stanford Medicine","Stanford University"]},{name:"Kaustubh Supekar",institutions:["Institute of Behavioral Sciences","Stanford University"]},{name:"Srikanth Ryali",institutions:["Institute of Behavioral Sciences","Stanford University"]},{name:"Vinod Menon",institutions:["Stanford University"]}],authorString:"Lucina Q. Uddin; Kaustubh Supekar; Srikanth Ryali; Vinod Menon",institutions:["Institute of Behavioral Sciences","Stanford Medicine","Stanford University"],countries:["JP","US"],year:2011,journal:"Journal of Neuroscience",citations:536,abstract:"Brain structural and functional development, throughout childhood and into adulthood, underlies the maturation of increasingly sophisticated cognitive abilities. High-level attentional and cognitive control processes rely on the integrity of, and dynamic interactions between, core neurocognitive networks. The right fronto-insular cortex (rFIC) is a critical component of a salience network (SN) that mediates interactions between large-scale brain networks involved in externally oriented attention [central executive network (CEN)] and internally oriented cognition [default mode network (DMN)]. How these systems reconfigure and mature with development is a critical question for cognitive neuroscience, with implications for neurodevelopmental pathologies affecting brain connectivity. Using functional and effective connectivity measures applied to fMRI data, we examine interactions within and between the SN, CEN, and DMN. We find that functional coupling between key network nodes is stronger in adults than in children, as are causal links emanating from the rFIC. Specifically, the causal influence of the rFIC on nodes of the SN and CEN was significantly greater in adults compared with children. Notably, these results were entirely replicated on an independent dataset of matched children and adults. Developmental changes in functional and effective connectivity were related to structural connectivity along these links. Diffusion tensor imaging tractography revealed increased structural integrity in adults compared with children along both within- and between-network pathways associated with the rFIC. These results suggest that structural and functional maturation of rFIC pathways is a critical component of the process by which human brain networks mature during development to support complex, flexible cognitive processes in adulthood.",keywords:["Neurocognitive","Default mode network","Cognition","Neuroscience","Functional connectivity"],concepts:["Neurocognitive","Default mode network","Cognition","Psychology","Neuroscience","Functional connectivity"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/31/50/18578.full.pdf",is_oa:!0,n_refs:77,n_refs_in_core:12,degree:35,community:2,deg_w:383.5,betweenness:.0039,pagerank:.00352,eigenvector:.0221,pdf_file:null,pdf_downloaded:!1},{id:90,oaid:"W2583548943",doi:"10.1016/j.neuroimage.2017.02.005",title:"Proportional thresholding in resting-state fMRI functional connectivity networks and consequences for patient-control connectome studies: Issues and recommendations",authors:[{name:"Martijn P. van den Heuvel",institutions:["Heidelberg University","University Hospital Heidelberg","University Medical Center Utrecht"]},{name:"Siemon C. de Lange",institutions:["University Medical Center Utrecht","Heidelberg University","University Hospital Heidelberg"]},{name:"Andrew Zalesky",institutions:["University of Melbourne"]},{name:"Caio Seguin",institutions:["University of Melbourne"]},{name:"B.T. Thomas Yeo",institutions:["National University of Singapore"]},{name:"Ruben Schmidt",institutions:["University Medical Center Utrecht"]}],authorString:"Martijn P. van den Heuvel; Siemon C. de Lange; Andrew Zalesky; Caio Seguin; B.T. Thomas Yeo; Ruben Schmidt",institutions:["Heidelberg University","National University of Singapore","University Hospital Heidelberg","University Medical Center Utrecht","University of Melbourne"],countries:["AU","DE","NL","SG"],year:2017,journal:"NeuroImage",citations:514,abstract:'Graph theoretical analysis has become an important tool in the examination of brain dysconnectivity in neurological and psychiatric brain disorders. A common analysis step in the construction of the functional graph or network involves "thresholding" of the connectivity matrix, selecting the set of edges that together form the graph on which network organization is evaluated. To avoid systematic differences in absolute number of edges, studies have argued against the use of an "absolute threshold" in case-control studies and have proposed the use of "proportional thresholding" instead, in which a pre-defined number of strongest connections are selected as network edges, ensuring equal network density across datasets. Here, we systematically studied the effect of proportional thresholding on the construction of functional matrices and subsequent graph analysis in patient-control functional connectome studies. In a few simple experiments we show that differences in overall strength of functional connectivity (FC) - as often observed between patients and controls - can have predictable consequences for between-group differences in network organization. In individual networks with lower overall FC the proportional thresholding algorithm has to select more edges based on lower correlations, which have (on average) a higher probability of being spurious, and thus introduces a higher degree of randomness in the resulting network. We show across both empirical and artificial patient-control datasets that lower levels of overall FC in either the patient or control group will most often lead to differences in network efficiency and clustering, suggesting that differences in FC across subjects will be artificially inflated or translated into differences in network organization. Based on the presented case-control findings we inform about the caveats of proportional thresholding in patient-control studies in which groups show a between-group difference in overall FC. We make recommendations on how to examine, report and to take into account overall FC effects in future patient-control functional connectome studies.',keywords:["Thresholding","Connectome","Spurious relationship","Connectomics","Resting state fMRI","Graph theory","Clustering coefficient"],concepts:["Thresholding","Connectome","Spurious relationship","Connectomics","Computer science","Resting state fMRI","Graph theory","Clustering coefficient"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"https://doi.org/10.1016/j.neuroimage.2017.02.005",is_oa:!0,n_refs:53,n_refs_in_core:11,degree:31,community:3,deg_w:295.5,betweenness:.0031,pagerank:.00289,eigenvector:.0167,pdf_file:null,pdf_downloaded:!1},{id:91,oaid:"W2101571519",doi:"10.1073/pnas.1220826110",title:"Cognitive relevance of the community structure of the human brain functional coactivation network",authors:[{name:"Nicolás Crossley",institutions:["King's College London"]},{name:"Andrea Mechelli",institutions:["King's College London"]},{name:"Petra E. Vértes",institutions:["University of Cambridge"]},{name:"Toby Winton‐Brown",institutions:["King's College London"]},{name:"Ameera X. Patel",institutions:["University of Cambridge"]},{name:"Cedric E. Ginestet",institutions:["Boston University","King's College London"]},{name:"Philip McGuire",institutions:["King's College London"]},{name:"Edward T. Bullmore",institutions:["National Health Service","GlaxoSmithKline (United Kingdom)","University of Cambridge","Cambridgeshire and Peterborough NHS Foundation Trust"]}],authorString:"Nicolás Crossley; Andrea Mechelli; Petra E. Vértes; Toby Winton‐Brown; Ameera X. Patel; Cedric E. Ginestet; Philip McGuire; Edward T. Bullmore",institutions:["Boston University","Cambridgeshire and Peterborough NHS Foundation Trust","GlaxoSmithKline (United Kingdom)","King's College London","National Health Service","University of Cambridge"],countries:["GB","US"],year:2013,journal:"Proceedings of the National Academy of Sciences",citations:507,abstract:"There is growing interest in the complex topology of human brain functional networks, often measured using resting-state functional MRI (fMRI). Here, we used a meta-analysis of the large primary literature that used fMRI or PET to measure task-related activation (>1,600 studies; 1985-2010). We estimated the similarity (Jaccard index) of the activation patterns across experimental tasks between each pair of 638 brain regions. This continuous coactivation matrix was used to build a weighted graph to characterize network topology. The coactivation network was modular, with occipital, central, and default-mode modules predominantly coactivated by specific cognitive domains (perception, action, and emotion, respectively). It also included a rich club of hub nodes, located in parietal and prefrontal cortex and often connected over long distances, which were coactivated by a diverse range of experimental tasks. Investigating the topological role of edges between a deactivated and an activated node, we found that such competitive interactions were most frequent between nodes in different modules or between an activated rich-club node and a deactivated peripheral node. Many aspects of the coactivation network were convergent with a connectivity network derived from resting state fMRI data (n = 27, healthy volunteers); although the connectivity network was more parsimoniously connected and differed in the anatomical locations of some hubs. We conclude that the community structure of human brain networks is relevant to cognitive function. Deactivations may play a role in flexible reconfiguration of the network according to cognitive demand, varying the integration between modules, and between the periphery and a central rich club.",keywords:["Coactivation","Resting state fMRI","Default mode network","Human Connectome Project","Cognition","Neuroscience","Intraparietal sulcus","Human brain"],concepts:["Coactivation","Resting state fMRI","Default mode network","Human Connectome Project","Cognition","Neuroscience","Intraparietal sulcus","Human brain"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"https://www.pnas.org/content/pnas/110/28/11583.full.pdf",is_oa:!0,n_refs:53,n_refs_in_core:14,degree:40,community:0,deg_w:523,betweenness:.0034,pagerank:.00437,eigenvector:.0352,pdf_file:null,pdf_downloaded:!1},{id:92,oaid:"W2086686257",doi:"10.1523/jneurosci.3554-12.2013",title:"The Convergence of Maturational Change and Structural Covariance in Human Cortical Networks",authors:[{name:"Aaron Alexander‐Bloch",institutions:["University of California, Los Angeles","University of Cambridge","National Institute of Mental Health"]},{name:"Armin Raznahan",institutions:["National Institute of Mental Health"]},{name:"Edward T. Bullmore",institutions:["GlaxoSmithKline (United Kingdom)","University of Cambridge","Cambridgeshire and Peterborough NHS Foundation Trust","Addenbrooke's Hospital"]},{name:"Jay N. Giedd",institutions:["National Institute of Mental Health"]}],authorString:"Aaron Alexander‐Bloch; Armin Raznahan; Edward T. Bullmore; Jay N. Giedd",institutions:["Addenbrooke's Hospital","Cambridgeshire and Peterborough NHS Foundation Trust","GlaxoSmithKline (United Kingdom)","National Institute of Mental Health","University of California, Los Angeles","University of Cambridge"],countries:["GB","US"],year:2013,journal:"Journal of Neuroscience",citations:507,abstract:"Large-scale covariance of cortical thickness or volume in distributed brain regions has been consistently reported by human neuroimaging studies. The mechanism of this population covariance of regional cortical anatomy has been hypothetically related to synchronized maturational changes in anatomically connected neuronal populations. Brain regions that grow together, i.e., increase or decrease in volume at the same rate over the course of years in the same individual, are thus expected to demonstrate strong structural covariance or anatomical connectivity across individuals. To test this prediction, we used a structural MRI dataset on healthy young people (N = 108; aged 9-22 years at enrollment), comprising 3-6 longitudinal scans on each participant over 6-12 years of follow-up. At each of 360 regional nodes, and for each participant, we estimated the following: (1) the cortical thickness in the median scan and (2) the linear rate of change in cortical thickness over years of serial scanning. We constructed structural and maturational association matrices and networks from these measurements. Both structural and maturational networks shared similar global and nodal topological properties, as well as mesoscopic features including a modular community structure, a relatively small number of highly connected hub regions, and a bias toward short distance connections. Using resting-state functional magnetic resonance imaging data on a subset of the sample (N = 32), we also demonstrated that functional connectivity and network organization was somewhat predictable by structural/maturational networks but demonstrated a stronger bias toward short distance connections and greater topological segregation. Brain structural covariance networks are likely to reflect synchronized developmental change in distributed cortical regions.",keywords:["Covariance","Neuroscience","Neuroimaging","Human brain","Brain size","Analysis of covariance","Functional connectivity"],concepts:["Covariance","Neuroscience","Neuroimaging","Human brain","Population","Brain size","Analysis of covariance","Functional connectivity"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/33/7/2889.full.pdf",is_oa:!0,n_refs:76,n_refs_in_core:13,degree:31,community:3,deg_w:365.5,betweenness:.0027,pagerank:.00321,eigenvector:.0263,pdf_file:"AlexanderBloch_2013.pdf",pdf_downloaded:!0},{id:93,oaid:"W2084009541",doi:"10.3389/fnsys.2010.00147",title:"Disrupted Modularity and Local Connectivity of Brain Functional Networks in Childhood-Onset Schizophrenia",authors:[{name:"Aaron Alexander‐Bloch",institutions:["University of Cambridge","Cambridge School"]},{name:"Nitin Gogtay",institutions:["National Institute of Mental Health"]},{name:"David Meunier",institutions:["University of Cambridge"]},{name:"Rasmus M. Birn",institutions:["University of Wisconsin–Madison"]},{name:"Liv Clasen",institutions:["National Institute of Mental Health"]},{name:"François Lalonde",institutions:["National Institute of Mental Health"]},{name:"Rhoshel Lenroot",institutions:["UNSW Sydney","Neuroscience Research Australia"]},{name:"Jay N. Giedd",institutions:["National Institute of Mental Health"]},{name:"Edward T. Bullmore",institutions:["University of Cambridge","Cambridge School"]}],authorString:"Aaron Alexander‐Bloch; Nitin Gogtay; David Meunier; Rasmus M. Birn; Liv Clasen; François Lalonde; Rhoshel Lenroot; Jay N. Giedd; Edward T. Bullmore",institutions:["Cambridge School","National Institute of Mental Health","Neuroscience Research Australia","UNSW Sydney","University of Cambridge","University of Wisconsin–Madison"],countries:["AU","GB","PT","US"],year:2010,journal:"Frontiers in Systems Neuroscience",citations:495,abstract:"Modularity is a fundamental concept in systems neuroscience, referring to the formation of local cliques or modules of densely intra-connected nodes that are sparsely inter-connected with nodes in other modules. Topological modularity of brain functional networks can quantify theoretically anticipated abnormality of brain network community structure - so-called dysmodularity - in developmental disorders such as childhood-onset schizophrenia (COS). We used graph theory to investigate topology of networks derived from resting-state fMRI data on 13 COS patients and 19 healthy volunteers. We measured functional connectivity between each pair of 100 regional nodes, focusing on wavelet correlation in the frequency interval 0.05-0.1 Hz, then applied global and local thresholding rules to construct graphs from each individual association matrix over the full range of possible connection densities. We show how local thresholding based on the minimum spanning tree facilitates group comparisons of networks by forcing the connectedness of sparse graphs. Threshold-dependent graph theoretical results are compatible with the results of a k-means unsupervised learning algorithm and a multi-resolution (spin glass) approach to modularity, both of which also find community structure but do not require thresholding of the association matrix. In general modularity of brain functional networks was significantly reduced in COS, due to a relatively reduced density of intra-modular connections between neighboring regions. Other network measures of local organization such as clustering were also decreased, while complementary measures of global efficiency and robustness were increased, in the COS group. The group differences in complex network properties were mirrored by differences in simpler statistical properties of the data, such as the variability of the global time series and the internal homogeneity of the time series within anatomical regions of interest.",keywords:["Modularity","Thresholding","Social connectedness","Complex network","Graph theory","Pattern recognition"],concepts:["Modularity (biology)","Thresholding","Social connectedness","Complex network","Graph theory","Computer science","Artificial intelligence","Pattern recognition (psychology)"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnsys.2010.00147/pdf",is_oa:!0,n_refs:100,n_refs_in_core:12,degree:40,community:3,deg_w:575.5,betweenness:.0026,pagerank:.00454,eigenvector:.0515,pdf_file:"AlexanderBloch_2010.pdf",pdf_downloaded:!0},{id:94,oaid:"W2114549884",doi:"10.1093/cercor/bhn003",title:"Revealing Modular Architecture of Human Brain Structural Networks by Using Cortical Thickness from MRI",authors:[{name:"Zhang J. Chen",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Yong He",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Pedro Rosa‐Neto",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Jürgen Germann",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Alan C. Evans",institutions:["Montreal Neurological Institute and Hospital","McGill University"]}],authorString:"Zhang J. Chen; Yong He; Pedro Rosa‐Neto; Jürgen Germann; Alan C. Evans",institutions:["McGill University","Montreal Neurological Institute and Hospital"],countries:["CA"],year:2008,journal:"Cerebral Cortex",citations:493,abstract:"Modularity, presumably shaped by evolutionary constraints, underlies the functionality of most complex networks ranged from social to biological networks. However, it remains largely unknown in human cortical networks. In a previous study, we demonstrated a network of correlations of cortical thickness among specific cortical areas and speculated that these correlations reflected an underlying structural connectivity among those brain regions. Here, we further investigated the intrinsic modular architecture of the human brain network derived from cortical thickness measurement. Modules were defined as groups of cortical regions that are connected morphologically to achieve the maximum network modularity. We show that the human cortical network is organized into 6 topological modules that closely overlap known functional domains such as auditory/language, strategic/executive, sensorimotor, visual, and mnemonic processing. The identified structure-based modular architecture may provide new insights into the functionality of cortical regions and connections between structural brain modules. This study provides the first report of modular architecture of the structural network in the human brain using cortical thickness measurements.",keywords:["Modularity","Modular design","Human brain","Neuroscience","Architecture","Cortex"],concepts:["Modularity (biology)","Modular design","Human brain","Neuroscience","Computer science","Architecture","Cortex (anatomy)","Psychology"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Complex Systems and Time Series Analysis"],pdf_url:"https://academic.oup.com/cercor/article-pdf/18/10/2374/17299204/bhn003.pdf",is_oa:!0,n_refs:72,n_refs_in_core:9,degree:59,community:1,deg_w:933,betweenness:.0059,pagerank:.00657,eigenvector:.1138,pdf_file:"Chen_2008.pdf",pdf_downloaded:!0},{id:95,oaid:"W2153436764",doi:"10.1093/cercor/bhq291",title:"Graph-Theoretical Analysis Reveals Disrupted Small-World Organization of Cortical Thickness Correlation Networks in Temporal Lobe Epilepsy",authors:[{name:"Boris C. Bernhardt",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Zhang Chen",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Yong He",institutions:["Beijing Normal University"]},{name:"Alan C. Evans",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Neda Bernasconi",institutions:["Montreal Neurological Institute and Hospital","McGill University"]}],authorString:"Boris C. Bernhardt; Zhang Chen; Yong He; Alan C. Evans; Neda Bernasconi",institutions:["Beijing Normal University","McGill University","Montreal Neurological Institute and Hospital"],countries:["CA","CN"],year:2011,journal:"Cerebral Cortex",citations:474,abstract:"Temporal lobe epilepsy (TLE) is the most common drug-resistant epilepsy in adults. As morphometric studies have shown widespread structural damage in TLE, this condition is often referred to as a system disorder with disrupted structural networks. Studies based on univariate statistical comparisons can only indirectly test such hypothesis. Graph theory provides a new approach to formally analyze large-scale networks. Using graph-theoretical analysis of magnetic resonance imaging-based cortical thickness correlations, we investigated the structural basis of the organization of such networks in 122 TLE patients and 47 age- and sex-matched healthy controls. Networks in patients and controls were characterized by a short path length between anatomical regions and a high degree of clustering, suggestive of a small-world topology. However, compared with controls, patients showed increased path length and clustering, altered distribution of network hubs, and higher vulnerability to targeted attacks, suggesting a reorganization of cortical thickness correlation networks. Longitudinal analysis demonstrated that network alterations intensify over time. Bootstrap simulations showed high reproducibility of network parameters across random subsamplings, indicating that altered network topology in TLE is a consistent finding. Increased network disruption was associated with unfavorable postoperative seizure outcome, implying adverse effects of epileptogenesis on large-scale network organization.",keywords:["Epileptogenesis","Temporal lobe","Average path length","Clustering coefficient","Epilepsy","Neuroscience","Correlation","Cluster analysis"],concepts:["Epileptogenesis","Temporal lobe","Average path length","Clustering coefficient","Epilepsy","Neuroscience","Correlation","Cluster analysis"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Neural dynamics and brain function"],pdf_url:"https://academic.oup.com/cercor/article-pdf/21/9/2147/17305218/bhq291.pdf",is_oa:!0,n_refs:96,n_refs_in_core:11,degree:30,community:1,deg_w:568.5,betweenness:5e-4,pagerank:.00421,eigenvector:.0722,pdf_file:null,pdf_downloaded:!1},{id:96,oaid:"W1996379253",doi:"10.1002/hbm.20517",title:"Small‐world properties of nonlinear brain activity in schizophrenia",authors:[{name:"Mikail Rubinov",institutions:["Black Dog Institute","UNSW Sydney","Schizophrenia Research Institute"]},{name:"S. A. Knock",institutions:["Black Dog Institute","UNSW Sydney"]},{name:"Cornelis J. Stam",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Sifis Micheloyannis",institutions:["University of Crete"]},{name:"Anthony Harris",institutions:["The University of Sydney","Westmead Hospital","Westmead Institute"]},{name:"Leanne M. Williams",institutions:["The University of Sydney","Westmead Hospital","Westmead Institute"]},{name:"Michael Breakspear",institutions:["Black Dog Institute","UNSW Sydney"]}],authorString:"Mikail Rubinov; S. A. Knock; Cornelis J. Stam; Sifis Micheloyannis; Anthony Harris; Leanne M. Williams; Michael Breakspear",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam","Black Dog Institute","Schizophrenia Research Institute","The University of Sydney","UNSW Sydney","University of Crete","Westmead Hospital","Westmead Institute"],countries:["AU","GR","NL"],year:2007,journal:"Human Brain Mapping",citations:473,abstract:'A disturbance in the interactions between distributed cortical regions may underlie the cognitive and perceptual dysfunction associated with schizophrenia. In this article, nonlinear measures of cortical interactions and graph-theoretical metrics of network topography are combined to investigate this schizophrenia "disconnection hypothesis." This is achieved by analyzing the spatiotemporal structure of resting state scalp EEG data previously acquired from 40 young subjects with a recent first episode of schizophrenia and 40 healthy matched controls. In each subject, a method of mapping the topography of nonlinear interactions between cortical regions was applied to a widely distributed array of these data. The resulting nonlinear correlation matrices were converted to weighted graphs. The path length (a measure of large-scale network integration), clustering coefficient (a measure of "cliquishness"), and hub structure of these graphs were used as metrics of the underlying brain network activity. The graphs of both groups exhibited high levels of local clustering combined with comparatively short path lengths--features consistent with a "small-world" topology--as well as the presence of strong, central hubs. The graphs in the schizophrenia group displayed lower clustering and shorter path lengths in comparison to the healthy group. Whilst still "small-world," these effects are consistent with a subtle randomization in the underlying network architecture--likely associated with a greater number of links connecting disparate clusters. This randomization may underlie the cognitive disturbances characteristic of schizophrenia.',keywords:["Schizophrenia","Small-world network","Clustering coefficient","Disconnection","Cluster analysis","Path length","Nonlinear system","Complex network"],concepts:["Schizophrenia (object-oriented programming)","Small-world network","Clustering coefficient","Disconnection","Cluster analysis","Path length","Nonlinear system","Complex network"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/hbm.20517",is_oa:!0,n_refs:69,n_refs_in_core:7,degree:38,community:1,deg_w:495.5,betweenness:.0023,pagerank:.00391,eigenvector:.0523,pdf_file:null,pdf_downloaded:!1},{id:97,oaid:"W2093597642",doi:"10.1016/j.dcn.2013.11.004",title:"Topological organization of the human brain functional connectome across the lifespan",authors:[{name:"Miao Cao",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Jinhui Wang",institutions:["Hangzhou Normal University","Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Zhengjia Dai",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Xiaoyan Cao",institutions:["Hangzhou Normal University","Chinese Academy of Sciences","Institute of Psychology, Chinese Academy of Sciences"]},{name:"Lili Jiang",institutions:["Chinese Academy of Sciences","Institute of Psychology, Chinese Academy of Sciences"]},{name:"Fengmei Fan",institutions:["Chinese Academy of Sciences","Institute of Psychology, Chinese Academy of Sciences","Beijing HuiLongGuan Hospital"]},{name:"Xiaowei Song",institutions:["Chinese Academy of Sciences","Institute of Biophysics"]},{name:"Mingrui Xia",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Ni Shu",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Qi Dong",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Michael P. Milham",institutions:["Nathan Kline Institute for Psychiatric Research","Child Mind Institute"]},{name:"F. Xavier Castellanos",institutions:["Nathan Kline Institute for Psychiatric Research","NYU Langone Health"]},{name:"Xi‐Nian Zuo",institutions:["Chinese Academy of Sciences","Beijing Normal University","Institute of Psychology, Chinese Academy of Sciences"]},{name:"Yong He",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]}],authorString:"Miao Cao; Jinhui Wang; Zhengjia Dai; Xiaoyan Cao; Lili Jiang; Fengmei Fan; Xiaowei Song; Mingrui Xia; Ni Shu; Qi Dong; Michael P. Milham; F. Xavier Castellanos et al.",institutions:["Beijing HuiLongGuan Hospital","Beijing Normal University","Child Mind Institute","Chinese Academy of Sciences","Chinese Institute for Brain Research","Hangzhou Normal University","Institute of Biophysics","Institute of Psychology, Chinese Academy of Sciences","NYU Langone Health","Nathan Kline Institute for Psychiatric Research"],countries:["CN","US"],year:2013,journal:"Developmental Cognitive Neuroscience",citations:471,abstract:"Human brain function undergoes complex transformations across the lifespan. We employed resting-state functional MRI and graph-theory approaches to systematically chart the lifespan trajectory of the topological organization of human whole-brain functional networks in 126 healthy individuals ranging in age from 7 to 85 years. Brain networks were constructed by computing Pearson's correlations in blood-oxygenation-level-dependent temporal fluctuations among 1024 parcellation units followed by graph-based network analyses. We observed that the human brain functional connectome exhibited highly preserved non-random modular and rich club organization over the entire age range studied. Further quantitative analyses revealed linear decreases in modularity and inverted-U shaped trajectories of local efficiency and rich club architecture. Regionally heterogeneous age effects were mainly located in several hubs (e.g., default network, dorsal attention regions). Finally, we observed inverse trajectories of long- and short-distance functional connections, indicating that the reorganization of connectivity concentrates and distributes the brain's functional networks. Our results demonstrate topological changes in the whole-brain functional connectome across nearly the entire human lifespan, providing insights into the neural substrates underlying individual variations in behavior and cognition. These results have important implications for disease connectomics because they provide a baseline for evaluating network impairments in age-related neuropsychiatric disorders.",keywords:["Connectome","Connectomics","Human brain","Modularity","Neuroscience","Resting state fMRI","Functional specialization"],concepts:["Connectome","Connectomics","Human brain","Modularity (biology)","Neuroscience","Resting state fMRI","Functional specialization","Psychology"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"https://doi.org/10.1016/j.dcn.2013.11.004",is_oa:!0,n_refs:109,n_refs_in_core:27,degree:50,community:0,deg_w:894.5,betweenness:.0045,pagerank:.00656,eigenvector:.0764,pdf_file:null,pdf_downloaded:!1},{id:98,oaid:"W2114099272",doi:"10.3389/fnsys.2010.00022",title:"Network scaling effects in graph analytic studies of human resting-state fMRI data",authors:[{name:"Alex Fornito",institutions:["University of Cambridge"]}],authorString:"Alex Fornito",institutions:["University of Cambridge"],countries:["GB"],year:2010,journal:"Frontiers in Systems Neuroscience",citations:456,abstract:"Graph analysis has become an increasingly popular tool for characterizing topological properties of brain connectivity networks. Within this approach, the brain is modeled as a graph comprising N nodes connected by M edges. In functional magnetic resonance imaging (fMRI) studies, the nodes typically represent brain regions and the edges some measure of interaction between them. These nodes are commonly defined using a variety of regional parcellation templates, which can vary both in the volume sampled by each region, and the number of regions parcellated. Here, we sought to investigate how such variations in parcellation templates affect key graph analytic measures of functional brain organization using resting-state fMRI in 30 healthy volunteers. Seven different parcellation resolutions (84, 91, 230, 438, 890, 1314, and 4320 regions) were investigated. We found that gross inferences regarding network topology, such as whether the brain is small-world or scale-free, were robust to the template used, but that both absolute values of, and individual differences in, specific parameters such as path length, clustering, small-worldness, and degree distribution descriptors varied considerably across the resolutions studied. These findings underscore the need to consider the effect that a specific parcellation approach has on graph analytic findings in human fMRI studies, and indicate that results obtained using different templates may not be directly comparable.",keywords:["Resting state fMRI","Clustering coefficient","Graph","Functional magnetic resonance imaging","Power graph analysis","Pattern recognition","Human brain","Cluster analysis"],concepts:["Resting state fMRI","Clustering coefficient","Graph","Functional magnetic resonance imaging","Power graph analysis","Pattern recognition (psychology)","Human brain","Cluster analysis"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnsys.2010.00022/pdf",is_oa:!0,n_refs:94,n_refs_in_core:17,degree:51,community:1,deg_w:990.5,betweenness:.0039,pagerank:.00698,eigenvector:.1127,pdf_file:"Fornito_2010.pdf",pdf_downloaded:!0},{id:99,oaid:"W1999174202",doi:"10.1523/jneurosci.0440-11.2011",title:"Cognitive Effort Drives Workspace Configuration of Human Brain Functional Networks",authors:[{name:"Manfred G. Kitzbichler",institutions:["University of Cambridge"]},{name:"Richard N. Henson",institutions:["MRC Cognition and Brain Sciences Unit","Medical Research Council"]},{name:"Marie L. Smith",institutions:["MRC Cognition and Brain Sciences Unit","Medical Research Council"]},{name:"Pradeep J. Nathan",institutions:["GlaxoSmithKline (United Kingdom)"]},{name:"Edward T. Bullmore",institutions:["GlaxoSmithKline (United Kingdom)","University of Cambridge"]}],authorString:"Manfred G. Kitzbichler; Richard N. Henson; Marie L. Smith; Pradeep J. Nathan; Edward T. Bullmore",institutions:["GlaxoSmithKline (United Kingdom)","MRC Cognition and Brain Sciences Unit","Medical Research Council","University of Cambridge"],countries:["GB"],year:2011,journal:"Journal of Neuroscience",citations:452,abstract:"Effortful cognitive performance is theoretically expected to depend on the formation of a global neuronal workspace. We tested specific predictions of workspace theory, using graph theoretical measures of network topology and physical distance of synchronization, in magnetoencephalographic data recorded from healthy adult volunteers (N = 13) during performance of a working memory task at several levels of difficulty. We found that greater cognitive effort caused emergence of a more globally efficient, less clustered, and less modular network configuration, with more long-distance synchronization between brain regions. This pattern of task-related workspace configuration was more salient in the β-band (16-32 Hz) and γ-band (32-63 Hz) networks, compared with both lower (α-band; 8-16 Hz) and higher (high γ-band; 63-125 Hz) frequency intervals. Workspace configuration of β-band networks was also greater in faster performing participants (with correct response latency less than the sample median) compared with slower performing participants. Processes of workspace formation and relaxation in relation to time-varying demands for cognitive effort could be visualized occurring in the course of task trials lasting <2 s. These experimental results provide support for workspace theory in terms of complex network metrics and directly demonstrate how cognitive effort breaks modularity to make human brain functional networks transiently adopt a more efficient but less economical configuration.",keywords:["Workspace","Cognition","Task","Modularity","Modular design","Synchronization","Latency"],concepts:["Workspace","Cognition","Computer science","Task (project management)","Modularity (biology)","Modular design","Synchronization (alternating current)","Latency (audio)"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://www.jneurosci.org/content/jneuro/31/22/8259.full.pdf",is_oa:!0,n_refs:69,n_refs_in_core:13,degree:38,community:0,deg_w:524.5,betweenness:.0022,pagerank:.00425,eigenvector:.0448,pdf_file:"Kitzbichler_2011.pdf",pdf_downloaded:!0},{id:100,oaid:"W2150442066",doi:"10.1093/cercor/bhq268",title:"Association between Functional Connectivity Hubs and Brain Networks",authors:[{name:"Dardo Tomasi",institutions:["National Institute on Alcohol Abuse and Alcoholism"]},{name:"Nora D. Volkow",institutions:["National Institute on Drug Abuse","National Institute on Alcohol Abuse and Alcoholism"]}],authorString:"Dardo Tomasi; Nora D. Volkow",institutions:["National Institute on Alcohol Abuse and Alcoholism","National Institute on Drug Abuse"],countries:["US"],year:2011,journal:"Cerebral Cortex",citations:451,abstract:'Functional networks are usually accessed with "resting-state" functional magnetic resonance imaging using preselected "seeds" regions. Frequently, however, the selection of the seed locations is arbitrary. Recently, we proposed local functional connectivity density mapping (FCDM), an ultrafast data-driven to locate highly connected brain regions (functional hubs). Here, we used the functional hubs obtained from local FCDM to determine the functional networks of the resting state in 979 healthy subjects without a priori hypotheses on seed locations. In addition, we computed the global functional connectivity hubs. Seven networks covering 80% of the gray matter volume were identified. Four major cortical hubs (ventral precuneus/posterior cingulate, inferior parietal cortex, cuneus, and postcentral gyrus) were linked to 4 cortical networks (default mode, dorsal attention, visual, and somatosensory). Three subcortical networks were associated to the major subcortical hubs (cerebellum, thalamus, and amygdala). The networks differed in their resting activity and topology. The higher coupling and overlap of subcortical networks was associated to higher contribution of short-range functional connectivity in thalamus and cerebellum. Whereas cortical local FCD hubs were also hubs of long-range connectivity, which corroborates the key role of cortical hubs in network architecture, subcortical hubs had minimal long-range connectivity. The significant variability among functional networks may underlie their sensitivity/resilience to neuropathology.',keywords:["Precuneus","Neuroscience","Default mode network","Resting state fMRI","Functional magnetic resonance imaging","Cuneus","Thalamus","Functional connectivity"],concepts:["Precuneus","Neuroscience","Default mode network","Resting state fMRI","Functional magnetic resonance imaging","Cuneus","Thalamus","Functional connectivity"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://academic.oup.com/cercor/article-pdf/21/9/2003/17304982/bhq268.pdf",is_oa:!0,n_refs:67,n_refs_in_core:9,degree:30,community:2,deg_w:316,betweenness:.0023,pagerank:.00301,eigenvector:.0195,pdf_file:"Tomasi_2011.pdf",pdf_downloaded:!0},{id:101,oaid:"W2058765104",doi:"10.1371/journal.pcbi.1000808",title:"The Organization of Local and Distant Functional Connectivity in the Human Brain",authors:[{name:"Jorge Sepulcre",institutions:["Athinoula A. Martinos Center for Biomedical Imaging","Harvard University","Howard Hughes Medical Institute"]},{name:"Hesheng Liu",institutions:["Harvard University","Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Tanveer Talukdar",institutions:["Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Iñigo Martincorena",institutions:["European Bioinformatics Institute","University of Cambridge"]},{name:"B.T. Thomas Yeo",institutions:["Harvard University","Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Randy L. Buckner",institutions:["Howard Hughes Medical Institute","Massachusetts General Hospital","Harvard University","Athinoula A. Martinos Center for Biomedical Imaging"]}],authorString:"Jorge Sepulcre; Hesheng Liu; Tanveer Talukdar; Iñigo Martincorena; B.T. Thomas Yeo; Randy L. Buckner",institutions:["Athinoula A. Martinos Center for Biomedical Imaging","European Bioinformatics Institute","Harvard University","Howard Hughes Medical Institute","Massachusetts General Hospital","University of Cambridge"],countries:["GB","US"],year:2010,journal:"PLoS Computational Biology",citations:442,abstract:"Information processing in the human brain arises from both interactions between adjacent areas and from distant projections that form distributed brain systems. Here we map interactions across different spatial scales by estimating the degree of intrinsic functional connectivity for the local (<or=14 mm) neighborhood directly surrounding brain regions as contrasted with distant (>14 mm) interactions. The balance between local and distant functional interactions measured at rest forms a map that separates sensorimotor cortices from heteromodal association areas and further identifies regions that possess both high local and distant cortical-cortical interactions. Map estimates of network measures demonstrate that high local connectivity is most often associated with a high clustering coefficient, long path length, and low physical cost. Task performance changed the balance between local and distant functional coupling in a subset of regions, particularly, increasing local functional coupling in regions engaged by the task. The observed properties suggest that the brain has evolved a balance that optimizes information-processing efficiency across different classes of specialized areas as well as mechanisms to modulate coupling in support of dynamically changing processing demands. We discuss the implications of these observations and applications of the present method for exploring normal and atypical brain function.",keywords:["Functional connectivity","Neuroscience","Default mode network","Brain mapping","Balance","Human brain","Task"],concepts:["Functional connectivity","Neuroscience","Default mode network","Computer science","Brain mapping","Balance (ability)","Human brain","Task (project management)"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1000808&type=printable",is_oa:!0,n_refs:85,n_refs_in_core:12,degree:30,community:2,deg_w:391.5,betweenness:.0017,pagerank:.00336,eigenvector:.0347,pdf_file:"Sepulcre_2010.pdf",pdf_downloaded:!0},{id:102,oaid:"W1998071216",doi:"10.1371/journal.pcbi.1000748",title:"Efficient Physical Embedding of Topologically Complex Information Processing Networks in Brains and Computer Circuits",authors:[{name:"Danielle S. Bassett",institutions:["University of Cambridge","National Institute of Mental Health","University of California, Santa Barbara"]},{name:"Daniel L. Greenfield",institutions:["University of Cambridge"]},{name:"Andreas Meyer‐Lindenberg",institutions:["Central Institute of Mental Health"]},{name:"Daniel R. Weinberger",institutions:["National Institute of Mental Health"]},{name:"Simon W. Moore",institutions:["University of Cambridge"]},{name:"Edward T. Bullmore",institutions:["Cambridge School","University of Cambridge"]}],authorString:"Danielle S. Bassett; Daniel L. Greenfield; Andreas Meyer‐Lindenberg; Daniel R. Weinberger; Simon W. Moore; Edward T. Bullmore",institutions:["Cambridge School","Central Institute of Mental Health","National Institute of Mental Health","University of California, Santa Barbara","University of Cambridge"],countries:["DE","GB","PT","US"],year:2010,journal:"PLoS Computational Biology",citations:433,abstract:"Nervous systems are information processing networks that evolved by natural selection, whereas very large scale integrated (VLSI) computer circuits have evolved by commercially driven technology development. Here we follow historic intuition that all physical information processing systems will share key organizational properties, such as modularity, that generally confer adaptivity of function. It has long been observed that modular VLSI circuits demonstrate an isometric scaling relationship between the number of processing elements and the number of connections, known as Rent's rule, which is related to the dimensionality of the circuit's interconnect topology and its logical capacity. We show that human brain structural networks, and the nervous system of the nematode C. elegans, also obey Rent's rule, and exhibit some degree of hierarchical modularity. We further show that the estimated Rent exponent of human brain networks, derived from MRI data, can explain the allometric scaling relations between gray and white matter volumes across a wide range of mammalian species, again suggesting that these principles of nervous system design are highly conserved. For each of these fractal modular networks, the dimensionality of the interconnect topology was greater than the 2 or 3 Euclidean dimensions of the space in which it was embedded. This relatively high complexity entailed extra cost in physical wiring: although all networks were economically or cost-efficiently wired they did not strictly minimize wiring costs. Artificial and biological information processing systems both may evolve to optimize a trade-off between physical cost and topological complexity, resulting in the emergence of homologous principles of economical, fractal and modular design across many different kinds of nervous and computational networks.",keywords:["Modularity","Very-large-scale integration","Curse of dimensionality","Information processing","Modular design","Network topology","Theoretical computer science"],concepts:["Computer science","Modularity (biology)","Very-large-scale integration","Curse of dimensionality","Information processing","Modular design","Network topology","Theoretical computer science"],topics:["Genetics, Aging, and Longevity in Model Organisms","Neural dynamics and brain function","Plant and Biological Electrophysiology Studies"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1000748&type=printable",is_oa:!0,n_refs:85,n_refs_in_core:6,degree:45,community:0,deg_w:535,betweenness:.0051,pagerank:.00435,eigenvector:.0449,pdf_file:"Bassett_2010.pdf",pdf_downloaded:!0},{id:103,oaid:"W2057569161",doi:"10.1523/jneurosci.2128-13.2013",title:"An Anatomical Substrate for Integration among Functional Networks in Human Cortex",authors:[{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]}],authorString:"Martijn P. van den Heuvel; Olaf Sporns",institutions:["Indiana University Bloomington","University Medical Center Utrecht"],countries:["NL","US"],year:2013,journal:"Journal of Neuroscience",citations:428,abstract:`The human brain shows several characteristics of an efficient communication network architecture, including short communication paths and the existence of modules interlinked by a small set of highly connected regions. Studies of structural networks comprising macroscopic white matter projections have shown that these putative hubs are densely interconnected, giving rise to a spatially distributed and topologically central collective called the "rich club." In parallel, studies of intrinsic brain activity have consistently revealed distinct functional communities or resting-state networks (RSNs), indicative of specialized processing and segregation of neuronal information. However, the pattern of structural connectivity interconnecting these functional RSNs and how such inter-RSN structural connections might bring about functional integration between RSNs remain largely unknown. Combining high-resolution diffusion weighted imaging with resting-state fMRI, we present novel evidence suggesting that the rich club structure plays a central role in cross-linking macroscopic RSNs of the human brain. Rich club hub nodes were present in all functional networks, accounted for a large proportion of "connector nodes," and were found to coincide with regions in which multiple networks overlap. In addition, a large proportion of all inter-RSN connections were found to involve rich club nodes, and these connections participated in a disproportionate number of communication paths linking nodes in different RSNs. Our findings suggest that the brain's rich club serves as a macroscopic anatomical substrate to cross-link functional networks and thus plays an important role in the integration of information between segregated functional domains of the human cortex.`,keywords:["Neuroscience","Resting state fMRI","Human brain","Functional specialization","White matter","Nerve net","Cortex"],concepts:["Neuroscience","Resting state fMRI","Human brain","Functional specialization","White matter","Nerve net","Cortex (anatomy)","Computer science"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/33/36/14489.full.pdf",is_oa:!0,n_refs:70,n_refs_in_core:21,degree:55,community:0,deg_w:944,betweenness:.0062,pagerank:.0073,eigenvector:.0577,pdf_file:"Heuvel_2013_b.pdf",pdf_downloaded:!0},{id:104,oaid:"W2020617938",doi:"10.1371/journal.pone.0021976",title:"Graph Theoretical Analysis of Functional Brain Networks: Test-Retest Evaluation on Short- and Long-Term Resting-State Functional MRI Data",authors:[{name:"Jinhui Wang",institutions:["Beijing Normal University"]},{name:"Xi‐Nian Zuo",institutions:["Institute of Psychology, Chinese Academy of Sciences","NYU Langone Health"]},{name:"Suril Gohel",institutions:["University Hospital, Newark"]},{name:"Michael P. Milham",institutions:["NYU Langone Health"]},{name:"Bharat B. Biswal",institutions:["University Hospital, Newark"]},{name:"Yong He",institutions:["Beijing Normal University"]}],authorString:"Jinhui Wang; Xi‐Nian Zuo; Suril Gohel; Michael P. Milham; Bharat B. Biswal; Yong He",institutions:["Beijing Normal University","Institute of Psychology, Chinese Academy of Sciences","NYU Langone Health","University Hospital, Newark"],countries:["CN","US"],year:2011,journal:"PLoS ONE",citations:423,abstract:"Graph-based computational network analysis has proven a powerful tool to quantitatively characterize functional architectures of the brain. However, the test-retest (TRT) reliability of graph metrics of functional networks has not been systematically examined. Here, we investigated TRT reliability of topological metrics of functional brain networks derived from resting-state functional magnetic resonance imaging data. Specifically, we evaluated both short-term (<1 hour apart) and long-term (>5 months apart) TRT reliability for 12 global and 6 local nodal network metrics. We found that reliability of global network metrics was overall low, threshold-sensitive and dependent on several factors of scanning time interval (TI, long-term>short-term), network membership (NM, networks excluding negative correlations>networks including negative correlations) and network type (NT, binarized networks>weighted networks). The dependence was modulated by another factor of node definition (ND) strategy. The local nodal reliability exhibited large variability across nodal metrics and a spatially heterogeneous distribution. Nodal degree was the most reliable metric and varied the least across the factors above. Hub regions in association and limbic/paralimbic cortices showed moderate TRT reliability. Importantly, nodal reliability was robust to above-mentioned four factors. Simulation analysis revealed that global network metrics were extremely sensitive (but varying degrees) to noise in functional connectivity and weighted networks generated numerically more reliable results in compared with binarized networks. For nodal network metrics, they showed high resistance to noise in functional connectivity and no NT related differences were found in the resistance. These findings provide important implications on how to choose reliable analytical schemes and network metrics of interest.",keywords:["Reliability","Complex network","Network analysis","Node","Metrics","Resting state fMRI","Term"],concepts:["Reliability (semiconductor)","Computer science","Complex network","Network analysis","Node (physics)","Metrics","Resting state fMRI","Term (time)"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0021976&type=printable",is_oa:!0,n_refs:75,n_refs_in_core:24,degree:47,community:1,deg_w:870,betweenness:.0027,pagerank:.00623,eigenvector:.0964,pdf_file:"Wang_2011.pdf",pdf_downloaded:!0},{id:105,oaid:"W2133182819",doi:"10.1093/cercor/bhu095",title:"The Neonatal Connectome During Preterm Brain Development",authors:[{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht","Wilhelmina Children's Hospital","Hersenstichting"]},{name:"Karina J. Kersbergen",institutions:["University Medical Center Utrecht","Wilhelmina Children's Hospital"]},{name:"Marcel A. de Reus",institutions:["Hersenstichting","University Medical Center Utrecht","Wilhelmina Children's Hospital"]},{name:"Kristin Keunen",institutions:["Hersenstichting","Wilhelmina Children's Hospital","University Medical Center Utrecht"]},{name:"René S. Kahn",institutions:["Hersenstichting","Wilhelmina Children's Hospital","University Medical Center Utrecht"]},{name:"Floris Groenendaal",institutions:["University Medical Center Utrecht","Hersenstichting","Wilhelmina Children's Hospital"]},{name:"Linda S. de Vries",institutions:["Wilhelmina Children's Hospital","University Medical Center Utrecht","Hersenstichting"]},{name:"Manon J.N.L. Benders",institutions:["Wilhelmina Children's Hospital","Hersenstichting","University Medical Center Utrecht"]}],authorString:"Martijn P. van den Heuvel; Karina J. Kersbergen; Marcel A. de Reus; Kristin Keunen; René S. Kahn; Floris Groenendaal; Linda S. de Vries; Manon J.N.L. Benders",institutions:["Hersenstichting","University Medical Center Utrecht","Wilhelmina Children's Hospital"],countries:["NL"],year:2014,journal:"Cerebral Cortex",citations:412,abstract:"The human connectome is the result of an elaborate developmental trajectory. Acquiring diffusion-weighted imaging and resting-state fMRI, we studied connectome formation during the preterm phase of macroscopic connectome genesis. In total, 27 neonates were scanned at week 30 and/or week 40 gestational age (GA). Examining the architecture of the neonatal anatomical brain network revealed a clear presence of a small-world modular organization before term birth. Analysis of neonatal functional connectivity (FC) showed the early formation of resting-state networks, suggesting that functional networks are present in the preterm brain, albeit being in an immature state. Moreover, structural and FC patterns of the neonatal brain network showed strong overlap with connectome architecture of the adult brain (85 and 81%, respectively). Analysis of brain development between week 30 and week 40 GA revealed clear developmental effects in neonatal connectome architecture, including a significant increase in white matter microstructure (P < 0.01), small-world topology (P < 0.01) and interhemispheric FC (P < 0.01). Computational analysis further showed that developmental changes involved an increase in integration capacity of the connectivity network as a whole. Taken together, we conclude that hallmark organizational structures of the human connectome are present before term birth and subject to early development.",keywords:["Connectome","Neuroscience","White matter","Resting state fMRI","Connectomics","Brain development","Human Connectome Project","Diffusion MRI"],concepts:["Connectome","Neuroscience","White matter","Resting state fMRI","Connectomics","Brain development","Human Connectome Project","Diffusion MRI"],topics:["Functional Brain Connectivity Studies","Neonatal and fetal brain pathology","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://research.vumc.nl/en/publications/84c32e85-080f-4d78-8828-490800ef4319",is_oa:!0,n_refs:121,n_refs_in_core:27,degree:49,community:0,deg_w:869.5,betweenness:.0036,pagerank:.00656,eigenvector:.0657,pdf_file:"Heuvel_2014.pdf",pdf_downloaded:!0},{id:106,oaid:"W2117995966",doi:"10.1186/1471-2202-10-101",title:"Functional neural network analysis in frontotemporal dementia and Alzheimer's disease using EEG and graph theory",authors:[{name:"Willem de Haan",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Yolande A.L. Pijnenburg",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"R.L.M. Strijers",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Yolande van der Made",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Wiesje M. van der Flier",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Philip Scheltens",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]},{name:"Cornelis J. Stam",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"]}],authorString:"Willem de Haan; Yolande A.L. Pijnenburg; R.L.M. Strijers; Yolande van der Made; Wiesje M. van der Flier; Philip Scheltens; Cornelis J. Stam",institutions:["Amsterdam UMC Location Vrije Universiteit Amsterdam"],countries:["NL"],year:2009,journal:"BMC Neuroscience",citations:406,abstract:"BACKGROUND: Although a large body of knowledge about both brain structure and function has been gathered over the last decades, we still have a poor understanding of their exact relationship. Graph theory provides a method to study the relation between network structure and function, and its application to neuroscientific data is an emerging research field. We investigated topological changes in large-scale functional brain networks in patients with Alzheimer's disease (AD) and frontotemporal lobar degeneration (FTLD) by means of graph theoretical analysis of resting-state EEG recordings. EEGs of 20 patients with mild to moderate AD, 15 FTLD patients, and 23 non-demented individuals were recorded in an eyes-closed resting-state. The synchronization likelihood (SL), a measure of functional connectivity, was calculated for each sensor pair in 0.5-4 Hz, 4-8 Hz, 8-10 Hz, 10-13 Hz, 13-30 Hz and 30-45 Hz frequency bands. The resulting connectivity matrices were converted to unweighted graphs, whose structure was characterized with several measures: mean clustering coefficient (local connectivity), characteristic path length (global connectivity) and degree correlation (network 'assortativity'). All results were normalized for network size and compared with random control networks. RESULTS: In AD, the clustering coefficient decreased in the lower alpha and beta bands (p < 0.001), and the characteristic path length decreased in the lower alpha and gamma bands (p < 0.05) compared to controls. In FTLD no significant differences with controls were found in these measures. The degree correlation decreased in both alpha bands in AD compared to controls (p < 0.05), but increased in the FTLD lower alpha band compared with controls (p < 0.01). CONCLUSION: With decreasing local and global connectivity parameters, the large-scale functional brain network organization in AD deviates from the optimal 'small-world' network structure towards a more 'random' type. This is associated with less efficient information exchange between brain areas, supporting the disconnection hypothesis of AD. Surprisingly, FTLD patients show changes in the opposite direction, towards a (perhaps excessively) more 'ordered' network structure, possibly reflecting a different underlying pathophysiological process.",keywords:["Assortativity","Clustering coefficient","Resting state fMRI","Dementia","Electroencephalography","Frontotemporal lobar degeneration","Graph theory","Neuroscience"],concepts:["Assortativity","Clustering coefficient","Resting state fMRI","Dementia","Electroencephalography","Frontotemporal lobar degeneration","Graph theory","Neuroscience"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://bmcneurosci.biomedcentral.com/counter/pdf/10.1186/1471-2202-10-101",is_oa:!0,n_refs:46,n_refs_in_core:9,degree:31,community:1,deg_w:379.5,betweenness:.0017,pagerank:.00319,eigenvector:.0404,pdf_file:"Haan_2009.pdf",pdf_downloaded:!0},{id:107,oaid:"W2022381144",doi:"10.1371/journal.pcbi.1002582",title:"Activity Dependent Degeneration Explains Hub Vulnerability in Alzheimer's Disease",authors:[{name:"Willem de Haan",institutions:["Amsterdam UMC Location VUmc"]},{name:"Katherine K. Mott",institutions:["Amsterdam UMC Location VUmc"]},{name:"Elisabeth C.W. van Straaten",institutions:["Amsterdam UMC Location VUmc"]},{name:"Philip Scheltens",institutions:["Amsterdam UMC Location VUmc"]},{name:"Cornelis J. Stam",institutions:["Amsterdam UMC Location VUmc"]}],authorString:"Willem de Haan; Katherine K. Mott; Elisabeth C.W. van Straaten; Philip Scheltens; Cornelis J. Stam",institutions:["Amsterdam UMC Location VUmc"],countries:["NL"],year:2012,journal:"PLoS Computational Biology",citations:405,abstract:"Brain connectivity studies have revealed that highly connected 'hub' regions are particularly vulnerable to Alzheimer pathology: they show marked amyloid-β deposition at an early stage. Recently, excessive local neuronal activity has been shown to increase amyloid deposition. In this study we use a computational model to test the hypothesis that hub regions possess the highest level of activity and that hub vulnerability in Alzheimer's disease is due to this feature. Cortical brain regions were modeled as neural masses, each describing the average activity (spike density and spectral power) of a large number of interconnected excitatory and inhibitory neurons. The large-scale network consisted of 78 neural masses, connected according to a human DTI-based cortical topology. Spike density and spectral power were positively correlated with structural and functional node degrees, confirming the high activity of hub regions, also offering a possible explanation for high resting state Default Mode Network activity. 'Activity dependent degeneration' (ADD) was simulated by lowering synaptic strength as a function of the spike density of the main excitatory neurons, and compared to random degeneration. Resulting structural and functional network changes were assessed with graph theoretical analysis. Effects of ADD included oscillatory slowing, loss of spectral power and long-range synchronization, hub vulnerability, and disrupted functional network topology. Observed transient increases in spike density and functional connectivity match reports in Mild Cognitive Impairment (MCI) patients, and may not be compensatory but pathological. In conclusion, the assumption of excessive neuronal activity leading to degeneration provides a possible explanation for hub vulnerability in Alzheimer's disease, supported by the observed relation between connectivity and activity and the reproduction of several neurophysiologic hallmarks. The insight that neuronal activity might play a causal role in Alzheimer's disease can have implications for early detection and interventional strategies.",keywords:["Neuroscience","Excitatory postsynaptic potential","Default mode network","Degeneration","Alzheimer's disease","Cognition","Topology"],concepts:["Neuroscience","Excitatory postsynaptic potential","Default mode network","Degeneration (medical)","Alzheimer's disease","Cognition","Topology (electrical circuits)","Computer science"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1002582&type=printable",is_oa:!0,n_refs:88,n_refs_in_core:16,degree:35,community:1,deg_w:337.5,betweenness:.0037,pagerank:.00309,eigenvector:.0249,pdf_file:"Haan_2012.pdf",pdf_downloaded:!0},{id:108,oaid:"W2962725064",doi:"10.1371/journal.pcbi.1003171",title:"Task-Based Core-Periphery Organization of Human Brain Dynamics",authors:[{name:"Danielle S. Bassett",institutions:["University of California, Santa Barbara"]},{name:"Nicholas F. Wymbs",institutions:["Imaging Center","University of California, Santa Barbara"]},{name:"M. Puck Rombach",institutions:["Oxford Applied Research (United Kingdom)","University of Oxford"]},{name:"Mason A. Porter",institutions:["University of Oxford","Oxford Applied Research (United Kingdom)"]},{name:"Peter J. Mucha",institutions:[]},{name:"Scott T. Grafton",institutions:["Imaging Center","University of California, Santa Barbara"]}],authorString:"Danielle S. Bassett; Nicholas F. Wymbs; M. Puck Rombach; Mason A. Porter; Peter J. Mucha; Scott T. Grafton",institutions:["Imaging Center","Oxford Applied Research (United Kingdom)","University of California, Santa Barbara","University of Oxford"],countries:["GB","US"],year:2013,journal:"PLoS Computational Biology",citations:381,abstract:"As a person learns a new skill, distinct synapses, brain regions, and circuits are engaged and change over time. In this paper, we develop methods to examine patterns of correlated activity across a large set of brain regions. Our goal is to identify properties that enable robust learning of a motor skill. We measure brain activity during motor sequencing and characterize network properties based on coherent activity between brain regions. Using recently developed algorithms to detect time-evolving communities, we find that the complex reconfiguration patterns of the brain's putative functional modules that control learning can be described parsimoniously by the combined presence of a relatively stiff temporal core that is composed primarily of sensorimotor and visual regions whose connectivity changes little in time and a flexible temporal periphery that is composed primarily of multimodal association regions whose connectivity changes frequently. The separation between temporal core and periphery changes over the course of training and, importantly, is a good predictor of individual differences in learning success. The core of dynamically stiff regions exhibits dense connectivity, which is consistent with notions of core-periphery organization established previously in social networks. Our results demonstrate that core-periphery organization provides an insightful way to understand how putative functional modules are linked. This, in turn, enables the prediction of fundamental human capacities, including the production of complex goal-directed behavior.",keywords:["Set","Core","Task","Control reconfiguration","Neuroscience","Association"],concepts:["Set (abstract data type)","Core (optical fiber)","Task (project management)","Computer science","Control reconfiguration","Neuroscience","Association (psychology)","Artificial intelligence"],topics:["Neural dynamics and brain function","Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1003171&type=printable",is_oa:!0,n_refs:129,n_refs_in_core:13,degree:35,community:0,deg_w:518.5,betweenness:.0028,pagerank:.0043,eigenvector:.0381,pdf_file:"Bassett_2013.pdf",pdf_downloaded:!0},{id:109,oaid:"W1989523430",doi:"10.1073/pnas.1324118111",title:"Rich-club organization of the newborn human brain",authors:[{name:"Gareth Ball",institutions:["St Thomas' Hospital","King's College London","Kings Health Partners"]},{name:"Paul Aljabar",institutions:["St Thomas' Hospital","King's College London","Kings Health Partners"]},{name:"Sally Zebari",institutions:["St Thomas' Hospital","King's College London","Kings Health Partners"]},{name:"Nora Tusor",institutions:["St Thomas' Hospital","King's College London","Kings Health Partners"]},{name:"Tomoki Arichi",institutions:["St Thomas' Hospital","King's College London","Kings Health Partners"]},{name:"Nazakat Merchant",institutions:["St Thomas' Hospital","King's College London","Kings Health Partners"]},{name:"Emma C. Robinson",institutions:["University of Oxford","Wellcome Centre for Integrative Neuroimaging"]},{name:"Enitan Ogundipe",institutions:["Chelsea and Westminster Hospital","Imperial College London"]},{name:"Daniel Rueckert",institutions:["Institute of Group Analysis","Imperial College London"]},{name:"A. David Edwards",institutions:["St Thomas' Hospital","King's College London","Kings Health Partners"]},{name:"Serena J. Counsell",institutions:["St Thomas' Hospital","King's College London","Kings Health Partners"]}],authorString:"Gareth Ball; Paul Aljabar; Sally Zebari; Nora Tusor; Tomoki Arichi; Nazakat Merchant; Emma C. Robinson; Enitan Ogundipe; Daniel Rueckert; A. David Edwards; Serena J. Counsell",institutions:["Chelsea and Westminster Hospital","Imperial College London","Institute of Group Analysis","King's College London","Kings Health Partners","St Thomas' Hospital","University of Oxford","Wellcome Centre for Integrative Neuroimaging"],countries:["GB"],year:2014,journal:"Proceedings of the National Academy of Sciences",citations:374,abstract:'Combining diffusion magnetic resonance imaging and network analysis in the adult human brain has identified a set of highly connected cortical hubs that form a "rich club"--a high-cost, high-capacity backbone thought to enable efficient network communication. Rich-club architecture appears to be a persistent feature of the mature mammalian brain, but it is not known when this structure emerges during human development. In this longitudinal study we chart the emergence of structural organization in mid to late gestation. We demonstrate that a rich club of interconnected cortical hubs is already present by 30 wk gestation. Subsequently, until the time of normal birth, the principal development is a proliferation of connections between core hubs and the rest of the brain. We also consider the impact of environmental factors on early network development, and compare term-born neonates to preterm infants at term-equivalent age. Though rich-club organization remains intact following premature birth, we reveal significant disruptions in both in cortical-subcortical connectivity and short-distance corticocortical connections. Rich club organization is present well before the normal time of birth and may provide the fundamental structural architecture for the subsequent emergence of complex neurological functions. Premature exposure to the extrauterine environment is associated with altered network architecture and reduced network capacity, which may in part account for the high prevalence of cognitive problems in preterm infants.',keywords:["Club","Neuroscience","Human brain","Cognition","Anatomy"],concepts:["Club","Neuroscience","Human brain","Cognition","Biology","Psychology"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Neonatal and fetal brain pathology"],pdf_url:"https://www.pnas.org/content/pnas/111/20/7456.full.pdf",is_oa:!0,n_refs:72,n_refs_in_core:13,degree:37,community:0,deg_w:448.5,betweenness:.0028,pagerank:.00392,eigenvector:.0263,pdf_file:"Ball_2014.pdf",pdf_downloaded:!0},{id:110,oaid:"W2008781224",doi:"10.1371/journal.pone.0040709",title:"GAT: A Graph-Theoretical Analysis Toolbox for Analyzing Between-Group Differences in Large-Scale Structural and Functional Brain Networks",authors:[{name:"S. M. Hadi Hosseini",institutions:["Stanford Medicine","Stanford University"]},{name:"Fumiko Hoeft",institutions:["University of California, San Francisco","Stanford University"]},{name:"Shelli R. Kesler",institutions:["Stanford University"]}],authorString:"S. M. Hadi Hosseini; Fumiko Hoeft; Shelli R. Kesler",institutions:["Stanford Medicine","Stanford University","University of California, San Francisco"],countries:["US"],year:2012,journal:"PLoS ONE",citations:370,abstract:"In recent years, graph theoretical analyses of neuroimaging data have increased our understanding of the organization of large-scale structural and functional brain networks. However, tools for pipeline application of graph theory for analyzing topology of brain networks is still lacking. In this report, we describe the development of a graph-analysis toolbox (GAT) that facilitates analysis and comparison of structural and functional network brain networks. GAT provides a graphical user interface (GUI) that facilitates construction and analysis of brain networks, comparison of regional and global topological properties between networks, analysis of network hub and modules, and analysis of resilience of the networks to random failure and targeted attacks. Area under a curve (AUC) and functional data analyses (FDA), in conjunction with permutation testing, is employed for testing the differences in network topologies; analyses that are less sensitive to the thresholding process. We demonstrated the capabilities of GAT by investigating the differences in the organization of regional gray-matter correlation networks in survivors of acute lymphoblastic leukemia (ALL) and healthy matched Controls (CON). The results revealed an alteration in small-world characteristics of the brain networks in the ALL survivors; an observation that confirm our hypothesis suggesting widespread neurobiological injury in ALL survivors. Along with demonstration of the capabilities of the GAT, this is the first report of altered large-scale structural brain networks in ALL survivors.",keywords:["Network topology","Network analysis","Power graph analysis","Graph theory","Toolbox","Topological data analysis","Complex network"],concepts:["Network topology","Computer science","Network analysis","Power graph analysis","Graph theory","Toolbox","Topological data analysis","Complex network"],topics:["Functional Brain Connectivity Studies","Health, Environment, Cognitive Aging","Cancer-related cognitive impairment studies"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0040709&type=printable",is_oa:!0,n_refs:98,n_refs_in_core:22,degree:40,community:1,deg_w:709,betweenness:.0015,pagerank:.00516,eigenvector:.082,pdf_file:"Hosseini_2012.pdf",pdf_downloaded:!0},{id:111,oaid:"W2150371779",doi:"10.3389/neuro.11.001.2010",title:"Cortical hubs form a module for multisensory integration on top of the hierarchy of cortical networks",authors:[{name:"Gorka Zamora‐López",institutions:["University of Potsdam"]}],authorString:"Gorka Zamora‐López",institutions:["University of Potsdam"],countries:["DE"],year:2010,journal:"Frontiers in Neuroinformatics",citations:354,abstract:"Sensory stimuli entering the nervous system follow particular paths of processing, typically separated (segregated) from the paths of other modal information. However, sensory perception, awareness and cognition emerge from the combination of information (integration). The corticocortical networks of cats and macaque monkeys display three prominent characteristics: (i) modular organisation (facilitating the segregation), (ii) abundant alternative processing paths and (iii) the presence of highly connected hubs. Here, we study in detail the organisation and potential function of the cortical hubs by graph analysis and information theoretical methods. We find that the cortical hubs form a spatially delocalised, but topologically central module with the capacity to integrate multisensory information in a collaborative manner. With this, we resolve the underlying anatomical substrate that supports the simultaneous capacity of the cortex to segregate and to integrate multisensory information.",keywords:["Sensory system","Macaque","Multisensory integration","Modular design","Neuroscience","Hierarchy","Perception"],concepts:["Sensory system","Macaque","Computer science","Multisensory integration","Modular design","Neuroscience","Hierarchy","Perception"],topics:["Neural dynamics and brain function","Functional Brain Connectivity Studies","Visual perception and processing mechanisms"],pdf_url:"https://www.frontiersin.org/articles/10.3389/neuro.11.001.2010/pdf",is_oa:!0,n_refs:75,n_refs_in_core:3,degree:41,community:0,deg_w:468,betweenness:.0031,pagerank:.00393,eigenvector:.0374,pdf_file:"ZamoraLpez_2010.pdf",pdf_downloaded:!0},{id:112,oaid:"W2031594486",doi:"10.3389/fnsys.2010.00021",title:"Typical and atypical development of functional human brain networks: insights from resting-state fMRI",authors:[{name:"Lucina Q. Uddin",institutions:["Stanford University"]}],authorString:"Lucina Q. Uddin",institutions:["Stanford University"],countries:["US"],year:2010,journal:"Frontiers in Systems Neuroscience",citations:351,abstract:"Over the past several decades, structural MRI studies have provided remarkable insights into human brain development by revealing the trajectory of gray and white matter maturation from childhood to adolescence and adulthood. In parallel, functional MRI studies have demonstrated changes in brain activation patterns accompanying cognitive development. Despite these advances, studying the maturation of functional brain networks underlying brain development continues to present unique scientific and methodological challenges. Resting-state fMRI (rsfMRI) has emerged as a novel method for investigating the development of large-scale functional brain networks in infants and young children. We review existing rsfMRI developmental studies and discuss how this method has begun to make significant contributions to our understanding of maturing brain organization. In particular, rsfMRI has been used to complement studies in other modalities investigating the emergence of functional segregation and integration across short and long-range connections spanning the entire brain. We show that rsfMRI studies help to clarify and reveal important principles of functional brain development, including a shift from diffuse to focal activation patterns, and simultaneous pruning of local connectivity and strengthening of long-range connectivity with age. The insights gained from these studies also shed light on potentially disrupted functional networks underlying atypical cognitive development associated with neurodevelopmental disorders. We conclude by identifying critical gaps in the current literature, discussing methodological issues, and suggesting avenues for future research.",keywords:["Resting state fMRI","Neuroscience","Synaptic pruning","Human brain","Cognition","Functional connectivity","Brain development"],concepts:["Resting state fMRI","Neuroscience","Synaptic pruning","Human brain","Cognition","Psychology","Functional connectivity","Brain development"],topics:["Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications","Neural dynamics and brain function"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnsys.2010.00021/pdf",is_oa:!0,n_refs:110,n_refs_in_core:9,degree:28,community:2,deg_w:490.5,betweenness:.0012,pagerank:.00421,eigenvector:.0318,pdf_file:"Uddin_2010.pdf",pdf_downloaded:!0},{id:113,oaid:"W2015334431",doi:"10.1523/jneurosci.3784-12.2013",title:"The Rich Club of the<i>C. elegans</i>Neuronal Connectome",authors:[{name:"Emma K. Towlson",institutions:["University of Cambridge"]},{name:"Petra E. Vértes",institutions:["University of Cambridge"]},{name:"Sebastian E. Ahnert",institutions:["University of Cambridge"]},{name:"William R Schafer",institutions:["MRC Laboratory of Molecular Biology","Medical Research Council"]},{name:"Edward T. Bullmore",institutions:["National Health Service","GlaxoSmithKline (United Kingdom)","University of Cambridge","Cambridgeshire and Peterborough NHS Foundation Trust","Addenbrooke's Hospital"]}],authorString:"Emma K. Towlson; Petra E. Vértes; Sebastian E. Ahnert; William R Schafer; Edward T. Bullmore",institutions:["Addenbrooke's Hospital","Cambridgeshire and Peterborough NHS Foundation Trust","GlaxoSmithKline (United Kingdom)","MRC Laboratory of Molecular Biology","Medical Research Council","National Health Service","University of Cambridge"],countries:["GB"],year:2013,journal:"Journal of Neuroscience",citations:350,abstract:"There is increasing interest in topological analysis of brain networks as complex systems, with researchers often using neuroimaging to represent the large-scale organization of nervous systems without precise cellular resolution. Here we used graph theory to investigate the neuronal connectome of the nematode worm Caenorhabditis elegans, which is defined anatomically at a cellular scale as 2287 synaptic connections between 279 neurons. We identified a small number of highly connected neurons as a rich club (N = 11) interconnected with high efficiency and high connection distance. Rich club neurons comprise almost exclusively the interneurons of the locomotor circuits, with known functional importance for coordinated movement. The rich club neurons are connector hubs, with high betweenness centrality, and many intermodular connections to nodes in different modules. On identifying the shortest topological paths (motifs) between pairs of peripheral neurons, the motifs that are found most frequently traverse the rich club. The rich club neurons are born early in development, before visible movement of the animal and before the main phase of developmental elongation of its body. We conclude that the high wiring cost of the globally integrative rich club of neurons in the C. elegans connectome is justified by the adaptive value of coordinated movement of the animal. The economical trade-off between physical cost and behavioral value of rich club organization in a cellular connectome confirms theoretical expectations and recapitulates comparable results from human neuroimaging on much larger scale networks, suggesting that this may be a general and scale-invariant principle of brain network organization.",keywords:["Connectome","Neuroscience","Betweenness centrality","Biological neural network","Interneuron","Centrality"],concepts:["Connectome","Neuroscience","Betweenness centrality","Biological neural network","Biology","Interneuron","Computer science","Centrality"],topics:["Genetics, Aging, and Longevity in Model Organisms","Functional Brain Connectivity Studies","Biofield Effects and Biophysics"],pdf_url:"https://www.jneurosci.org/content/jneuro/33/15/6380.full.pdf",is_oa:!0,n_refs:45,n_refs_in_core:11,degree:50,community:0,deg_w:625,betweenness:.005,pagerank:.00514,eigenvector:.0375,pdf_file:"Towlson_2013.pdf",pdf_downloaded:!0},{id:114,oaid:"W1997491128",doi:"10.1523/jneurosci.2964-08.2008",title:"Microstructural Organization of the Cingulum Tract and the Level of Default Mode Functional Connectivity",authors:[{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]},{name:"René C.W. Mandl",institutions:["Utrecht University","University Medical Center Utrecht"]},{name:"Judith Luigjes",institutions:["Utrecht University","University Medical Center Utrecht"]},{name:"Hilleke E. Hulshoff Pol",institutions:["Utrecht University","University Medical Center Utrecht"]}],authorString:"Martijn P. van den Heuvel; René C.W. Mandl; Judith Luigjes; Hilleke E. Hulshoff Pol",institutions:["University Medical Center Utrecht","Utrecht University"],countries:["NL"],year:2008,journal:"Journal of Neuroscience",citations:350,abstract:"The default mode network is a functionally connected network of brain regions that show highly synchronized intrinsic neuronal activation during rest. However, less is known about the structural connections of this network, which could play an important role in the observed functional connectivity patterns. In this study, we examined the microstructural organization of the cingulum tract in relation to the level of resting-state default mode functional synchronization. Resting-state functional magnetic resonance imaging and diffusion tensor imaging data of 45 healthy subjects were acquired on a 3 tesla scanner. Both structural and functional connectivity of the default mode network were examined. In all subjects, the cingulum tract was identified from the total collection of reconstructed tracts to interconnect the precuneus/posterior cingulate cortex and medial frontal cortex, key regions of the default mode network. A significant positive correlation was found between the average fractional anisotropy value of the cingulum tract and the level of functional connectivity between the precuneus/posterior cingulate cortex and medial frontal cortex. Our results suggest a direct relationship between the structural and functional connectivity measures of the default mode network and contribute to the understanding of default mode network connectivity.",keywords:["Default mode network","Cingulum","Precuneus","Posterior cingulate","Neuroscience","Functional magnetic resonance imaging","Fractional anisotropy","Resting state fMRI"],concepts:["Default mode network","Cingulum (brain)","Precuneus","Posterior cingulate","Neuroscience","Functional magnetic resonance imaging","Fractional anisotropy","Resting state fMRI"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/28/43/10844.full.pdf",is_oa:!0,n_refs:64,n_refs_in_core:8,degree:32,community:2,deg_w:404.5,betweenness:.0028,pagerank:.00363,eigenvector:.0277,pdf_file:"Heuvel_2008.pdf",pdf_downloaded:!0},{id:115,oaid:"W2182367256",doi:"10.1016/j.neuroimage.2015.09.041",title:"Generative models of the human connectome",authors:[{name:"Richard F. Betzel",institutions:["Indiana University Bloomington"]},{name:"Andrea Avena‐Koenigsberger",institutions:["Indiana University Bloomington"]},{name:"Joaquín Goñi",institutions:["Indiana University Bloomington"]},{name:"Ye He",institutions:["Chinese Academy of Sciences","Institute of Psychology, Chinese Academy of Sciences"]},{name:"Marcel A. de Reus",institutions:["University Medical Center Utrecht"]},{name:"Alessandra Griffa",institutions:["École Polytechnique Fédérale de Lausanne","University of Lausanne"]},{name:"Petra E. Vértes",institutions:["University of Cambridge"]},{name:"Bratislav Mišić",institutions:["Indiana University Bloomington"]},{name:"Jean‐Philippe Thiran",institutions:["École Polytechnique Fédérale de Lausanne","University of Lausanne"]},{name:"Patric Hagmann",institutions:["University of Lausanne","École Polytechnique Fédérale de Lausanne"]},{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]},{name:"Xi-Nian Zuo",institutions:["Chinese Academy of Sciences","Institute of Psychology, Chinese Academy of Sciences"]},{name:"Edward T. Bullmore",institutions:["University of Cambridge"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]}],authorString:"Richard F. Betzel; Andrea Avena‐Koenigsberger; Joaquín Goñi; Ye He; Marcel A. de Reus; Alessandra Griffa; Petra E. Vértes; Bratislav Mišić; Jean‐Philippe Thiran; Patric Hagmann; Martijn P. van den Heuvel; Xi-Nian Zuo et al.",institutions:["Chinese Academy of Sciences","Indiana University Bloomington","Institute of Psychology, Chinese Academy of Sciences","University Medical Center Utrecht","University of Cambridge","University of Lausanne","École Polytechnique Fédérale de Lausanne"],countries:["CH","CN","GB","NL","US"],year:2015,journal:"NeuroImage",citations:344,abstract:"The human connectome represents a network map of the brain's wiring diagram and the pattern into which its connections are organized is thought to play an important role in cognitive function. The generative rules that shape the topology of the human connectome remain incompletely understood. Earlier work in model organisms has suggested that wiring rules based on geometric relationships (distance) can account for many but likely not all topological features. Here we systematically explore a family of generative models of the human connectome that yield synthetic networks designed according to different wiring rules combining geometric and a broad range of topological factors. We find that a combination of geometric constraints with a homophilic attachment mechanism can create synthetic networks that closely match many topological characteristics of individual human connectomes, including features that were not included in the optimization of the generative model itself. We use these models to investigate a lifespan dataset and show that, with age, the model parameters undergo progressive changes, suggesting a rebalancing of the generative factors underlying the connectome across the lifespan.",keywords:["Connectome","Generative grammar","Human Connectome Project","Generative model","Topology","Function"],concepts:["Connectome","Generative grammar","Human Connectome Project","Generative model","Computer science","Topology (electrical circuits)","Function (biology)","Artificial intelligence"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Complex Network Analysis Techniques"],pdf_url:"https://doi.org/10.1016/j.neuroimage.2015.09.041",is_oa:!0,n_refs:83,n_refs_in_core:8,degree:34,community:0,deg_w:482,betweenness:.0023,pagerank:.00423,eigenvector:.0209,pdf_file:"Betzel_2015.pdf",pdf_downloaded:!0},{id:116,oaid:"W2504084072",doi:"10.1093/brain/aww194",title:"Brain networks under attack: robustness properties and the impact of lesions",authors:[{name:"Hannelore Aerts",institutions:["Ghent University"]},{name:"Wim Fias",institutions:["Ghent University"]},{name:"Karen Caeyenberghs",institutions:["Australian Catholic University"]},{name:"Daniele Marinazzo",institutions:["Ghent University"]}],authorString:"Hannelore Aerts; Wim Fias; Karen Caeyenberghs; Daniele Marinazzo",institutions:["Australian Catholic University","Ghent University"],countries:["AU","BE"],year:2016,journal:"Brain",citations:331,abstract:"A growing number of studies approach the brain as a complex network, the so-called 'connectome'. Adopting this framework, we examine what types or extent of damage the brain can withstand-referred to as network 'robustness'-and conversely, which kind of distortions can be expected after brain lesions. To this end, we review computational lesion studies and empirical studies investigating network alterations in brain tumour, stroke and traumatic brain injury patients. Common to these three types of focal injury is that there is no unequivocal relationship between the anatomical lesion site and its topological characteristics within the brain network. Furthermore, large-scale network effects of these focal lesions are compared to those of a widely studied multifocal neurodegenerative disorder, Alzheimer's disease, in which central parts of the connectome are preferentially affected. Results indicate that human brain networks are remarkably resilient to different types of lesions, compared to other types of complex networks such as random or scale-free networks. However, lesion effects have been found to depend critically on the topological position of the lesion. In particular, damage to network hub regions-and especially those connecting different subnetworks-was found to cause the largest disturbances in network organization. Regardless of lesion location, evidence from empirical and computational lesion studies shows that lesions cause significant alterations in global network topology. The direction of these changes though remains to be elucidated. Encouragingly, both empirical and modelling studies have indicated that after focal damage, the connectome carries the potential to recover at least to some extent, with normalization of graph metrics being related to improved behavioural and cognitive functioning. To conclude, we highlight possible clinical implications of these findings, point out several methodological limitations that pertain to the study of brain diseases adopting a network approach, and provide suggestions for future research.",keywords:["Lesion","Connectome","Neuroscience","Network topology","Robustness","Brain damage","Disease","Medicine"],concepts:["Lesion","Connectome","Neuroscience","Network topology","Robustness (evolution)","Brain damage","Disease","Medicine"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"https://academic.oup.com/brain/article-pdf/139/12/3063/11155564/aww194.pdf",is_oa:!0,n_refs:143,n_refs_in_core:16,degree:32,community:1,deg_w:440.5,betweenness:.0018,pagerank:.00367,eigenvector:.0394,pdf_file:null,pdf_downloaded:!1},{id:117,oaid:"W2341654072",doi:"10.1093/cercor/bhw089",title:"Network-Level Structure-Function Relationships in Human Neocortex",authors:[{name:"Bratislav Mišić",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Richard F. Betzel",institutions:["University of Pennsylvania"]},{name:"Marcel A. de Reus",institutions:["University Medical Center Utrecht"]},{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]},{name:"Marc G. Berman",institutions:["University of Chicago"]},{name:"Anthony R. McIntosh",institutions:["Baycrest Hospital","Rotman Research Institute"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]}],authorString:"Bratislav Mišić; Richard F. Betzel; Marcel A. de Reus; Martijn P. van den Heuvel; Marc G. Berman; Anthony R. McIntosh; Olaf Sporns",institutions:["Baycrest Hospital","Indiana University Bloomington","McGill University","Montreal Neurological Institute and Hospital","Rotman Research Institute","University Medical Center Utrecht","University of Chicago","University of Pennsylvania"],countries:["CA","NL","US"],year:2016,journal:"Cerebral Cortex",citations:331,abstract:"The dynamics of spontaneous fluctuations in neural activity are shaped by underlying patterns of anatomical connectivity. While numerous studies have demonstrated edge-wise correspondence between structural and functional connections, much less is known about how large-scale coherent functional network patterns emerge from the topology of structural networks. In the present study, we deploy a multivariate statistical technique, partial least squares, to investigate the association between spatially extended structural networks and functional networks. We find multiple statistically robust patterns, reflecting reliable combinations of structural and functional subnetworks that are optimally associated with one another. Importantly, these patterns generally do not show a one-to-one correspondence between structural and functional edges, but are instead distributed and heterogeneous, with many functional relationships arising from nonoverlapping sets of anatomical connections. We also find that structural connections between high-degree hubs are disproportionately represented, suggesting that these connections are particularly important in establishing coherent functional networks. Altogether, these results demonstrate that the network organization of the cerebral cortex supports the emergence of diverse functional network configurations that often diverge from the underlying anatomical substrate.",keywords:["Neocortex","Association","Function","Functional connectivity","Functional diversity","Complex network","Neuroscience"],concepts:["Neocortex","Computer science","Association (psychology)","Function (biology)","Functional connectivity","Functional diversity","Complex network","Neuroscience"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"https://academic.oup.com/cercor/article-pdf/26/7/3285/6711665/bhw089.pdf",is_oa:!0,n_refs:92,n_refs_in_core:14,degree:32,community:0,deg_w:503,betweenness:.002,pagerank:.00422,eigenvector:.0327,pdf_file:"Mii_2016.pdf",pdf_downloaded:!0},{id:118,oaid:"W1984988256",doi:"10.1371/journal.pone.0046497",title:"Rich Club Organization of Macaque Cerebral Cortex and Its Role in Network Communication",authors:[{name:"Logan Harriger",institutions:["Indiana University Bloomington"]},{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]}],authorString:"Logan Harriger; Martijn P. van den Heuvel; Olaf Sporns",institutions:["Indiana University Bloomington","University Medical Center Utrecht"],countries:["NL","US"],year:2012,journal:"PLoS ONE",citations:328,abstract:"Graph-theoretical analysis of brain connectivity data has revealed significant features of brain network organization across a range of species. Consistently, large-scale anatomical networks exhibit highly nonrandom attributes including an efficient small world modular architecture, with distinct network communities that are interlinked by hub regions. The functional importance of hubs motivates a closer examination of their mutual interconnections, specifically to examine the hypothesis that hub regions are more densely linked than expected based on their degree alone, i.e. forming a central rich club. Extending recent findings of rich club topology in the cat and human brain, this report presents evidence for the existence of rich club organization in the cerebral cortex of a non-human primate, the macaque monkey, based on a connectivity data set representing a collation of numerous tract tracing studies. Rich club regions comprise portions of prefrontal, parietal, temporal and insular cortex and are widely distributed across network communities. An analysis of network motifs reveals that rich club regions tend to form star-like configurations, indicative of their central embedding within sets of nodes. In addition, rich club nodes and edges participate in a large number of short paths across the network, and thus contribute disproportionately to global communication. As rich club regions tend to attract and disperse communication paths, many of the paths follow a characteristic pattern of first increasing and then decreasing node degree. Finally, the existence of non-reciprocal projections imposes a net directional flow of paths into and out of the rich club, with some regions preferentially attracting and others dispersing signals. Overall, the demonstration of rich club organization in a non-human primate contributes to our understanding of the network principles underlying neural connectivity in the mammalian brain, and further supports the hypothesis that rich club regions and connections have a central role in global brain communication.",keywords:["Macaque","Neuroscience","Primate","Evolutionary biology"],concepts:["Macaque","Biology","Neuroscience","Primate","Computer science","Evolutionary biology"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0046497&type=printable",is_oa:!0,n_refs:79,n_refs_in_core:13,degree:55,community:0,deg_w:1064.5,betweenness:.0056,pagerank:.00791,eigenvector:.0837,pdf_file:"Harriger_2012.pdf",pdf_downloaded:!0},{id:119,oaid:"W2136981862",doi:"10.1093/cercor/bhr388",title:"The Anatomical Distance of Functional Connections Predicts Brain Network Topology in Health and Schizophrenia",authors:[{name:"Aaron Alexander‐Bloch",institutions:["University of California, Los Angeles","University of Cambridge","National Institute of Mental Health"]},{name:"Petra E. Vértes",institutions:["University of Cambridge"]},{name:"Reva Stidd",institutions:["National Institute of Mental Health"]},{name:"François Lalonde",institutions:["National Institute of Mental Health"]},{name:"Liv Clasen",institutions:["National Institute of Mental Health"]},{name:"Judith L. Rapoport",institutions:["National Institute of Mental Health"]},{name:"Jay N. Giedd",institutions:["National Institute of Mental Health"]},{name:"Edward T. Bullmore",institutions:["University of Cambridge"]},{name:"Nitin Gogtay",institutions:["National Institute of Mental Health"]}],authorString:"Aaron Alexander‐Bloch; Petra E. Vértes; Reva Stidd; François Lalonde; Liv Clasen; Judith L. Rapoport; Jay N. Giedd; Edward T. Bullmore; Nitin Gogtay",institutions:["National Institute of Mental Health","University of California, Los Angeles","University of Cambridge"],countries:["GB","US"],year:2012,journal:"Cerebral Cortex",citations:327,abstract:'The human brain is a topologically complex network embedded in anatomical space. Here, we systematically explored relationships between functional connectivity, complex network topology, and anatomical (Euclidean) distance between connected brain regions, in the resting-state functional magnetic resonance imaging brain networks of 20 healthy volunteers and 19 patients with childhood-onset schizophrenia (COS). Normal between-subject differences in average distance of connected edges in brain graphs were strongly associated with variation in topological properties of functional networks. In addition, a club or subset of connector hubs was identified, in lateral temporal, parietal, dorsal prefrontal, and medial prefrontal/cingulate cortical regions. In COS, there was reduced strength of functional connectivity over short distances especially, and therefore, global mean connection distance of thresholded graphs was significantly greater than normal. As predicted from relationships between spatial and topological properties of normal networks, this disorder-related proportional increase in connection distance was associated with reduced clustering and modularity and increased global efficiency of COS networks. Between-group differences in connection distance were localized specifically to connector hubs of multimodal association cortex. In relation to the neurodevelopmental pathogenesis of schizophrenia, we argue that the data are consistent with the interpretation that spatial and topological disturbances of functional network organization could arise from excessive "pruning" of short-distance functional connections in schizophrenia.',keywords:["Schizophrenia","Topology","Functional magnetic resonance imaging","Neuroscience","Modularity","Default mode network","Human brain","Functional connectivity"],concepts:["Schizophrenia (object-oriented programming)","Topology (electrical circuits)","Functional magnetic resonance imaging","Neuroscience","Modularity (biology)","Default mode network","Human brain","Functional connectivity"],topics:["Functional Brain Connectivity Studies","Mental Health Research Topics","Neural dynamics and brain function"],pdf_url:"https://academic.oup.com/cercor/article-pdf/23/1/127/17307051/bhr388.pdf",is_oa:!0,n_refs:79,n_refs_in_core:23,degree:48,community:3,deg_w:749,betweenness:.0032,pagerank:.00559,eigenvector:.0674,pdf_file:"AlexanderBloch_2012.pdf",pdf_downloaded:!0},{id:120,oaid:"W2158244090",doi:"10.1093/cercor/bhr221",title:"Similarity-Based Extraction of Individual Networks from Gray Matter MRI Scans",authors:[{name:"Betty M. Tijms",institutions:["University of Edinburgh"]},{name:"Peggy Seriès",institutions:["University of Edinburgh"]},{name:"David Willshaw",institutions:["University of Edinburgh"]},{name:"Stephen M. Lawrie",institutions:["University of Edinburgh"]}],authorString:"Betty M. Tijms; Peggy Seriès; David Willshaw; Stephen M. Lawrie",institutions:["University of Edinburgh"],countries:["GB"],year:2011,journal:"Cerebral Cortex",citations:324,abstract:'The characterization of gray matter morphology of individual brains is an important issue in neuroscience. Graph theory has been used to describe cortical morphology, with networks based on covariation of gray matter volume or thickness between cortical areas across people. Here, we extend this research by proposing a new method that describes the gray matter morphology of an individual cortex as a network. In these large-scale morphological networks, nodes represent small cortical regions, and edges connect regions that have a statistically similar structure. The method was applied to a healthy sample (n = 14, scanned at 2 different time points). For all networks, we described the spatial degree distribution, average minimum path length, average clustering coefficient, small world property, and betweenness centrality (BC). Finally, we studied the reproducibility of all these properties. The networks showed more clustering than random networks and a similar minimum path length, indicating that they were "small world." The spatial degree and BC distributions corresponded closely to those from group-derived networks. All network property values were reproducible over the 2 time points examined. Our results demonstrate that intracortical similarities can be used to provide a robust statistical description of individual gray matter morphology.',keywords:["Betweenness centrality","Clustering coefficient","Cluster analysis","Pattern recognition","Small-world network","Path length"],concepts:["Betweenness centrality","Clustering coefficient","Cluster analysis","Computer science","Pattern recognition (psychology)","Small-world network","Path length","Artificial intelligence"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Mental Health Research Topics"],pdf_url:"https://academic.oup.com/cercor/article-pdf/22/7/1530/17306139/bhr221.pdf",is_oa:!0,n_refs:98,n_refs_in_core:17,degree:35,community:1,deg_w:647.5,betweenness:.0011,pagerank:.00472,eigenvector:.0806,pdf_file:null,pdf_downloaded:!1},{id:121,oaid:"W2092131848",doi:"10.1073/pnas.1208933109",title:"Hubs of brain functional networks are radically reorganized in comatose patients",authors:[{name:"Sophie Achard",institutions:["Centre National de la Recherche Scientifique","GIPSA-Lab"]},{name:"Chantal Delon‐Martin",institutions:["Inserm","Université Joseph Fourier"]},{name:"Petra E. Vértes",institutions:["University of Cambridge"]},{name:"Félix Renard",institutions:["Centre National de la Recherche Scientifique","GIPSA-Lab"]},{name:"Maleka Schenck",institutions:["Université de Strasbourg"]},{name:"Francis Schneider",institutions:["Université de Strasbourg"]},{name:"Christian Heinrich",institutions:["Laboratoire des Sciences de l'Ingénieur, de l'Informatique et de l'Imagerie","Université de Strasbourg"]},{name:"Stéphane Kremer",institutions:["Hôpital d'Hautepierre","Université de Strasbourg"]},{name:"Edward T. Bullmore",institutions:["National Health Service","GlaxoSmithKline (United Kingdom)","University of Cambridge","Cambridgeshire and Peterborough NHS Foundation Trust"]}],authorString:"Sophie Achard; Chantal Delon‐Martin; Petra E. Vértes; Félix Renard; Maleka Schenck; Francis Schneider; Christian Heinrich; Stéphane Kremer; Edward T. Bullmore",institutions:["Cambridgeshire and Peterborough NHS Foundation Trust","Centre National de la Recherche Scientifique","GIPSA-Lab","GlaxoSmithKline (United Kingdom)","Hôpital d'Hautepierre","Inserm","Laboratoire des Sciences de l'Ingénieur, de l'Informatique et de l'Imagerie","National Health Service","University of Cambridge","Université Joseph Fourier","Université de Strasbourg"],countries:["FR","GB"],year:2012,journal:"Proceedings of the National Academy of Sciences",citations:319,abstract:'Human brain networks have topological properties in common with many other complex systems, prompting the following question: what aspects of brain network organization are critical for distinctive functional properties of the brain, such as consciousness? To address this question, we used graph theoretical methods to explore brain network topology in resting state functional MRI data acquired from 17 patients with severely impaired consciousness and 20 healthy volunteers. We found that many global network properties were conserved in comatose patients. Specifically, there was no significant abnormality of global efficiency, clustering, small-worldness, modularity, or degree distribution in the patient group. However, in every patient, we found evidence for a radical reorganization of high degree or highly efficient "hub" nodes. Cortical regions that were hubs of healthy brain networks had typically become nonhubs of comatose brain networks and vice versa. These results indicate that global topological properties of complex brain networks may be homeostatically conserved under extremely different clinical conditions and that consciousness likely depends on the anatomical location of hub nodes in human brain networks.',keywords:["Modularity","Consciousness","Human brain","Complex network","Neuroscience","Clustering coefficient","Network topology"],concepts:["Modularity (biology)","Consciousness","Human brain","Complex network","Neuroscience","Clustering coefficient","Computer science","Network topology"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"https://www.pnas.org/content/pnas/109/50/20608.full.pdf",is_oa:!0,n_refs:42,n_refs_in_core:10,degree:34,community:3,deg_w:307.5,betweenness:.0028,pagerank:.00288,eigenvector:.0216,pdf_file:"Achard_2012.pdf",pdf_downloaded:!0},{id:122,oaid:"W2622948156",doi:"10.1002/nbm.3752",title:"Building connectomes using diffusion MRI: why, how and but",authors:[{name:"Stamatios N. Sotiropoulos",institutions:["University of Nottingham","University of Oxford","Wellcome Centre for Integrative Neuroimaging"]},{name:"Andrew Zalesky",institutions:["The University of Melbourne","Melbourne Health"]}],authorString:"Stamatios N. Sotiropoulos; Andrew Zalesky",institutions:["Melbourne Health","The University of Melbourne","University of Nottingham","University of Oxford","Wellcome Centre for Integrative Neuroimaging"],countries:["AU","GB"],year:2017,journal:"NMR in Biomedicine",citations:318,abstract:"Why has diffusion MRI become a principal modality for mapping connectomes in vivo? How do different image acquisition parameters, fiber tracking algorithms and other methodological choices affect connectome estimation? What are the main factors that dictate the success and failure of connectome reconstruction? These are some of the key questions that we aim to address in this review. We provide an overview of the key methods that can be used to estimate the nodes and edges of macroscale connectomes, and we discuss open problems and inherent limitations. We argue that diffusion MRI-based connectome mapping methods are still in their infancy and caution against blind application of deep white matter tractography due to the challenges inherent to connectome reconstruction. We review a number of studies that provide evidence of useful microstructural and network properties that can be extracted in various independent and biologically relevant contexts. Finally, we highlight some of the key deficiencies of current macroscale connectome mapping methodologies and motivate future developments.",keywords:["Connectome","Diffusion MRI","Connectomics","Human Connectome Project","Tractography","Key"],concepts:["Connectome","Diffusion MRI","Computer science","Connectomics","Human Connectome Project","Tractography","Key (lock)","Artificial intelligence"],topics:["Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications","Functional Brain Connectivity Studies"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/nbm.3752",is_oa:!0,n_refs:254,n_refs_in_core:18,degree:34,community:0,deg_w:593.5,betweenness:.0029,pagerank:.00489,eigenvector:.0363,pdf_file:null,pdf_downloaded:!1},{id:123,oaid:"W1985821218",doi:"10.1523/jneurosci.4858-10.2011",title:"Genetic Influences on Cost-Efficient Organization of Human Cortical Functional Networks",authors:[{name:"Alex Fornito",institutions:["University of Cambridge"]},{name:"Andrew Zalesky",institutions:["The University of Melbourne","Melbourne Health"]},{name:"Danielle S. Bassett",institutions:["University of Cambridge"]},{name:"David Meunier",institutions:["University of Cambridge"]},{name:"Ian Ellison-Wright",institutions:["Avon and Wiltshire Mental Health Partnership NHS Trust","University of Cambridge"]},{name:"Murat Yücel",institutions:["The University of Melbourne"]},{name:"Stephen J. Wood",institutions:["The University of Melbourne","Melbourne Health","University of Birmingham"]},{name:"Karen Shaw",institutions:["The University of Melbourne","Melbourne Health"]},{name:"Jennifer O’Connor",institutions:["The University of Melbourne","Melbourne Health"]},{name:"Deborah A. Nertney",institutions:["The University of Queensland","Park Centre for Mental Health","Queensland Centre for Mental Health Research"]},{name:"Bryan Mowry",institutions:["The University of Queensland","Park Centre for Mental Health","Queensland Centre for Mental Health Research"]},{name:"Christos Pantelis",institutions:["The University of Melbourne","Melbourne Health"]},{name:"Edward T. Bullmore",institutions:["University of Cambridge","Addenbrooke's Hospital"]}],authorString:"Alex Fornito; Andrew Zalesky; Danielle S. Bassett; David Meunier; Ian Ellison-Wright; Murat Yücel; Stephen J. Wood; Karen Shaw; Jennifer O’Connor; Deborah A. Nertney; Bryan Mowry; Christos Pantelis et al.",institutions:["Addenbrooke's Hospital","Avon and Wiltshire Mental Health Partnership NHS Trust","Melbourne Health","Park Centre for Mental Health","Queensland Centre for Mental Health Research","The University of Melbourne","The University of Queensland","University of Birmingham","University of Cambridge"],countries:["AU","GB"],year:2011,journal:"Journal of Neuroscience",citations:306,abstract:"The human cerebral cortex is a complex network of functionally specialized regions interconnected by axonal fibers, but the organizational principles underlying cortical connectivity remain unknown. Here, we report evidence that one such principle for functional cortical networks involves finding a balance between maximizing communication efficiency and minimizing connection cost, referred to as optimization of network cost-efficiency. We measured spontaneous fluctuations of the blood oxygenation level-dependent signal using functional magnetic resonance imaging in healthy monozygotic (16 pairs) and dizygotic (13 pairs) twins and characterized cost-efficient properties of brain network functional connectivity between 1041 distinct cortical regions. At the global network level, 60% of the interindividual variance in cost-efficiency of cortical functional networks was attributable to additive genetic effects. Regionally, significant genetic effects were observed throughout the cortex in a largely bilateral pattern, including bilateral posterior cingulate and medial prefrontal cortices, dorsolateral prefrontal and superior parietal cortices, and lateral temporal and inferomedial occipital regions. Genetic effects were stronger for cost-efficiency than for other metrics considered, and were more clearly significant in functional networks operating in the 0.09-0.18 Hz frequency interval than at higher or lower frequencies. These findings are consistent with the hypothesis that brain networks evolved to satisfy competitive selection criteria of maximizing efficiency and minimizing cost, and that optimization of network cost-efficiency represents an important principle for the brain's functional organization.",keywords:["Functional magnetic resonance imaging","Neuroscience","Prefrontal cortex","Dorsolateral prefrontal cortex","Posterior cingulate","Brain mapping"],concepts:["Functional magnetic resonance imaging","Neuroscience","Prefrontal cortex","Dorsolateral prefrontal cortex","Posterior cingulate","Computer science","Brain mapping","Psychology"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/31/9/3261.full.pdf",is_oa:!0,n_refs:79,n_refs_in_core:13,degree:40,community:3,deg_w:657.5,betweenness:.0028,pagerank:.00494,eigenvector:.0669,pdf_file:"Fornito_2011.pdf",pdf_downloaded:!0},{id:124,oaid:"W2039172538",doi:"10.1093/cercor/bhu246",title:"Identifying and Mapping Connectivity Patterns of Brain Network Hubs in Alzheimer's Disease",authors:[{name:"Zhengjia Dai",institutions:["Beijing Normal University","McGovern Institute for Brain Research"]},{name:"Chao‐Gan Yan",institutions:["McGovern Institute for Brain Research","Nathan Kline Institute for Psychiatric Research"]},{name:"Kuncheng Li",institutions:["Capital Medical University"]},{name:"Zhi­qun Wang",institutions:["Capital Medical University"]},{name:"Jinhui Wang",institutions:["McGovern Institute for Brain Research"]},{name:"Miao Cao",institutions:["McGovern Institute for Brain Research","Beijing Normal University"]},{name:"Qixiang Lin",institutions:["McGovern Institute for Brain Research","Beijing Normal University"]},{name:"Ni Shu",institutions:["Beijing Normal University","McGovern Institute for Brain Research"]},{name:"Mingrui Xia",institutions:["McGovern Institute for Brain Research","Beijing Normal University"]},{name:"Yanchao Bi",institutions:["Beijing Normal University","McGovern Institute for Brain Research"]},{name:"Yong He",institutions:["McGovern Institute for Brain Research","Beijing Normal University"]}],authorString:"Zhengjia Dai; Chao‐Gan Yan; Kuncheng Li; Zhi­qun Wang; Jinhui Wang; Miao Cao; Qixiang Lin; Ni Shu; Mingrui Xia; Yanchao Bi; Yong He",institutions:["Beijing Normal University","Capital Medical University","McGovern Institute for Brain Research","Nathan Kline Institute for Psychiatric Research"],countries:["CN","US"],year:2014,journal:"Cerebral Cortex",citations:304,abstract:"Alzheimer's disease (AD) is associated not only with regional gray matter damages, but also with abnormalities in functional integration between brain regions. Here, we employed resting-state functional magnetic resonance imaging data and voxel-based graph-theory analysis to systematically investigate intrinsic functional connectivity patterns of whole-brain networks in 32 AD patients and 38 healthy controls (HCs). We found that AD selectively targeted highly connected hub regions (in terms of nodal functional connectivity strength) of brain networks, involving the medial and lateral prefrontal and parietal cortices, insula, and thalamus. This impairment was connectivity distance-dependent (Euclidean), with the most prominent disruptions appearing in the long-range connections (e.g., 100-130 mm). Moreover, AD also disrupted functional connections within the default-mode, salience and executive-control modules, and connections between the salience and executive-control modules. These disruptions of hub connectivity and modular integrity significantly correlated with the patients' cognitive performance. Finally, the nodal connectivity strength in the posteromedial cortex exhibited a highly discriminative power in distinguishing individuals with AD from HCs. Taken together, our results emphasize AD-related degeneration of specific brain hubs, thus providing novel insights into the pathophysiological mechanisms of connectivity dysfunction in AD and suggesting the potential of using network hub connectivity as a diagnostic biomarker.",keywords:["Neuroscience","Default mode network","Functional magnetic resonance imaging","Salience","Prefrontal cortex","Thalamus","Functional connectivity"],concepts:["Neuroscience","Default mode network","Functional magnetic resonance imaging","Salience (neuroscience)","Prefrontal cortex","Psychology","Thalamus","Functional connectivity"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://academic.oup.com/cercor/article-pdf/25/10/3723/14101737/bhu246.pdf",is_oa:!0,n_refs:125,n_refs_in_core:27,degree:43,community:2,deg_w:660.5,betweenness:.0038,pagerank:.00518,eigenvector:.0543,pdf_file:null,pdf_downloaded:!1},{id:125,oaid:"W2903794313",doi:"10.1016/j.dcn.2018.12.005",title:"The development of brain network hubs",authors:[{name:"Stuart Oldham",institutions:["Monash University"]},{name:"Alex Fornito",institutions:["Monash University"]}],authorString:"Stuart Oldham; Alex Fornito",institutions:["Monash University"],countries:["AU"],year:2018,journal:"Developmental Cognitive Neuroscience",citations:274,abstract:"Some brain regions have a central role in supporting integrated brain function, marking them as network hubs. Given the functional importance of hubs, it is natural to ask how they emerge during development and to consider how they shape the function of the maturing brain. Here, we review evidence examining how brain network hubs, both in structural and functional connectivity networks, develop over the prenatal, neonate, childhood, and adolescent periods. The available evidence suggests that structural hubs of the brain arise in the prenatal period and show a consistent spatial topography through development, but undergo a protracted period of consolidation that extends into late adolescence. In contrast, the hubs of brain functional networks show a more variable topography, being predominantly located in primary cortical areas in early development, before moving to association areas by late childhood. These findings suggest that while the basic anatomical infrastructure of hubs may be established early, the functional viability and integrative capacity of these areas undergoes extensive postnatal maturation. Not all findings are consistent with this view however. We consider methodological factors that might drive these inconsistencies, and which should be addressed to promote a more rigorous investigation of brain network development.",keywords:["Brain development","Neuroscience","Brain Structure and Function","Brain function","Late childhood","Connectome","Functional connectivity"],concepts:["Psychology","Brain development","Neuroscience","Brain Structure and Function","Brain function","Late childhood","Connectome","Functional connectivity"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://doi.org/10.1016/j.dcn.2018.12.005",is_oa:!0,n_refs:208,n_refs_in_core:43,degree:58,community:0,deg_w:1029.5,betweenness:.0072,pagerank:.00779,eigenvector:.0677,pdf_file:null,pdf_downloaded:!1},{id:126,oaid:"W2166905390",doi:"10.1093/cercor/bht064",title:"Structural and Functional Aspects Relating to Cost and Benefit of Rich Club Organization in the Human Cerebral Cortex",authors:[{name:"Guusje Collin",institutions:["University Medical Center Utrecht"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]},{name:"René C.W. Mandl",institutions:["University Medical Center Utrecht"]},{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]}],authorString:"Guusje Collin; Olaf Sporns; René C.W. Mandl; Martijn P. van den Heuvel",institutions:["Indiana University Bloomington","University Medical Center Utrecht"],countries:["NL","US"],year:2013,journal:"Cerebral Cortex",citations:271,abstract:`Recent findings have demonstrated that a small set of highly connected brain regions may play a central role in enabling efficient communication between cortical regions, together forming a densely interconnected "rich club." However, the density and spatial layout of the rich club also suggest that it constitutes a costly feature of brain architecture. Here, combining anatomical T1, diffusion tensor imaging, magnetic transfer imaging, and functional MRI, several aspects of structural and functional connectivity of the brain's rich club were examined. Our findings suggest that rich club regions and rich club connections exhibit high levels of wiring volume, high levels of white matter organization, high levels of metabolic energy usage, long maturational trajectories, more variable regional time series, and more inter-regional functional couplings. Taken together, these structural and functional measures extend the notion that rich club organization represents a high-cost feature of brain architecture that puts a significant strain on brain resources. The high cost of the rich club may, however, be offset by significant functional benefits that the rich club confers to the brain network as a whole.`,keywords:["Club","White matter","Neuroscience","Functional organization","Diffusion MRI","Spatial organization","Architecture"],concepts:["Club","White matter","Neuroscience","Functional organization","Diffusion MRI","Spatial organization","Computer science","Architecture"],topics:["Advanced Neuroimaging Techniques and Applications","Functional Brain Connectivity Studies","Transcranial Magnetic Stimulation Studies"],pdf_url:"https://academic.oup.com/cercor/article-pdf/24/9/2258/890457/bht064.pdf",is_oa:!0,n_refs:72,n_refs_in_core:23,degree:53,community:0,deg_w:827.5,betweenness:.005,pagerank:.00635,eigenvector:.0578,pdf_file:null,pdf_downloaded:!1},{id:127,oaid:"W2237883872",doi:"10.1073/pnas.1513302113",title:"A transcriptional signature of hub connectivity in the mouse connectome",authors:[{name:"Ben Fulcher",institutions:["Monash University"]},{name:"Alex Fornito",institutions:["Monash University"]}],authorString:"Ben Fulcher; Alex Fornito",institutions:["Monash University"],countries:["AU"],year:2016,journal:"Proceedings of the National Academy of Sciences",citations:265,abstract:'Connectivity is not distributed evenly throughout the brain. Instead, it is concentrated on a small number of highly connected neural elements that act as network hubs. Across different species and measurement scales, these hubs show dense interconnectivity, forming a core or "rich club" that integrates information across anatomically distributed neural systems. Here, we show that projections between connectivity hubs of the mouse brain are both central (i.e., they play an important role in neural communication) and costly (i.e., they extend over long anatomical distances) aspects of network organization that carry a distinctive genetic signature. Analyzing the neuronal connectivity of 213 brain regions and the transcriptional coupling, across 17,642 genes, between each pair of regions, we find that coupling is highest for pairs of connected hubs, intermediate for links between hubs and nonhubs, and lowest for connected pairs of nonhubs. The high transcriptional coupling associated with hub connectivity is driven by genes regulating the oxidative synthesis and metabolism of ATP--the primary energetic currency of neuronal communication. This genetic signature contrasts that identified for neuronal connectivity in general, which is driven by genes regulating neuronal, synaptic, and axonal structure and function. Our findings establish a direct link between molecular function and the large-scale topology of neuronal connectivity, showing that brain hubs display a tight coordination of gene expression, often over long anatomical distances, that is intimately related to the metabolic requirements of these highly active network elements.',keywords:["Connectome","Signature","Neuroscience","Functional connectivity","Computational biology"],concepts:["Connectome","Signature (topology)","Neuroscience","Functional connectivity","Biology","Computational biology"],topics:["Congenital heart defects research","Neuroscience of respiration and sleep"],pdf_url:"https://www.pnas.org/content/pnas/113/5/1435.full.pdf",is_oa:!0,n_refs:53,n_refs_in_core:15,degree:34,community:0,deg_w:378.5,betweenness:.0015,pagerank:.00347,eigenvector:.0181,pdf_file:"Fulcher_2016.pdf",pdf_downloaded:!0},{id:128,oaid:"W2949118732",doi:"10.1371/journal.pone.0178798",title:"BRAPH: A graph theory software for the analysis of brain connectivity",authors:[{name:"Mite Mijalkov",institutions:["Bilkent University"]},{name:"Ehsan Kakaei",institutions:["Bilkent University"]},{name:"Joana B. Pereira",institutions:["Karolinska Institutet"]},{name:"Eric Westman",institutions:["Karolinska Institutet"]},{name:"Giovanni Volpe",institutions:["University of Gothenburg","Bilkent University"]},{name:"for the Alzheimer's Disease Neuroimaging Initiative",institutions:[]}],authorString:"Mite Mijalkov; Ehsan Kakaei; Joana B. Pereira; Eric Westman; Giovanni Volpe; for the Alzheimer's Disease Neuroimaging Initiative",institutions:["Bilkent University","Karolinska Institutet","University of Gothenburg"],countries:["SE","TR"],year:2017,journal:"PLoS ONE",citations:261,abstract:"The brain is a large-scale complex network whose workings rely on the interaction between its various regions. In the past few years, the organization of the human brain network has been studied extensively using concepts from graph theory, where the brain is represented as a set of nodes connected by edges. This representation of the brain as a connectome can be used to assess important measures that reflect its topological architecture. We have developed a freeware MatLab-based software (BRAPH-BRain Analysis using graPH theory) for connectivity analysis of brain networks derived from structural magnetic resonance imaging (MRI), functional MRI (fMRI), positron emission tomography (PET) and electroencephalogram (EEG) data. BRAPH allows building connectivity matrices, calculating global and local network measures, performing non-parametric permutations for group comparisons, assessing the modules in the network, and comparing the results to random networks. By contrast to other toolboxes, it allows performing longitudinal comparisons of the same patients across different points in time. Furthermore, even though a user-friendly interface is provided, the architecture of the program is modular (object-oriented) so that it can be easily expanded and customized. To demonstrate the abilities of BRAPH, we performed structural and functional graph theory analyses in two separate studies. In the first study, using MRI data, we assessed the differences in global and nodal network topology in healthy controls, patients with amnestic mild cognitive impairment, and patients with Alzheimer's disease. In the second study, using resting-state fMRI data, we compared healthy controls and Parkinson's patients with mild cognitive impairment.",keywords:["Graph theory","Graph","Computational biology","Combinatorics","Theoretical computer science"],concepts:["Graph theory","Computer science","Graph","Computational biology"],topics:["Functional Brain Connectivity Studies","Mental Health Research Topics","Complex Network Analysis Techniques"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0178798&type=printable",is_oa:!0,n_refs:57,n_refs_in_core:17,degree:31,community:3,deg_w:295,betweenness:.0022,pagerank:.00277,eigenvector:.0224,pdf_file:"Mijalkov_2017.pdf",pdf_downloaded:!0},{id:129,oaid:"W1974644418",doi:"10.3389/fncom.2011.00005",title:"The Non-Random Brain: Efficiency, Economy, and Complex Dynamics",authors:[{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]}],authorString:"Olaf Sporns",institutions:["Indiana University Bloomington"],countries:["US"],year:2011,journal:"Frontiers in Computational Neuroscience",citations:245,abstract:"Modern anatomical tracing and imaging techniques are beginning to reveal the structural anatomy of neural circuits at small and large scales in unprecedented detail. When examined with analytic tools from graph theory and network science, neural connectivity exhibits highly non-random features, including high clustering and short path length, as well as modules and highly central hub nodes. These characteristic topological features of neural connections shape non-random dynamic interactions that occur during spontaneous activity or in response to external stimulation. Disturbances of connectivity and thus of neural dynamics are thought to underlie a number of disease states of the brain, and some evidence suggests that degraded functional performance of brain networks may be the outcome of a process of randomization affecting their nodes and edges. This article provides a survey of the non-random structure of neural connectivity, primarily at the large scale of regions and pathways in the mammalian cerebral cortex. In addition, we will discuss how non-random connections can give rise to differentiated and complex patterns of dynamics and information flow. Finally, we will explore the idea that at least some disorders of the nervous system are associated with increased randomness of neural connections.",keywords:["Randomness","Neuroscience","Random graph","Biological neural network","Network dynamics","Artificial neural network","Complex network"],concepts:["Randomness","Computer science","Neuroscience","Random graph","Biological neural network","Network dynamics","Artificial neural network","Complex network"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fncom.2011.00005/pdf",is_oa:!0,n_refs:156,n_refs_in_core:19,degree:40,community:1,deg_w:799,betweenness:.0032,pagerank:.00583,eigenvector:.085,pdf_file:"Sporns_2011_b.pdf",pdf_downloaded:!0},{id:130,oaid:"W2297988641",doi:"10.1038/srep30770",title:"Optimally controlling the human connectome: the role of network topology",authors:[{name:"Richard F. Betzel",institutions:["University of Pennsylvania"]},{name:"Shi Gu",institutions:["University of Pennsylvania"]},{name:"John D. Medaglia",institutions:["University of Pennsylvania"]},{name:"Fabio Pasqualetti",institutions:["University of California, Riverside"]},{name:"Danielle S. Bassett",institutions:["University of Pennsylvania"]}],authorString:"Richard F. Betzel; Shi Gu; John D. Medaglia; Fabio Pasqualetti; Danielle S. Bassett",institutions:["University of California, Riverside","University of Pennsylvania"],countries:["US"],year:2016,journal:"Scientific Reports",citations:238,abstract:"To meet ongoing cognitive demands, the human brain must seamlessly transition from one brain state to another, in the process drawing on different cognitive systems. How does the brain's network of anatomical connections help facilitate such transitions? Which features of this network contribute to making one transition easy and another transition difficult? Here, we address these questions using network control theory. We calculate the optimal input signals to drive the brain to and from states dominated by different cognitive systems. The input signals allow us to assess the contributions made by different brain regions. We show that such contributions, which we measure as energy, are correlated with regions' weighted degrees. We also show that the network communicability, a measure of direct and indirect connectedness between brain regions, predicts the extent to which brain regions compensate when input to another region is suppressed. Finally, we identify optimal states in which the brain should start (and finish) in order to minimize transition energy. We show that the optimal target states display high activity in hub regions, implicating the brain's rich club. Furthermore, when rich club organization is destroyed, the energy cost associated with state transitions increases significantly, demonstrating that it is the richness of brain regions that makes them ideal targets.",keywords:["Social connectedness","Cognition","Process","Measure","Human brain","Topology","Transition","Control"],concepts:["Social connectedness","Computer science","Cognition","Process (computing)","Measure (data warehouse)","Human brain","Topology (electrical circuits)","Transition (genetics)"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://www.nature.com/articles/srep30770.pdf",is_oa:!0,n_refs:85,n_refs_in_core:16,degree:35,community:0,deg_w:447.5,betweenness:.0017,pagerank:.00397,eigenvector:.0211,pdf_file:"Betzel_2016.pdf",pdf_downloaded:!0},{id:131,oaid:"W2156518076",doi:"10.3389/fnhum.2013.00624",title:"Imaging structural and functional brain networks in temporal lobe epilepsy",authors:[{name:"Boris C. Bernhardt",institutions:["Montreal Neurological Institute and Hospital","Max Planck Institute for Human Cognitive and Brain Sciences","McGill University"]},{name:"Seok‐Jun Hong",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Andrea Bernasconi",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Neda Bernasconi",institutions:["Montreal Neurological Institute and Hospital","McGill University"]}],authorString:"Boris C. Bernhardt; Seok‐Jun Hong; Andrea Bernasconi; Neda Bernasconi",institutions:["Max Planck Institute for Human Cognitive and Brain Sciences","McGill University","Montreal Neurological Institute and Hospital"],countries:["CA","DE"],year:2013,journal:"Frontiers in Human Neuroscience",citations:236,abstract:"Early imaging studies in temporal lobe epilepsy (TLE) focused on the search for mesial temporal sclerosis, as its surgical removal results in clinically meaningful improvement in about 70% of patients. Nevertheless, a considerable subgroup of patients continues to suffer from post-operative seizures. Although the reasons for surgical failure are not fully understood, electrophysiological and imaging data suggest that anomalies extending beyond the temporal lobe may have negative impact on outcome. This hypothesis has revived the concept of human epilepsy as a disorder of distributed brain networks. Recent methodological advances in non-invasive neuroimaging have led to quantify structural and functional networks in vivo. While structural networks can be inferred from diffusion MRI tractography and inter-regional covariance patterns of structural measures such as cortical thickness, functional connectivity is generally computed based on statistical dependencies of neurophysiological time-series, measured through functional MRI or electroencephalographic techniques. This review considers the application of advanced analytical methods in structural and functional connectivity analyses in TLE. We will specifically highlight findings from graph-theoretical analysis that allow assessing the topological organization of brain networks. These studies have provided compelling evidence that TLE is a system disorder with profound alterations in local and distributed networks. In addition, there is emerging evidence for the utility of network properties as clinical diagnostic markers. Nowadays, a network perspective is considered to be essential to the understanding of the development, progression, and management of epilepsy.",keywords:["Temporal lobe","Neuroscience","Epilepsy","Neuroimaging","Tractography","Diffusion MRI","Neurophysiology"],concepts:["Temporal lobe","Neuroscience","Epilepsy","Neuroimaging","Tractography","Diffusion MRI","Neurophysiology","Psychology"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnhum.2013.00624/pdf",is_oa:!0,n_refs:218,n_refs_in_core:21,degree:35,community:1,deg_w:632,betweenness:.0015,pagerank:.00467,eigenvector:.0729,pdf_file:"Bernhardt_2013.pdf",pdf_downloaded:!0},{id:132,oaid:"W2152573143",doi:"10.1002/hbm.22877",title:"Age‐related changes in the topological organization of the white matter structural connectome across the human lifespan",authors:[{name:"Tengda Zhao",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Miao Cao",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Haijing Niu",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Xi‐Nian Zuo",institutions:["Chinese Academy of Sciences","Beijing Normal University","Wuhan Institute of Physics and Mathematics","Institute of Genetics and Developmental Biology","Institute of Psychology, Chinese Academy of Sciences","Institute of Physics"]},{name:"Alan C. Evans",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Yong He",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Qi Dong",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Ni Shu",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]}],authorString:"Tengda Zhao; Miao Cao; Haijing Niu; Xi‐Nian Zuo; Alan C. Evans; Yong He; Qi Dong; Ni Shu",institutions:["Beijing Normal University","Chinese Academy of Sciences","Chinese Institute for Brain Research","Institute of Genetics and Developmental Biology","Institute of Physics","Institute of Psychology, Chinese Academy of Sciences","McGill University","Montreal Neurological Institute and Hospital","Wuhan Institute of Physics and Mathematics"],countries:["CA","CN"],year:2015,journal:"Human Brain Mapping",citations:228,abstract:"Lifespan is a dynamic process with remarkable changes in brain structure and function. Previous neuroimaging studies have indicated age-related microstructural changes in specific white matter tracts during development and aging. However, the age-related alterations in the topological architecture of the white matter structural connectome across the human lifespan remain largely unknown. Here, a cohort of 113 healthy individuals (ages 9-85) with both diffusion and structural MRI acquisitions were examined. For each participant, the high-resolution white matter structural networks were constructed by deterministic fiber tractography among 1024 parcellation units and were quantified with graph theoretical analyses. The global network properties, including network strength, cost, topological efficiency, and robustness, followed an inverted U-shaped trajectory with a peak age around the third decade. The brain areas with the most significantly nonlinear changes were located in the prefrontal and temporal cortices. Different brain regions exhibited heterogeneous trajectories: the posterior cingulate and lateral temporal cortices displayed prolonged maturation/degeneration compared with the prefrontal cortices. Rich-club organization was evident across the lifespan, whereas hub integration decreased linearly with age, especially accompanied by the loss of frontal hubs and their connections. Additionally, age-related changes in structural connections were predominantly located within and between the prefrontal and temporal modules. Finally, based on the graph metrics of structural connectome, accurate predictions of individual age were obtained (r = 0.77). Together, the data indicated a dynamic topological organization of the brain structural connectome across human lifespan, which may provide possible structural substrates underlying functional and cognitive changes with age.",keywords:["Connectome","White matter","Neuroscience","Human brain","Functional connectivity","Medicine"],concepts:["Connectome","White matter","Neuroscience","Human brain","Psychology","Functional connectivity","Biology"],topics:["Advanced Neuroimaging Techniques and Applications","Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/hbm.22877",is_oa:!0,n_refs:98,n_refs_in_core:19,degree:34,community:0,deg_w:477,betweenness:.0018,pagerank:.00394,eigenvector:.0334,pdf_file:null,pdf_downloaded:!1},{id:133,oaid:"W2021077818",doi:"10.1523/jneurosci.4793-12.2013",title:"Probabilistic Diffusion Tractography and Graph Theory Analysis Reveal Abnormal White Matter Structural Connectivity Networks in Drug-Naive Boys with Attention Deficit/Hyperactivity Disorder",authors:[{name:"Qingjiu Cao",institutions:["Peking University","Peking University Sixth Hospital"]},{name:"Ni Shu",institutions:["Beijing Normal University"]},{name:"An Li",institutions:["Peking University","Beijing Hospital","Peking University Sixth Hospital"]},{name:"Ping Wang",institutions:["Peking University","Beijing Hospital","Peking University Sixth Hospital"]},{name:"Li Sun",institutions:["Peking University","Beijing Hospital","Peking University Sixth Hospital"]},{name:"Mingrui Xia",institutions:["Beijing Normal University"]},{name:"Junhua Wang",institutions:["Beijing Normal University"]},{name:"Gaolang Gong",institutions:["Beijing Normal University"]},{name:"Yu‐Feng Zang",institutions:["Affiliated Hospital of Hangzhou Normal University","Zhejiang Lab","Zhejiang University"]},{name:"Wang Yf",institutions:["Peking University","Beijing Hospital","Peking University Sixth Hospital"]},{name:"Yong He",institutions:["Beijing Normal University"]}],authorString:"Qingjiu Cao; Ni Shu; An Li; Ping Wang; Li Sun; Mingrui Xia; Junhua Wang; Gaolang Gong; Yu‐Feng Zang; Wang Yf; Yong He",institutions:["Affiliated Hospital of Hangzhou Normal University","Beijing Hospital","Beijing Normal University","Peking University","Peking University Sixth Hospital","Zhejiang Lab","Zhejiang University"],countries:["CN"],year:2013,journal:"Journal of Neuroscience",citations:219,abstract:"Attention-deficit/hyperactivity disorder (ADHD), which is characterized by core symptoms of inattention and hyperactivity/impulsivity, is one of the most common neurodevelopmental disorders of childhood. Neuroimaging studies have suggested that these behavioral disturbances are associated with abnormal functional connectivity among brain regions. However, the alterations in the structural connections that underlie these behavioral and functional deficits remain poorly understood. Here, we used diffusion magnetic resonance imaging and probabilistic tractography method to examine whole-brain white matter (WM) structural connectivity in 30 drug-naive boys with ADHD and 30 healthy controls. The WM networks of the human brain were constructed by estimating inter-regional connectivity probability. The topological properties of the resultant networks (e.g., small-world and network efficiency) were then analyzed using graph theoretical approaches. Nonparametric permutation tests were applied for between-group comparisons of these graphic metrics. We found that both the ADHD and control groups showed an efficient small-world organization in the whole-brain WM networks, suggesting a balance between structurally segregated and integrated connectivity patterns. However, relative to controls, patients with ADHD exhibited decreased global efficiency and increased shortest path length, with the most pronounced efficiency decreases in the left parietal, frontal, and occipital cortices. Intriguingly, the ADHD group showed decreased structural connectivity in the prefrontal-dominant circuitry and increased connectivity in the orbitofrontal-striatal circuitry, and these changes significantly correlated with the inattention and hyperactivity/impulsivity symptoms, respectively. The present study shows disrupted topological organization of large-scale WM networks in ADHD, extending our understanding of how structural disruptions of neuronal circuits underlie behavioral disturbances in patients with ADHD.",keywords:["Impulsivity","Attention deficit hyperactivity disorder","White matter","Diffusion MRI","Neuroimaging","Neuroscience","Tractography"],concepts:["Impulsivity","Attention deficit hyperactivity disorder","Psychology","White matter","Diffusion MRI","Neuroimaging","Neuroscience","Tractography"],topics:["Advanced Neuroimaging Techniques and Applications","Functional Brain Connectivity Studies","Attention Deficit Hyperactivity Disorder"],pdf_url:"https://www.jneurosci.org/content/jneuro/33/26/10676.full.pdf",is_oa:!0,n_refs:75,n_refs_in_core:16,degree:34,community:1,deg_w:475,betweenness:.0013,pagerank:.00378,eigenvector:.0482,pdf_file:null,pdf_downloaded:!1},{id:134,oaid:"W2950467641",doi:"10.1162/netn_a_00075",title:"Distance-dependent consensus thresholds for generating group-representative structural brain networks",authors:[{name:"Richard F. Betzel",institutions:["Indiana University Bloomington"]},{name:"Alessandra Griffa",institutions:["Amsterdam Neuroscience"]},{name:"Patric Hagmann",institutions:["University of Lausanne"]},{name:"Bratislav Mišić",institutions:["Montreal Neurological Institute and Hospital","McGill University"]}],authorString:"Richard F. Betzel; Alessandra Griffa; Patric Hagmann; Bratislav Mišić",institutions:["Amsterdam Neuroscience","Indiana University Bloomington","McGill University","Montreal Neurological Institute and Hospital","University of Lausanne"],countries:["CA","CH","NL","US"],year:2018,journal:"Network Neuroscience",citations:216,abstract:"Large-scale structural brain networks encode white matter connectivity patterns among distributed brain areas. These connection patterns are believed to support cognitive processes and, when compromised, can lead to neurocognitive deficits and maladaptive behavior. A powerful approach for studying the organizing principles of brain networks is to construct group-representative networks from multisubject cohorts. Doing so amplifies signal to noise ratios and provides a clearer picture of brain network organization. Here, we show that current approaches for generating sparse group-representative networks overestimate the proportion of short-range connections present in a network and, as a result, fail to match subject-level networks along a wide range of network statistics. We present an alternative approach that preserves the connection-length distribution of individual subjects. We have used this method in previous papers to generate group-representative networks, though to date its performance has not been appropriately benchmarked and compared against other methods. As a result of this simple modification, the networks generated using this approach successfully recapitulate subject-level properties, outperforming similar approaches by better preserving features that promote integrative brain function rather than segregative. The method developed here holds promise for future studies investigating basic organizational principles and features of large-scale structural brain networks.",keywords:["Neurocognitive","Construct","Cognition","ENCODE","Complex network","Range"],concepts:["Neurocognitive","Computer science","Construct (python library)","Cognition","ENCODE","Artificial intelligence","Complex network","Range (aeronautics)"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Neural dynamics and brain function"],pdf_url:"https://www.mitpressjournals.org/doi/pdf/10.1162/netn_a_00075",is_oa:!0,n_refs:71,n_refs_in_core:12,degree:28,community:0,deg_w:329.5,betweenness:.0012,pagerank:.00307,eigenvector:.0157,pdf_file:"Betzel_2018.pdf",pdf_downloaded:!0},{id:135,oaid:"W2952857756",doi:"10.1162/netn_a_00054",title:"Graph theory approaches to functional network organization in brain disorders: A critique for a brave new small-world",authors:[{name:"Michael N. Hallquist",institutions:["Pennsylvania State University","Imaging Center"]},{name:"Frank G. Hillary",institutions:["Pennsylvania State University","Imaging Center","Penn State Milton S. Hershey Medical Center"]}],authorString:"Michael N. Hallquist; Frank G. Hillary",institutions:["Imaging Center","Penn State Milton S. Hershey Medical Center","Pennsylvania State University"],countries:["US"],year:2018,journal:"Network Neuroscience",citations:215,abstract:"Over the past two decades, resting-state functional connectivity (RSFC) methods have provided new insights into the network organization of the human brain. Studies of brain disorders such as Alzheimer's disease or depression have adapted tools from graph theory to characterize differences between healthy and patient populations. Here, we conducted a review of clinical network neuroscience, summarizing methodological details from 106 RSFC studies. Although this approach is prevalent and promising, our review identified four challenges. First, the composition of networks varied remarkably in terms of region parcellation and edge definition, which are fundamental to graph analyses. Second, many studies equated the number of connections across graphs, but this is conceptually problematic in clinical populations and may induce spurious group differences. Third, few graph metrics were reported in common, precluding meta-analyses. Fourth, some studies tested hypotheses at one level of the graph without a clear neurobiological rationale or considering how findings at one level (e.g., global topology) are contextualized by another (e.g., modular structure). Based on these themes, we conducted network simulations to demonstrate the impact of specific methodological decisions on case-control comparisons. Finally, we offer suggestions for promoting convergence across clinical studies in order to facilitate progress in this important field.",keywords:["Spurious relationship","Graph theory","Graph","Network science","Cognitive science","Data science"],concepts:["Spurious relationship","Graph theory","Graph","Computer science","Network science","Psychology","Cognitive science","Data science"],topics:["Functional Brain Connectivity Studies","Mental Health Research Topics","Health, Environment, Cognitive Aging"],pdf_url:"https://www.mitpressjournals.org/doi/pdf/10.1162/netn_a_00054",is_oa:!0,n_refs:98,n_refs_in_core:13,degree:28,community:3,deg_w:280.5,betweenness:.0023,pagerank:.00281,eigenvector:.013,pdf_file:"Hallquist_2018.pdf",pdf_downloaded:!0},{id:136,oaid:"W2290913813",doi:"10.1002/brb3.448",title:"Single‐subject morphological brain networks: connectivity mapping, topological characterization and test–retest reliability",authors:[{name:"Hao Wang",institutions:["Hangzhou Normal University"]},{name:"Xiaoqing Jin",institutions:["Zhejiang Hospital"]},{name:"Ye Zhang",institutions:["Hangzhou Normal University"]},{name:"Jinhui Wang",institutions:["Hangzhou Normal University"]}],authorString:"Hao Wang; Xiaoqing Jin; Ye Zhang; Jinhui Wang",institutions:["Hangzhou Normal University","Zhejiang Hospital"],countries:["CN"],year:2016,journal:"Brain and Behavior",citations:214,abstract:"INTRODUCTION: Structural MRI has long been used to characterize local morphological features of the human brain. Coordination patterns of the local morphological features among regions, however, are not well understood. Here, we constructed individual-level morphological brain networks and systematically examined their topological organization and long-term test-retest reliability under different analytical schemes of spatial smoothing, brain parcellation, and network type. METHODS: This study included 57 healthy participants and all participants completed two MRI scan sessions. Individual morphological brain networks were constructed by estimating interregional similarity in the distribution of regional gray matter volume in terms of the Kullback-Leibler divergence measure. Graph-based global and nodal network measures were then calculated, followed by the statistical comparison and intra-class correlation analysis. RESULTS: The morphological brain networks were highly reproducible between sessions with significantly larger similarities for interhemispheric connections linking bilaterally homotopic regions. Further graph-based analyses revealed that the morphological brain networks exhibited nonrandom topological organization of small-worldness, high parallel efficiency and modular architecture regardless of the analytical choices of spatial smoothing, brain parcellation and network type. Moreover, several paralimbic and association regions were consistently revealed to be potential hubs. Nonetheless, the three studied factors particularly spatial smoothing significantly affected quantitative characterization of morphological brain networks. Further examination of long-term reliability revealed that all the examined network topological properties showed fair to excellent reliability irrespective of the analytical strategies, but performing spatial smoothing significantly improved reliability. Interestingly, nodal centralities were positively correlated with their reliabilities, and nodal degree and efficiency outperformed nodal betweenness with respect to reliability. CONCLUSIONS: Our findings support single-subject morphological network analysis as a meaningful and reliable method to characterize structural organization of the human brain; this method thus opens a new avenue toward understanding the substrate of intersubject variability in behavior and function and establishing morphological network biomarkers in brain disorders.",keywords:["Smoothing","Reliability","Pattern recognition","Neuroimaging","Human brain","Cartography"],concepts:["Smoothing","Reliability (semiconductor)","Pattern recognition (psychology)","Computer science","Artificial intelligence","Neuroimaging","Human brain","Cartography"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Topological and Geometric Data Analysis"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/brb3.448",is_oa:!0,n_refs:95,n_refs_in_core:24,degree:38,community:1,deg_w:668,betweenness:.0013,pagerank:.0049,eigenvector:.0755,pdf_file:null,pdf_downloaded:!1},{id:137,oaid:"W2016944352",doi:"10.1523/jneurosci.4085-10.2011",title:"Discrete Neuroanatomical Networks Are Associated with Specific Cognitive Abilities in Old Age",authors:[{name:"Wei Wen",institutions:["UNSW Sydney"]},{name:"Wanlin Zhu",institutions:["UNSW Sydney","Neuropsychiatric Research Institute"]},{name:"Yong He",institutions:["Beijing Normal University"]},{name:"Nicole A. Kochan",institutions:["UNSW Sydney","Neuropsychiatric Research Institute"]},{name:"Simone Reppermund",institutions:["UNSW Sydney"]},{name:"Melissa J. Slavin",institutions:["UNSW Sydney"]},{name:"Henry Brodaty",institutions:["UNSW Sydney","Prince of Wales Hospital"]},{name:"J. Douglas Crawford",institutions:["UNSW Sydney","Neuropsychiatric Research Institute"]},{name:"Aihua Xia",institutions:["The University of Melbourne"]},{name:"Perminder S. Sachdev",institutions:["UNSW Sydney","Neuropsychiatric Research Institute"]}],authorString:"Wei Wen; Wanlin Zhu; Yong He; Nicole A. Kochan; Simone Reppermund; Melissa J. Slavin; Henry Brodaty; J. Douglas Crawford; Aihua Xia; Perminder S. Sachdev",institutions:["Beijing Normal University","Neuropsychiatric Research Institute","Prince of Wales Hospital","The University of Melbourne","UNSW Sydney"],countries:["AU","CN","US"],year:2011,journal:"Journal of Neuroscience",citations:208,abstract:"There have been many attempts at explaining age-related cognitive decline on the basis of regional brain changes, with the usual but inconsistent findings being that smaller gray matter volumes in certain brain regions predict worse cognitive performance in specific domains. Additionally, compromised white matter integrity, as suggested by white matter hyperintensities or decreased regional white matter fractional anisotropy, has an adverse impact on cognitive functions. The human brain is, however, a network and it may be more appropriate to relate cognitive functions to properties of the network rather than specific brain regions. We report on graph theory-based analyses of diffusion tensor imaging tract-derived connectivity in a sample of 342 healthy individuals aged 72-92 years. The cognitive domains included processing speed, memory, language, visuospatial, and executive functions. We examined the association of these cognitive assessments with both the connectivity of the whole brain network and individual cortical regions. We found that the efficiency of the whole brain network of cortical fiber connections had an influence on processing speed and visuospatial and executive functions. Correlations between connectivity of specific regions and cognitive assessments were also observed, e.g., stronger connectivity in regions such as superior frontal gyrus and posterior cingulate cortex were associated with better executive function. Similar to the relationship between regional connectivity efficiency and age, greater processing speed was significantly correlated with better connectivity of nearly all the cortical regions. For the first time, regional anatomical connectivity maps related to processing speed and visuospatial and executive functions in the elderly are identified.",keywords:["Cognition","White matter","Fractional anisotropy","Neuroscience","Diffusion MRI","Effects of sleep deprivation on cognitive performance","Posterior cingulate"],concepts:["Cognition","Psychology","White matter","Fractional anisotropy","Neuroscience","Diffusion MRI","Effects of sleep deprivation on cognitive performance","Posterior cingulate"],topics:["Advanced Neuroimaging Techniques and Applications","Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/31/4/1204.full.pdf",is_oa:!0,n_refs:65,n_refs_in_core:14,degree:34,community:1,deg_w:455,betweenness:.0011,pagerank:.00362,eigenvector:.047,pdf_file:null,pdf_downloaded:!1},{id:138,oaid:"W2149687651",doi:"10.3389/fncom.2013.00169",title:"Defining nodes in complex brain networks",authors:[{name:"M. Stanley",institutions:["Wake Forest University"]},{name:"Malaak N. Moussa",institutions:["Wake Forest University"]},{name:"Brielle Paolini",institutions:["Wake Forest University"]},{name:"Robert G. Lyday",institutions:["Wake Forest University"]},{name:"Jonathan H. Burdette",institutions:["Wake Forest University"]},{name:"Paul J. Laurienti",institutions:["Wake Forest University"]}],authorString:"M. Stanley; Malaak N. Moussa; Brielle Paolini; Robert G. Lyday; Jonathan H. Burdette; Paul J. Laurienti",institutions:["Wake Forest University"],countries:["US"],year:2013,journal:"Frontiers in Computational Neuroscience",citations:207,abstract:'Network science holds great promise for expanding our understanding of the human brain in health, disease, development, and aging. Network analyses are quickly becoming the method of choice for analyzing functional MRI data. However, many technical issues have yet to be confronted in order to optimize results. One particular issue that remains controversial in functional brain network analyses is the definition of a network node. In functional brain networks a node represents some predefined collection of brain tissue, and an edge measures the functional connectivity between pairs of nodes. The characteristics of a node, chosen by the researcher, vary considerably in the literature. This manuscript reviews the current state of the art based on published manuscripts and highlights the strengths and weaknesses of three main methods for defining nodes. Voxel-wise networks are constructed by assigning a node to each, equally sized brain area (voxel). The fMRI time-series recorded from each voxel is then used to create the functional network. Anatomical methods utilize atlases to define the nodes based on brain structure. The fMRI time-series from all voxels within the anatomical area are averaged and subsequently used to generate the network. Functional activation methods rely on data from traditional fMRI activation studies, often from databases, to identify network nodes. Such methods identify the peaks or centers of mass from activation maps to determine the location of the nodes. Small (~10-20 millimeter diameter) spheres located at the coordinates of the activation foci are then applied to the data being used in the network analysis. The fMRI time-series from all voxels in the sphere are then averaged, and the resultant time series is used to generate the network. We attempt to clarify the discussion and move the study of complex brain networks forward. While the "correct" method to be used remains an open, possibly unsolvable question that deserves extensive debate and research, we argue that the best method available at the current time is the voxel-wise method.',keywords:["Voxel","Node","Resting state fMRI","Network analysis","Data mining","Neuroscience"],concepts:["Computer science","Voxel","Node (physics)","Resting state fMRI","Artificial intelligence","Network analysis","Data mining"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Mental Health Research Topics"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fncom.2013.00169/pdf",is_oa:!0,n_refs:74,n_refs_in_core:14,degree:30,community:3,deg_w:340,betweenness:.0022,pagerank:.00314,eigenvector:.0207,pdf_file:"Stanley_2013.pdf",pdf_downloaded:!0},{id:139,oaid:"W2049130783",doi:"10.1111/jcpp.12365",title:"Annual Research Review: Growth connectomics – the organization and reorganization of brain networks during normal and abnormal development",authors:[{name:"Petra E. Vértes",institutions:["University of Cambridge","Cambridgeshire and Peterborough NHS Foundation Trust"]},{name:"Edward T. Bullmore",institutions:["GlaxoSmithKline (United Kingdom)","University of Cambridge","Cambridgeshire and Peterborough NHS Foundation Trust"]}],authorString:"Petra E. Vértes; Edward T. Bullmore",institutions:["Cambridgeshire and Peterborough NHS Foundation Trust","GlaxoSmithKline (United Kingdom)","University of Cambridge"],countries:["GB"],year:2014,journal:"Journal of Child Psychology and Psychiatry",citations:207,abstract:"BACKGROUND: We first give a brief introduction to graph theoretical analysis and its application to the study of brain network topology or connectomics. Within this framework, we review the existing empirical data on developmental changes in brain network organization across a range of experimental modalities (including structural and functional MRI, diffusion tensor imaging, magnetoencephalography and electroencephalography in humans). SYNTHESIS: We discuss preliminary evidence and current hypotheses for how the emergence of network properties correlates with concomitant cognitive and behavioural changes associated with development. We highlight some of the technical and conceptual challenges to be addressed by future developments in this rapidly moving field. Given the parallels previously discovered between neural systems across species and over a range of spatial scales, we also review some recent advances in developmental network studies at the cellular scale. We highlight the opportunities presented by such studies and how they may complement neuroimaging in advancing our understanding of brain development. Finally, we note that many brain and mind disorders are thought to be neurodevelopmental in origin and that charting the trajectory of brain network changes associated with healthy development also sets the stage for understanding abnormal network development. CONCLUSIONS: We therefore briefly review the clinical relevance of network metrics as potential diagnostic markers and some recent efforts in computational modelling of brain networks which might contribute to a more mechanistic understanding of neurodevelopmental disorders in future.",keywords:["Connectomics","Neuroscience","Neuroimaging","Connectome","Diffusion MRI","Magnetoencephalography","Cognitive science","Modalities"],concepts:["Connectomics","Neuroscience","Neuroimaging","Connectome","Diffusion MRI","Magnetoencephalography","Cognitive science","Modalities"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Fetal and Pediatric Neurological Disorders"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/jcpp.12365",is_oa:!0,n_refs:185,n_refs_in_core:30,degree:47,community:0,deg_w:963,betweenness:.0033,pagerank:.00701,eigenvector:.0831,pdf_file:null,pdf_downloaded:!1},{id:140,oaid:"W3035809474",doi:"10.1002/jmri.27188",title:"Mapping Structural Connectivity Using Diffusion <scp>MRI</scp>: Challenges and Opportunities",authors:[{name:"Chun‐Hung Yeh",institutions:["The University of Melbourne","Chang Gung University","Florey Institute of Neuroscience and Mental Health","Chang Gung Memorial Hospital","Linkou Chang Gung Memorial Hospital"]},{name:"Derek K. Jones",institutions:["Cardiff University","Australian Catholic University"]},{name:"Xiaoyun Liang",institutions:["The University of Melbourne","Florey Institute of Neuroscience and Mental Health","Australian Catholic University"]},{name:"Maxime Descoteaux",institutions:["Université de Sherbrooke"]},{name:"Alan Connelly",institutions:["The University of Melbourne","Florey Institute of Neuroscience and Mental Health"]}],authorString:"Chun‐Hung Yeh; Derek K. Jones; Xiaoyun Liang; Maxime Descoteaux; Alan Connelly",institutions:["Australian Catholic University","Cardiff University","Chang Gung Memorial Hospital","Chang Gung University","Florey Institute of Neuroscience and Mental Health","Linkou Chang Gung Memorial Hospital","The University of Melbourne","Université de Sherbrooke"],countries:["AU","CA","GB","TW"],year:2020,journal:"Journal of Magnetic Resonance Imaging",citations:200,abstract:"Diffusion MRI-based tractography is the most commonly-used technique when inferring the structural brain connectome, i.e., the comprehensive map of the connections in the brain. The utility of graph theory-a powerful mathematical approach for modeling complex network systems-for analyzing tractography-based connectomes brings important opportunities to interrogate connectome data, providing novel insights into the connectivity patterns and topological characteristics of brain structural networks. When applying this framework, however, there are challenges, particularly regarding methodological and biological plausibility. This article describes the challenges surrounding quantitative tractography and potential solutions. In addition, challenges related to the calculation of global network metrics based on graph theory are discussed.Evidence Level: 5Technical Efficacy: Stage 1.",keywords:["Connectome","Tractography","Diffusion MRI","Connectomics","Human Connectome Project","Graph theory","Graph"],concepts:["Connectome","Tractography","Diffusion MRI","Computer science","Connectomics","Human Connectome Project","Graph theory","Graph"],topics:["Advanced Neuroimaging Techniques and Applications","Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/jmri.27188",is_oa:!0,n_refs:114,n_refs_in_core:19,degree:34,community:0,deg_w:443.5,betweenness:.0028,pagerank:.00384,eigenvector:.0296,pdf_file:null,pdf_downloaded:!1},{id:141,oaid:"W2292856201",doi:"10.1093/cercor/bhw038",title:"Early Development of Functional Network Segregation Revealed by Connectomic Analysis of the Preterm Human Brain",authors:[{name:"Miao Cao",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Yong He",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Zhengjia Dai",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Xuhong Liao",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Tina Jeon",institutions:["Children's Hospital of Philadelphia"]},{name:"Minhui Ouyang",institutions:["Children's Hospital of Philadelphia"]},{name:"Lina F. Chalak",institutions:[]},{name:"Yanchao Bi",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Nancy Rollins",institutions:["The University of Texas Southwestern Medical Center"]},{name:"Qi Dong",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Hao Huang",institutions:["Children's Hospital of Philadelphia","University of Pennsylvania"]}],authorString:"Miao Cao; Yong He; Zhengjia Dai; Xuhong Liao; Tina Jeon; Minhui Ouyang; Lina F. Chalak; Yanchao Bi; Nancy Rollins; Qi Dong; Hao Huang",institutions:["Beijing Normal University","Children's Hospital of Philadelphia","Chinese Institute for Brain Research","The University of Texas Southwestern Medical Center","University of Pennsylvania"],countries:["CN","US"],year:2016,journal:"Cerebral Cortex",citations:199,abstract:"Human brain functional networks are topologically organized with nontrivial connectivity characteristics such as small-worldness and densely linked hubs to support highly segregated and integrated information processing. However, how they emerge and change at very early developmental phases remains poorly understood. Here, we used resting-state functional MRI and voxel-based graph theory analysis to systematically investigate the topological organization of whole-brain networks in 40 infants aged around 31 to 42 postmenstrual weeks. The functional connectivity strength and heterogeneity increased significantly in primary motor, somatosensory, visual, and auditory regions, but much less in high-order default-mode and executive-control regions. The hub and rich-club structures in primary regions were already present at around 31 postmenstrual weeks and exhibited remarkable expansions with age, accompanied by increased local clustering and shortest path length, indicating a transition from a relatively random to a more organized configuration. Moreover, multivariate pattern analysis using support vector regression revealed that individual brain maturity of preterm babies could be predicted by the network connectivity patterns. Collectively, we highlighted a gradually enhanced functional network segregation manner in the third trimester, which is primarily driven by the rapid increases of functional connectivity of the primary regions, providing crucial insights into the topological development patterns prior to birth.",keywords:["Default mode network","Resting state fMRI","Functional connectivity","Neuroscience","Human brain","Somatosensory system","Voxel","Clustering coefficient"],concepts:["Default mode network","Resting state fMRI","Functional connectivity","Neuroscience","Human brain","Somatosensory system","Voxel","Clustering coefficient"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://academic.oup.com/cercor/article-pdf/27/3/1949/25418852/bhw038.pdf",is_oa:!0,n_refs:84,n_refs_in_core:21,degree:35,community:0,deg_w:511.5,betweenness:.0015,pagerank:.00415,eigenvector:.0419,pdf_file:null,pdf_downloaded:!1},{id:142,oaid:"W2063751901",doi:"10.1371/journal.pone.0088297",title:"Structural and Functional Rich Club Organization of the Brain in Children and Adults",authors:[{name:"David S. Grayson",institutions:["Oregon Health & Science University","University of California, Davis"]},{name:"Siddharth Ray",institutions:["Oregon Health & Science University"]},{name:"Samuel D. Carpenter",institutions:["Oregon Health & Science University"]},{name:"Swathi Iyer",institutions:["Oregon Health & Science University"]},{name:"Taciana G. Costa Dias",institutions:["Hospital das Clínicas da Faculdade de Medicina da Universidade de São Paulo","Oregon Health & Science University"]},{name:"Corinne A. Stevens",institutions:["Oregon Health & Science University"]},{name:"Joel T. Nigg",institutions:["Oregon Health & Science University"]},{name:"Damien A. Fair",institutions:["Oregon Health & Science University","Advanced Imaging Research (United States)"]}],authorString:"David S. Grayson; Siddharth Ray; Samuel D. Carpenter; Swathi Iyer; Taciana G. Costa Dias; Corinne A. Stevens; Joel T. Nigg; Damien A. Fair",institutions:["Advanced Imaging Research (United States)","Hospital das Clínicas da Faculdade de Medicina da Universidade de São Paulo","Oregon Health & Science University","University of California, Davis"],countries:["BR","US"],year:2014,journal:"PLoS ONE",citations:199,abstract:"Recent studies using Magnetic Resonance Imaging (MRI) have proposed that the brain's white matter is organized as a rich club, whereby the most highly connected regions of the brain are also highly connected to each other. Here we use both functional and diffusion-weighted MRI in the human brain to investigate whether the rich club phenomena is present with functional connectivity, and how this organization relates to the structural phenomena. We also examine whether rich club regions serve to integrate information between distinct brain systems, and conclude with a brief investigation of the developmental trajectory of rich-club phenomena. In agreement with prior work, both adults and children showed robust structural rich club organization, comprising regions of the superior medial frontal/dACC, medial parietal/PCC, insula, and inferior temporal cortex. We also show that these regions were highly integrated across the brain's major networks. Functional brain networks were found to have rich club phenomena in a similar spatial layout, but a high level of segregation between systems. While no significant differences between adults and children were found structurally, adults showed significantly greater functional rich club organization. This difference appeared to be driven by a specific set of connections between superior parietal, insula, and supramarginal cortex. In sum, this work highlights the existence of both a structural and functional rich club in adult and child populations with some functional changes over development. It also offers a potential target in examining atypical network organization in common developmental brain disorders, such as ADHD and Autism.",keywords:["Supramarginal gyrus","Neuroscience","Club","Insula","Functional magnetic resonance imaging","White matter","Posterior parietal cortex"],concepts:["Supramarginal gyrus","Neuroscience","Club","Insula","Functional magnetic resonance imaging","White matter","Posterior parietal cortex","Psychology"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Neural dynamics and brain function"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0088297&type=printable",is_oa:!0,n_refs:59,n_refs_in_core:13,degree:35,community:0,deg_w:543.5,betweenness:.0025,pagerank:.00449,eigenvector:.0349,pdf_file:"Grayson_2014.pdf",pdf_downloaded:!0},{id:143,oaid:"W2171775073",doi:"10.1371/journal.pone.0024678",title:"Development Trends of White Matter Connectivity in the First Years of Life",authors:[{name:"Pew‐Thian Yap",institutions:["University of North Carolina at Chapel Hill","Imaging Center"]},{name:"Yong Fan",institutions:["University of North Carolina at Chapel Hill","Imaging Center"]},{name:"Yasheng Chen",institutions:["Imaging Center","University of North Carolina at Chapel Hill"]},{name:"John H. Gilmore",institutions:["University of North Carolina at Chapel Hill"]},{name:"Weili Lin",institutions:["University of North Carolina at Chapel Hill","Imaging Center"]},{name:"Dinggang Shen",institutions:["University of North Carolina at Chapel Hill","Imaging Center"]}],authorString:"Pew‐Thian Yap; Yong Fan; Yasheng Chen; John H. Gilmore; Weili Lin; Dinggang Shen",institutions:["Imaging Center","University of North Carolina at Chapel Hill"],countries:["US"],year:2011,journal:"PLoS ONE",citations:198,abstract:"The human brain is organized into a collection of interacting networks with specialized functions to support various cognitive functions. Recent research has reached a consensus that the brain manifests small-world topology, which implicates both global and local efficiency at minimal wiring costs, and also modular organization, which indicates functional segregation and specialization. However, the important questions of how and when the small-world topology and modular organization come into existence remain largely unanswered. Taking a graph theoretic approach, we attempt to shed light on this matter by an in vivo study, using diffusion tensor imaging based fiber tractography, on 39 healthy pediatric subjects with longitudinal data collected at average ages of 2 weeks, 1 year, and 2 years. Our results indicate that the small-world architecture exists at birth with efficiency that increases in later stages of development. In addition, we found that the networks are broad scale in nature, signifying the existence of pivotal connection hubs and resilience of the brain network to random and targeted attacks. We also observed, with development, that the brain network seems to evolve progressively from a local, predominantly proximity based, connectivity pattern to a more distributed, predominantly functional based, connectivity pattern. These observations suggest that the brain in the early years of life has relatively efficient systems that may solve similar information processing problems, but in divergent ways.",keywords:["Connectomics","White matter","Tractography","Diffusion MRI","Modular design","Modularity","Neuroscience"],concepts:["Connectomics","White matter","Tractography","Computer science","Diffusion MRI","Modular design","Modularity (biology)","Neuroscience"],topics:["Advanced Neuroimaging Techniques and Applications","Functional Brain Connectivity Studies","Advanced MRI Techniques and Applications"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0024678&type=printable",is_oa:!0,n_refs:64,n_refs_in_core:12,degree:33,community:1,deg_w:480,betweenness:.0012,pagerank:.00375,eigenvector:.0552,pdf_file:"Yap_2011.pdf",pdf_downloaded:!0},{id:144,oaid:"W2181732012",doi:"10.1371/journal.pcbi.1004533",title:"A Functional Cartography of Cognitive Systems",authors:[{name:"Marcelo G. Mattar",institutions:["University of Pennsylvania"]},{name:"Michael W. Cole",institutions:["Rutgers, The State University of New Jersey"]},{name:"Sharon L. Thompson‐Schill",institutions:["University of Pennsylvania"]},{name:"Danielle S. Bassett",institutions:["University of Pennsylvania"]}],authorString:"Marcelo G. Mattar; Michael W. Cole; Sharon L. Thompson‐Schill; Danielle S. Bassett",institutions:["Rutgers, The State University of New Jersey","University of Pennsylvania"],countries:["US"],year:2015,journal:"PLoS Computational Biology",citations:197,abstract:"One of the most remarkable features of the human brain is its ability to adapt rapidly and efficiently to external task demands. Novel and non-routine tasks, for example, are implemented faster than structural connections can be formed. The neural underpinnings of these dynamics are far from understood. Here we develop and apply novel methods in network science to quantify how patterns of functional connectivity between brain regions reconfigure as human subjects perform 64 different tasks. By applying dynamic community detection algorithms, we identify groups of brain regions that form putative functional communities, and we uncover changes in these groups across the 64-task battery. We summarize these reconfiguration patterns by quantifying the probability that two brain regions engage in the same network community (or putative functional module) across tasks. These tools enable us to demonstrate that classically defined cognitive systems-including visual, sensorimotor, auditory, default mode, fronto-parietal, cingulo-opercular and salience systems-engage dynamically in cohesive network communities across tasks. We define the network role that a cognitive system plays in these dynamics along the following two dimensions: (i) stability vs. flexibility and (ii) connected vs. isolated. The role of each system is therefore summarized by how stably that system is recruited over the 64 tasks, and how consistently that system interacts with other systems. Using this cartography, classically defined cognitive systems can be categorized as ephemeral integrators, stable loners, and anything in between. Our results provide a new conceptual framework for understanding the dynamic integration and recruitment of cognitive systems in enabling behavioral adaptability across both task and rest conditions. This work has important implications for understanding cognitive network reconfiguration during different task sets and its relationship to cognitive effort, individual variation in cognitive performance, and fatigue.",keywords:["Default mode network","Cognition","Salience","Task","Flexibility","Cognitive science"],concepts:["Default mode network","Cognition","Salience (neuroscience)","Computer science","Task (project management)","Flexibility (engineering)","Cognitive science","Artificial intelligence"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1004533&type=printable",is_oa:!0,n_refs:109,n_refs_in_core:15,degree:31,community:0,deg_w:444,betweenness:.0023,pagerank:.0039,eigenvector:.0221,pdf_file:"Mattar_2015.pdf",pdf_downloaded:!0},{id:145,oaid:"W2104841736",doi:"10.1093/schbul/sbt162",title:"Impaired Rich Club Connectivity in Unaffected Siblings of Schizophrenia Patients",authors:[{name:"Guusje Collin",institutions:["Heidelberg University","University Hospital Heidelberg","University Medical Center Utrecht","Hersenstichting"]},{name:"René S. Kahn",institutions:["University Medical Center Utrecht","Hersenstichting"]},{name:"Marcel A. de Reus",institutions:["University Medical Center Utrecht","Hersenstichting"]},{name:"Wiepke Cahn",institutions:["University Medical Center Utrecht","Hersenstichting"]},{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht","Hersenstichting"]}],authorString:"Guusje Collin; René S. Kahn; Marcel A. de Reus; Wiepke Cahn; Martijn P. van den Heuvel",institutions:["Heidelberg University","Hersenstichting","University Hospital Heidelberg","University Medical Center Utrecht"],countries:["DE","NL"],year:2013,journal:"Schizophrenia Bulletin",citations:194,abstract:"Schizophrenia has been conceptualized as a disorder of brain connectivity. Recent studies suggest that brain connectivity may be disproportionally impaired among the so-called rich club. This small core of densely interconnected hub regions has been hypothesized to form an important infrastructure for global brain communication and integration of information across different systems of the brain. Given the heritable nature of the illness, we hypothesized that connectivity disturbances, including abnormal rich club connectivity, may be related to familial vulnerability for schizophrenia. To test this hypothesis, both schizophrenia patients and unaffected siblings of patients were investigated. Rich club organization was examined in networks derived from diffusion-weighted imaging in 40 schizophrenia patients, 54 unaffected siblings of patients, and 51 healthy control subjects. Connectivity between rich club hubs was differentially reduced across groups (P = .014), such that it was highest in controls, intermediate in siblings (7.9% reduced relative to controls), and lowest in patients (19.6% reduced compared to controls). Furthermore, in patients, lower levels of rich club connectivity were found to be related to longer duration of illness and worse overall functioning. Together, these findings suggest that impaired rich club connectivity is related to familial, possibly reflecting genetic, vulnerability for schizophrenia. Our findings support a central role for abnormal rich club organization in the etiology of schizophrenia.",keywords:["Schizophrenia","Club","Etiology","Vulnerability","Psychosis","Neuroscience","Psychiatry"],concepts:["Schizophrenia (object-oriented programming)","Club","Etiology","Vulnerability (computing)","Psychology","Psychosis","Neuroscience","Psychiatry"],topics:["Advanced Neuroimaging Techniques and Applications","Functional Brain Connectivity Studies","Schizophrenia research and treatment"],pdf_url:"https://academic.oup.com/schizophreniabulletin/article-pdf/40/2/438/16975781/sbt162.pdf",is_oa:!0,n_refs:71,n_refs_in_core:17,degree:35,community:0,deg_w:485,betweenness:.0015,pagerank:.00408,eigenvector:.031,pdf_file:null,pdf_downloaded:!1},{id:146,oaid:"W2003870624",doi:"10.1038/ncomms2388",title:"A pairwise maximum entropy model accurately describes resting-state human brain networks",authors:[{name:"Takamitsu Watanabe",institutions:["The University of Tokyo"]},{name:"Satoshi Hirose",institutions:["The University of Tokyo"]},{name:"Hiroyuki Wada",institutions:["NTT Medical Center"]},{name:"Y. Imai",institutions:["NTT Medical Center"]},{name:"Toru Machida",institutions:["NTT Medical Center"]},{name:"Ichiro Shirouzu",institutions:["NTT Medical Center"]},{name:"Seiki Konishi",institutions:["The University of Tokyo"]},{name:"Yasushi Miyashita",institutions:["The University of Tokyo"]},{name:"Naoki Masuda",institutions:["The University of Tokyo"]}],authorString:"Takamitsu Watanabe; Satoshi Hirose; Hiroyuki Wada; Y. Imai; Toru Machida; Ichiro Shirouzu; Seiki Konishi; Yasushi Miyashita; Naoki Masuda",institutions:["NTT Medical Center","The University of Tokyo"],countries:["JP"],year:2013,journal:"Nature Communications",citations:193,abstract:"The resting-state human brain networks underlie fundamental cognitive functions and consist of complex interactions among brain regions. However, the level of complexity of the resting-state networks has not been quantified, which has prevented comprehensive descriptions of the brain activity as an integrative system. Here, we address this issue by demonstrating that a pairwise maximum entropy model, which takes into account region-specific activity rates and pairwise interactions, can be robustly and accurately fitted to resting-state human brain activities obtained by functional magnetic resonance imaging. Furthermore, to validate the approximation of the resting-state networks by the pairwise maximum entropy model, we show that the functional interactions estimated by the pairwise maximum entropy model reflect anatomical connexions more accurately than the conventional functional connectivity method. These findings indicate that a relatively simple statistical model not only captures the structure of the resting-state networks but also provides a possible method to derive physiological information about various large-scale brain networks. During rest, the different regions of the human brain still carry out complex interactions. In this study, a pairwise maximum entropy model is used to quantify the complexity of these interactions during rest, showing that the model is able to capture the structure of the resting-state human brain networks.",keywords:["Pairwise comparison","Resting state fMRI","Principle of maximum entropy","Human brain","Entropy","Functional connectivity"],concepts:["Pairwise comparison","Resting state fMRI","Principle of maximum entropy","Computer science","Human brain","Entropy (arrow of time)","Artificial intelligence","Functional connectivity"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://www.nature.com/articles/ncomms2388.pdf",is_oa:!0,n_refs:62,n_refs_in_core:13,degree:28,community:2,deg_w:272.5,betweenness:.0018,pagerank:.00267,eigenvector:.0165,pdf_file:"Watanabe_2013.pdf",pdf_downloaded:!0},{id:147,oaid:"W3179229384",doi:"10.1038/s41467-021-24306-2",title:"Genetic influences on hub connectivity of the human connectome",authors:[{name:"Aurina Arnatkevičiūtė",institutions:["Monash Health","Monash University"]},{name:"Ben Fulcher",institutions:["The University of Sydney","Monash University"]},{name:"Stuart Oldham",institutions:["Monash University"]},{name:"Jeggan Tiego",institutions:["Monash University"]},{name:"Casey Paquola",institutions:["Montreal Neurological Institute and Hospital","Forschungszentrum Jülich","McGill University"]},{name:"Zachary F. Gerring",institutions:["QIMR Berghofer Medical Research Institute"]},{name:"Kevin Aquino",institutions:["The University of Sydney","Monash University"]},{name:"Ziarih Hawi",institutions:["Monash University"]},{name:"Beth P. Johnson",institutions:["Monash University"]},{name:"Gareth Ball",institutions:["The University of Melbourne","Murdoch Children's Research Institute"]},{name:"Marieke Klein",institutions:["Radboud University Nijmegen","Radboud University Medical Center","University of California San Diego"]},{name:"Gustavo Deco",institutions:["Institució Catalana de Recerca i Estudis Avançats","Universitat Pompeu Fabra","Max Planck Institute for Human Cognitive and Brain Sciences","Monash University"]},{name:"Barbara Franke",institutions:["Radboud University Nijmegen","Radboud University Medical Center"]},{name:"Mark A. Bellgrove",institutions:["Monash University"]},{name:"Alex Fornito",institutions:["Monash University"]}],authorString:"Aurina Arnatkevičiūtė; Ben Fulcher; Stuart Oldham; Jeggan Tiego; Casey Paquola; Zachary F. Gerring; Kevin Aquino; Ziarih Hawi; Beth P. Johnson; Gareth Ball; Marieke Klein; Gustavo Deco et al.",institutions:["Forschungszentrum Jülich","Institució Catalana de Recerca i Estudis Avançats","Max Planck Institute for Human Cognitive and Brain Sciences","McGill University","Monash Health","Monash University","Montreal Neurological Institute and Hospital","Murdoch Children's Research Institute","QIMR Berghofer Medical Research Institute","Radboud University Medical Center","Radboud University Nijmegen","The University of Melbourne","The University of Sydney","Universitat Pompeu Fabra","University of California San Diego"],countries:["AU","CA","DE","ES","NL","US"],year:2021,journal:"Nature Communications",citations:190,abstract:"Brain network hubs are both highly connected and highly inter-connected, forming a critical communication backbone for coherent neural dynamics. The mechanisms driving this organization are poorly understood. Using diffusion-weighted magnetic resonance imaging in twins, we identify a major role for genes, showing that they preferentially influence connectivity strength between network hubs of the human connectome. Using transcriptomic atlas data, we show that connected hubs demonstrate tight coupling of transcriptional activity related to metabolic and cytoarchitectonic similarity. Finally, comparing over thirteen generative models of network growth, we show that purely stochastic processes cannot explain the precise wiring patterns of hubs, and that model performance can be improved by incorporating genetic constraints. Our findings indicate that genes play a strong and preferential role in shaping the functionally valuable, metabolically costly connections between connectome hubs.",keywords:["Connectome","Functional connectivity","Computational biology","Genetics","Neuroscience"],concepts:["Connectome","Biology","Functional connectivity","Computational biology","Genetics","Neuroscience","Computer science"],topics:["Traumatic Brain Injury Research","Genetics and Physical Performance","Cardiovascular Effects of Exercise"],pdf_url:"https://www.nature.com/articles/s41467-021-24306-2.pdf",is_oa:!0,n_refs:105,n_refs_in_core:16,degree:31,community:0,deg_w:387,betweenness:.0011,pagerank:.00352,eigenvector:.0169,pdf_file:"Arnatkeviit_2021.pdf",pdf_downloaded:!0},{id:148,oaid:"W2520835145",doi:"10.1162/netn_a_00002",title:"The modular organization of human anatomical brain networks: Accounting for the cost of wiring",authors:[{name:"Richard F. Betzel",institutions:["University of Pennsylvania"]},{name:"John D. Medaglia",institutions:["University of Pennsylvania"]},{name:"Lia Papadopoulos",institutions:["University of Pennsylvania"]},{name:"Graham L. Baum",institutions:["University of Pennsylvania"]},{name:"Ruben C. Gur",institutions:["University of Pennsylvania"]},{name:"Raquel E. Gur",institutions:["University of Pennsylvania"]},{name:"David R. Roalf",institutions:["University of Pennsylvania"]},{name:"Theodore D. Satterthwaite",institutions:["University of Pennsylvania"]},{name:"Danielle S. Bassett",institutions:["University of Pennsylvania","Philadelphia University"]}],authorString:"Richard F. Betzel; John D. Medaglia; Lia Papadopoulos; Graham L. Baum; Ruben C. Gur; Raquel E. Gur; David R. Roalf; Theodore D. Satterthwaite; Danielle S. Bassett",institutions:["Philadelphia University","University of Pennsylvania"],countries:["US"],year:2017,journal:"Network Neuroscience",citations:187,abstract:"Brain networks are expected to be modular. However, existing techniques for estimating a network's modules make it difficult to assess the influence of organizational principles such as wiring cost reduction on the detected modules. Here we present a modification of an existing module detection algorithm that allowed us to focus on connections that are unexpected under a cost-reduction wiring rule and to identify modules from among these connections. We applied this technique to anatomical brain networks and showed that the modules we detected differ from those detected using the standard technique. We demonstrated that these novel modules are spatially distributed, exhibit unique functional fingerprints, and overlap considerably with rich clubs, giving rise to an alternative and complementary interpretation of the functional roles of specific brain regions. Finally, we demonstrated that, using the modified module detection approach, we can detect modules in a developmental dataset that track normative patterns of maturation. Collectively, these findings support the hypothesis that brain networks are composed of modules and provide additional insight into the function of those modules.",keywords:["Modular design","Cost accounting","Neuroscience","Business","Accounting"],concepts:["Modular design","Cost accounting","Computer science","Neuroscience","Business"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Bioinformatics and Genomic Networks"],pdf_url:"https://www.mitpressjournals.org/doi/pdf/10.1162/NETN_a_00002",is_oa:!0,n_refs:136,n_refs_in_core:17,degree:36,community:0,deg_w:685.5,betweenness:.0018,pagerank:.00556,eigenvector:.0332,pdf_file:"Betzel_2017.pdf",pdf_downloaded:!0},{id:149,oaid:"W1524688107",doi:"10.1523/jneurosci.5043-14.2015",title:"Developmental Changes in Brain Network Hub Connectivity in Late Adolescence",authors:[{name:"Simon Baker",institutions:["The University of Melbourne","Eastern Health","Monash Health","Melbourne Health","Monash University"]},{name:"Dan I. Lubman",institutions:["Eastern Health","Monash University"]},{name:"Murat Yücel",institutions:["The University of Melbourne","Monash Health","Melbourne Health","Monash University"]},{name:"Nicholas B. Allen",institutions:["Orygen Youth Health"]},{name:"Sarah Whittle",institutions:["The University of Melbourne","Melbourne Health"]},{name:"Ben Fulcher",institutions:["Monash Health","Monash University"]},{name:"Andrew Zalesky",institutions:["The University of Melbourne","Melbourne Health"]},{name:"Alex Fornito",institutions:["The University of Melbourne","Monash Health","Melbourne Health","Monash University"]}],authorString:"Simon Baker; Dan I. Lubman; Murat Yücel; Nicholas B. Allen; Sarah Whittle; Ben Fulcher; Andrew Zalesky; Alex Fornito",institutions:["Eastern Health","Melbourne Health","Monash Health","Monash University","Orygen Youth Health","The University of Melbourne"],countries:["AU"],year:2015,journal:"Journal of Neuroscience",citations:186,abstract:'The human brain undergoes substantial development throughout adolescence and into early adulthood. This maturational process is thought to include the refinement of connectivity between putative connectivity hub regions of the brain, which collectively form a dense core that enhances the functional integration of anatomically distributed, and functionally specialized, neural systems. Here, we used longitudinal diffusion magnetic resonance imaging to characterize changes in connectivity between 80 cortical and subcortical anatomical regions over a 2 year period in 31 adolescents between the ages of 15 and 19 years. Connectome-wide analysis indicated that only a small subset of connections showed evidence of statistically significant developmental change over the study period, with 8% and 6% of connections demonstrating decreased and increased structural connectivity, respectively. Nonetheless, these connections linked 93% and 90% of the 80 regions, respectively, pointing to a selective, yet anatomically distributed pattern of developmental changes that involves most of the brain. Hub regions showed a distinct tendency to be highly connected to each other, indicating robust "rich-club" organization. Moreover, connectivity between hubs was disproportionately influenced by development, such that connectivity between subcortical hubs decreased over time, whereas frontal-subcortical and frontal-parietal hub-hub connectivity increased over time. These findings suggest that late adolescence is characterized by selective, yet significant remodeling of hub-hub connectivity, with the topological organization of hubs shifting emphasis from subcortical hubs in favor of an increasingly prominent role for frontal hub regions.',keywords:["Connectome","Neuroscience","Human Connectome Project","Functional connectivity","Diffusion MRI","Period"],concepts:["Connectome","Neuroscience","Human Connectome Project","Functional connectivity","Diffusion MRI","Period (music)","Biology","Psychology"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/35/24/9078.full.pdf",is_oa:!0,n_refs:69,n_refs_in_core:18,degree:36,community:0,deg_w:467.5,betweenness:.0023,pagerank:.00401,eigenvector:.0265,pdf_file:null,pdf_downloaded:!1},{id:150,oaid:"W2162763711",doi:"10.1523/jneurosci.0752-14.2014",title:"Linking Macroscale Graph Analytical Organization to Microscale Neuroarchitectonics in the Macaque Connectome",authors:[{name:"Lianne H. Scholtens",institutions:["University Medical Center Utrecht"]},{name:"Ruben Schmidt",institutions:["University Medical Center Utrecht"]},{name:"Marcel A. de Reus",institutions:["University Medical Center Utrecht"]},{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]}],authorString:"Lianne H. Scholtens; Ruben Schmidt; Marcel A. de Reus; Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"],countries:["NL"],year:2014,journal:"Journal of Neuroscience",citations:183,abstract:`Macroscale connectivity of the mammalian brain has been shown to display several characteristics of an efficient communication network architecture. In parallel, at the microscopic scale, histological studies have extensively revealed large interregional variation in cortical neural architectonics. However, how these two "scales" of cerebrum organization are linked remains an open question. Collating and combining data across multiple studies on the cortical cytoarchitecture of the macaque cortex with information on macroscale anatomical wiring derived from tract tracing studies, this study focuses on examining the interplay between macroscale organization of the macaque connectome and microscale cortical neuronal architecture. Our findings show that both macroscale degree as well as the topological role in the overall network are related to the level of neuronal complexity of cortical regions at the microscale, showing (among several effects) a positive overall association between macroscale degree and metrics of microscale pyramidal complexity. Macroscale hub regions, together forming a densely interconnected "rich club," are noted to display a high level of neuronal complexity, findings supportive of a high level of integrative neuronal processes to occur in these regions. Together, we report on cross-scale observations that jointly suggest that a region's microscale neuronal architecture is tuned to its role in the global brain network.`,keywords:["Microscale chemistry","Cytoarchitecture","Neuroscience","Connectome","Macaque","Mammalian brain","Nerve net"],concepts:["Microscale chemistry","Cytoarchitecture","Neuroscience","Connectome","Macaque","Biology","Mammalian brain","Nerve net"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/34/36/12192.full.pdf",is_oa:!0,n_refs:88,n_refs_in_core:20,degree:38,community:0,deg_w:506,betweenness:.002,pagerank:.00428,eigenvector:.0307,pdf_file:null,pdf_downloaded:!1},{id:151,oaid:"W2807642177",doi:"10.7150/thno.23772",title:"Rich club disturbances of the human connectome from subjective cognitive decline to Alzheimer's disease",authors:[{name:"Tianyi Yan",institutions:["Beijing Institute of Technology","Ministry of Industry and Information Technology"]},{name:"Wenhui Wang",institutions:["Beijing Institute of Technology","Ministry of Industry and Information Technology"]},{name:"Yang Liu",institutions:["Capital Medical University"]},{name:"Kewei Chen",institutions:["Good Samaritan Medical Center","Banner Alzheimer’s Institute"]},{name:"Rong Chen",institutions:["University of Maryland, Baltimore","University of Maryland Medical Center"]},{name:"Ying Han",institutions:["Capital Medical University","Beijing Geriatric Hospital","National Clinical Research Center for Digestive Diseases","Chinese Institute for Brain Research"]}],authorString:"Tianyi Yan; Wenhui Wang; Yang Liu; Kewei Chen; Rong Chen; Ying Han",institutions:["Banner Alzheimer’s Institute","Beijing Geriatric Hospital","Beijing Institute of Technology","Capital Medical University","Chinese Institute for Brain Research","Good Samaritan Medical Center","Ministry of Industry and Information Technology","National Clinical Research Center for Digestive Diseases","University of Maryland Medical Center","University of Maryland, Baltimore"],countries:["CN","US"],year:2018,journal:"Theranostics",citations:182,abstract:"Alzheimer's disease (AD) has a preclinical phase that can last for decades prior to clinical dementia onset. Subjective cognitive decline (SCD) is regarded as the last preclinical AD stage prior to the development of amnestic mild cognitive decline (aMCI) and AD dementia (d-AD). The analysis of brain structural networks based on diffusion tensor imaging (DTI) has identified the so-called 'rich club', a set of cortical regions highly connected to each other, with other regions referred to as peripheral. It has been reported that rich club architecture is affected by regional atrophy and connectivity, which are reduced in patients with aMCI and d-AD.",keywords:["Dementia","Cognitive decline","Connectome","Neuroscience","Cognition","Disease","Diffusion MRI","Medicine"],concepts:["Dementia","Cognitive decline","Connectome","Neuroscience","Cognition","Disease","Diffusion MRI","Medicine"],topics:["Advanced Neuroimaging Techniques and Applications","Functional Brain Connectivity Studies","Dementia and Cognitive Impairment Research"],pdf_url:"https://www.thno.org/v08p3237.pdf",is_oa:!0,n_refs:90,n_refs_in_core:20,degree:34,community:0,deg_w:351,betweenness:.0023,pagerank:.00315,eigenvector:.0267,pdf_file:"Yan_2018.pdf",pdf_downloaded:!0},{id:152,oaid:"W3106195219",doi:"10.1038/s41467-017-01189-w",title:"The diverse club",authors:[{name:"Maxwell A. Bertolero",institutions:["University of Pennsylvania","University of California, Berkeley"]},{name:"B.T. Thomas Yeo",institutions:["National University of Singapore","National University Heart Centre Singapore","A*STAR-NUS Clinical Imaging Research Centre"]},{name:"Mark D’Esposito",institutions:["University of California, Berkeley"]}],authorString:"Maxwell A. Bertolero; B.T. Thomas Yeo; Mark D’Esposito",institutions:["A*STAR-NUS Clinical Imaging Research Centre","National University Heart Centre Singapore","National University of Singapore","University of California, Berkeley","University of Pennsylvania"],countries:["SG","US"],year:2017,journal:"Nature Communications",citations:181,abstract:'A complex system can be represented and analyzed as a network, where nodes represent the units of the network and edges represent connections between those units. For example, a brain network represents neurons as nodes and axons between neurons as edges. In many networks, some nodes have a disproportionately high number of edges as well as many edges between each other and are referred to as the "rich club". In many different networks, the nodes of this club are assumed to support global network integration. Here we show that another set of nodes, which have edges diversely distributed across the network, form a "diverse club". The diverse club exhibits, to a greater extent than the rich club, properties consistent with an integrative network function-these nodes are more highly interconnected and their edges are more critical for efficient global integration. Finally, these two clubs potentially evolved via distinct selection pressures.',keywords:["Club","Set","Global network","Function","Selection","Computer network","Distributed computing"],concepts:["Club","Computer science","Set (abstract data type)","Global network","Function (biology)","Selection (genetic algorithm)","Computer network","Distributed computing"],topics:["Neural dynamics and brain function","Complex Network Analysis Techniques","Functional Brain Connectivity Studies"],pdf_url:"https://www.nature.com/articles/s41467-017-01189-w.pdf",is_oa:!0,n_refs:79,n_refs_in_core:14,degree:28,community:0,deg_w:331,betweenness:.0013,pagerank:.00311,eigenvector:.0156,pdf_file:"Bertolero_2017.pdf",pdf_downloaded:!0},{id:153,oaid:"W2171554905",doi:"10.1098/rstb.2014.0165",title:"Dwelling quietly in the rich club: brain network determinants of slow cortical fluctuations",authors:[{name:"Leonardo L. Gollo",institutions:["QIMR Berghofer Medical Research Institute"]},{name:"Andrew Zalesky",institutions:["The University of Melbourne","Melbourne Health"]},{name:"R. Matthew Hutchison",institutions:["Harvard University"]},{name:"Martijn van den Heuvel",institutions:["University Medical Center Utrecht"]},{name:"Michael Breakspear",institutions:["QIMR Berghofer Medical Research Institute","Metro South Health"]}],authorString:"Leonardo L. Gollo; Andrew Zalesky; R. Matthew Hutchison; Martijn van den Heuvel; Michael Breakspear",institutions:["Harvard University","Melbourne Health","Metro South Health","QIMR Berghofer Medical Research Institute","The University of Melbourne","University Medical Center Utrecht"],countries:["AU","NL","US"],year:2015,journal:"Philosophical Transactions of the Royal Society B Biological Sciences",citations:181,abstract:"For more than a century, cerebral cartography has been driven by investigations of structural and morphological properties of the brain across spatial scales and the temporal/functional phenomena that emerge from these underlying features. The next era of brain mapping will be driven by studies that consider both of these components of brain organization simultaneously--elucidating their interactions and dependencies. Using this guiding principle, we explored the origin of slowly fluctuating patterns of synchronization within the topological core of brain regions known as the rich club, implicated in the regulation of mood and introspection. We find that a constellation of densely interconnected regions that constitute the rich club (including the anterior insula, amygdala and precuneus) play a central role in promoting a stable, dynamical core of spontaneous activity in the primate cortex. The slow timescales are well matched to the regulation of internal visceral states, corresponding to the somatic correlates of mood and anxiety. In contrast, the topology of the surrounding 'feeder' cortical regions shows unstable, rapidly fluctuating dynamics likely to be crucial for fast perceptual processes. We discuss these findings in relation to psychiatric disorders and the future of connectomics.",keywords:["Amygdala","Synchronization","Mood","Human brain","Nerve net","Perception","Network dynamics","Relation"],concepts:["Neuroscience","Psychology","Amygdala","Biology","Synchronization (alternating current)","Mood","Human brain","Nerve net"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Transcranial Magnetic Stimulation Studies"],pdf_url:"https://royalsocietypublishing.org/doi/pdf/10.1098/rstb.2014.0165",is_oa:!0,n_refs:117,n_refs_in_core:12,degree:29,community:0,deg_w:288.5,betweenness:.0015,pagerank:.00284,eigenvector:.0126,pdf_file:"Gollo_2015.pdf",pdf_downloaded:!0},{id:154,oaid:"W1978675410",doi:"10.1371/journal.pone.0055347",title:"Topological Organization of Functional Brain Networks in Healthy Children: Differences in Relation to Age, Sex, and Intelligence",authors:[{name:"Kai Wu",institutions:["Tohoku University","Institute of Aging","South China University of Technology"]},{name:"Yasuyuki Taki",institutions:["Tohoku University"]},{name:"Kazunori Sato",institutions:["Tohoku University"]},{name:"Hiroshi Hashizume",institutions:["Tohoku University"]},{name:"Yuko Sassa",institutions:["Tohoku University"]},{name:"Hikaru Takeuchi",institutions:["Tohoku University"]},{name:"Benjamin Thyreau",institutions:["Tohoku University"]},{name:"Yong He",institutions:["Beijing Normal University"]},{name:"Alan C. Evans",institutions:["Montreal Neurological Institute and Hospital","McGill University"]},{name:"Xiaobo Li",institutions:["Yeshiva University","Albert Einstein College of Medicine"]},{name:"Ryuta Kawashima",institutions:["Tohoku University"]},{name:"Hiroshi Fukuda",institutions:["Tohoku University"]}],authorString:"Kai Wu; Yasuyuki Taki; Kazunori Sato; Hiroshi Hashizume; Yuko Sassa; Hikaru Takeuchi; Benjamin Thyreau; Yong He; Alan C. Evans; Xiaobo Li; Ryuta Kawashima; Hiroshi Fukuda",institutions:["Albert Einstein College of Medicine","Beijing Normal University","Institute of Aging","McGill University","Montreal Neurological Institute and Hospital","South China University of Technology","Tohoku University","Yeshiva University"],countries:["CA","CN","JP","US"],year:2013,journal:"PLoS ONE",citations:179,abstract:"Recent studies have demonstrated developmental changes of functional brain networks derived from functional connectivity using graph theoretical analysis, which has been rapidly translated to studies of brain network organization. However, little is known about sex- and IQ-related differences in the topological organization of functional brain networks during development. In this study, resting-state fMRI (rs-fMRI) was used to map the functional brain networks in 51 healthy children. We then investigated the effects of age, sex, and IQ on economic small-world properties and regional nodal properties of the functional brain networks. At a global level of whole networks, we found significant age-related increases in the small-worldness and local efficiency, significant higher values of the global efficiency in boys compared with girls, and no significant IQ-related difference. Age-related increases in the regional nodal properties were found predominately in the frontal brain regions, whereas the parietal, temporal, and occipital brain regions showed age-related decreases. Significant sex-related differences in the regional nodal properties were found in various brain regions, primarily related to the default mode, language, and vision systems. Positive correlations between IQ and the regional nodal properties were found in several brain regions related to the attention system, whereas negative correlations were found in various brain regions primarily involved in the default mode, emotion, and language systems. Together, our findings of the network topology of the functional brain networks in healthy children and its relationship with age, sex, and IQ bring new insights into the understanding of brain maturation and cognitive development during childhood and adolescence.",keywords:["Default mode network","Resting state fMRI","Neuroscience","Human brain","Functional integration","Functional connectivity","Developmental psychology"],concepts:["Default mode network","Resting state fMRI","Psychology","Neuroscience","Human brain","Functional integration","Functional connectivity","Developmental psychology"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0055347&type=printable",is_oa:!0,n_refs:111,n_refs_in_core:27,degree:48,community:1,deg_w:1028,betweenness:.0026,pagerank:.00712,eigenvector:.1182,pdf_file:"Wu_2013.pdf",pdf_downloaded:!0},{id:155,oaid:"W1574443118",doi:"10.1523/jneurosci.1448-13.2013",title:"Rich Club Organization and Intermodule Communication in the Cat Connectome",authors:[{name:"Marcel A. de Reus",institutions:["University Medical Center Utrecht"]},{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]}],authorString:"Marcel A. de Reus; Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"],countries:["NL"],year:2013,journal:"Journal of Neuroscience",citations:172,abstract:'Macroscopic brain networks have been shown to display several properties of an efficient communication architecture. In light of global communication, the formation of a densely connected neural "rich club" of hubs is of particular interest, because brain hubs have been suggested to play a key role in enabling short communication pathways within neural networks. Here, analyzing the cat connectome as reconstructed from tract tracing data (Scannell et al., 1995), we provide several lines of evidence of an important role of the structural rich club to interlink functional domains. First, rich club hub nodes were found to be mostly present at the boundaries between functional communities and well represented among intermodule hubs, displaying a diverse connectivity profile. Second, rich club connections, linking nodes of the rich club, and feeder connections, linking non-rich club nodes to rich club nodes, were found to comprise 86% of the intermodule connections, whereas local connections between peripheral nodes mostly spanned between nodes of the same functional community. Third, almost 90% of all intermodule communication paths were found to follow a sequence or "path motif" that involved rich club or feeder edges and thus traversed a rich club node. Together, our findings provide evidence of the structural rich club to form a central infrastructure for intermodule communication in the brain.',keywords:["Club","Connectome","Node","Neuroscience","Communication","Functional connectivity"],concepts:["Club","Connectome","Computer science","Node (physics)","Neuroscience","Communication"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.jneurosci.org/content/jneuro/33/32/12929.full.pdf",is_oa:!0,n_refs:49,n_refs_in_core:15,degree:44,community:0,deg_w:700,betweenness:.0027,pagerank:.00567,eigenvector:.0418,pdf_file:null,pdf_downloaded:!1},{id:156,oaid:"W2314682713",doi:"10.3389/fnana.2016.00025",title:"Toward Developmental Connectomics of the Human Brain",authors:[{name:"Miao Cao",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Hao Huang",institutions:["University of Pennsylvania","Children's Hospital of Philadelphia"]},{name:"Yun Peng",institutions:["Capital Medical University","Beijing Children’s Hospital"]},{name:"Qi Dong",institutions:["Beijing Normal University","Chinese Institute for Brain Research"]},{name:"Yong He",institutions:["Chinese Institute for Brain Research","Beijing Normal University"]}],authorString:"Miao Cao; Hao Huang; Yun Peng; Qi Dong; Yong He",institutions:["Beijing Children’s Hospital","Beijing Normal University","Capital Medical University","Children's Hospital of Philadelphia","Chinese Institute for Brain Research","University of Pennsylvania"],countries:["CN","US"],year:2016,journal:"Frontiers in Neuroanatomy",citations:157,abstract:"Imaging connectomics based on graph theory has become an effective and unique methodological framework for studying structural and functional connectivity patterns of the developing brain. Normal brain development is characterized by continuous and significant network evolution throughout infancy, childhood, and adolescence, following specific maturational patterns. Disruption of these normal changes is associated with neuropsychiatric developmental disorders, such as autism spectrum disorders or attention-deficit hyperactivity disorder. In this review, we focused on the recent progresses regarding typical and atypical development of human brain networks from birth to early adulthood, using a connectomic approach. Specifically, by the time of birth, structural networks already exhibit adult-like organization, with global efficient small-world and modular structures, as well as hub regions and rich-clubs acting as communication backbones. During development, the structure networks are fine-tuned, with increased global integration and robustness and decreased local segregation, as well as the strengthening of the hubs. In parallel, functional networks undergo more dramatic changes during maturation, with both increased integration and segregation during development, as brain hubs shift from primary regions to high order functioning regions, and the organization of modules transitions from a local anatomical emphasis to a more distributed architecture. These findings suggest that structural networks develop earlier than functional networks; meanwhile functional networks demonstrate more dramatic maturational changes with the evolution of structural networks serving as the anatomical backbone. In this review, we also highlighted topologically disorganized characteristics in structural and functional brain networks in several major developmental neuropsychiatric disorders (e.g., autism spectrum disorders, attention-deficit hyperactivity disorder and developmental dyslexia). Collectively, we showed that delineation of the brain network from a connectomics perspective offers a unique and refreshing view of both normal development and neuropsychiatric disorders.",keywords:["Connectomics","Neuroscience","Connectome","Autism spectrum disorder","Autism","Brain development","Functional connectivity"],concepts:["Connectomics","Neuroscience","Connectome","Autism spectrum disorder","Autism","Psychology","Brain development","Functional connectivity"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnana.2016.00025/pdf",is_oa:!0,n_refs:151,n_refs_in_core:37,degree:52,community:0,deg_w:931.5,betweenness:.0048,pagerank:.00691,eigenvector:.0776,pdf_file:"Cao_2016_b.pdf",pdf_downloaded:!0},{id:157,oaid:"W2621395617",doi:"10.1038/s41598-017-03420-6",title:"The dynamic functional core network of the human brain at rest",authors:[{name:"Aya Kabbara",institutions:["Inserm","Lebanese University","Laboratoire Traitement du Signal et de l'Image","Université de Rennes"]},{name:"Wassim El Falou",institutions:["Lebanese University"]},{name:"Mohamad Khalil",institutions:["Lebanese University"]},{name:"Fabrice Wendling",institutions:["Inserm","Laboratoire Traitement du Signal et de l'Image","Université de Rennes"]},{name:"Mahmoud Hassan",institutions:["Inserm","Laboratoire Traitement du Signal et de l'Image","Université de Rennes"]}],authorString:"Aya Kabbara; Wassim El Falou; Mohamad Khalil; Fabrice Wendling; Mahmoud Hassan",institutions:["Inserm","Laboratoire Traitement du Signal et de l'Image","Lebanese University","Université de Rennes"],countries:["FR","LB"],year:2017,journal:"Scientific Reports",citations:152,abstract:"The human brain is an inherently complex and dynamic system. Even at rest, functional brain networks dynamically reconfigure in a well-organized way to warrant an efficient communication between brain regions. However, a precise characterization of this reconfiguration at very fast time-scale (hundreds of millisecond) during rest remains elusive. In this study, we used dense electroencephalography data recorded during task-free paradigm to track the fast temporal dynamics of spontaneous brain networks. Results obtained from network-based analysis methods revealed the existence of a functional dynamic core network formed of a set of key brain regions that ensure segregation and integration functions. Brain regions within this functional core share high betweenness centrality, strength and vulnerability (high impact on the network global efficiency) and low clustering coefficient. These regions are mainly located in the cingulate and the medial frontal cortex. In particular, most of the identified hubs were found to belong to the Default Mode Network. Results also revealed that the same central regions may dynamically alternate and play the role of either provincial (local) or connector (global) hubs.",keywords:["Betweenness centrality","Default mode network","Dynamic functional connectivity","Neuroscience","Human brain","Network dynamics","Core"],concepts:["Betweenness centrality","Default mode network","Computer science","Dynamic functional connectivity","Neuroscience","Human brain","Network dynamics","Core (optical fiber)"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","EEG and Brain-Computer Interfaces"],pdf_url:"https://www.nature.com/articles/s41598-017-03420-6.pdf",is_oa:!0,n_refs:98,n_refs_in_core:21,degree:35,community:0,deg_w:505,betweenness:.0029,pagerank:.00418,eigenvector:.0392,pdf_file:"Kabbara_2017.pdf",pdf_downloaded:!0},{id:158,oaid:"W2895588666",doi:"10.1038/s41380-018-0267-2",title:"Connectomics of bipolar disorder: a critical review, and evidence for dynamic instabilities within interoceptive networks",authors:[{name:"Alistair Perry",institutions:["QIMR Berghofer Medical Research Institute","Max Planck Institute for Human Development","Max Planck Institute for the History of Science","University College London"]},{name:"Gloria Roberts",institutions:["Black Dog Institute","UNSW Sydney","Prince of Wales Hospital"]},{name:"Philip B. Mitchell",institutions:["Black Dog Institute","UNSW Sydney","Prince of Wales Hospital"]},{name:"Michael Breakspear",institutions:["QIMR Berghofer Medical Research Institute","Metro South Health"]}],authorString:"Alistair Perry; Gloria Roberts; Philip B. Mitchell; Michael Breakspear",institutions:["Black Dog Institute","Max Planck Institute for Human Development","Max Planck Institute for the History of Science","Metro South Health","Prince of Wales Hospital","QIMR Berghofer Medical Research Institute","UNSW Sydney","University College London"],countries:["AU","DE","GB"],year:2018,journal:"Molecular Psychiatry",citations:150,abstract:'The notion that specific cognitive and emotional processes arise from functionally distinct brain regions has lately shifted toward a connectivity-based approach that emphasizes the role of network-mediated integration across regions. The clinical neurosciences have likewise shifted from a predominantly lesion-based approach to a connectomic paradigm-framing disorders as diverse as stroke, schizophrenia (SCZ), and dementia as "dysconnection syndromes". Here we position bipolar disorder (BD) within this paradigm. We first summarise the disruptions in structural, functional and effective connectivity that have been documented in BD. Not surprisingly, these disturbances show a preferential impact on circuits that support emotional processes, cognitive control and executive functions. Those at high risk (HR) for BD also show patterns of connectivity that differ from both matched control populations and those with BD, and which may thus speak to neurobiological markers of both risk and resilience. We highlight research fields that aim to link brain network disturbances to the phenotype of BD, including the study of large-scale brain dynamics, the principles of network stability and control, and the study of interoception (the perception of physiological states). Together, these findings suggest that the affective dysregulation of BD arises from dynamic instabilities in interoceptive circuits which subsequently impact on fear circuitry and cognitive control systems. We describe the resulting disturbance as a "psychosis of interoception".',keywords:["Bipolar disorder","Neuroscience","Cognition","Interoception","Schizophrenia","Dementia","Psychosis"],concepts:["Bipolar disorder","Neuroscience","Psychology","Cognition","Interoception","Schizophrenia (object-oriented programming)","Dementia","Psychosis"],topics:["Functional Brain Connectivity Studies","Bipolar Disorder and Treatment","Psychosomatic Disorders and Their Treatments"],pdf_url:"https://www.nature.com/articles/s41380-018-0267-2.pdf",is_oa:!0,n_refs:297,n_refs_in_core:27,degree:41,community:0,deg_w:674,betweenness:.0032,pagerank:.00527,eigenvector:.0487,pdf_file:"Perry_2018.pdf",pdf_downloaded:!0},{id:159,oaid:"W2149919638",doi:"10.1371/journal.pone.0094115",title:"Altered Network Topologies and Hub Organization in Adults with Autism: A Resting-State fMRI Study",authors:[{name:"Takashi Itahashi",institutions:["Showa University"]},{name:"Takashi Yamada",institutions:["Showa University"]},{name:"Hiromi Watanabe",institutions:["Showa University"]},{name:"Motoaki Nakamura",institutions:["Kanagawa Rehabilitation Hospital","Showa University"]},{name:"Daiki Jimbo",institutions:["Showa University"]},{name:"Seiji Shioda",institutions:["Showa University"]},{name:"Kazuo Toriizuka",institutions:["Showa University"]},{name:"Nobumasa Kato",institutions:["Showa University"]},{name:"Ryuichiro Hashimoto",institutions:["Tokyo Metropolitan University","Showa University"]}],authorString:"Takashi Itahashi; Takashi Yamada; Hiromi Watanabe; Motoaki Nakamura; Daiki Jimbo; Seiji Shioda; Kazuo Toriizuka; Nobumasa Kato; Ryuichiro Hashimoto",institutions:["Kanagawa Rehabilitation Hospital","Showa University","Tokyo Metropolitan University"],countries:["JP"],year:2014,journal:"PLoS ONE",citations:149,abstract:'Recent functional magnetic resonance imaging (fMRI) studies on autism spectrum condition (ASC) have identified dysfunctions in specific brain networks involved in social and non-social cognition that persist into adulthood. Although increasing numbers of fMRI studies have revealed atypical functional connectivity in the adult ASC brain, such functional alterations at the network level have not yet been fully characterized within the recently developed graph-theoretical framework. Here, we applied a graph-theoretical analysis to resting-state fMRI data acquired from 46 adults with ASC and 46 age- and gender-matched controls, to investigate the topological properties and organization of autistic brain network. Analyses of global metrics revealed that, relative to the controls, participants with ASC exhibited significant decreases in clustering coefficient and characteristic path length, indicating a shift towards randomized organization. Furthermore, analyses of local metrics revealed a significantly altered organization of the hub nodes in ASC, as shown by analyses of hub disruption indices using multiple local metrics and by a loss of "hubness" in several nodes (e.g., the bilateral superior temporal sulcus, right dorsolateral prefrontal cortex, and precuneus) that are critical for social and non-social cognitive functions. In particular, local metrics of the anterior cingulate cortex consistently showed significant negative correlations with the Autism-Spectrum Quotient score. Our results demonstrate altered patterns of global and local topological properties that may underlie impaired social and non-social cognition in ASC.',keywords:["Precuneus","Autism","Functional magnetic resonance imaging","Resting state fMRI","Prefrontal cortex","Autism spectrum disorder","Cognition","Neuroscience"],concepts:["Precuneus","Autism","Functional magnetic resonance imaging","Resting state fMRI","Prefrontal cortex","Autism spectrum disorder","Cognition","Neuroscience"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0094115&type=printable",is_oa:!0,n_refs:122,n_refs_in_core:20,degree:35,community:3,deg_w:447,betweenness:.0023,pagerank:.00376,eigenvector:.0384,pdf_file:"Itahashi_2014.pdf",pdf_downloaded:!0},{id:160,oaid:"W2766143187",doi:"10.1155/2017/8362741",title:"Complex Brain Network Analysis and Its Applications to Brain Disorders: A Survey",authors:[{name:"Jin Liu",institutions:["Central South University"]},{name:"Min Li",institutions:["Central South University"]},{name:"Yi Pan",institutions:["Georgia State University"]},{name:"Wei Lan",institutions:["Central South University"]},{name:"Ruiqing Zheng",institutions:["Central South University"]},{name:"Fang‐Xiang Wu",institutions:["University of Saskatchewan"]},{name:"Jianxin Wang",institutions:["Central South University"]}],authorString:"Jin Liu; Min Li; Yi Pan; Wei Lan; Ruiqing Zheng; Fang‐Xiang Wu; Jianxin Wang",institutions:["Central South University","Georgia State University","University of Saskatchewan"],countries:["CA","CN","US"],year:2017,journal:"Complexity",citations:148,abstract:"It is well known that most brain disorders are complex diseases, such as Alzheimer’s disease (AD) and schizophrenia (SCZ). In general, brain regions and their interactions can be modeled as complex brain network, which describe highly efficient information transmission in a brain. Therefore, complex brain network analysis plays an important role in the study of complex brain diseases. With the development of noninvasive neuroimaging and electrophysiological techniques, experimental data can be produced for constructing complex brain networks. In recent years, researchers have found that brain networks constructed by using neuroimaging data and electrophysiological data have many important topological properties, such as small-world property, modularity, and rich club. More importantly, many brain disorders have been found to be associated with the abnormal topological structures of brain networks. These findings provide not only a new perspective to explore the pathological mechanisms of brain disorders, but also guidance for early diagnosis and treatment of brain disorders. The purpose of this survey is to provide a comprehensive overview for complex brain network analysis and its applications to brain disorders.",keywords:["Neuroimaging","Neuroscience","Modularity","Schizophrenia","Brain disease","Complex network"],concepts:["Neuroimaging","Neuroscience","Modularity (biology)","Schizophrenia (object-oriented programming)","Brain disease","Complex network","Computer science","Psychology"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"http://downloads.hindawi.com/journals/complexity/2017/8362741.pdf",is_oa:!0,n_refs:169,n_refs_in_core:21,degree:36,community:0,deg_w:585,betweenness:.0026,pagerank:.00461,eigenvector:.0516,pdf_file:null,pdf_downloaded:!1},{id:161,oaid:"W2012249671",doi:"10.1016/j.nicl.2013.12.005",title:"Altered network properties of the fronto-parietal network and the thalamus in impaired consciousness",authors:[{name:"Julia Crone",institutions:["Paracelsus Medical University","Christian Doppler Klinik","University of Salzburg"]},{name:"Andrea Soddu",institutions:["Western University","University of Liège"]},{name:"Yvonne Höller",institutions:["Paracelsus Medical University","Christian Doppler Klinik","University of Salzburg"]},{name:"Audrey Vanhaudenhuyse",institutions:["University of Liège"]},{name:"Matthias Schurz",institutions:["University of Salzburg"]},{name:"Jürgen Bergmann",institutions:["Christian Doppler Klinik","Paracelsus Medical University"]},{name:"Elisabeth Schmid",institutions:["Christian Doppler Klinik","Paracelsus Medical University"]},{name:"Eugen Trinka",institutions:["Christian Doppler Klinik","Paracelsus Medical University"]},{name:"Steven Laureys",institutions:["University of Liège"]},{name:"Martin Kronbichler",institutions:["Christian Doppler Klinik","Paracelsus Medical University","University of Salzburg"]}],authorString:"Julia Crone; Andrea Soddu; Yvonne Höller; Audrey Vanhaudenhuyse; Matthias Schurz; Jürgen Bergmann; Elisabeth Schmid; Eugen Trinka; Steven Laureys; Martin Kronbichler",institutions:["Christian Doppler Klinik","Paracelsus Medical University","University of Liège","University of Salzburg","Western University"],countries:["AT","BE","CA"],year:2014,journal:"NeuroImage Clinical",citations:141,abstract:"Recovery of consciousness has been associated with connectivity in the frontal cortex and parietal regions modulated by the thalamus. To examine this model and to relate alterations to deficits in cognitive functioning and conscious processing, we investigated topological network properties in patients with chronic disorders of consciousness recovered from coma. Resting state fMRI data of 34 patients with unresponsive wakefulness syndrome and 25 in minimally conscious state were compared to 28 healthy controls. We investigated global and local network characteristics. Additionally, behavioral measures were correlated with the local metrics of 28 regions within the fronto-parietal network and the thalamus. In chronic disorders of consciousness, modularity at the global level was reduced suggesting a disturbance in the optimal balance between segregation and integration. Moreover, network properties were altered in several regions which are associated with conscious processing (particularly, in medial parietal, and frontal regions, as well as in the thalamus). Between minimally conscious and unconscious patients the local efficiency of medial parietal regions differed. Alterations in the thalamus were particularly evident in non-conscious patients. Most of the regions affected in patients with impaired consciousness belong to the so-called 'rich club' of highly interconnected central nodes. Disturbances in their topological characteristics have severe impact on information integration and are reflected in deficits in cognitive functioning probably leading to a total breakdown of consciousness.",keywords:["Thalamus","Minimally conscious state","Neuroscience","Persistent vegetative state","Consciousness","Wakefulness","Resting state fMRI"],concepts:["Thalamus","Minimally conscious state","Neuroscience","Persistent vegetative state","Consciousness","Wakefulness","Psychology","Resting state fMRI"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Traumatic Brain Injury Research"],pdf_url:"https://doi.org/10.1016/j.nicl.2013.12.005",is_oa:!0,n_refs:76,n_refs_in_core:13,degree:28,community:3,deg_w:269,betweenness:.0019,pagerank:.00265,eigenvector:.0204,pdf_file:"Crone_2014.pdf",pdf_downloaded:!0},{id:162,oaid:"W2091337721",doi:"10.1371/journal.pone.0051250",title:"Hierarchical Alteration of Brain Structural and Functional Networks in Female Migraine Sufferers",authors:[{name:"Jixin Liu",institutions:["Xidian University"]},{name:"Ling Zhao",institutions:["Chengdu University of Traditional Chinese Medicine"]},{name:"Guoying Li",institutions:["Xidian University"]},{name:"Shiwei Xiong",institutions:["Xidian University"]},{name:"Jiaofen Nan",institutions:["Xidian University"]},{name:"Jing Li",institutions:["Xidian University"]},{name:"Kai Yuan",institutions:["Xidian University"]},{name:"Karen M. von Deneen",institutions:["Xidian University"]},{name:"Fanrong Liang",institutions:["Chengdu University of Traditional Chinese Medicine"]},{name:"Wei Qin",institutions:["Xidian University"]},{name:"Jie Tian",institutions:["Xidian University","Chinese Academy of Sciences","Shandong Institute of Automation"]}],authorString:"Jixin Liu; Ling Zhao; Guoying Li; Shiwei Xiong; Jiaofen Nan; Jing Li; Kai Yuan; Karen M. von Deneen; Fanrong Liang; Wei Qin; Jie Tian",institutions:["Chengdu University of Traditional Chinese Medicine","Chinese Academy of Sciences","Shandong Institute of Automation","Xidian University"],countries:["CN"],year:2012,journal:"PLoS ONE",citations:136,abstract:"BACKGROUND: Little is known about the changes of brain structural and functional connectivity networks underlying the pathophysiology in migraine. We aimed to investigate how the cortical network reorganization is altered by frequent cortical overstimulation associated with migraine. METHODOLOGY/PRINCIPAL FINDINGS: Gray matter volumes and resting-state functional magnetic resonance imaging signal correlations were employed to construct structural and functional networks between brain regions in 43 female patients with migraine (PM) and 43 gender-matched healthy controls (HC) by using graph theory-based approaches. Compared with the HC group, the patients showed abnormal global topology in both structural and functional networks, characterized by higher mean clustering coefficients without significant change in the shortest absolute path length, which indicated that the PM lost optimal topological organization in their cortical networks. Brain hubs related to pain-processing revealed abnormal nodal centrality in both structural and functional networks, including the precentral gyrus, orbital part of the inferior frontal gyrus, parahippocampal gyrus, anterior cingulate gyrus, thalamus, temporal pole of the middle temporal gyrus and the inferior parietal gyrus. Negative correlations were found between migraine duration and regions with abnormal centrality. Furthermore, the dysfunctional connections in patients' cortical networks formed into a connected component and three dysregulated modules were identified involving pain-related information processing and motion-processing visual networks. CONCLUSIONS: Our results may reflect brain alteration dynamics resulting from migraine and suggest that long-term and high-frequency headache attacks may cause both structural and functional connectivity network reorganization. The disrupted information exchange between brain areas in migraine may be reshaped into a hierarchical modular structure progressively.",keywords:["Neuroscience","Migraine","Functional magnetic resonance imaging","Parahippocampal gyrus","Precentral gyrus","Brain mapping","Superior frontal gyrus"],concepts:["Neuroscience","Migraine","Functional magnetic resonance imaging","Parahippocampal gyrus","Precentral gyrus","Psychology","Brain mapping","Superior frontal gyrus"],topics:["Migraine and Headache Studies","Functional Brain Connectivity Studies","Neurological disorders and treatments"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0051250&type=printable",is_oa:!0,n_refs:60,n_refs_in_core:14,degree:29,community:1,deg_w:286.5,betweenness:.0013,pagerank:.00261,eigenvector:.0323,pdf_file:"Liu_2012.pdf",pdf_downloaded:!0},{id:163,oaid:"W2004297311",doi:"10.1371/journal.pcbi.1003427",title:"Communication Efficiency and Congestion of Signal Traffic in Large-Scale Brain Networks",authors:[{name:"Bratislav Mišić",institutions:["University of Toronto","Baycrest Hospital","Rotman Research Institute"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]},{name:"Anthony R. McIntosh",institutions:["University of Toronto","Baycrest Hospital","Rotman Research Institute"]}],authorString:"Bratislav Mišić; Olaf Sporns; Anthony R. McIntosh",institutions:["Baycrest Hospital","Indiana University Bloomington","Rotman Research Institute","University of Toronto"],countries:["CA","US"],year:2014,journal:"PLoS Computational Biology",citations:135,abstract:'The complex connectivity of the cerebral cortex suggests that inter-regional communication is a primary function. Using computational modeling, we show that anatomical connectivity may be a major determinant for global information flow in brain networks. A macaque brain network was implemented as a communication network in which signal units flowed between grey matter nodes along white matter paths. Compared to degree-matched surrogate networks, information flow on the macaque brain network was characterized by higher loss rates, faster transit times and lower throughput, suggesting that neural connectivity may be optimized for speed rather than fidelity. Much of global communication was mediated by a "rich club" of hub regions: a sub-graph comprised of high-degree nodes that are more densely interconnected with each other than predicted by chance. First, macaque communication patterns most closely resembled those observed for a synthetic rich club network, but were less similar to those seen in a synthetic small world network, suggesting that the former is a more fundamental feature of brain network topology. Second, rich club regions attracted the most signal traffic and likewise, connections between rich club regions carried more traffic than connections between non-rich club regions. Third, a number of rich club regions were significantly under-congested, suggesting that macaque connectivity actively shapes information flow, funneling traffic towards some nodes and away from others. Together, our results indicate a critical role of the rich club of hub nodes in dynamic aspects of global brain communication.',keywords:["Macaque","Information flow","Computer network","Nerve net","Distributed computing","Neuroscience"],concepts:["Macaque","Computer science","Information flow","Computer network","Nerve net","Distributed computing","Neuroscience"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","stochastic dynamics and bifurcation"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1003427&type=printable",is_oa:!0,n_refs:57,n_refs_in_core:9,degree:29,community:0,deg_w:365.5,betweenness:9e-4,pagerank:.00328,eigenvector:.0242,pdf_file:"Mii_2014.pdf",pdf_downloaded:!0},{id:164,oaid:"W1850248061",doi:"10.1073/pnas.1502052112",title:"Randomization and resilience of brain functional networks as systems-level endophenotypes of schizophrenia",authors:[{name:"Chun‐Yi Zac Lo",institutions:["National Yang Ming Chiao Tung University"]},{name:"Tsung-Wei Su",institutions:["National Yang Ming Chiao Tung University","National Yang Ming University Hospital"]},{name:"Chu‐Chung Huang",institutions:["National Yang Ming Chiao Tung University"]},{name:"Chia‐Chun Hung",institutions:["National Yang Ming Chiao Tung University","Taichung Veterans General Hospital"]},{name:"Wei-Ling Chen",institutions:["Taichung Veterans General Hospital"]},{name:"Tsuo‐Hung Lan",institutions:["Taichung Veterans General Hospital"]},{name:"Ching‐Po Lin",institutions:["National Yang Ming Chiao Tung University"]},{name:"Edward T. Bullmore",institutions:["National Health Service","GlaxoSmithKline (United Kingdom)","University of Cambridge","Cambridge University Hospitals NHS Foundation Trust","National Institute for Health and Care Research","Cambridgeshire and Peterborough NHS Foundation Trust"]}],authorString:"Chun‐Yi Zac Lo; Tsung-Wei Su; Chu‐Chung Huang; Chia‐Chun Hung; Wei-Ling Chen; Tsuo‐Hung Lan; Ching‐Po Lin; Edward T. Bullmore",institutions:["Cambridge University Hospitals NHS Foundation Trust","Cambridgeshire and Peterborough NHS Foundation Trust","GlaxoSmithKline (United Kingdom)","National Health Service","National Institute for Health and Care Research","National Yang Ming Chiao Tung University","National Yang Ming University Hospital","Taichung Veterans General Hospital","University of Cambridge"],countries:["GB","TW"],year:2015,journal:"Proceedings of the National Academy of Sciences",citations:133,abstract:"Schizophrenia is increasingly conceived as a disorder of brain network organization or dysconnectivity syndrome. Functional MRI (fMRI) networks in schizophrenia have been characterized by abnormally random topology. We tested the hypothesis that network randomization is an endophenotype of schizophrenia and therefore evident also in nonpsychotic relatives of patients. Head movement-corrected, resting-state fMRI data were acquired from 25 patients with schizophrenia, 25 first-degree relatives of patients, and 29 healthy volunteers. Graphs were used to model functional connectivity as a set of edges between regional nodes. We estimated the topological efficiency, clustering, degree distribution, resilience, and connection distance (in millimeters) of each functional network. The schizophrenic group demonstrated significant randomization of global network metrics (reduced clustering, greater efficiency), a shift in the degree distribution to a more homogeneous form (fewer hubs), a shift in the distance distribution (proportionally more long-distance edges), and greater resilience to targeted attack on network hubs. The networks of the relatives also demonstrated abnormal randomization and resilience compared with healthy volunteers, but they were typically less topologically abnormal than the patients' networks and did not have abnormal connection distances. We conclude that schizophrenia is associated with replicable and convergent evidence for functional network randomization, and a similar topological profile was evident also in nonpsychotic relatives, suggesting that this is a systems-level endophenotype or marker of familial risk. We speculate that the greater resilience of brain networks may confer some fitness advantages on nonpsychotic relatives that could explain persistence of this endophenotype in the population.",keywords:["Endophenotype","Schizophrenia","Randomization","Resting state fMRI","Connectome","Neuroscience"],concepts:["Endophenotype","Schizophrenia (object-oriented programming)","Randomization","Population","Resting state fMRI","Connectome","Psychology","Neuroscience"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Mental Health Research Topics"],pdf_url:"https://www.pnas.org/content/pnas/112/29/9123.full.pdf",is_oa:!0,n_refs:68,n_refs_in_core:23,degree:37,community:3,deg_w:541.5,betweenness:.0018,pagerank:.00434,eigenvector:.0425,pdf_file:null,pdf_downloaded:!1},{id:165,oaid:"W2118446773",doi:"10.1214/13-ss103",title:"Analyzing complex functional brain networks: Fusing statistics and network science to understand the brain",authors:[{name:"Sean L. Simpson",institutions:["Wake Forest University"]},{name:"F. DuBois Bowman",institutions:["Emory University"]},{name:"Paul J. Laurienti",institutions:["Wake Forest University"]}],authorString:"Sean L. Simpson; F. DuBois Bowman; Paul J. Laurienti",institutions:["Emory University","Wake Forest University"],countries:["US"],year:2013,journal:"Statistics Surveys",citations:132,abstract:"Complex functional brain network analyses have exploded over the last decade, gaining traction due to their profound clinical implications. The application of network science (an interdisciplinary offshoot of graph theory) has facilitated these analyses and enabled examining the brain as an integrated system that produces complex behaviors. While the field of statistics has been integral in advancing activation analyses and some connectivity analyses in functional neuroimaging research, it has yet to play a commensurate role in complex network analyses. Fusing novel statistical methods with network-based functional neuroimage analysis will engender powerful analytical tools that will aid in our understanding of normal brain function as well as alterations due to various brain disorders. Here we survey widely used statistical and network science tools for analyzing fMRI network data and discuss the challenges faced in filling some of the remaining methodological gaps. When applied and interpreted correctly, the fusion of network scientific and statistical methods has a chance to revolutionize the understanding of brain function.",keywords:["Network science","Complex network","Neuroimaging","Network analysis","Functional neuroimaging","Field","Statistical analysis","Brain function"],concepts:["Network science","Computer science","Complex network","Neuroimaging","Data science","Artificial intelligence","Network analysis","Functional neuroimaging"],topics:["Functional Brain Connectivity Studies","Mental Health Research Topics","Neural dynamics and brain function"],pdf_url:"https://projecteuclid.org/journals/statistics-surveys/volume-7/issue-none/Analyzing-complex-functional-brain-networks--Fusing-statistics-and-network/10.1214/13-SS103.pdf",is_oa:!0,n_refs:143,n_refs_in_core:15,degree:30,community:1,deg_w:525.5,betweenness:.0013,pagerank:.00409,eigenvector:.0553,pdf_file:"Simpson_2013.pdf",pdf_downloaded:!0},{id:166,oaid:"W2609746265",doi:"10.3389/fninf.2017.00028",title:"Topological Filtering of Dynamic Functional Brain Networks Unfolds Informative Chronnectomics: A Novel Data-Driven Thresholding Scheme Based on Orthogonal Minimal Spanning Trees (OMSTs)",authors:[{name:"Stavros I. Dimitriadis",institutions:["Cardiff University"]},{name:"Christos Salis",institutions:["University of Western Macedonia"]},{name:"Ioannis Tarnanas",institutions:["Aristotle University of Thessaloniki","ETH Zurich"]},{name:"David E.J. Linden",institutions:["Cardiff University"]}],authorString:"Stavros I. Dimitriadis; Christos Salis; Ioannis Tarnanas; David E.J. Linden",institutions:["Aristotle University of Thessaloniki","Cardiff University","ETH Zurich","University of Western Macedonia"],countries:["CH","GB","GR"],year:2017,journal:"Frontiers in Neuroinformatics",citations:131,abstract:"The human brain is a large-scale system of functionally connected brain regions. This system can be modeled as a network, or graph, by dividing the brain into a set of regions, or “nodes,” and quantifying the strength of the connections between nodes, or “edges,” as the temporal correlation in their patterns of activity. Network analysis, a part of graph theory, provides a set of summary statistics that can be used to describe complex brain networks in a meaningful way. The large-scale organization of the brain has features of complex networks that can be quantified using network measures from graph theory. The adaptation of both bivariate (mutual information) and multivariate (Granger causality) connectivity estimators to quantify the synchronization between multichannel recordings yields a fully connected, weighted, (a)symmetric functional connectivity graph (FCG), representing the associations among all brain areas. The aforementioned procedure leads to an extremely dense network of tens up to a few hundreds of weights. Therefore, this FCG must be filtered out so that the ''true'' connectivity pattern can emerge. Here, we compared a large number of well-known topological thresholding techniques with the novel proposed data-driven scheme based on orthogonal minimal spanning trees (OMSTs). OMSTs filter brain connectivity networks based on the optimization between the global efficiency of the network and the cost preserving its wiring. We demonstrated the proposed method in a large EEG database (N=101 subjects) with eyes-open (EO) and eyes-closed (EC) tasks by adopting a time-varying approach with the main scope to extract features that can totally distinguish each subject from the rest of the set. Additionally, the reliability of the proposed scheme was estimated in a second case study of fMRI resting-state activity with multiple scans . Our results demonstrated clearly that the proposed thresholding scheme outperformed a large list of thresholding schemes based on the recognition accuracy of each subject compared to the rest of the cohort (EEG). Additionally, the reliability of the network metrics based on the fMRI dynamic networks was improved based on the proposed topological filtering scheme. Overall, the proposed algorithm could be used across neuroimaging and multimodal studies as a common",keywords:["Thresholding","Scheme","Topological data analysis","Topology","Functional connectivity","Pattern recognition"],concepts:["Thresholding","Scheme (mathematics)","Computer science","Topological data analysis","Topology (electrical circuits)","Functional connectivity","Artificial intelligence","Pattern recognition (psychology)"],topics:["Neural dynamics and brain function","Functional Brain Connectivity Studies","Neural Networks and Applications"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fninf.2017.00028/pdf",is_oa:!0,n_refs:121,n_refs_in_core:17,degree:31,community:3,deg_w:331,betweenness:.0018,pagerank:.00299,eigenvector:.0266,pdf_file:"Dimitriadis_2017.pdf",pdf_downloaded:!0},{id:167,oaid:"W2145654434",doi:"10.3389/fnins.2011.00083",title:"Exploring Brain Function from Anatomical Connectivity",authors:[{name:"Gorka Zamora‐López",institutions:["Cal Poly Humboldt","Bernstein Center for Computational Neuroscience Berlin"]},{name:"Changsong Zhou",institutions:["Hong Kong Baptist University"]},{name:"Jürgen Kurths",institutions:["Cal Poly Humboldt","University of Aberdeen","Bernstein Center for Computational Neuroscience Berlin","Potsdam Institute for Climate Impact Research"]}],authorString:"Gorka Zamora‐López; Changsong Zhou; Jürgen Kurths",institutions:["Bernstein Center for Computational Neuroscience Berlin","Cal Poly Humboldt","Hong Kong Baptist University","Potsdam Institute for Climate Impact Research","University of Aberdeen"],countries:["DE","GB","HK","US"],year:2011,journal:"Frontiers in Neuroscience",citations:129,abstract:"The intrinsic relationship between the architecture of the brain and the range of sensory and behavioral phenomena it produces is a relevant question in neuroscience. Here, we review recent knowledge gained on the architecture of the anatomical connectivity by means of complex network analysis. It has been found that cortico-cortical networks display a few prominent characteristics: (i) modular organization, (ii) abundant alternative processing paths, and (iii) the presence of highly connected hubs. Additionally, we present a novel classification of cortical areas of the cat according to the role they play in multisensory connectivity. All these properties represent an ideal anatomical substrate supporting rich dynamical behaviors, facilitating the capacity of the brain to process sensory information of different modalities segregated and to integrate them toward a comprehensive perception of the real world. The results here exposed are mainly based on anatomical data of cats' brain, but further observations suggest that, from worms to humans, the nervous system of all animals might share these fundamental principles of organization.",keywords:["Neuroscience","Sensory system","Stimulus modality","Perception","Process","Functional connectivity","Modular design"],concepts:["Neuroscience","Sensory system","Stimulus modality","Perception","Process (computing)","Computer science","Functional connectivity","Modular design"],topics:["Neural dynamics and brain function","Functional Brain Connectivity Studies","EEG and Brain-Computer Interfaces"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnins.2011.00083/pdf",is_oa:!0,n_refs:97,n_refs_in_core:7,degree:29,community:0,deg_w:387,betweenness:.0012,pagerank:.00337,eigenvector:.0305,pdf_file:"ZamoraLpez_2011.pdf",pdf_downloaded:!0},{id:168,oaid:"W1964757651",doi:"10.1017/nws.2013.19",title:"Multi-scale community organization of the human structural connectome and its relationship with resting-state functional connectivity",authors:[{name:"Richard F. Betzel",institutions:["Indiana University Bloomington"]},{name:"Alessandra Griffa",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Andrea Avena‐Koenigsberger",institutions:["Indiana University Bloomington"]},{name:"Joaquín Goñi",institutions:["Indiana University Bloomington"]},{name:"Jean‐Philippe Thiran",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Patric Hagmann",institutions:["École Polytechnique Fédérale de Lausanne"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]}],authorString:"Richard F. Betzel; Alessandra Griffa; Andrea Avena‐Koenigsberger; Joaquín Goñi; Jean‐Philippe Thiran; Patric Hagmann; Olaf Sporns",institutions:["Indiana University Bloomington","École Polytechnique Fédérale de Lausanne"],countries:["CH","US"],year:2013,journal:"Network Science",citations:129,abstract:"Abstract The human connectome has been widely studied over the past decade. A principal finding is that it can be decomposed into communities of densely interconnected brain regions. Past studies have often used single-scale modularity measures in order to infer the connectome's community structure, possibly overlooking interesting structure at other organizational scales. In this report, we used the partition stability framework, which defines communities in terms of a Markov process (random walk), to infer the connectome's multi-scale community structure. Comparing the community structure to observed resting-state functional connectivity revealed communities across a broad range of scales that were closely related to functional connectivity. This result suggests a mapping between communities in structural networks, models of influence-spreading and diffusion, and brain function. It further suggests that the spread of influence among brain regions may not be limited to a single characteristic scale.",keywords:["Connectome","Resting state fMRI","Community structure","Human Connectome Project","Functional connectivity","Neuroscience"],concepts:["Connectome","Resting state fMRI","Community structure","Computer science","Human Connectome Project","Functional connectivity"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Complex Network Analysis Techniques"],pdf_url:"https://www.cambridge.org/core/services/aop-cambridge-core/content/view/97B9B699236A2F129684F1D80D1DA220/S2050124213000192a.pdf/div-class-title-multi-scale-community-organization-of-the-human-structural-connectome-and-its-relationship-with-resting-state-functional-connectivity-div.pdf",is_oa:!0,n_refs:80,n_refs_in_core:10,degree:28,community:0,deg_w:397,betweenness:.0012,pagerank:.00351,eigenvector:.0231,pdf_file:"Betzel_2013.pdf",pdf_downloaded:!0},{id:169,oaid:"W3202828119",doi:"10.1038/s41386-021-01156-6",title:"Prefrontal connectomics: from anatomy to human imaging",authors:[{name:"Suzanne N. Haber",institutions:["McLean Hospital","University of Rochester Medical Center","University of Rochester"]},{name:"Hesheng Liu",institutions:["Harvard University","Medical University of South Carolina","Massachusetts General Hospital"]},{name:"Jakob Seidlitz",institutions:["University of Pennsylvania"]},{name:"Edward T. Bullmore",institutions:["University of Cambridge"]}],authorString:"Suzanne N. Haber; Hesheng Liu; Jakob Seidlitz; Edward T. Bullmore",institutions:["Harvard University","Massachusetts General Hospital","McLean Hospital","Medical University of South Carolina","University of Cambridge","University of Pennsylvania","University of Rochester","University of Rochester Medical Center"],countries:["GB","US"],year:2021,journal:"Neuropsychopharmacology",citations:129,abstract:'The fundamental importance of prefrontal cortical connectivity to information processing and, therefore, disorders of cognition, emotion, and behavior has been recognized for decades. Anatomic tracing studies in animals have formed the basis for delineating the direct monosynaptic connectivity, from cells of origin, through axon trajectories, to synaptic terminals. Advances in neuroimaging combined with network science have taken the lead in developing complex wiring diagrams or connectomes of the human brain. A key question is how well these magnetic resonance imaging (MRI)-derived networks and hubs reflect the anatomic "hard wiring" first proposed to underlie the distribution of information for large-scale network interactions. In this review, we address this challenge by focusing on what is known about monosynaptic prefrontal cortical connections in non-human primates and how this compares to MRI-derived measurements of network organization in humans. First, we outline the anatomic cortical connections and pathways for each prefrontal cortex (PFC) region. We then review the available MRI-based techniques for indirectly measuring structural and functional connectivity, and introduce graph theoretical methods for analysis of hubs, modules, and topologically integrative features of the connectome. Finally, we bring these two approaches together, using specific examples, to demonstrate how monosynaptic connections, demonstrated by tract-tracing studies, can directly inform understanding of the composition of PFC nodes and hubs, and the edges or pathways that connect PFC to cortical and subcortical areas.',keywords:["Connectomics","Neuroscience","Prefrontal cortex","Connectome","Neuroimaging","Functional magnetic resonance imaging","Tracing"],concepts:["Connectomics","Neuroscience","Prefrontal cortex","Connectome","Neuroimaging","Functional magnetic resonance imaging","Tracing","Computer science"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.nature.com/articles/s41386-021-01156-6.pdf",is_oa:!0,n_refs:246,n_refs_in_core:20,degree:34,community:0,deg_w:474.5,betweenness:.0026,pagerank:.00407,eigenvector:.0259,pdf_file:"Haber_2021.pdf",pdf_downloaded:!0},{id:170,oaid:"W2794272206",doi:"10.3389/fninf.2018.00007",title:"Clustering Coefficients for Correlation Networks",authors:[{name:"Naoki Masuda",institutions:["University of Bristol"]},{name:"Michiko Sakaki",institutions:["University of Reading","Kochi University of Technology"]},{name:"Takahiro Ezaki",institutions:["Japan Science and Technology Agency"]},{name:"Takamitsu Watanabe",institutions:["University College London"]}],authorString:"Naoki Masuda; Michiko Sakaki; Takahiro Ezaki; Takamitsu Watanabe",institutions:["Japan Science and Technology Agency","Kochi University of Technology","University College London","University of Bristol","University of Reading"],countries:["GB","JP"],year:2018,journal:"Frontiers in Neuroinformatics",citations:128,abstract:"Graph theory is a useful tool for deciphering structural and functional networks of the brain on various spatial and temporal scales. The clustering coefficient quantifies the abundance of connected triangles in a network and is a major descriptive statistics of networks. For example, it finds an application in the assessment of small-worldness of brain networks, which is affected by attentional and cognitive conditions, age, psychiatric disorders and so forth. However, it remains unclear how the clustering coefficient should be measured in a correlation-based network, which is among major representations of brain networks. In the present article, we propose clustering coefficients tailored to correlation matrices. The key idea is to use three-way partial correlation or partial mutual information to measure the strength of the association between the two neighboring nodes of a focal node relative to the amount of pseudo-correlation expected from indirect paths between the nodes. Our method avoids the difficulties of previous applications of clustering coefficient (and other) measures in defining correlational networks, i.e., thresholding on the correlation value, discarding of negative correlation values, the pseudo-correlation problem and full partial correlation matrices whose estimation is computationally difficult. For proof of concept, we apply the proposed clustering coefficient measures to functional magnetic resonance imaging data obtained from healthy participants of various ages and compare them with conventional clustering coefficients. We show that the clustering coefficients decline with the age. The proposed clustering coefficients are more strongly correlated with age than the conventional ones are. We also show that the local variants of the proposed clustering coefficients (i.e., abundance of triangles around a focal node) are useful in characterizing individual nodes. In contrast, the conventional local clustering coefficients were strongly correlated with and therefore may be confounded by the node's connectivity. The proposed methods are expected to help us to understand clustering and lack thereof in correlational brain networks, such as those derived from functional time series and across-participant correlation in neuroanatomical properties.",keywords:["Clustering coefficient","Cluster analysis","Partial correlation","Correlation","Correlation coefficient","Thresholding","Pearson product-moment correlation coefficient","Correlation clustering"],concepts:["Clustering coefficient","Cluster analysis","Partial correlation","Correlation","Correlation coefficient","Thresholding","Pearson product-moment correlation coefficient","Correlation clustering"],topics:["Functional Brain Connectivity Studies","Mental Health Research Topics","Complex Systems and Time Series Analysis"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fninf.2018.00007/pdf",is_oa:!0,n_refs:83,n_refs_in_core:15,degree:29,community:3,deg_w:342,betweenness:.0015,pagerank:.00306,eigenvector:.026,pdf_file:"Masuda_2018.pdf",pdf_downloaded:!0},{id:171,oaid:"W4220959954",doi:"10.1016/j.plrev.2022.03.001",title:"Networks behind the morphology and structural design of living systems",authors:[{name:"Marko Gosak",institutions:["University of Maribor"]},{name:"Marko Milojević",institutions:["University of Maribor"]},{name:"Maja Duh",institutions:["University of Maribor"]},{name:"Kristijan Skok",institutions:["University of Maribor","Graz University Hospital"]},{name:"Matjaž Perc",institutions:["China Medical University","Alma Mater Europaea","University of Maribor","Complexity Science Hub","China Medical University Hospital"]}],authorString:"Marko Gosak; Marko Milojević; Maja Duh; Kristijan Skok; Matjaž Perc",institutions:["Alma Mater Europaea","China Medical University","China Medical University Hospital","Complexity Science Hub","Graz University Hospital","University of Maribor"],countries:["AT","SI","TW"],year:2022,journal:"Physics of Life Reviews",citations:126,abstract:"Technological advances in imaging techniques and biometric data acquisition have enabled us to apply methods of network science to study the morphology and structural design of organelles, organs, and tissues, as well as the coordinated interactions among them that yield a healthy physiology at the level of whole organisms. We here review research dedicated to these advances, in particular focusing on networks between cells, the topology of multicellular structures, neural interactions, fluid transportation networks, and anatomical networks. The percolation of blood vessels, structural connectivity within the brain, the porous structure of bones, and relations between different anatomical parts of the human body are just some of the examples that we explore in detail. We argue and show that the models, methods, and algorithms developed in the realm of network science are ushering in a new era of network-based inquiry into the morphology and structural design of living systems in the broadest possible terms. We also emphasize that the need and applicability of this research is likely to increase significantly in the years to come due to the rapid progress made in the development of bioartificial substitutes and tissue engineering.",keywords:["Multicellular organism","Living systems","Biological network","Network science","Realm","Percolation"],concepts:["Computer science","Artificial intelligence","Multicellular organism","Living systems","Biological network","Network science","Realm","Percolation (cognitive psychology)"],topics:["Functional Brain Connectivity Studies","Data Visualization and Analytics","Cell Image Analysis Techniques"],pdf_url:"https://linkinghub.elsevier.com/science/article/pii/S1571064522000124/pdfft?md5=06586913d94ac4630c43b923dca7fa07&pid=1-s2.0-S1571064522000124-main.pdf",is_oa:!0,n_refs:274,n_refs_in_core:16,degree:30,community:0,deg_w:270,betweenness:.0021,pagerank:.00263,eigenvector:.0182,pdf_file:null,pdf_downloaded:!1},{id:172,oaid:"W1992849759",doi:"10.1093/cercor/bhu259",title:"Effects of Beta-Amyloid on Resting State Functional Connectivity Within and Between Networks Reflect Known Patterns of Regional Vulnerability",authors:[{name:"Jeremy A. Elman",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Cindee Madison",institutions:["University of California, Berkeley"]},{name:"Suzanne L. Baker",institutions:["Lawrence Berkeley National Laboratory"]},{name:"Jacob W. Vogel",institutions:["University of California, Berkeley"]},{name:"Shawn Marks",institutions:["University of California, Berkeley"]},{name:"Sam Crowley",institutions:["Lawrence Berkeley National Laboratory"]},{name:"James P. O’Neil",institutions:["Lawrence Berkeley National Laboratory"]},{name:"William J. Jagust",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"]}],authorString:"Jeremy A. Elman; Cindee Madison; Suzanne L. Baker; Jacob W. Vogel; Shawn Marks; Sam Crowley; James P. O’Neil; William J. Jagust",institutions:["Lawrence Berkeley National Laboratory","University of California, Berkeley"],countries:["US"],year:2014,journal:"Cerebral Cortex",citations:126,abstract:"Beta-amyloid (Aβ) deposition is one of the hallmarks of Alzheimer's disease (AD). However, it is also present in some cognitively normal elderly adults and may represent a preclinical disease state. While AD patients exhibit disrupted functional connectivity (FC) both within and between resting-state networks, studies of preclinical cases have focused primarily on the default mode network (DMN). The extent to which Aβ-related effects occur outside of the DMN and between networks remains unclear. In the present study, we examine how within- and between-network FC are related to both global and regional Aβ deposition as measured by [(11)C]PIB-PET in 92 cognitively normal older people. We found that within-network FC changes occurred in multiple networks, including the DMN. Changes of between-network FC were also apparent, suggesting that regions maintaining connections to multiple networks may be particularly susceptible to Aβ-induced alterations. Cortical regions showing altered FC clustered in parietal and temporal cortex, areas known to be susceptible to AD pathology. These results likely represent a mix of local network disruption, compensatory reorganization, and impaired control network function. They indicate the presence of Aβ-related dysfunction of neural systems in cognitively normal people well before these areas become hypometabolic with the onset of cognitive decline.",keywords:["Default mode network","Neuroscience","Resting state fMRI","Cognition","Disease","Cognitive decline","Functional connectivity"],concepts:["Default mode network","Neuroscience","Resting state fMRI","Cognition","Disease","Cognitive decline","Functional connectivity","Psychology"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Alzheimer's disease research and treatments"],pdf_url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC4712800/pdf/bhu259.pdf",is_oa:!0,n_refs:95,n_refs_in_core:17,degree:31,community:2,deg_w:344,betweenness:.0021,pagerank:.00329,eigenvector:.0159,pdf_file:null,pdf_downloaded:!1},{id:173,oaid:"W1998486151",doi:"10.1371/journal.pone.0096505",title:"Disrupted Functional Brain Connectivity and Its Association to Structural Connectivity in Amnestic Mild Cognitive Impairment and Alzheimer’s Disease",authors:[{name:"Yu Sun",institutions:["National University of Singapore","Shanghai Jiao Tong University"]},{name:"Qihua Yin",institutions:["Ruijin Hospital","Shanghai Jiao Tong University"]},{name:"Rong Fang",institutions:["Shanghai Jiao Tong University","Ruijin Hospital"]},{name:"Xiaoxiao Yan",institutions:["Shanghai Jiao Tong University"]},{name:"Ying Wang",institutions:["Shanghai Jiao Tong University","Ruijin Hospital"]},{name:"Anastasios Bezerianos",institutions:["National University of Singapore"]},{name:"Huidong Tang",institutions:["Ruijin Hospital","Shanghai Jiao Tong University"]},{name:"Fei Miao",institutions:["Ruijin Hospital","Shanghai Jiao Tong University"]},{name:"Junfeng Sun",institutions:["Shanghai Jiao Tong University"]}],authorString:"Yu Sun; Qihua Yin; Rong Fang; Xiaoxiao Yan; Ying Wang; Anastasios Bezerianos; Huidong Tang; Fei Miao; Junfeng Sun",institutions:["National University of Singapore","Ruijin Hospital","Shanghai Jiao Tong University"],countries:["CN","SG"],year:2014,journal:"PLoS ONE",citations:125,abstract:"Although anomalies in the topological architecture of whole-brain connectivity have been found to be associated with Alzheimer's disease (AD), our understanding about the progression of AD in a functional connectivity (FC) perspective is still rudimentary and few study has explored the function-structure relations in brain networks of AD patients. By using resting-state functional MRI (fMRI), this study firstly investigated organizational alternations in FC networks in 12 AD patients, 15 amnestic mild cognitive impairment (aMCI) patients, and 14 age-matched healthy aging subjects and found that all three groups exhibit economical small-world network properties. Nonetheless, we found a decline of the optimal architecture in the progression of AD, represented by a more localized modular organization with less efficient local information transfer. Our results also show that aMCI forms a boundary between normal aging and AD and represents a functional continuum between healthy aging and the earliest signs of dementia. Moreover, we revealed a dissociated relationship between the overall FC and structural connectivity (SC) in AD patients. In this study, diffusion tensor imaging tractography was used to map the structural network of the same individuals. The decreased FC-SC coupling may be indicative of more stringent and less dynamic brain function in AD patients. Our findings provided insightful implications for understanding the pathophysiological mechanisms of brain dysfunctions in aMCI and AD patients and demonstrated that functional disorders can be characterized by multimodal neuroimaging-based metrics.",keywords:["Neuroscience","Dementia","Neuroimaging","Diffusion MRI","Disease","Cognition","Tractography"],concepts:["Neuroscience","Dementia","Neuroimaging","Diffusion MRI","Disease","Cognition","Tractography","Psychology"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0096505&type=printable",is_oa:!0,n_refs:83,n_refs_in_core:19,degree:33,community:1,deg_w:527.5,betweenness:.0011,pagerank:.00406,eigenvector:.0535,pdf_file:"Sun_2014.pdf",pdf_downloaded:!0},{id:174,oaid:"W1965468519",doi:"10.3389/fpsyt.2012.00032",title:"Connectomic Intermediate Phenotypes for Psychiatric Disorders",authors:[{name:"Alex Fornito",institutions:["The University of Melbourne","Melbourne Health"]},{name:"Edward T. Bullmore",institutions:["University of Cambridge"]}],authorString:"Alex Fornito; Edward T. Bullmore",institutions:["Melbourne Health","The University of Melbourne","University of Cambridge"],countries:["AU","GB"],year:2012,journal:"Frontiers in Psychiatry",citations:122,abstract:"Psychiatric disorders are phenotypically heterogeneous entities with a complex genetic basis. To mitigate this complexity, many investigators study so-called intermediate phenotypes (IPs) that putatively provide a more direct index of the physiological effects of candidate genetic risk variants than overt psychiatric syndromes. Magnetic resonance imaging (MRI) is a particularly popular technique for measuring such phenotypes because it allows interrogation of diverse aspects of brain structure and function in vivo. Much of this work however, has focused on relatively simple measures that quantify variations in the physiology or tissue integrity of specific brain regions in isolation, contradicting an emerging consensus that most major psychiatric disorders do not arise from isolated dysfunction in one or a few brain regions, but rather from disturbed interactions within and between distributed neural circuits; i.e., they are disorders of brain connectivity. The recent proliferation of new MRI techniques for comprehensively mapping the entire connectivity architecture of the brain, termed the human connectome, has provided a rich repertoire of tools for understanding how genetic variants implicated in mental disorder impact distinct neural circuits. In this article, we review research using these connectomic techniques to understand how genetic variation influences the connectivity and topology of human brain networks. We highlight recent evidence from twin and imaging genetics studies suggesting that the penetrance of candidate risk variants for mental illness, such as those in SLC6A4, MAOA, ZNF804A, and APOE, may be higher for IPs characterized at the level of distributed neural systems than at the level of spatially localized brain regions. The findings indicate that imaging connectomics provides a powerful framework for understanding how genetic risk for psychiatric disease is expressed through altered structure and function of the human connectome.",keywords:["Imaging genetics","Neuroscience","Connectome","Genetic architecture","Mental illness","Research Domain Criteria","Brain Structure and Function","Phenotype"],concepts:["Imaging genetics","Neuroscience","Connectome","Genetic architecture","Mental illness","Research Domain Criteria","Brain Structure and Function","Phenotype"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Mental Health Research Topics"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fpsyt.2012.00032/pdf",is_oa:!0,n_refs:239,n_refs_in_core:23,degree:41,community:3,deg_w:738.5,betweenness:.0031,pagerank:.00547,eigenvector:.0756,pdf_file:"Fornito_2012.pdf",pdf_downloaded:!0},{id:175,oaid:"W1927762784",doi:"10.1093/brain/awv145",title:"Network topology and functional connectivity disturbances precede the onset of Huntington’s disease",authors:[{name:"Deborah L. Harrington",institutions:["University of California San Diego","VA San Diego Healthcare System"]},{name:"Mikail Rubinov",institutions:["University of Cambridge"]},{name:"Sally Durgerian",institutions:["Medical College of Wisconsin"]},{name:"Lyla Mourany",institutions:["Cleveland Clinic","Cognitive Neuroimaging Lab","The Neurological Institute"]},{name:"Christine Reece",institutions:["Cleveland Clinic","Cognitive Neuroimaging Lab","The Neurological Institute"]},{name:"Katherine Koenig",institutions:["Cleveland Clinic"]},{name:"Edward T. Bullmore",institutions:["University of Cambridge"]},{name:"Jeffrey D. Long",institutions:["University of Iowa"]},{name:"Jane S. Paulsen",institutions:["University of Iowa"]},{name:"for the PREDICT-HD investigators of the Huntington Study Group",institutions:["Cleveland Clinic","The Neurological Institute"]},{name:"Stephen M. Rao",institutions:["Cognitive Neuroimaging Lab"]}],authorString:"Deborah L. Harrington; Mikail Rubinov; Sally Durgerian; Lyla Mourany; Christine Reece; Katherine Koenig; Edward T. Bullmore; Jeffrey D. Long; Jane S. Paulsen; for the PREDICT-HD investigators of the Huntington Study Group; Stephen M. Rao",institutions:["Cleveland Clinic","Cognitive Neuroimaging Lab","Medical College of Wisconsin","The Neurological Institute","University of California San Diego","University of Cambridge","University of Iowa","VA San Diego Healthcare System"],countries:["FR","GB","US"],year:2015,journal:"Brain",citations:122,abstract:"Cognitive, motor and psychiatric changes in prodromal Huntington's disease have nurtured the emergent need for early interventions. Preventive clinical trials for Huntington's disease, however, are limited by a shortage of suitable measures that could serve as surrogate outcomes. Measures of intrinsic functional connectivity from resting-state functional magnetic resonance imaging are of keen interest. Yet recent studies suggest circumscribed abnormalities in resting-state functional magnetic resonance imaging connectivity in prodromal Huntington's disease, despite the spectrum of behavioural changes preceding a manifest diagnosis. The present study used two complementary analytical approaches to examine whole-brain resting-state functional magnetic resonance imaging connectivity in prodromal Huntington's disease. Network topology was studied using graph theory and simple functional connectivity amongst brain regions was explored using the network-based statistic. Participants consisted of gene-negative controls (n = 16) and prodromal Huntington's disease individuals (n = 48) with various stages of disease progression to examine the influence of disease burden on intrinsic connectivity. Graph theory analyses showed that global network interconnectivity approximated a random network topology as proximity to diagnosis neared and this was associated with decreased connectivity amongst highly-connected rich-club network hubs, which integrate processing from diverse brain regions. However, functional segregation within the global network (average clustering) was preserved. Functional segregation was also largely maintained at the local level, except for the notable decrease in the diversity of anterior insula intermodular-interconnections (participation coefficient), irrespective of disease burden. In contrast, network-based statistic analyses revealed patterns of weakened frontostriatal connections and strengthened frontal-posterior connections that evolved as disease burden increased. These disturbances were often related to long-range connections involving peripheral nodes and interhemispheric connections. A strong association was found between weaker connectivity and decreased rich-club organization, indicating that whole-brain simple connectivity partially expressed disturbances in the communication of highly-connected hubs. However, network topology and network-based statistic connectivity metrics did not correlate with key markers of executive dysfunction (Stroop Test, Trail Making Test) in prodromal Huntington's disease, which instead were related to whole-brain connectivity disturbances in nodes (right inferior parietal, right thalamus, left anterior cingulate) that exhibited multiple aberrant connections and that mediate executive control. Altogether, our results show for the first time a largely disease burden-dependent functional reorganization of whole-brain networks in prodromal Huntington's disease. Both analytic approaches provided a unique window into brain reorganization that was not related to brain atrophy or motor symptoms. Longitudinal studies currently in progress will chart the course of functional changes to determine the most sensitive markers of disease progression.",keywords:["Huntington's disease","Neuroscience","Functional connectivity","Disease","Network topology","Topology"],concepts:["Huntington's disease","Neuroscience","Functional connectivity","Disease","Network topology","Topology (electrical circuits)","Psychology","Computer science"],topics:["Genetic Neurodegenerative Diseases","Functional Brain Connectivity Studies","Neurological disorders and treatments"],pdf_url:"https://academic.oup.com/brain/article-pdf/138/8/2332/13800041/awv145.pdf",is_oa:!0,n_refs:89,n_refs_in_core:17,degree:32,community:0,deg_w:329,betweenness:.002,pagerank:.00301,eigenvector:.0215,pdf_file:null,pdf_downloaded:!1},{id:176,oaid:"W2286966543",doi:"10.1017/s1355617715000995",title:"Measuring Cortical Connectivity in Alzheimer’s Disease as a Brain Neural Network Pathology: Toward Clinical Applications",authors:[{name:"Stefan Teipel",institutions:["German Center for Neurodegenerative Diseases","University of Rostock"]},{name:"Michel J. Grothe",institutions:["German Center for Neurodegenerative Diseases"]},{name:"Juan Zhou",institutions:["Duke-NUS Medical School"]},{name:"Jorge Sepulcre",institutions:["Harvard University","Gordon Center for Medical Imaging","Massachusetts General Hospital"]},{name:"Martin Dyrba",institutions:["German Center for Neurodegenerative Diseases"]},{name:"Christian Sorg",institutions:["Technical University of Munich"]},{name:"Claudio Babiloni",institutions:["IRCCS Ospedale San Raffaele","Istituto di Ricovero e Cura a Carattere Scientifico San Raffaele","Sapienza University of Rome"]}],authorString:"Stefan Teipel; Michel J. Grothe; Juan Zhou; Jorge Sepulcre; Martin Dyrba; Christian Sorg; Claudio Babiloni",institutions:["Duke-NUS Medical School","German Center for Neurodegenerative Diseases","Gordon Center for Medical Imaging","Harvard University","IRCCS Ospedale San Raffaele","Istituto di Ricovero e Cura a Carattere Scientifico San Raffaele","Massachusetts General Hospital","Sapienza University of Rome","Technical University of Munich","University of Rostock"],countries:["DE","IT","SG","US"],year:2016,journal:"Journal of the International Neuropsychological Society",citations:115,abstract:"OBJECTIVES: The objective was to review the literature on diffusion tensor imaging as well as resting-state functional magnetic resonance imaging and electroencephalography (EEG) to unveil neuroanatomical and neurophysiological substrates of Alzheimer's disease (AD) as a brain neural network pathology affecting structural and functional cortical connectivity underlying human cognition. METHODS: We reviewed papers registered in PubMed and other scientific repositories on the use of these techniques in amnesic mild cognitive impairment (MCI) and clinically mild AD dementia patients compared to cognitively intact elderly individuals (Controls). RESULTS: Hundreds of peer-reviewed (cross-sectional and longitudinal) papers have shown in patients with MCI and mild AD compared to Controls (1) impairment of callosal (splenium), thalamic, and anterior-posterior white matter bundles; (2) reduced correlation of resting state blood oxygen level-dependent activity across several intrinsic brain circuits including default mode and attention-related networks; and (3) abnormal power and functional coupling of resting state cortical EEG rhythms. Clinical applications of these measures are still limited. CONCLUSIONS: Structural and functional (in vivo) cortical connectivity measures represent a reliable marker of cerebral reserve capacity and should be used to predict and monitor the evolution of AD and its relative impact on cognitive domains in pre-clinical, prodromal, and dementia stages of AD.",keywords:["Neuroscience","Dementia","Default mode network","Resting state fMRI","Electroencephalography","Alzheimer's disease","Cognition"],concepts:["Neuroscience","Dementia","Default mode network","Psychology","Resting state fMRI","Electroencephalography","Alzheimer's disease","Cognition"],topics:["Dementia and Cognitive Impairment Research","Functional Brain Connectivity Studies","Epilepsy research and treatment"],pdf_url:"https://www.cambridge.org/core/services/aop-cambridge-core/content/view/A9273597980316E0EA453E473244BD02/S1355617715000995a.pdf/div-class-title-measuring-cortical-connectivity-in-alzheimer-s-disease-as-a-brain-neural-network-pathology-toward-clinical-applications-div.pdf",is_oa:!0,n_refs:244,n_refs_in_core:20,degree:35,community:2,deg_w:519.5,betweenness:.0032,pagerank:.00452,eigenvector:.0248,pdf_file:"Teipel_2016.pdf",pdf_downloaded:!0},{id:177,oaid:"W2793015464",doi:"10.1016/j.dcn.2018.02.001",title:"Hubs in the human fetal brain network",authors:[{name:"Marion I. van den Heuvel",institutions:["United States Department of Health and Human Services","Wayne State University","Tilburg University","University Medical Center Utrecht","Eunice Kennedy Shriver National Institute of Child Health and Human Development"]},{name:"Marion I. van den Heuvel",institutions:["Wayne State University","University Medical Center Utrecht"]},{name:"Elise Turk",institutions:["United States Department of Health and Human Services","Wayne State University","University Medical Center Utrecht","Eunice Kennedy Shriver National Institute of Child Health and Human Development"]},{name:"Janessa H. Manning",institutions:["Wayne State University"]},{name:"Jasmine L. Hect",institutions:["United States Department of Health and Human Services","Wayne State University","Eunice Kennedy Shriver National Institute of Child Health and Human Development"]},{name:"Edgar Hernández‐Andrade",institutions:["United States Department of Health and Human Services","Wayne State University","Eunice Kennedy Shriver National Institute of Child Health and Human Development"]},{name:"Sonia S. Hassan",institutions:["United States Department of Health and Human Services","Wayne State University","University of Michigan","Eunice Kennedy Shriver National Institute of Child Health and Human Development","Michigan State University"]},{name:"Roberto Romero",institutions:["Wayne State University","University Medical Center Utrecht"]},{name:"Martijn P. van den Heuvel",institutions:["United States Department of Health and Human Services","Wayne State University","University Medical Center Utrecht","Eunice Kennedy Shriver National Institute of Child Health and Human Development"]},{name:"Martijn P. van den Heuvel",institutions:["Wayne State University","University Medical Center Utrecht"]},{name:"Moriah E. Thomason",institutions:["Wayne State University"]}],authorString:"Marion I. van den Heuvel; Marion I. van den Heuvel; Elise Turk; Janessa H. Manning; Jasmine L. Hect; Edgar Hernández‐Andrade; Sonia S. Hassan; Roberto Romero; Martijn P. van den Heuvel; Martijn P. van den Heuvel; Moriah E. Thomason",institutions:["Eunice Kennedy Shriver National Institute of Child Health and Human Development","Michigan State University","Tilburg University","United States Department of Health and Human Services","University Medical Center Utrecht","University of Michigan","Wayne State University"],countries:["NL","US"],year:2018,journal:"Developmental Cognitive Neuroscience",citations:113,abstract:"Advances in neuroimaging and network analyses have lead to discovery of highly connected regions, or hubs, in the connectional architecture of the human brain. Whether these hubs emerge in utero, has yet to be examined. The current study addresses this question and aims to determine the location of neural hubs in human fetuses. Fetal resting-state fMRI data (N = 105) was used to construct connectivity matrices for 197 discrete brain regions. We discovered that within the connectional functional organization of the human fetal brain key hubs are emerging. Consistent with prior reports in infants, visual and motor regions were identified as emerging hub areas, specifically in cerebellar areas. We also found evidence for network hubs in association cortex, including areas remarkably close to the adult fusiform facial and Wernicke areas. Functional significance of hub structure was confirmed by computationally deleting hub versus random nodes and observing that global efficiency decreased significantly more when hubs were removed (p < .001). Taken together, we conclude that both primary and association brain regions demonstrate centrality in network organization before birth. While fetal hubs may be important for facilitating network communication, they may also form potential points of vulnerability in fetal brain development.",keywords:["Centrality","Neuroscience","Human brain","Neuroimaging","Connectome","Association","Brain mapping"],concepts:["Centrality","Neuroscience","Human brain","Psychology","Neuroimaging","Connectome","Association (psychology)","Brain mapping"],topics:["Functional Brain Connectivity Studies","Neonatal and fetal brain pathology","Neural dynamics and brain function"],pdf_url:"https://www.sciencedirect.com/science/article/pii/S1878929317301755/pdfft?md5=52300907f5cb0fa3abb3541e73ce0391&pid=1-s2.0-S1878929317301755-main.pdf",is_oa:!0,n_refs:71,n_refs_in_core:17,degree:28,community:0,deg_w:231.5,betweenness:.0023,pagerank:.00242,eigenvector:.0124,pdf_file:"Heuvel_2018.pdf",pdf_downloaded:!0},{id:178,oaid:"W1949946847",doi:"10.1002/hbm.23017",title:"Brain network analysis reveals affected connectome structure in bipolar I disorder",authors:[{name:"Guusje Collin",institutions:["University Medical Center Utrecht"]},{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]},{name:"Lucija Abramovic",institutions:["University Medical Center Utrecht"]},{name:"Annabel Vreeker",institutions:["University Medical Center Utrecht"]},{name:"Marcel A. de Reus",institutions:["University Medical Center Utrecht"]},{name:"Neeltje E.M. van Haren",institutions:["University Medical Center Utrecht"]},{name:"Marco P. Boks",institutions:["University Medical Center Utrecht"]},{name:"Roel A. Ophoff",institutions:["University of California, Los Angeles","University Medical Center Utrecht"]},{name:"René S. Kahn",institutions:["University Medical Center Utrecht"]}],authorString:"Guusje Collin; Martijn P. van den Heuvel; Lucija Abramovic; Annabel Vreeker; Marcel A. de Reus; Neeltje E.M. van Haren; Marco P. Boks; Roel A. Ophoff; René S. Kahn",institutions:["University Medical Center Utrecht","University of California, Los Angeles"],countries:["NL","US"],year:2015,journal:"Human Brain Mapping",citations:107,abstract:`The notion that healthy brain function emerges from coordinated neural activity constrained by the brain's network of anatomical connections--i.e., the connectome--suggests that alterations in the connectome's wiring pattern may underlie brain disorders. Corroborating this hypothesis, studies in schizophrenia are indicative of altered connectome architecture including reduced communication efficiency, disruptions of central brain hubs, and affected "rich club" organization. Whether similar deficits are present in bipolar disorder is currently unknown. This study examines structural connectome topology in 216 bipolar I disorder patients as compared to 144 healthy controls, focusing in particular on central regions (i.e., brain hubs) and connections (i.e., rich club connections, interhemispheric connections) of the brain's network. We find that bipolar I disorder patients exhibit reduced global efficiency (-4.4%, P =0.002) and that this deficit relates (r = 0.56, P < 0.001) to reduced connectivity strength of interhemispheric connections (-13.0%, P = 0.001). Bipolar disorder patients were found not to show predominant alterations in the strength of brain hub connections in general, or of connections spanning brain hubs (i.e., "rich club" connections) in particular (all P > 0.1). These findings highlight a role for aberrant brain network architecture in bipolar I disorder with reduced global efficiency in association with disruptions in interhemispheric connectivity, while the central "rich club" system appears not to be particularly affected.`,keywords:["Connectome","Bipolar disorder","Neuroscience","Schizophrenia","Brain function","Functional connectivity","Psychiatry"],concepts:["Connectome","Bipolar disorder","Neuroscience","Schizophrenia (object-oriented programming)","Psychology","Brain function","Functional connectivity"],topics:["Functional Brain Connectivity Studies","Bipolar Disorder and Treatment","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://pure.amsterdamumc.nl/ws/files/159992510/Brain-network-analysis-reveals-affected-connectome-structure-in-bipolar-i-disorder.pdf",is_oa:!0,n_refs:90,n_refs_in_core:16,degree:31,community:0,deg_w:304.5,betweenness:.0015,pagerank:.00289,eigenvector:.0195,pdf_file:"Collin_2015.pdf",pdf_downloaded:!0},{id:179,oaid:"W2160987050",doi:"10.3389/fncom.2013.00189",title:"The Laplacian spectrum of neural networks",authors:[{name:"Siemon C. de Lange",institutions:["University Medical Center Utrecht"]},{name:"Marcel A. de Reus",institutions:["University Medical Center Utrecht"]},{name:"Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"]}],authorString:"Siemon C. de Lange; Marcel A. de Reus; Martijn P. van den Heuvel",institutions:["University Medical Center Utrecht"],countries:["NL"],year:2014,journal:"Frontiers in Computational Neuroscience",citations:107,abstract:`The brain is a complex network of neural interactions, both at the microscopic and macroscopic level. Graph theory is well suited to examine the global network architecture of these neural networks. Many popular graph metrics, however, encode average properties of individual network elements. Complementing these "conventional" graph metrics, the eigenvalue spectrum of the normalized Laplacian describes a network's structure directly at a systems level, without referring to individual nodes or connections. In this paper, the Laplacian spectra of the macroscopic anatomical neuronal networks of the macaque and cat, and the microscopic network of the Caenorhabditis elegans were examined. Consistent with conventional graph metrics, analysis of the Laplacian spectra revealed an integrative community structure in neural brain networks. Extending previous findings of overlap of network attributes across species, similarity of the Laplacian spectra across the cat, macaque and C. elegans neural networks suggests a certain level of consistency in the overall architecture of the anatomical neural networks of these species. Our results further suggest a specific network class for neural networks, distinct from conceptual small-world and scale-free models as well as several empirical networks.`,keywords:["Spectrum","Laplace operator","Artificial neural network","Mathematical analysis"],concepts:["Spectrum (functional analysis)","Laplace operator","Computer science","Artificial neural network","Artificial intelligence"],topics:["Neural Networks and Applications","Neural Networks Stability and Synchronization","Neural dynamics and brain function"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fncom.2013.00189/pdf",is_oa:!0,n_refs:82,n_refs_in_core:15,degree:31,community:0,deg_w:437.5,betweenness:.0011,pagerank:.00372,eigenvector:.0312,pdf_file:"Lange_2014.pdf",pdf_downloaded:!0},{id:180,oaid:"W2053897009",doi:"10.1371/journal.pone.0068860",title:"Glucose Metabolism during Resting State Reveals Abnormal Brain Networks Organization in the Alzheimer’s Disease and Mild Cognitive Impairment",authors:[{name:"Gretel Sanabria-Díaz",institutions:["Cuban Neuroscience Center"]},{name:"Eduardo Martínez‐Montes",institutions:["Cuban Neuroscience Center"]},{name:"Lester Melie‐García",institutions:["Cuban Neuroscience Center"]},{name:"the Alzheimer’s Disease Neuroimaging Initiative",institutions:[]}],authorString:"Gretel Sanabria-Díaz; Eduardo Martínez‐Montes; Lester Melie‐García; the Alzheimer’s Disease Neuroimaging Initiative",institutions:["Cuban Neuroscience Center"],countries:["CU"],year:2013,journal:"PLoS ONE",citations:106,abstract:"This paper aims to study the abnormal patterns of brain glucose metabolism co-variations in Alzheimer disease (AD) and Mild Cognitive Impairment (MCI) patients compared to Normal healthy controls (NC) using the Alzheimer Disease Neuroimaging Initiative (ADNI) database. The local cerebral metabolic rate for glucose (CMRgl) in a set of 90 structures belonging to the AAL atlas was obtained from Fluro-Deoxyglucose Positron Emission Tomography data in resting state. It is assumed that brain regions whose CMRgl values are significantly correlated are functionally associated; therefore, when metabolism is altered in a single region, the alteration will affect the metabolism of other brain areas with which it interrelates. The glucose metabolism network (represented by the matrix of the CMRgl co-variations among all pairs of structures) was studied using the graph theory framework. The highest concurrent fluctuations in CMRgl were basically identified between homologous cortical regions in all groups. Significant differences in CMRgl co-variations in AD and MCI groups as compared to NC were found. The AD and MCI patients showed aberrant patterns in comparison to NC subjects, as detected by global and local network properties (global and local efficiency, clustering index, and others). MCI network's attributes showed an intermediate position between NC and AD, corroborating it as a transitional stage from normal aging to Alzheimer disease. Our study is an attempt at exploring the complex association between glucose metabolism, CMRgl covariations and the attributes of the brain network organization in AD and MCI.",keywords:["Alzheimer's disease","Positron emission tomography","Cognitive decline","Neuroimaging","Resting state fMRI","Neuroscience","Carbohydrate metabolism","Cognitive impairment"],concepts:["Alzheimer's disease","Positron emission tomography","Cognitive decline","Neuroimaging","Resting state fMRI","Neuroscience","Carbohydrate metabolism","Cognitive impairment"],topics:["Functional Brain Connectivity Studies","Alzheimer's disease research and treatments","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0068860&type=printable",is_oa:!0,n_refs:138,n_refs_in_core:20,degree:34,community:1,deg_w:482,betweenness:.0021,pagerank:.00402,eigenvector:.0372,pdf_file:"Sanabria-Daz_2013.pdf",pdf_downloaded:!0},{id:181,oaid:"W2049130306",doi:"10.3389/fnsys.2012.00043",title:"MR connectomics: a conceptual framework for studying the developing brain",authors:[{name:"Patric Hagmann",institutions:["École Polytechnique Fédérale de Lausanne","University of Lausanne"]},{name:"P. Ellen Grant",institutions:["Boston Children's Hospital","Massachusetts General Hospital","Athinoula A. Martinos Center for Biomedical Imaging"]},{name:"Damien A. Fair",institutions:["Oregon Health & Science University"]}],authorString:"Patric Hagmann; P. Ellen Grant; Damien A. Fair",institutions:["Athinoula A. Martinos Center for Biomedical Imaging","Boston Children's Hospital","Massachusetts General Hospital","Oregon Health & Science University","University of Lausanne","École Polytechnique Fédérale de Lausanne"],countries:["CH","US"],year:2012,journal:"Frontiers in Systems Neuroscience",citations:102,abstract:`THE COMBINATION OF ADVANCED NEUROIMAGING TECHNIQUES AND MAJOR DEVELOPMENTS IN COMPLEX NETWORK SCIENCE, HAVE GIVEN BIRTH TO A NEW FRAMEWORK FOR STUDYING THE BRAIN: "connectomics." This framework provides the ability to describe and study the brain as a dynamic network and to explore how the coordination and integration of information processing may occur. In recent years this framework has been used to investigate the developing brain and has shed light on many dynamic changes occurring from infancy through adulthood. The aim of this article is to review this work and to discuss what we have learned from it. We will also use this body of work to highlight key technical aspects that are necessary in general for successful connectome analysis using today's advanced neuroimaging techniques. We look to identify current limitations of such approaches, what can be improved, and how these points generalize to other topics in connectome research.`,keywords:["Connectomics","Neuroscience","Connectome","Cognitive science","Functional connectivity"],concepts:["Connectomics","Neuroscience","Connectome","Computer science","Cognitive science"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnsys.2012.00043/pdf",is_oa:!0,n_refs:267,n_refs_in_core:17,degree:34,community:2,deg_w:757,betweenness:.002,pagerank:.00576,eigenvector:.067,pdf_file:"Hagmann_2012.pdf",pdf_downloaded:!0},{id:182,oaid:"W2038911336",doi:"10.3389/fnsys.2015.00044",title:"Brain enhancement through cognitive training: a new insight from brain connectome",authors:[{name:"Fumihiko Taya",institutions:["National University of Singapore"]},{name:"Yu Sun",institutions:["National University of Singapore"]},{name:"Fabio Babiloni",institutions:["Sapienza University of Rome"]},{name:"Nitish V. Thakor",institutions:["Johns Hopkins University","National University of Singapore"]},{name:"Anastasios Bezerianos",institutions:["National University of Singapore"]}],authorString:"Fumihiko Taya; Yu Sun; Fabio Babiloni; Nitish V. Thakor; Anastasios Bezerianos",institutions:["Johns Hopkins University","National University of Singapore","Sapienza University of Rome"],countries:["IT","SG","US"],year:2015,journal:"Frontiers in Systems Neuroscience",citations:101,abstract:"Owing to the recent advances in neurotechnology and the progress in understanding of brain cognitive functions, improvements of cognitive performance or acceleration of learning process with brain enhancement systems is not out of our reach anymore, on the contrary, it is a tangible target of contemporary research. Although a variety of approaches have been proposed, we will mainly focus on cognitive training interventions, in which learners repeatedly perform cognitive tasks to improve their cognitive abilities. In this review article, we propose that the learning process during the cognitive training can be facilitated by an assistive system monitoring cognitive workloads using electroencephalography (EEG) biomarkers, and the brain connectome approach can provide additional valuable biomarkers for facilitating leaners' learning processes. For the purpose, we will introduce studies on the cognitive training interventions, EEG biomarkers for cognitive workload, and human brain connectome. As cognitive overload and mental fatigue would reduce or even eliminate gains of cognitive training interventions, a real-time monitoring of cognitive workload can facilitate the learning process by flexibly adjusting difficulty levels of the training task. Moreover, cognitive training interventions should have effects on brain sub-networks, not on a single brain region, and graph theoretical network metrics quantifying topological architecture of the brain network can differentiate with respect to individual cognitive states as well as to different individuals' cognitive abilities, suggesting that the connectome is a valuable approach for tracking the learning progress. Although only a few studies have exploited the connectome approach for studying alterations of the brain network induced by cognitive training interventions so far, we believe that it would be a useful technique for capturing improvements of cognitive functions.",keywords:["Cognition","Connectome","Cognitive training","Psychological intervention","Process","Effects of sleep deprivation on cognitive performance"],concepts:["Cognition","Connectome","Cognitive training","Psychological intervention","Computer science","Psychology","Process (computing)","Effects of sleep deprivation on cognitive performance"],topics:["Functional Brain Connectivity Studies","EEG and Brain-Computer Interfaces","Cognitive Functions and Memory"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnsys.2015.00044/pdf",is_oa:!0,n_refs:182,n_refs_in_core:19,degree:33,community:0,deg_w:409,betweenness:.0022,pagerank:.00344,eigenvector:.036,pdf_file:"Taya_2015.pdf",pdf_downloaded:!0},{id:183,oaid:"W2092457219",doi:"10.1371/journal.pcbi.1003557",title:"Influence of Wiring Cost on the Large-Scale Architecture of Human Cortical Connectivity",authors:[{name:"Dávid Samu",institutions:["University of Sussex"]},{name:"Anil K. Seth",institutions:["University of Sussex"]},{name:"Thomas Nowotny",institutions:["University of Sussex"]}],authorString:"Dávid Samu; Anil K. Seth; Thomas Nowotny",institutions:["University of Sussex"],countries:["GB"],year:2014,journal:"PLoS Computational Biology",citations:101,abstract:"In the past two decades some fundamental properties of cortical connectivity have been discovered: small-world structure, pronounced hierarchical and modular organisation, and strong core and rich-club structures. A common assumption when interpreting results of this kind is that the observed structural properties are present to enable the brain's function. However, the brain is also embedded into the limited space of the skull and its wiring has associated developmental and metabolic costs. These basic physical and economic aspects place separate, often conflicting, constraints on the brain's connectivity, which must be characterized in order to understand the true relationship between brain structure and function. To address this challenge, here we ask which, and to what extent, aspects of the structural organisation of the brain are conserved if we preserve specific spatial and topological properties of the brain but otherwise randomise its connectivity. We perform a comparative analysis of a connectivity map of the cortical connectome both on high- and low-resolutions utilising three different types of surrogate networks: spatially unconstrained ('random'), connection length preserving ('spatial'), and connection length optimised ('reduced') surrogates. We find that unconstrained randomisation markedly diminishes all investigated architectural properties of cortical connectivity. By contrast, spatial and reduced surrogates largely preserve most properties and, interestingly, often more so in the reduced surrogates. Specifically, our results suggest that the cortical network is less tightly integrated than its spatial constraints would allow, but more strongly segregated than its spatial constraints would necessitate. We additionally find that hierarchical organisation and rich-club structure of the cortical connectivity are largely preserved in spatial and reduced surrogates and hence may be partially attributable to cortical wiring constraints. In contrast, the high modularity and strong s-core of the high-resolution cortical network are significantly stronger than in the surrogates, underlining their potential functional relevance in the brain.",keywords:["Connectome","Connectomics","Modular design","Modularity","Function","Scale","Neuroscience"],concepts:["Connectome","Computer science","Connectomics","Modular design","Modularity (biology)","Function (biology)","Scale (ratio)","Neuroscience"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Neural dynamics and brain function"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1003557&type=printable",is_oa:!0,n_refs:102,n_refs_in_core:20,degree:38,community:0,deg_w:668.5,betweenness:.0024,pagerank:.00506,eigenvector:.0656,pdf_file:"Samu_2014.pdf",pdf_downloaded:!0},{id:184,oaid:"W2121594036",doi:"10.1098/rstb.2013.0525",title:"Functional brain networks: great expectations, hard times and the big leap forward",authors:[{name:"David Papo",institutions:["Universidad Politécnica de Madrid"]},{name:"Massimiliano Zanin",institutions:["Innaxis Foundation & Research Institute","Universidade Nova de Lisboa"]},{name:"José A. Pineda‐Pardo",institutions:["Universidad Politécnica de Madrid"]},{name:"Stefano Boccaletti",institutions:["Institute for Complex Systems"]},{name:"Javier M. Buldú",institutions:["Universidad Rey Juan Carlos","Universidad Politécnica de Madrid"]}],authorString:"David Papo; Massimiliano Zanin; José A. Pineda‐Pardo; Stefano Boccaletti; Javier M. Buldú",institutions:["Innaxis Foundation & Research Institute","Institute for Complex Systems","Universidad Politécnica de Madrid","Universidad Rey Juan Carlos","Universidade Nova de Lisboa"],countries:["ES","IT","PT"],year:2014,journal:"Philosophical Transactions of the Royal Society B Biological Sciences",citations:99,abstract:"Many physical and biological systems can be studied using complex network theory, a new statistical physics understanding of graph theory. The recent application of complex network theory to the study of functional brain networks has generated great enthusiasm as it allows addressing hitherto non-standard issues in the field, such as efficiency of brain functioning or vulnerability to damage. However, in spite of its high degree of generality, the theory was originally designed to describe systems profoundly different from the brain. We discuss some important caveats in the wholesale application of existing tools and concepts to a field they were not originally designed to describe. At the same time, we argue that complex network theory has not yet been taken full advantage of, as many of its important aspects are yet to make their appearance in the neuroscience literature. Finally, we propose that, rather than simply borrowing from an existing theory, functional neural networks can inspire a fundamental reformulation of complex network theory, to account for its exquisitely complex functioning mode.",keywords:["Generality","Cognitive science","Complex network","Graph theory","Enthusiasm","Complex system","Field"],concepts:["Generality","Computer science","Cognitive science","Complex network","Graph theory","Enthusiasm","Complex system","Field (mathematics)"],topics:["Neural dynamics and brain function","Functional Brain Connectivity Studies","stochastic dynamics and bifurcation"],pdf_url:"https://royalsocietypublishing.org/doi/pdf/10.1098/rstb.2013.0525",is_oa:!0,n_refs:176,n_refs_in_core:18,degree:33,community:0,deg_w:581,betweenness:.0015,pagerank:.00454,eigenvector:.0526,pdf_file:null,pdf_downloaded:!1},{id:185,oaid:"W2022891394",doi:"10.3389/fnhum.2014.00647",title:"Simulated rich club lesioning in brain networks: a scaffold for communication and integration?",authors:[{name:"Marcel A. de Reus",institutions:["Utrecht University"]},{name:"Martijn P. van den Heuvel",institutions:[]}],authorString:"Marcel A. de Reus; Martijn P. van den Heuvel",institutions:["Utrecht University"],countries:["NL"],year:2014,journal:"Frontiers in Human Neuroscience",citations:98,abstract:"OPINION article Front. Hum. Neurosci., 21 August 2014Sec. Cognitive Neuroscience https://doi.org/10.3389/fnhum.2014.00647",keywords:["Hum","Neuroscience","Club","Cognition","Cognitive science","Art"],concepts:["Hum","Neuroscience","Club","Cognition","Psychology","Cognitive science"],topics:["Advanced Memory and Neural Computing","Functional Brain Connectivity Studies","Neural dynamics and brain function"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnhum.2014.00647/pdf",is_oa:!0,n_refs:35,n_refs_in_core:13,degree:29,community:0,deg_w:259,betweenness:.0014,pagerank:.00268,eigenvector:.0102,pdf_file:"Reus_2014.pdf",pdf_downloaded:!0},{id:186,oaid:"W2609116249",doi:"10.3389/fnana.2017.00034",title:"Construction of Individual Morphological Brain Networks with Multiple Morphometric Features",authors:[{name:"Wan Li",institutions:["Beijing University of Technology","Henan Bioengineering Technology Research Center"]},{name:"Chunlan Yang",institutions:["Beijing University of Technology","Henan Bioengineering Technology Research Center"]},{name:"Feng Shi",institutions:["Cedars-Sinai Medical Center"]},{name:"Shuicai Wu",institutions:["Beijing University of Technology","Henan Bioengineering Technology Research Center"]},{name:"Qun Wang",institutions:["Beijing Tian Tan Hospital"]},{name:"Yingnan Nie",institutions:["Beijing University of Technology","Henan Bioengineering Technology Research Center"]},{name:"Xin Zhang",institutions:["Beijing University of Technology","Henan Bioengineering Technology Research Center"]}],authorString:"Wan Li; Chunlan Yang; Feng Shi; Shuicai Wu; Qun Wang; Yingnan Nie; Xin Zhang",institutions:["Beijing Tian Tan Hospital","Beijing University of Technology","Cedars-Sinai Medical Center","Henan Bioengineering Technology Research Center"],countries:["CN","US"],year:2017,journal:"Frontiers in Neuroanatomy",citations:98,abstract:"In recent years, researchers have increased attentions to the morphological brain network, which is generally constructed by measuring the mathematical correlation across regions using a certain morphometric feature, such as regional cortical thickness and voxel intensity. However, cerebral structure can be characterized by various factors, such as regional volume, surface area, and curvature. Moreover, most of the morphological brain networks are population-based, which has limitations in the investigations of individual difference and clinical applications. Hence, we have extended previous studies by proposing a novel method for realizing the construction of an individual-based morphological brain network through a combination of multiple morphometric features. In particular, interregional connections are estimated using our newly introduced feature vectors, namely, the Pearson correlation coefficient of the concatenation of seven morphometric features. Experiments were performed on a healthy cohort of 55 subjects (24 males aged from 20 to 29 and 31 females aged from 20 to 28) each scanned twice, and reproducibility was evaluated through test-retest reliability. The robustness of morphometric features was measured firstly to select the more reproducible features to form the connectomes. Then the topological properties were analyzed and compared with previous reports of different modalities. Small-worldness was observed in all the subjects at the range of the entire network sparsity (20-40%), and configurations were comparable with previous findings at the sparsity of 23%. The spatial distributions of the hub were found to be significantly influenced by the individual variances, and the hubs obtained by averaging across subjects and sparsities showed correspondence with previous reports. The intraclass coefficient of graphic properties (clustering coefficient = 0.83, characteristic path length = 0.81, betweenness centrality = 0.78) indicates the robustness of the present method. Results demonstrate that the multiple morphometric features can be applied to form a rational reproducible individual-based morphological brain network.",keywords:["Pattern recognition","Voxel","Human Connectome Project","Feature","Correlation","Concatenation","Connectome"],concepts:["Pattern recognition (psychology)","Artificial intelligence","Voxel","Human Connectome Project","Feature (linguistics)","Correlation","Concatenation (mathematics)","Connectome"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Neural dynamics and brain function"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnana.2017.00034/pdf",is_oa:!0,n_refs:83,n_refs_in_core:18,degree:32,community:1,deg_w:468,betweenness:8e-4,pagerank:.0037,eigenvector:.0495,pdf_file:"Li_2017.pdf",pdf_downloaded:!0},{id:187,oaid:"W2766024669",doi:"10.1111/jcpp.12838",title:"Annual Research Review: Not just a small adult brain: understanding later neurodevelopment through imaging the neonatal brain",authors:[{name:"Dafnis Batallé",institutions:["King's College London"]},{name:"A. David Edwards",institutions:["King's College London"]},{name:"Jonathan O’Muircheartaigh",institutions:["Wellcome Centre for Human Neuroimaging","King's College London"]}],authorString:"Dafnis Batallé; A. David Edwards; Jonathan O’Muircheartaigh",institutions:["King's College London","Wellcome Centre for Human Neuroimaging"],countries:["GB"],year:2017,journal:"Journal of Child Psychology and Psychiatry",citations:97,abstract:"BACKGROUND: There has been a recent proliferation in neuroimaging research focusing on brain development in the prenatal, neonatal and very early childhood brain. Early brain injury and preterm birth are associated with increased risk of neurodevelopmental disorders, indicating the importance of this early period for later outcome. SCOPE AND METHODOLOGY: Although using a wide range of different methodologies and investigating diverse samples, the common aim of many of these studies has been to both track normative development and investigate deviations in this development to predict behavioural, cognitive and neurological function in childhood. Here we review structural and functional neuroimaging studies investigating the developing brain. We focus on practical and technical complexities of studying this early age range and discuss how neuroimaging techniques have been successfully applied to investigate later neurodevelopmental outcome. CONCLUSIONS: Neuroimaging markers of later outcome still have surprisingly low predictive power and their specificity to individual neurodevelopmental disorders is still under question. However, the field is still young, and substantial challenges to both acquiring and modeling neonatal data are being met.",keywords:["Neuroimaging","Brain research","Neuroscience","Brain development","Developmental psychology"],concepts:["Psychology","Neuroimaging","Brain research","Neuroscience","Brain development","Developmental psychology"],topics:["Neonatal and fetal brain pathology","Infant Development and Preterm Care","Functional Brain Connectivity Studies"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/jcpp.12838",is_oa:!0,n_refs:237,n_refs_in_core:14,degree:25,community:0,deg_w:232,betweenness:.0019,pagerank:.00241,eigenvector:.0125,pdf_file:"Batall_2017.pdf",pdf_downloaded:!0},{id:188,oaid:"W2787478603",doi:"10.1371/journal.pcbi.1005989",title:"Hub connectivity, neuronal diversity, and gene expression in the Caenorhabditis elegans connectome",authors:[{name:"Aurina Arnatkevičiūtė",institutions:["Monash University"]},{name:"Ben Fulcher",institutions:["Monash University"]},{name:"Roger Pocock",institutions:["Monash University"]},{name:"Alex Fornito",institutions:["Monash University"]}],authorString:"Aurina Arnatkevičiūtė; Ben Fulcher; Roger Pocock; Alex Fornito",institutions:["Monash University"],countries:["AU"],year:2018,journal:"PLoS Computational Biology",citations:95,abstract:"Studies of nervous system connectivity, in a wide variety of species and at different scales of resolution, have identified several highly conserved motifs of network organization. One such motif is a heterogeneous distribution of connectivity across neural elements, such that some elements act as highly connected and functionally important network hubs. These brain network hubs are also densely interconnected, forming a so-called rich club. Recent work in mouse has identified a distinctive transcriptional signature of neural hubs, characterized by tightly coupled expression of oxidative metabolism genes, with similar genes characterizing macroscale inter-modular hub regions of the human cortex. Here, we sought to determine whether hubs of the neuronal C. elegans connectome also show tightly coupled gene expression. Using open data on the chemical and electrical connectivity of 279 C. elegans neurons, and binary gene expression data for each neuron across 948 genes, we computed a correlated gene expression score for each pair of neurons, providing a measure of their gene expression similarity. We demonstrate that connections between hub neurons are the most similar in their gene expression while connections between nonhubs are the least similar. Genes with the greatest contribution to this effect are involved in glutamatergic and cholinergic signaling, and other communication processes. We further show that coupled expression between hub neurons cannot be explained by their neuronal subtype (i.e., sensory, motor, or interneuron), separation distance, chemically secreted neurotransmitter, birth time, pairwise lineage distance, or their topological module affiliation. Instead, this coupling is intrinsically linked to the identity of most hubs as command interneurons, a specific class of interneurons that regulates locomotion. Our results suggest that neural hubs may possess a distinctive transcriptional signature, preserved across scales and species, that is related to the involvement of hubs in regulating the higher-order behaviors of a given organism.",keywords:["Interneuron","Connectome","Neuroscience","Gene","Caenorhabditis elegans","Connectomics","Gene expression"],concepts:["Biology","Interneuron","Connectome","Neuroscience","Gene","Caenorhabditis elegans","Connectomics","Gene expression"],topics:["Genetics, Aging, and Longevity in Model Organisms","Mitochondrial Function and Pathology","Photoreceptor and optogenetics research"],pdf_url:"https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1005989&type=printable",is_oa:!0,n_refs:135,n_refs_in_core:21,degree:37,community:0,deg_w:605,betweenness:.0017,pagerank:.00503,eigenvector:.0287,pdf_file:"Arnatkeviit_2018.pdf",pdf_downloaded:!0},{id:189,oaid:"W2154829277",doi:"10.3389/fnsys.2012.00001",title:"Tinnitus: network pathophysiology-network pharmacology",authors:[{name:"Ana Belén Elgoyhen",institutions:["Consejo Nacional de Investigaciones Científicas y Técnicas","Universidad de Buenos Aires","Experimental Medicine and Biology Institute"]},{name:"Berthold Langguth",institutions:["University of Regensburg"]},{name:"Sven Vanneste",institutions:["Antwerp University Hospital"]},{name:"Dirk De Ridder",institutions:["Antwerp University Hospital"]}],authorString:"Ana Belén Elgoyhen; Berthold Langguth; Sven Vanneste; Dirk De Ridder",institutions:["Antwerp University Hospital","Consejo Nacional de Investigaciones Científicas y Técnicas","Experimental Medicine and Biology Institute","Universidad de Buenos Aires","University of Regensburg"],countries:["AR","BE","DE"],year:2012,journal:"Frontiers in Systems Neuroscience",citations:95,abstract:'Tinnitus, the phantom perception of sound, is a prevalent disorder. One in 10 adults has clinically significant subjective tinnitus, and for one in 100, tinnitus severely affects their quality of life. Despite the significant unmet clinical need for a safe and effective drug targeting tinnitus relief, there is currently not a single Food and Drug Administration (FDA)-approved drug on the market. The search for drugs that target tinnitus is hampered by the lack of a deep knowledge of the underlying neural substrates of this pathology. Recent studies are increasingly demonstrating that, as described for other central nervous system (CNS) disorders, tinnitus is a pathology of brain networks. The application of graph theoretical analysis to brain networks has recently provided new information concerning their topology, their robustness and their vulnerability to attacks. Moreover, the philosophy behind drug design and pharmacotherapy in CNS pathologies is changing from that of "magic bullets" that target individual chemoreceptors or "disease-causing genes" into that of "magic shotguns," "promiscuous" or "dirty drugs" that target "disease-causing networks," also known as network pharmacology. In the present work we provide some insight into how this knowledge could be applied to tinnitus pathophysiology and pharmacotherapy.',keywords:["Tinnitus","Medicine","Neuroscience","Disease","Pharmacotherapy","Audiology","Psychiatry"],concepts:["Tinnitus","Medicine","Neuroscience","Disease","Pharmacotherapy"],topics:["Neural dynamics and brain function","Olfactory and Sensory Function Studies","Functional Brain Connectivity Studies"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnsys.2012.00001/pdf",is_oa:!0,n_refs:236,n_refs_in_core:17,degree:31,community:1,deg_w:490,betweenness:6e-4,pagerank:.00377,eigenvector:.0602,pdf_file:"Elgoyhen_2012.pdf",pdf_downloaded:!0},{id:190,oaid:"W3212204052",doi:"10.3389/fnins.2022.816331",title:"Functional Connectivity of the Brain Across Rodents and Humans",authors:[{name:"Nan Xu",institutions:["Georgia Institute of Technology","Emory University"]},{name:"Theodore J. LaGrow",institutions:["Georgia Institute of Technology"]},{name:"Nmachi Anumba",institutions:["Georgia Institute of Technology","Emory University"]},{name:"Azalea Lee",institutions:["Emory University"]},{name:"Xiaodi Zhang",institutions:["Georgia Institute of Technology","Emory University"]},{name:"Behnaz Yousefi",institutions:["Georgia Institute of Technology","Emory University"]},{name:"Yasmine Bassil",institutions:["Emory University"]},{name:"Gloria Perrin Clavijo",institutions:["Georgia Institute of Technology","Emory University"]},{name:"Vahid Khalilzad Sharghi",institutions:["Georgia Institute of Technology","Emory University"]},{name:"Eric Maltbie",institutions:["Georgia Institute of Technology","Emory University"]},{name:"Lisa Meyer-Baese",institutions:["Georgia Institute of Technology","Emory University"]},{name:"Maysam Nezafati",institutions:["Georgia Institute of Technology","Emory University"]},{name:"Wen‐Ju Pan",institutions:["Georgia Institute of Technology","Emory University"]},{name:"Shella Keilholz",institutions:["Georgia Institute of Technology","Emory University"]}],authorString:"Nan Xu; Theodore J. LaGrow; Nmachi Anumba; Azalea Lee; Xiaodi Zhang; Behnaz Yousefi; Yasmine Bassil; Gloria Perrin Clavijo; Vahid Khalilzad Sharghi; Eric Maltbie; Lisa Meyer-Baese; Maysam Nezafati et al.",institutions:["Emory University","Georgia Institute of Technology"],countries:["US"],year:2022,journal:"Frontiers in Neuroscience",citations:95,abstract:"Resting-state functional magnetic resonance imaging (rs-fMRI), which measures the spontaneous fluctuations in the blood oxygen level-dependent (BOLD) signal, is increasingly utilized for the investigation of the brain's physiological and pathological functional activity. Rodents, as a typical animal model in neuroscience, play an important role in the studies that examine the neuronal processes that underpin the spontaneous fluctuations in the BOLD signal and the functional connectivity that results. Translating this knowledge from rodents to humans requires a basic knowledge of the similarities and differences across species in terms of both the BOLD signal fluctuations and the resulting functional connectivity. This review begins by examining similarities and differences in anatomical features, acquisition parameters, and preprocessing techniques, as factors that contribute to functional connectivity. Homologous functional networks are compared across species, and aspects of the BOLD fluctuations such as the topography of the global signal and the relationship between structural and functional connectivity are examined. Time-varying features of functional connectivity, obtained by sliding windowed approaches, quasi-periodic patterns, and coactivation patterns, are compared across species. Applications demonstrating the use of rs-fMRI as a translational tool for cross-species analysis are discussed, with an emphasis on neurological and psychiatric disorders. Finally, open questions are presented to encapsulate the future direction of the field.",keywords:["Functional connectivity","Neuroscience","Coactivation","Functional magnetic resonance imaging","Dynamic functional connectivity","Resting state fMRI","Blood-oxygen-level dependent","Functional imaging"],concepts:["Functional connectivity","Neuroscience","Coactivation","Functional magnetic resonance imaging","Dynamic functional connectivity","Resting state fMRI","Blood-oxygen-level dependent","Functional imaging"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced MRI Techniques and Applications"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnins.2022.816331/pdf",is_oa:!0,n_refs:333,n_refs_in_core:18,degree:32,community:2,deg_w:293,betweenness:.0059,pagerank:.00297,eigenvector:.0103,pdf_file:"Xu_2022.pdf",pdf_downloaded:!0},{id:191,oaid:"W2905339609",doi:"10.3389/fnagi.2018.00404",title:"Alterations in Brain Network Topology and Structural-Functional Connectome Coupling Relate to Cognitive Impairment",authors:[{name:"Juan Wang",institutions:["National Neuroscience Institute","National University of Singapore"]},{name:"Reza Khosrowabadi",institutions:["Shahid Beheshti University","Institute for Cognitive Science Studies","National Neuroscience Institute","National University of Singapore"]},{name:"Kwun Kei Ng",institutions:["National University of Singapore","National Neuroscience Institute"]},{name:"Zhaoping Hong",institutions:["National University of Singapore","National Neuroscience Institute"]},{name:"Joanna Su Xian Chong",institutions:["National Neuroscience Institute","National University of Singapore"]},{name:"Yijun Wang",institutions:["National Neuroscience Institute","National University of Singapore"]},{name:"Chun-Yin Chen",institutions:["National Neuroscience Institute","National University of Singapore"]},{name:"Saima Hilal",institutions:["National University of Singapore"]},{name:"Narayanaswamy Venketasubramanian",institutions:["Raffles Institution"]},{name:"Tien Yin Wong",institutions:["Singapore National Eye Center","National University Health System","Singapore Eye Research Institute"]},{name:"Christopher Chen",institutions:["National Neuroscience Institute","National University of Singapore"]},{name:"M. Kamran Ikram",institutions:["Singapore National Eye Center","Singapore Eye Research Institute","National University of Singapore","National University Health System","University Medical Center Utrecht"]},{name:"Juan Zhou",institutions:["National University of Singapore","Agency for Science, Technology and Research","National Neuroscience Institute"]}],authorString:"Juan Wang; Reza Khosrowabadi; Kwun Kei Ng; Zhaoping Hong; Joanna Su Xian Chong; Yijun Wang; Chun-Yin Chen; Saima Hilal; Narayanaswamy Venketasubramanian; Tien Yin Wong; Christopher Chen; M. Kamran Ikram et al.",institutions:["Agency for Science, Technology and Research","Institute for Cognitive Science Studies","National Neuroscience Institute","National University Health System","National University of Singapore","Raffles Institution","Shahid Beheshti University","Singapore Eye Research Institute","Singapore National Eye Center","University Medical Center Utrecht"],countries:["IR","NL","SG"],year:2018,journal:"Frontiers in Aging Neuroscience",citations:94,abstract:"According to the network-based neurodegeneration hypothesis, neurodegenerative diseases target specific large-scale neural networks, such as the default mode network, and may propagate along the structural and functional connections within and between these brain networks. Cognitive impairment no dementia (CIND) represents an early prodromal stage but few studies have examined brain topological changes within and between brain structural and functional networks. To this end, we studied the structural networks [diffusion magnetic resonance imaging (MRI)] and functional networks (task-free functional MRI) in CIND (61 mild, 56 moderate) and healthy older adults (97 controls). Structurally, compared with controls, moderate CIND had lower global efficiency, and lower nodal centrality and nodal efficiency in the thalamus, somatomotor network, and higher-order cognitive networks. Mild CIND only had higher nodal degree centrality in dorsal parietal regions. Functional differences were more subtle, with both CIND groups showing lower nodal centrality and efficiency in temporal and somatomotor regions. Importantly, CIND generally had higher structural-functional connectome correlation than controls. The higher structural-functional topological similarity was undesirable as higher correlation was associated with poorer verbal memory, executive function, and visuoconstruction. Our findings highlighted the distinct and progressive changes in brain structural-functional networks at the prodromal stage of neurodegenerative diseases.",keywords:["Connectome","Functional magnetic resonance imaging","Neuroscience","Cognition","Default mode network","Betweenness centrality","Centrality"],concepts:["Connectome","Functional magnetic resonance imaging","Neuroscience","Cognition","Default mode network","Betweenness centrality","Centrality","Psychology"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Dementia and Cognitive Impairment Research"],pdf_url:"https://www.frontiersin.org/articles/10.3389/fnagi.2018.00404/pdf",is_oa:!0,n_refs:143,n_refs_in_core:22,degree:36,community:1,deg_w:522.5,betweenness:.003,pagerank:.0042,eigenvector:.0416,pdf_file:"Wang_2018.pdf",pdf_downloaded:!0},{id:192,oaid:"W2130847410",doi:"10.1186/s12868-015-0193-z",title:"Kuramoto model simulation of neural hubs and dynamic synchrony in the human cerebral connectome",authors:[{name:"Ruben Schmidt",institutions:["Utrecht University","Heidelberg University","University Hospital Heidelberg","University Medical Center Utrecht"]},{name:"Karl J. R. LaFleur",institutions:["Utrecht University","Heidelberg University","University Hospital Heidelberg","University Medical Center Utrecht"]},{name:"Marcel A. de Reus",institutions:["Heidelberg University","University Hospital Heidelberg","University Medical Center Utrecht"]},{name:"Leonard H. van den Berg",institutions:["Utrecht University","Heidelberg University","University Hospital Heidelberg","University Medical Center Utrecht"]},{name:"Martijn P. van den Heuvel",institutions:["Heidelberg University","University Hospital Heidelberg","University Medical Center Utrecht"]}],authorString:"Ruben Schmidt; Karl J. R. LaFleur; Marcel A. de Reus; Leonard H. van den Berg; Martijn P. van den Heuvel",institutions:["Heidelberg University","University Hospital Heidelberg","University Medical Center Utrecht","Utrecht University"],countries:["DE","NL"],year:2015,journal:"BMC Neuroscience",citations:91,abstract:"BACKGROUND: The topological structure of the wiring of the mammalian brain cortex plays an important role in shaping the functional dynamics of large-scale neural activity. Due to their central embedding in the network, high degree hub regions and their connections (often referred to as the 'rich club') have been hypothesized to facilitate intermodular neural communication and global integration of information by means of synchronization. Here, we examined the theoretical role of anatomical hubs and their wiring in brain dynamics. The Kuramoto model was used to simulate interaction of cortical brain areas by means of coupled phase oscillators-with anatomical connections between regions derived from diffusion weighted imaging and module assignment of brain regions based on empirically determined resting-state data. RESULTS: Our findings show that synchrony among hub nodes was higher than any module's intramodular synchrony (p < 10(-4), for cortical coupling strengths, λ, in the range 0.02 < λ < 0.05), suggesting that hub nodes lead the functional modules in the process of synchronization. Furthermore, suppressing structural connectivity among hub nodes resulted in an elevated modular state (p < 4.1 × l0(-3), 0.015 < λ < 0.04), indicating that hub-to-hub connections are critical in intermodular synchronization. Finally, perturbing the oscillatory behavior of hub nodes prevented functional modules from synchronizing, implying that synchronization of functional modules is dependent on the hub nodes' behavior. CONCLUSION: Our results converge on anatomical hubs having a leading role in intermodular synchronization and integration in the human brain.",keywords:["Connectome","Synchronization","Process","Synchronizing","Neuroscience","Modular design","Kuramoto model"],concepts:["Connectome","Synchronization (alternating current)","Computer science","Process (computing)","Synchronizing","Neuroscience","Modular design","Kuramoto model"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Cerebrospinal fluid and hydrocephalus"],pdf_url:"https://bmcneurosci.biomedcentral.com/counter/pdf/10.1186/s12868-015-0193-z",is_oa:!0,n_refs:61,n_refs_in_core:13,degree:28,community:0,deg_w:278,betweenness:.0018,pagerank:.00282,eigenvector:.0118,pdf_file:"Schmidt_2015.pdf",pdf_downloaded:!0},{id:193,oaid:"W2212279317",doi:"10.1038/srep17755",title:"Functional properties of resting state networks in healthy full-term newborns",authors:[{name:"Josepheen De Asis‐Cruz",institutions:["Children's National"]},{name:"Marine Bouyssi-Kobar",institutions:["Children's National"]},{name:"Iordanis E. Evangelou",institutions:["Children's National"]},{name:"Gilbert Vézina",institutions:["Children's National"]},{name:"Catherine Limperopoulos",institutions:["Children's National"]}],authorString:"Josepheen De Asis‐Cruz; Marine Bouyssi-Kobar; Iordanis E. Evangelou; Gilbert Vézina; Catherine Limperopoulos",institutions:["Children's National"],countries:["US"],year:2015,journal:"Scientific Reports",citations:86,abstract:"Objective, early, and non-invasive assessment of brain function in high-risk newborns is critical to initiate timely interventions and to minimize long-term neurodevelopmental disabilities. A prerequisite to identifying deviations from normal, however, is the availability of baseline measures of brain function derived from healthy, full-term newborns. Recent advances in functional MRI combined with graph theoretic techniques may provide important, currently unavailable, quantitative markers of normal neurodevelopment. In the current study, we describe important properties of resting state networks in 60 healthy, full-term, unsedated newborns. The neonate brain exhibited an efficient and economical small world topology: densely connected nearby regions, sparse, but well integrated, distant connections, a small world index greater than 1, and global/local efficiency greater than network cost. These networks showed a heavy-tailed degree distribution, suggesting the presence of regions that are more richly connected to others ('hubs'). These hubs, identified using degree and betweenness centrality measures, show a more mature hub organization than previously reported. Targeted attacks on hubs show that neonate networks are more resilient than simulated scale-free networks. Networks fragmented faster and global efficiency decreased faster when betweenness, as opposed to degree, hubs were attacked suggesting a more influential role of betweenness hub in the neonate network.",keywords:["Betweenness centrality","Centrality","Complex network","Term","Degree distribution","Small-world network","Resting state fMRI"],concepts:["Betweenness centrality","Centrality","Computer science","Complex network","Term (time)","Degree distribution","Small-world network","Resting state fMRI"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Photoreceptor and optogenetics research"],pdf_url:"https://www.nature.com/articles/srep17755.pdf",is_oa:!0,n_refs:65,n_refs_in_core:15,degree:31,community:0,deg_w:396,betweenness:.0022,pagerank:.00346,eigenvector:.0301,pdf_file:"AsisCruz_2015.pdf",pdf_downloaded:!0},{id:194,oaid:"W1968637703",doi:"10.1007/s40708-015-0009-z",title:"A review of structural and functional brain networks: small world and atlas",authors:[{name:"Zhijun Yao",institutions:["Lanzhou University"]},{name:"Bin Hu",institutions:["Lanzhou University"]},{name:"Yuanwei Xie",institutions:["Lanzhou University"]},{name:"Philip Moore",institutions:["Lanzhou University"]},{name:"Jiaxiang Zheng",institutions:["Lanzhou University"]}],authorString:"Zhijun Yao; Bin Hu; Yuanwei Xie; Philip Moore; Jiaxiang Zheng",institutions:["Lanzhou University"],countries:["CN"],year:2015,journal:"Brain Informatics",citations:79,abstract:"Brain networks can be divided into two categories: structural and functional networks. Many studies of neuroscience have reported that the complex brain networks are characterized by small-world or scale-free properties. The identification of nodes is the key factor in studying the properties of networks on the macro-, micro- or mesoscale in both structural and functional networks. In the study of brain networks, nodes are always determined by atlases. Therefore, the selection of atlases is critical, and appropriate atlases are helpful to combine the analyses of structural and functional networks. Currently, some problems still exist in the establishment or usage of atlases, which are often caused by the segmentation or the parcellation of the brain. We suggest that quantification of brain networks might be affected by the selection of atlases to a large extent. In the process of building atlases, the influences of single subjects and groups should be balanced. In this article, we focused on the effects of atlases on the analysis of brain networks and the improved divisions based on the tractography or connectivity in the parcellation of atlases.",keywords:["Atlas","Neuroscience","Functional connectivity","Complex network","Brain atlas"],concepts:["Computer science","Atlas (anatomy)","Neuroscience","Artificial intelligence","Functional connectivity","Complex network","Brain atlas"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Neural dynamics and brain function"],pdf_url:"https://braininformatics.springeropen.com/counter/pdf/10.1007/s40708-015-0009-z",is_oa:!0,n_refs:92,n_refs_in_core:19,degree:33,community:1,deg_w:435,betweenness:.0014,pagerank:.00349,eigenvector:.047,pdf_file:"Yao_2015.pdf",pdf_downloaded:!0},{id:195,oaid:"W2794875199",doi:"10.1038/s41598-019-39243-w",title:"Discordant attributes of structural and functional brain connectivity in a two-layer multiplex network",authors:[{name:"Sol Lim",institutions:["University of Cambridge","Indiana University Bloomington"]},{name:"Filippo Radicchi",institutions:["Indiana University Bloomington"]},{name:"Martijn P. van den Heuvel",institutions:["Amsterdam Neuroscience","Vrije Universiteit Amsterdam"]},{name:"Olaf Sporns",institutions:["Indiana University Bloomington"]}],authorString:"Sol Lim; Filippo Radicchi; Martijn P. van den Heuvel; Olaf Sporns",institutions:["Amsterdam Neuroscience","Indiana University Bloomington","University of Cambridge","Vrije Universiteit Amsterdam"],countries:["GB","NL","US"],year:2019,journal:"Scientific Reports",citations:79,abstract:"Several studies have suggested that functional connectivity (FC) is constrained by the underlying structural connectivity (SC) and mutually correlated. However, not many studies have focused on differences in the network organization of SC and FC, and on how these differences may inform us about their mutual interaction. To explore this issue, we adopt a multi-layer framework, with SC and FC, constructed using Magnetic Resonance Imaging (MRI) data from the Human Connectome Project, forming a two-layer multiplex network. In particular, we examine node strength assortativity within and between the SC and FC layer. We find that, in general, SC is organized assortatively, indicating brain regions are on average connected to other brain regions with similar node strengths. On the other hand, FC shows disassortative mixing. This discrepancy is apparent also among individual resting-state networks within SC and FC. In addition, these patterns show lateralization, with disassortative mixing within FC subnetworks mainly driven from the left hemisphere. We discuss our findings in the context of robustness to structural failure, and we suggest that discordant and lateralized patterns of associativity in SC and FC may provide clues to understand laterality of some neurological dysfunctions and recovery.",keywords:["Connectome","Assortativity","Neuroscience","Functional connectivity","Context","Multiplex","Functional magnetic resonance imaging"],concepts:["Connectome","Assortativity","Neuroscience","Functional connectivity","Context (archaeology)","Computer science","Multiplex","Functional magnetic resonance imaging"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://www.nature.com/articles/s41598-019-39243-w.pdf",is_oa:!0,n_refs:138,n_refs_in_core:14,degree:28,community:0,deg_w:329.5,betweenness:.0031,pagerank:.00316,eigenvector:.0158,pdf_file:"Lim_2019.pdf",pdf_downloaded:!0},{id:196,oaid:"W1993780789",doi:"10.1371/journal.pone.0023460",title:"Driving and Driven Architectures of Directed Small-World Human Brain Functional Networks",authors:[{name:"Chao‐Gan Yan",institutions:["Beijing Normal University"]},{name:"Yong He",institutions:["Beijing Normal University"]}],authorString:"Chao‐Gan Yan; Yong He",institutions:["Beijing Normal University"],countries:["CN"],year:2011,journal:"PLoS ONE",citations:79,abstract:"Recently, increasing attention has been focused on the investigation of the human brain connectome that describes the patterns of structural and functional connectivity networks of the human brain. Many studies of the human connectome have demonstrated that the brain network follows a small-world topology with an intrinsically cohesive modular structure and includes several network hubs in the medial parietal regions. However, most of these studies have only focused on undirected connections between regions in which the directions of information flow are not taken into account. How the brain regions causally influence each other and how the directed network of human brain is topologically organized remain largely unknown. Here, we applied linear multivariate Granger causality analysis (GCA) and graph theoretical approaches to a resting-state functional MRI dataset with a large cohort of young healthy participants (n = 86) to explore connectivity patterns of the population-based whole-brain functional directed network. This directed brain network exhibited prominent small-world properties, which obviously improved previous results of functional MRI studies showing weak small-world properties in the directed brain networks in terms of a kernel-based GCA and individual analysis. This brain network also showed significant modular structures associated with 5 well known subsystems: fronto-parietal, visual, paralimbic/limbic, subcortical and primary systems. Importantly, we identified several driving hubs predominantly located in the components of the attentional network (e.g., the inferior frontal gyrus, supplementary motor area, insula and fusiform gyrus) and several driven hubs predominantly located in the components of the default mode network (e.g., the precuneus, posterior cingulate gyrus, medial prefrontal cortex and inferior parietal lobule). Further split-half analyses indicated that our results were highly reproducible between two independent subgroups. The current study demonstrated the directions of spontaneous information flow and causal influences in the directed brain networks, thus providing new insights into our understanding of human brain functional connectome.",keywords:["Connectome","Default mode network","Neuroscience","Human brain","Task-positive network","Connectomics","Resting state fMRI","Human Connectome Project"],concepts:["Connectome","Default mode network","Neuroscience","Human brain","Task-positive network","Connectomics","Resting state fMRI","Human Connectome Project"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced Neuroimaging Techniques and Applications"],pdf_url:"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0023460&type=printable",is_oa:!0,n_refs:100,n_refs_in_core:15,degree:30,community:1,deg_w:572.5,betweenness:7e-4,pagerank:.00422,eigenvector:.0783,pdf_file:"Yan_2011.pdf",pdf_downloaded:!0},{id:197,oaid:"W1559608009",doi:"10.1002/hbm.22406",title:"Altered topological properties of the cortical motor-related network in patients with subcortical stroke revealed by graph theoretical analysis",authors:[{name:"Dazhi Yin",institutions:["East China Normal University"]},{name:"Fan Song",institutions:["Fudan University","Huashan Hospital"]},{name:"Dongrong Xu",institutions:["New York Psychoanalytic Society and Institute","Columbia University"]},{name:"Limin Sun",institutions:["Fudan University","Huashan Hospital"]},{name:"Weiwei Men",institutions:["East China Normal University"]},{name:"Lili Zang",institutions:["East China Normal University"]},{name:"Xu Yan",institutions:["East China Normal University"]},{name:"Mingxia Fan",institutions:["East China Normal University"]}],authorString:"Dazhi Yin; Fan Song; Dongrong Xu; Limin Sun; Weiwei Men; Lili Zang; Xu Yan; Mingxia Fan",institutions:["Columbia University","East China Normal University","Fudan University","Huashan Hospital","New York Psychoanalytic Society and Institute"],countries:["CN","US"],year:2013,journal:"Human Brain Mapping",citations:74,abstract:"Cerebral neuroplasticity after stroke has been elucidated by functional neuroimaging. However, little is known concerning how topological properties of the cortical motor-related network evolved following subcortical stroke. In the present study, we investigated 24 subcortical stroke patients with only left motor pathway damaged and 24 matched healthy controls. A cortical motor-related network consisting of 20 brain regions remote from the primary lesion was constructed using resting-state functional MRI datasets. We subsequently used graph theoretical approaches to analyze the topological properties of this network in both stroke patients and healthy controls. In addition, we divided the stroke patients into two subgroups according to their outcomes in hand function to explore relationships between topological properties of this network and outcomes in hand function. Although we observed that the cortical motor-related network in both healthy controls and stroke patients exhibited small-world topology, the local efficiency of this network in stroke patients is higher than and global efficiency is lower than those in healthy controls. In addition, striking alterations in the betweenness centrality of regions were found in stroke patients, including the contralesional supplementary motor area, dorsolateral premotor cortex, and anterior inferior cerebellum. Moreover, we observed significant correlations between betweenness centrality of regions and Fugl-Meyer assessment scores. A tendency for the cortical motor-related network to be close to a regular configuration and altered betweenness centrality of regions were demonstrated in patients with subcortical stroke. This study provided insight into functional organization after subcortical stroke from the viewpoint of network topology.",keywords:["Betweenness centrality","Neuroscience","Stroke","Motor cortex","Connectome","Neuroplasticity","Premotor cortex","Primary motor cortex"],concepts:["Betweenness centrality","Neuroscience","Stroke (engine)","Motor cortex","Connectome","Neuroplasticity","Premotor cortex","Primary motor cortex"],topics:["Functional Brain Connectivity Studies","Advanced Neuroimaging Techniques and Applications","Advanced MRI Techniques and Applications"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/hbm.22406?download=true",is_oa:!0,n_refs:68,n_refs_in_core:16,degree:30,community:1,deg_w:446,betweenness:8e-4,pagerank:.00355,eigenvector:.0509,pdf_file:null,pdf_downloaded:!1},{id:198,oaid:"W2536956699",doi:"10.1146/annurev-bioeng-071516-044511",title:"Emerging Frontiers of Neuroengineering: A Network Science of Brain Connectivity",authors:[{name:"Danielle S. Bassett",institutions:["University of Pennsylvania"]},{name:"Ankit N. Khambhati",institutions:["University of Pennsylvania"]},{name:"Scott T. Grafton",institutions:["University of California, Santa Barbara","Imaging Center"]}],authorString:"Danielle S. Bassett; Ankit N. Khambhati; Scott T. Grafton",institutions:["Imaging Center","University of California, Santa Barbara","University of Pennsylvania"],countries:["US"],year:2017,journal:"Annual Review of Biomedical Engineering",citations:66,abstract:"Neuroengineering is faced with unique challenges in repairing or replacing complex neural systems that are composed of many interacting parts. These interactions form intricate patterns over large spatiotemporal scales and produce emergent behaviors that are difficult to predict from individual elements. Network science provides a particularly appropriate framework in which to study and intervene in such systems by treating neural elements (cells, volumes) as nodes in a graph and neural interactions (synapses, white matter tracts) as edges in that graph. Here, we review the emerging discipline of network neuroscience, which uses and develops tools from graph theory to better understand and manipulate neural systems from micro- to macroscales. We present examples of how human brain imaging data are being modeled with network analysis and underscore potential pitfalls. We then highlight current computational and theoretical frontiers and emphasize their utility in informing diagnosis and monitoring, brain-machine interfaces, and brain stimulation. A flexible and rapidly evolving enterprise, network neuroscience provides a set of powerful approaches and fundamental insights that are critical for the neuroengineer's tool kit.",keywords:["Neural engineering","Connectomics","Systems neuroscience","Computational neuroscience","Neuroscience","Artificial neural network"],concepts:["Computer science","Neural engineering","Connectomics","Systems neuroscience","Computational neuroscience","Neuroscience","Artificial neural network","Artificial intelligence"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced MRI Techniques and Applications"],pdf_url:"https://www.annualreviews.org/doi/pdf/10.1146/annurev-bioeng-071516-044511",is_oa:!0,n_refs:214,n_refs_in_core:21,degree:35,community:0,deg_w:525,betweenness:.0026,pagerank:.00444,eigenvector:.0283,pdf_file:null,pdf_downloaded:!1},{id:199,oaid:"W3160703572",doi:"10.1002/hbm.25462",title:"Principles and open questions in functional brain network reconstruction",authors:[{name:"Onerva Korhonen",institutions:["Universidad Politécnica de Madrid","Aalto University"]},{name:"Massimiliano Zanin",institutions:["Institute for Cross-Disciplinary Physics and Complex Systems"]},{name:"David Papo",institutions:["University of Ferrara","Italian Institute of Technology","Center for Translational Neurophysiology of Speech and Communication"]}],authorString:"Onerva Korhonen; Massimiliano Zanin; David Papo",institutions:["Aalto University","Center for Translational Neurophysiology of Speech and Communication","Institute for Cross-Disciplinary Physics and Complex Systems","Italian Institute of Technology","Universidad Politécnica de Madrid","University of Ferrara"],countries:["ES","FI","IT"],year:2021,journal:"Human Brain Mapping",citations:64,abstract:"Graph theory is now becoming a standard tool in system-level neuroscience. However, endowing observed brain anatomy and dynamics with a complex network representation involves often covert theoretical assumptions and methodological choices which affect the way networks are reconstructed from experimental data, and ultimately the resulting network properties and their interpretation. Here, we review some fundamental conceptual underpinnings and technical issues associated with brain network reconstruction, and discuss how their mutual influence concurs in clarifying the organization of brain function.",keywords:["Covert","Cognitive science","Neuroscience","Representation","Complex network","Network science","Connectomics"],concepts:["Covert","Cognitive science","Neuroscience","Computer science","Representation (politics)","Complex network","Network science","Connectomics"],topics:["Functional Brain Connectivity Studies","Neural dynamics and brain function","Advanced MRI Techniques and Applications"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/hbm.25462",is_oa:!0,n_refs:421,n_refs_in_core:17,degree:32,community:0,deg_w:522,betweenness:.0025,pagerank:.00446,eigenvector:.0255,pdf_file:"Korhonen_2021.pdf",pdf_downloaded:!0}],n={n_papers:200,papers_with_refs:200,mean_refs:99.7,direct_citation_edges:2835,coupling_edges_kept:1345,total_edges_kept:4186,data_mode:"co-citation",reference_source:"OpenAlex referenced_works"},i={papers:e,completeness:n};export{n as completeness,i as default,e as papers};
